(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["496"] = {"atoms": {"496.1": {"x": [[9, "مقدمة الشارح\r"]], "pg": [9, 9]}, "496.2": {"x": [[9, "بسم الله الرحمن الرحيم\rيقول أحمد الفقير المقّري ... المغربيّ المالكي الأشعري\r[الشرح]\r(بسم الله الرحمن الرحيم) أي: أبتدئ باسم الذات المتصف بالرحمة إيجادا وإمداد، وإظهارا واستعداد، وشمول الرحمن لكل شيء مدلول عليه بقوله سبحانه: {وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ} [الأعراف: 156]\rفالبسملة جامعة لكل شيء أصلا وفرعا، حقيقة وشرعا، فلهذا ابتدأ بها استمدادا بمدد الله تعالى المتصل بكل شيء، ولم يقل بالله الرحمن الرحيم، لدفع توهم القسم؛ لأن التأثير للذات العلية؛ بأسمائها لا بطريق العلية، والكلام على البسملة مما يطول؛ وقد أفرد بالتصنيف من الأئمة الفحول. (يقول) أي: الآن وفيما سيأتي من الزمان إبقاء لشهادة التوحيد، وبيانا لحاله الكائن عليه في طلب المزيد، وهذا هو الأليق في هذا المقام، كما أن اللائق بالشيخ ابن مالك قوله في ألفيته: قال محمد هو ابن مالك. لعدم إرادته إظهار التلبس بشواغل العربية في الحال، ولا دوام شهود ذلك منه في المال. (أحمد) اسمه رحمه الله تعالى، وهو أحمد بن محمد بن أحمد بن يحنى بن عبد الرحمن بن أبي القيس بن محمد، أبو العباس.\r(الفقير) أي: المفتقر إلى ربه تعالى، أخر الوصف عن الأصل محافظة للوزن. (المقري) بفتح الميم وتشديد القاف وآخرها راء مهملة: نسبة إلى مقر بالتشديد قرية من قرى تلمسها إليها نسبة آبائه، ويجوز في هذه النسبة فتح الميم وسكون القاف لغتان أشهرهما الأولى.\r(المغربي) نسبة إلى قطر المعرب، فإن من ذلك بلاده تلمسان واد فيها، ونشأ بها، وقد نزل بلاد فارس من العرب الأقصى، ثم دخل مصر المحروسة في شهر رجب سنة ثمان وعشرين بعد الألف، وتزوج فيها من السادة الوفائية بعد أداء فريضة الحج، ثم زار بيت المقدس، ورجع إلى القاهرة، ودخل بلادنا دمشق الشام، في سنة سبع وثلاثين وألف في أوائل شعبان، ولم يتفق لغيره من العلماء الواردين إلى دمشق ما اتفق له من الحظوة والإقبال عليه، وكان كثير الاعتناء بمدح الشام وأهلها، وله في ذلك النظم البديع، فمن ذلك قوله رحمه الله:"], [10, "الحمد لله الذي توحيده ... أجل ما اعتنى به عبيده\r[الشرح]\rقال لي ما تقول في الشام حبر شام من بارق العلا ما شامه\rقلت ما ذا اقول في وصف أرض هي في وجنة المحاسن شامه\rوذهب إلى مصر ثم عاد إلى دمشق مرة ثانية في سنة أربعين والف، وحصله له من الإكرام ما حصل له في المرة الأولى، ثم رجع على مصر وعزم على التهيؤ المكين في دمشق ففاجأته المنية بمصر رحمه الله تعالى، في جمادى الآخرة سنة إحدى وأربعين وألف، ودُفن في مقبرة المجاورين.\rوقال الشيخ إبراهيم الأكرمي، خادم ضريح الشيخ الأكبر محيي الدين ابن العربي - رضي الله عنه - في تاريخ وفاته، في ختم الفصل به فارخوه (خاتم) وله من المصنفات رحمه الله تعالى أشياء كثيرة، منها هذه القصيدة، التي سماها (إضاءة الدجنة في عقائد أهل السنة) ولع كتاب (عرف الطيب في أخبار الن الخطيب)، (وفتح المتعال في مدح النعال)، (وأزهار الكمامة في أخبار العمامة)، (وأزهار الرياض في أخبار القاضي عياض)، (وعرف النشق في أخبار دمشق)، (وروض الأنس العاطرة الأنفاس في ذكر من لقيته من أعلام مراكش وفاس)، (والدر الثمين في أسماء الهادي الأمين)، (وحاشية على أم البراهين)، رحمه الله تعالى رحمه الله تعالى رحمة واسعة، ورفع دكره في المقربين.\r(المالكي) نسبة إلى مذهب الإمام مالك بن أنس - رضي الله عنه -، في فروع الفقه.\r(الأشعري) نسبة على مذهب الشيخ أبي الحين الأشعري رحمه الله تعالى في أصول علم الكلام.\r(الحمد) أي: الشكر. (الله) أي: الواجب الوجد، ومفيض الإنعام والجود. (الذي توحيده) أي: اعتقاد وحدانيته ذاتا وصفاتا وأفعالا. (أجل) أي: اشرف وأعظم. (ما) أي: شيء. (اعتنى به) أيك اهتم له (عبيده) جمع عبد، وهو: من له صفة العبودية الله تعالى وهي أفضل ن العبادة. فالعبد المتحقق في نفسه بصفة عبوديته أفضل من العابد القائم بعبادته، والمراد من حيث ذلك الوصف وغلا فإن احدهما لا يفك عن الآخر في الكاملين، ومعنى العبادة فعل ما يرضى به الرب، ومعنى العبودية الرضا بما يفعله الرب، وفيه براعة الاستهلال بأن هذه المنظومة في علم التوحيد، ومدح علم التوحيد بأنه أجل العلوم قدرا وأعظمها مثوبة وأجرا."], [11, "العالم الحي القديم الباقي ... القادر الغني بالإطلاق\rمرشدنا من فضله وجوده ..... بصنعه المعرب عن وجوده\r[الشرح]\r(العالم) بالجر صفة الله تعالى. (الحي) صفة لع تعالى، وكذا البواقي، وتقديم العالم على الحي مراعاة للوزن؛ ولأن المعلومات تدل على العلم أولا والعلم يدل على الحياة في نظر العقلاء، وسياتي بيانه إن شاء الله تعالى. (القديم) أي المتصف بالقديم والقديم من أسماء الله تعالى التسعة والتسعين، كما ورد في حديث الن ماجه في السنن، من أبواب الذكر، قال: حدثنا هشام بن عمار، حدثنا عبد الملك بن محمد الصنعاني، حدثنا أبو المنذر زهير بن محمد التميمي، حدثنا موسى بن عقبة، حدثني عبد الرحمن الاعرج، عن أبي هريرة - رضي الله عنه - الحديث بطوله وفيه الاسم المذكور.\r(الباقي) أي: المتصف بالبقاء. والفرق بين الاسم والصفة اعتباري، فإن قصد بالاسم اتصاف فهو صفة، وإن قصد بالصفة التقيين فهو اسم. وقيل: إن أريد جهة الحق تعالى فهي صفة، وإن أريد جهة الخلق فهي اسم. (القادر) أي: الذي له القدرة على كل شيء بلا واسطة ليخرج المقتدر، فإن القادر بوسائط الأسباب وهو أبلغ في الظهور، من جهة الخلق فإن زيادة المبني في متحد الصيغة تدل على زيادة المعنى، ولا بد من قيد متحد الصيغة كالرحمن الرحيم ليخرج مختلفها كتخمة وتخم وحذر وحاذر. والمقتدر أكثر الخلق لا من جهته سبحانه وتعالى، كالعليم والعلام بالنسية إلى العالم.\r(الغني) بالتشديد، أي: المتصف بالاستغناء عن كل شيء ذاتا وصفة وأفعالا و أحكاما. (بالإطلاق) متعلق بالغني وهو الغني المطلق ليخرج الغني المقيد الذي يكون للعبد بالله تعالى من وجه دون وجه، كالغني بالله من جهة المال أو الجاه أو غيرها، فإنه تعالى منزه عنه أزلا وأبدا.\r(مرشدنا) أي: دال لنا وهادينا معشر عباده المكلفين إلى معرفته وعبادته أي: دال لنا وهادينا معشر عباده المكلفين على معرفته وعبادته. (من) محض. (فضله) أي: إحسانه إلينا وكرمه. (وجوه) لا لغرض منه تعالى في جلب نفع له بذلك، ولا دفع ضرر عنه، ولا باستحقاق لنا عليه، والمراد أن ذلك حاصل منه بوجه الإمكان من طرفه وطرفنا لا بطريق الوجوب والإيجاب، ليخرج مذهب الحكماء والمعتزلة القائلين بالوجوب الذاتي والتعليل وإيجاب الصلاح والأصلح عليه تعالى في حق عباده (يصنعه) متعلق بمرشدنا والباء للملابسة والمصاحبة، فدخلت عليه بثياب السفر، لا"], [12, "...........................................\r[الشرح]\rللاستعانة، فإنه تعالى يستعين بشيء على شيء لوجوب الغني المطلق له عزّ وجل كما مر.\rونظر ذلك قوله تعالى: {ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ} [النحل: 32]. أي: بملابسة ذلك ومصاحبته. وكذلك قوله تعالى: {وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ} [الزخرف: 72].أي: بسبب ذلك ومعنى الملابسة والمصالحة في العمل ملابسه الجزء أو مصاحبته دخول عند دخول الجنة.\rواقتصر النووي رحمه الله تعالى في شرح صحيح مسلم على معنى السبية فقط. ولا يرد على ذلك أحاديث البخاري ومسلم، عن أبي هريرة قال: قال رسول الله - صلى الله عليه وسلم -: (لن ينجي منكم أحدا عمله). قالوا: ولا أنت يا رسول الله؟ قال: (ولا أنا إلا أن يتغمدني الله رحمته) (¬1) الحديث.\r\rوفي رواية مسلم، عن ابي هريرة قال: قال رسول الله - صلى الله عليه وسلم -: (قاربوا وسددوا واعملوا أنه لا ينجو أحد منكم بعمله) (¬2). الحديث. فإن هذه الباء المنفي مدخولها معناها الاستعانة. أي: لا يستعين أحد منكم على ذلك بعمله بل برحمة الله تعالى وفضله ..\r(المعرب) أي: الكاشف والمبين نعت الصنعة والصنع بمعنى: المصنوع كالخلق بمعنى المخلوق والمراد كل مصنوع من مصنوعاته، أو بالمعنى المصدري: أي: فعله المعرب. (عن وجوده) سبحانه، أي: كونه موجودا عند العقول يعني ثابتا محققا وذلك حكم التكليف الشرعي لا عن وجوده الحقيقي الذي هو عليه في نفسه سبحانه وتعالى وتقدسن بحيث يصير بذلك مدركا في العقول محاطا به في الإفهام، فإن ذلك شأن الوجود المقيد ووجوده تعالى مطلق بالإطلاق الحقيقي فيستحيل عليه الإدراك بالعقول والإحاطة بالأفهام من حيث هو سبحانه كما سيأتي إن شاء الله تعالى.\r¬__________\r(¬1) () رواه أحمد في المسند (2/ 451، 466)، (3/ 52، 337)، وابن المبارك في الزهد (ص 507)، والطيالسي في المسند (1/ 305)، والطبراني في الأوسط (6/ 332)، (8/ 74)، وفي الشاميين (1/ 396)، والربيع في مسنده (1/ 282)، وابن حبان في صحيحه (2/ 60)، والحكيم في النوادر (1/ 95)، 04/ 78)\r(¬2) () رواه مسلم (4/ 2171)، وابن حبان (2/ 435)، وأحمد في المسند (2/ 466)، (6/ 273)."], [13, "سبحانه جل عن النظائر ..... وكل ما يخطر في الضمائر\rوأفضل الصلاة والسلام ...... لمن حوى جوامع الكلام\r[الشرح]\rفإن الوجود على أربعة أنواع: الوجود العلمي: كوجود زيد مثلا في علمنا وهو حصول صرته في خيالنا. والوجود القولي: كوجود ويد في كلامنا وهو حصول حروف اسمه في نطقنا بذلك.\rوالوجود الرقمي: كوجود ويد في كتابتنا وهو رسم حروف اسمه في القرطاس. وهذه الوجودات الثلاث، الوجود الرقمي منها يدل على الوجود القولي، والوجود القولي يدل على الوجود العلمي، والوجود العلمي هو المراد هنا بوجود الله تعالى الذي تعرب عنه مصنوعاته عند العقلاء وهو الذي وقع به التكليف الشرعي، فيؤمن مثبته ويكفر جاحده، أي: مثبته في علمه بعقله وجاحده منم علمه بعقله إلا فهو تعالى على ما هو في وجود العيني لا يصل إليه علم عالم ولا جحد جاحد تبارك وتقدس.\rوأما النوع الرابع، وهو الوجود العيني: وهو الوجود الحقيقي للشيء كوجود زيد مثلا في ذاته خارجا عن علمنا وقولنا وكتابتنا فهو المراد بامتناع إدراكه في حق الله تعالى. وعدم دلالة مصنوعاته عليه بهذا المعنى لعدم وجود شيء بالنسبة إليه وذلك هو المنزه بالتنزيه التام كما سيأتي، وأشار الناظم رحمه الله تعالى هنا إلى ذلك بقوله تعده: (سبحانه) أي: هو منزه. (جل) أي: عظم. (عن النظائر) جمع نظير. بمعنى شبيه له في ذاته وصفاته وأفعاله على حسب وجوده العنين الحقيقي ستحانه وتعالى. (و) عن (كل ما) أي: شيء (يخطر في الضمائر) أي: النفوس من جميع المعاني كما قال بعضهم: كل ما خطر ببالك فالله بخلاف ذلك.\r(وأفضل الصلاة) من الله تعالى وهي الرحمة. (و) أفضل (السلام) أي: الأمان من كل نقص. (لمن) أي: للذي أو للنبي (حوى) أي: حاز (جوامع الكلم) أي: الكلمات البليغة الجوامع لأنواع المعاني وهو نبينا محمد - صلى الله عليه وسلم - إشارة لما ورد عنه - صلى الله عليه وسلم - في حديث البخاري ومسلم، والنسائي، عن ابي هريرة - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: (بُعثت بجوامع الكلم ونُصرت بالرعب) (¬1) الحديث\r¬__________\r(¬1) () رواه البخاري (3 م 1087)، (6/ 2573)، ومسلم (1/ 371) ن والنسائي (6/ 3، 4)"], [14, "وأفهم الحق ذوي الأذهان .... وأفحم الخصوم بالبرهان\rوحض كل الناس أن يقولوا ... شهادة تزكوا بها العقول\r[الشرح]\r(وأفهم) - صلى الله عليه وسلم -. (الحق) معقول أول وهو ما جاء به - صلى الله عليه وسلم - من الاعتقاد والأعمال والأحوال وغير ذلك وهو ضد الباطل. والفرق بين الحق والصدق اعتباري، فإن اعتبرت مطابقة نقس الأمر له فهو حقن وإن اعتبرت مطابقته لنفس الأمر فهو صدق. وقيل: لا فرق بينهما كما قرره السعد التفتازاني في أوائل شرح العقائد. (ذوي) جميع ذي بمعنى صاحب مفعول ثان. (الأذهان) جمع ذهن.\rقال في المصباح المنير: الذهن الذكاء والفطنة والجمع أذهان. وفي القاموس، الذهن بالكسر الفهم والعقل وحفظ القلب والفطنة ويحرك القوة وجمعه اذهان. (وأفحم) أي: غلب واسكت. قال في المصباح المنير: فحم الصبي يفحم بفتحتين فحوما وفحاما بالضم: بكى حتى انقطع صوته، ومنه قيل أفحمت الخصم إفحاما: إذا اسكته بالحجة. انتهى\rولا يخفى ما بين أفحم وأفهم من الجناس المضارع لقرب المخرج بين الهاء والحاء كقوله تعالى: {وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْأَوْنَ عَنْهُ} [الأنعام: 26]. (الخصوم) جمع خصم، وهم المخالفون في الدين والملة، وقد يطلق الخصم على كل مخالف ولو في المذهب. (بالبرهان) متعلق بأفحم، والبرهان: بالضم الحجة كذا في القاموس، وقد يخص بالقطعي والدليل يشمل القطعي والظني، وحقيقة البرهان ما تركب من مقدمات كلها يقينية، والغرض من البرهان تحصيل اليقين.\r(حض) يقال: حضه على الأمر حضا من باب قتل حمله عليه كذا في المصباح، والمرد أمر. (كل الناس) أي: المكلفين منهم. (أني يقولوا) بألسنتهم معتقدين ذلك بقلوبهم. (شهادة) وهي أشهد أن لا إله إلا الله، وأشهد أن محمد رسول الله، فالمراد جنسها لتشمل الشهادتين أو شهادة التوحيد أولا ولهذا وصفها بجملة قوله: (تزكي) أي: تطيب ومنه قولهم: مسكي ذكي. قال في القاموس: مسكي زكي وذاك وذكية ساطع ريحه. والذكاء بالمد: سرعة الفطنة ودكت النار اشتهد لهبها. (بها العقول) أي: يحصل لها الذكاء والفطنة أو تقوى في الإدراك وهو إشارة إلى ما ورد في حديث مسلم، والنسائي، عن ابي هريرة - رضي الله عنه -، أن رسول الله - صلى الله عليه وسلم - قال: (أُمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله، فمن قال لا إله إلا الله عصم مني ماله ونفسه إلا بحقه وحسابه على الله)."], [15, "فمن أجاب نال خيرا جذلّه .... ومن أبى أذلّه وجدله\r[الشرح]\rوفي رواية لمسلم، أن رسول الله - صلى الله عليه وسلم - قال: (أُقاتل الناس حتى يشهدوا أن لا إله إلا الله ويؤمنوا بي وبما جئت به فإذا فعلوا ذلك عصموا مني دمائهم وأموالهم إلا بحقها وحسابهم على الله) (¬1).\rوروى النسائي، عن أنس بن مالك - رضي الله عنه -، قال: لما توفي رسول الله - رضي الله عنه - ارتدت العرب، قال عمر) (¬2): كيف تقاتل العرب؟ فقال أبوبكر - رضي الله عنه -: إنما قال رسول الله - صلى الله عليه وسلم -: (أُمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله) الحديث بطوله.\r(فمن أجاب) أي: قبل ما أمر به من الحق. (نال) في الدنيا والأخرة. (خيرا) وتنكيره للتعظيم. (جد) يقال جد الشيء يجد بالكسر جده فهو جديد فهو خلاف القديم كذا في المصباح. (له) أي: لمن أجاب والجملة نعت للخير أي: ينال خيرا جديدا يناله، ويجوز أن يكون جد أي: عظم ذلك الخير له، قال في الصحاح: وفي حديث أنس: (كان الرجل منا إذا قرأ البقرة وآل عمران جد فينا) (¬3) أي: عظم في أعيننا. انتهى\rويجوز أن يكون جد أي: اجتهد يعني ذلك المجيب له أي: لذلك الخير. قال في المصباح: الجد في الأمر الاجتهاد وهو مصدر يقال من جد يجد من بابي ضرب وقتل والاسم الجد بالكسر. (ومن أبى) أي: امتنع عن الإجابة. (أذله) أي: حقره. (وجدّله) بالتشديد. قال في المصباح: جدلته تجديلا ألقيته، أي: على الجدالة وطعنه فجدله، وفي القاموس: الجدالة كسحابة الأرض أو ذات رمل رقيق وجد له فانجدل وتجدل صرعه على الجدالة. انتهى. يعني طرحه وصرعه بالحجج البينات الباهرات أو بالمحاربة والقتال وأنواع الغزوات.\r¬__________\r(¬1) () رواه البخاري (1/ 17، 153)، (2/ 507)، ومسلم (1/ 51، 53) (4/ 1871)، والحاكم (1/ 544)، والترميذي (5/ 3، 4) والدارمي (2/ 287)، وأبو داود (2/ 93)، (3/ 44، 207)، والنسائي (5/ 14)، (6/ 4، 7)، (7/ 76/، 78)، وابن ماجه (1/ 27، 28).\r(¬2) () يعني: لسيدنا أبي بكر الصديق\r(¬3) () رواه أحمد في المسند (3/ 120)"], [16, "صلى عليه الله ما الحق اعتلا ... مع آله صحبه ومن تلا\rوبعده فالعلوم ذات كثره ... وبعضها له مزيد الأثره\rونوّعت إلى اعتقاد وعمل ... والأول الكلام مستدني الأمل\r[الشرح]\r(صلى عليه الله) تأكيد للصلاة المذكورة. (ما) مصدر بظرفية. (الحق) ضد الباطل أو اسم الله سبحانه. (اعتلا) أي: ارتفع يعني مدة اعتلاء الحق وارتفاعه في الأرض والسماء. (مع) شمول الصلاة والسلام المذكرين لجميع. (آله) أي: أهل بيته ... : - صلى الله عليه وسلم - من أقاربه المؤمنين به إلى يوم القيامة وأزواجه الطاهرات. (وصحبه) وجمع صاحب كركب جمع راكب، ويجمع على صحاب كجائع وجياع وصحبان مثل شبان والأصحاب جمع صحب مثل فرخ وأفراخ، والصحابة بالفتح الأصحاب وهي في الأصل مصدر وجمع الأصحاب أصحايب كذا في الصحاح. وفي المصباح صحبته أصحبه صحبة فأنا صاحب، والجمع صحب وأصحاب وصحابة والأصل في هذا الإطلاق لمن حصل لع رؤية ومجالسة. (ومن تلا) أي: تبع يقال تلوت الرجال أتلوه تلوا على فعول تبعته فأنا له تال وتلو أيضا، وزاد جمل كذا في المصباح والمراد بذلك التابعون للصحابة بالخير والإحسان إلى آخر الزمان.\r(وبعد) بالبناء على الضم لقطعه ونية معنى المضاف إليه، والوال نائبة عن أما وصلة أما بعد، وهي فصل الخطاب الذي قال الله تعالى في حق داود - صلى الله عليه وسلم -: {وَآتَيْنَاهُ الْحِكْمَةَ وَفَصْلَ الْخِطَابِ} [ص: 20]. كما قيل. (فالعلوم) جمع علم. (ذات كثره) بسكون الهاء للوزن بحيث لا تكاد نتضبط أنواعها. (وبعضها) أي: العلوم. (له مزيد) أي: زيادة الأثر بسكون الهاء أيضا في آخره، وبفتح الهمزة الثاء المثلثة: الاسم من أثر يؤثر إيثارا إذا أعطى، وفي الحديث قال النبي - صلى الله عليه وسلم - للأنصار: (ستلقون بعدي \"الأثرة\" فاصبروا). وأراد أنه يستأثر عليكم فيفضلكم غيركم في قضية من الفيء كذا في نهاية بان الأثير. وفي المصباح: آثرته بالمد: فضلته. واستأثر بالشيء: استبد به والاسم الأثرة مثال بصلة. انتهى. والمراد له مزيد الاستبداد والتقديم على غيره من العلوم.\r(ونوعت) أي: العلوم. (إلى) علم. (اعتقاد) القلب. (و) إلى العلم. (عمل) بالسكون للوزن بالجوارح وهو علم الفقه. (والأول) أي: علم الاعتقاد هو (الكلام) أي: علم الكلام، سمّي به لأن عنوان مباحثته كان قولهم في كذا لأن مسألة الكلام الإلهي"], [17, "وكل علم للمزية اكتسب ... فالفضل من معلومه له انتسب\rوعلم أصل الدين مشهور الشرف ... وخيره المنثور ما له طرف\rوكيف لا وهو المفيد للورا ... علما بمن أنشاهم وصورا\rوحكمه على البرايا انحتما ... والنّجاة فاز من له انتمى\r[الشرح]\rكانت أشهر مباحثه وأكثرها نزعا وجدلا ولغير ذلك أيضا. (مستدني) مستقرب. (الأمل) بالسكون أي: ما يتمناه الإنسان من رفعة المقام والجاه عند الله تعالى وعند الناء في الدنيا والآخرة، يعني: أن هذا العلم الذي هو علم الكلام يقرب الإنسان إلى مقصوده وأمله، ويوصله إلى ما يتمناه من كمال حاله وعمله.\r(وكل علم) من العلوم الشرعية. (للمزية) أي: الفضيلة على من العلوم. (اكتسب) بالسكون للوزن، أي: احتوى كعلم التفسير لما أنه يبحث فيه عن معاني كلا م الله تعالى إلا احتوى على المزية والفضيلة على الحديث النبوي، وعلم له المزية على علم التعبير للمنامات، وعلم اللغة، وكذا علوم العربية، وبقية العلوم كذلك لبعضها المزية على البعض. (فالفضل) الحاص لذلك العلم. (من معلومه) أي: ما يعلم فيه. (له انتسب) بالسكون أيضا فكل علم كان معلومه الذي يبحث فيه عنه تشريفا بالنسبة إلى غيره كان أشرف من غيره. (وعلم أصل الدين) وهو علم الكلام الذي يبحث فيه عن كيفية الاعتقاد الصحيح وغيره في حق الله تعالى وحق أنبيائه ورسله وما جاءوا به من عند الله تعالى. (مشهور الشرف) بالسكون للوزن، أي: للفضيلة لأنه فرض على المكلف قبل غيره من الفرائض؛ لأن معرفة المعبود سابقة على معرفة العباد وضعا وشرعا. (وخيره) أي: منفعته المترتبة عليه. (المنثور) أي: المتفرق الكثير. (ما له طرف) بالسكون أيضا، أي: حد يحده.\r(وكيف لا) يكون في هذه المثابة. (وهو) أي: علم الكلام، هو علم أصول الدين.\r(المفيد للورا) أي: المخلوقين. (علما) مفعول لقوله مفيد. (بمن) أي: بالذي أو بإله. (أنشأهم) أي: خلقهم. (وصورا) الألف للإطلاق أي: صورهم وهو الله تعالى ربهم ورب كل شيء.\r(وحكمه) أي: هذا العلم يعني أثره الثابت. (على البرايا) أي: جميع المكلفين.\r(انحتما) انقطع بلزومه والألف للإطلاق. وفي المصباح: حتم عليه الأمر حتما من باب ضرب، أوجبه جزما، وانحتم الأمر وتحتم الأمر وجب وجوبا لا يمكن إسقاطه. (وبالنجاة)"], [18, "لأنه بنوره ينقذ من ... ظلمه تقليد فنفعه ضمن\rوكم به لعلماء المله ... من كتب بالقصد مستقله\rما بين منثور ونظم يهتصر ... جناه من مطوّل ومختصر\r[الشرح]\rفي الدنيا والآخرة. (فاز من) أي: الذي أو انسان. (له انتمى) أي: انتسب يعني: صار من أهل هذا العلم ومن حملته.\r(لأنه) أي: الشأن. (بنوره) أي: نور هذا العلم. (ينفذ) أي: يخلص ويسلم. (من ظلمة تقليد) لغيره من أهل الإسلام. (فنفعه) مبتدأ، أي: نفع هذا العلم. (ضمن) خير المبتدأ، يعني: أن نفعه ضامن للإنقاذ من ظلمة التقليد، فإن المقلد في اعتقاده لما كان لا معرفة له بما قلد فيه كان بمنزلة الماشي في الظلمة يقع في المهالك ولا يشعر، ويشير إلى ذلك ما ورد في الحديث الذي أخرجه البخاري في الفتن، عن عبد الله بن مسعود، وأبي موسى الأشعري قال: النبي - صلى الله عليه وسلم -: (إن بين يدي الساعة لأيّأما يرفع فيها العلم وينزل فيها الجهل (¬1). الحديث\rوفي حديث أبي داود، عن أبي موسى الأشعري قال: قال رسول الله - صلى الله عليه وسلم -: (إن بين أيديكم فتنا كقطع الليل المظلم يصبح الرجل فيها مؤمنا ويمسى كافرا، ويمسي مؤمنا ويصبح كافرا) (¬2).\rوفي حديث ابن ماجه، عن ابي أسامة الباهلي قال: قال رسول الله - صلى الله عليه وسلم -: (ستكون فتن يصبح الرجل فيها مؤمنا ويمسي كافرا، إلا من أحياه الله بالعلم) (¬3). وهذه الأحاديث تدل على أن المراد بالعلم العلم الذي يعرف بع الإيمان من الكفر، وهو علم الاعتقاد المنقذ من ظلمات التقليد والعناد. (وكم به) أي: فيه. (لعلماء) هذه. (الملة) الإسلامية. (من كتب) جمع كتاب. (بالقصد مستقله) نعت الكتب. (ما بين منثور) وهو خلاف المنظوم. (ونظم) أي: منظوم. (يهتصر) بالبناء للمفعول وسكون الراء للوزن. قال في القاموس: الهصر: الجذب والإمالة والإدناء وعطف شيء رطب كغصن ونحوهن هصره يهصره\r¬__________\r(¬1) () رواه البخاري (6/ 2590)، ومسلم (4/ 2056)، وأحمد في المسند (1/ 405، 450)، (4/ 392)، الترمذي (4/ 419)، وابن ماجه (2/ 1345).\r(¬2) () رواه أبو داود (4/ 100، 101)، والترمذي (4/ 487)، وابن ماجه (2/ 1310).\r(¬3) () رواه ابن ماجه (2/ 1305)، والدارمي (1/ 109)، والروياني في مسنده (2/ 280)، والفريابي في صفة المنافق (ص 79)."], [19, "وإنني ملت إلى اتّباع ... لهم وإن كنت قصير الباع\rفجئت في المطلب الوحيد ... بنبذة نتفع في التوحيد\rسمّيتها إضاءة الدجنة ... لكونها اعتقاد أهل السنة\rوذاك لمّا أن حللت القاهرة ... بعد الوصول للبقاع الطّاهرة\r[الشرح]\rفانهصر واهتصره فاهتصر. (جناه) نائب الفاعل، والجنا مثل الحصار، يجني من الشجر ما دام غصّا والجني على فعيل مثله، وجنيت الثمرة أجنيها وأجتنيها بمعناه كذا في المصباح. (من مطول ومختصر) بالسكون أيضا بيان للمنثور والمنظوم من الكتب في هذا العلم وهو ظاهر.\r(وإنني ملت إلى اتباع) أي: متابعتي. (لهم) أي: لعلماء الملة فيما فعلوه. (وإن كنت) بالنسبة إليهم. (قصير الباع) والباع: هو مسافة ما بين الكتفين إذا بسطها يمينا وشمالا كذا في المصباح، وقصير الباع كناية عن قصير اليدين الذي لا يمكنه تناول الشيء المرتفع هضما لنفسه رحمه الله تعالى كما هو عادة العلماء الأعلام من أئمة الإسلام.\r(فجئت في) ذا (المطلب) أي: هذا الأمر الذي طلب مني. (الوحيد) أي: الذي لا مثل له. (بنبذه) أي: قطعة صغيرة منبوذة لصغرها بالنسبة إلى كتاب الكبار المؤلفة في ذلك. (تنفع) المكلفين. (في) علم. (التوحيد) أي: اعتقاد وحدانيته الله تعالى وما يتبع من ذلك من بقية مسائل هذا العلم المبني كله مسألة توحيد الله تعالى.\r(سميتها) أي: هذه النبذة. (إضاءة) أي: إنارة وإشراق. (الدجنة) وهي كحذقة.\rوبكسرتين الظلمة والغيم المطبق الريان المظلم لا مطر فيه والجمع دجن كذا في القاموس، كأنه شبه الجهل بالله تعالى بالظلمة المطلقة والغيم المتراكم، وشبه هذه المنظومة بما تحتوي عليه من المسائل الاعتقادية بالنور الذي أشرق في تلك الظلمة فيمحوها ويزيلها. (لكونها) أي: هذه المنظوم النبذة. (اعتقاد أهل السنة والجماعة) نصر الله تعالى كلمتهم إلى قيام الساعة، ولم يذكر فيها شيء من عقائد المخالفين من الحكماء والمعتزلة.\r(وذاك) أن مجيئي بهذه النبذة المنظوم كان (لما أن حللت) أي: نزلت. (القاهرة) بالسكون للوزن، وهي مصر المحروسة. قال في المصباح: حللت بالبلد حلولا من باب قعد، إذا نزلت به، ويتعدى بنفسه أيضا فيقال: حللت البلد. (بعد الوصول للبقاع) جمع"], [20, "منتبذا عن مظهر المغمور ... مسترشدا بالأزهر المعمور\rوكان من منّ مزكي النية ... درسي به العقائد السنية\r[الشرح]\rبقعة. (الطاهرة) بالسكون أيضا وهي بلاد الحجاز، يعني أداء فريضة الحج وزيارة النبي - صلى الله عليه وسلم -.\r(منتبذا) حال من فاعل حللت. وفي المصباح: نبذته نبذا من باب ضرب ألقيته وانتبذت مكانا، اتخذته بمعزل يكون بعيدا عن القوم. انتهى. فمعنى منتبذا متخذا مكانا بعيدا. (عن مظهر) أي: مان ظهوري بمعنى مولدي، يعني عن بلادي التي نشأت فيها.\r(المغمور) المستور، من غمره إذا ستر، نعت لمظهره يعني أنه ظهر من مكان غير مشهور إلى مكان مشهور، أو المغمور: أي المستور بالأفاضل والعلماء مدحة لبلاده متأسفا على حاله حيث صار مطروحا في غيرها من البلاد حليف دار الغربة وقصور المراد، ولا يخفى ما بين قوله مظهري والمغمور من الطباق بذكر الضدين من الظهور والستر. (مسترشدا) أي: طالبا الإرشاد ممن هو من أهله من العباد. (بالأزهر) أي فيه: وهو الجامع المشهور في مصر المحروسة، وهذه نيته في المجاروة المأنوسة جريا على عادة على عادة أهل الكمال في لزوم طريق التواضع بصدق الحال. (المعمور) من العمارة والمراد عمارته بالذكر والعلم والصدق واليقين وإحكام مقام الفقر والتوكل وغير ذلك، وبين المعمور الجناس المصحف.\rوكان من (من) أي: إحسان وإنعام. (مزكي) من قولهم: زكا الزرع في الأرض يزكو وكوا من باب قعد وأزكا بالألف مثله. والزكاء بالمد: النمو والزيادة وزكا الرجل يزكو إذا صلح وزكيته بالتثقيل نسبة إلى الزكاء: وهو الصلاح كذا في المصباح أي: منمي ومصلح. (النية) بسكون الهاء أي: قصد القلب في الأمور: وهو حسن النية وطهارة القلب، قال تعالى في قوم: {وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ} [الزخرف: 72]. وفي حديث أبي داود السجستاني، عن أبي هريرة رضي الله عنه، عن رسول الله - صلى الله عليه وسلم -: قال: (حسن الظن من حسن العبادة). (درسي به) أي: الجامع الأزهري يعني فيه. (العقائد) مفعول درسي. (السنيه) بالسكون وتشديد النون نسبة إلى السنة التي هي على مذهب أهل السنة والجماعة وبالتخفيف من السنا بالقصر: وهو الضوء كذا في المصباح. وفي القاموس: السنا ضوء البرق، وبالمد الرفعة. انتهى. فمعنى السنية: المضيئة أو الرفعية السامية أبدلت همزتها ياء."], [21, "فرام مني بعض الفن ... نظمي لها بحكم حين الظن\rولست للذي انتحى بأهل ... بأنني ذو خطأ وجهل\rفازداد حثه عليّ ونما ... وقال لي اجعل مثل هذا مغنما\rفلم أجد بدّا من الإسعاف ... مع كون رسم العلم غير عافي\rوالله أرجو أن يكون ذاك من ... فعل جميل من رياء قد أمن\r[الشرح]\r(فرام) أي: طلب وقصد. (مني بعض أهل الفن) الألف واللام عوض عن المضاف إليه، أي: في هذا العلم الذي هو علم التوحيد نظمي. (مفعول) رام. (لها) أي: هذه النبيذة المنظومة. (بحكم) أي: بسبب مت تحكم به طبيعة. (حسن الظن) الحسن من رؤية الكمال في أحوال الرجال. (ولست للذي انتحى) أي: طلب مني وقصد. قال في القاموس: نحاه وينحوه وينحاه: قصده كانتحاه. (بأهل) أي: ما أنا بأهل لما طلبه مني. (لأنني ذو) أي: صاحب. (خطأ وجهل) تواضعا منه رحمه الله تعالى.\r(فازداد حثه) أي: طلبه لذلك. (علي) بالتشديد متعلق بازداد. (ونما) أي: كثر. (وقال لي اجعل مثل هذا) المطلوب منك. (مغنما) أي: غنيمة. قال في المصباح: غنمت الشيء أغنمه غنما: أصبته وغنيمة ومغنما والمجموع الغنائم والمغانم. وفي القاموس: المغنم والغنيمة والغنم بالضم: الفيء غنم بالكسر غنما بالضم وبالفتح والتحريك وغنيمة وغنمنا بالضم: الفيء غنم بالكسر غنما بالضم وبالفتح والتحريك وغنيمة وغنما بالضم، والفوز بالشيء بلا مشقة.\r(فلم أجد بدّأً) يقال لا بد من كذا: أي لا محيد عنه لا يعرف استعماله إلا مقرونا بالنفس كذا في المصباح. وفي الصحاح، وقوله: لا بد من كذا كأنه قال: لا فراق منه، ويقال: البد العوض. (من الإسعاف) يقال: سعف بحاجته منع وأسعف: قضيتها له واسعفته، أعنت على أمره.\r(مع كون رسم) قال في القاموس: الرسم الأثر أو بقيته، او ما لا شخص له من الآثار والجمع أرسم ورسوم. (العلم) بسبب وجود العلماء. (غير عافي) أو مندرس، يقال: عفا المترل يعفوا عفوا وعفوا وعفاء بالفتح والمد: درس، وعفته الريح يستعمل لازما ومتعديا ومنه: {عَفَا اللَّهُ عَنْكَ} [التوبة: 43]. أي: محا ذنوبك.\r(والله) بالنصب مفعول مقدم للاهتمام والحصر. (وأرجو أن يكون ذلك) أي: فعل ما طلب مني محسوبا. (من) جملة (فعل جميل) أي: بر وإحسان وإنعام أنعم الله تعالى به."], [22, "وأن يثيبني به يوم الجزا ... ومن وعا أو خط هذا الرجزا\rويجزل المواهب السنية ... ويسعف الراجين بالأمنية\rفالغيث من إنعامه قد كفا ... على البرايا وهو حسبي\r[الشرح]\rعلىّ لأن من أكبر الطاعات وأعظم القربات. (من) شوب (رياء قد أمن) سلم من الرياء والسمعة فكان خالصا لوجهه تعالى الكريم.\r(و) أرجو من الله تعالى أيضا. (أن يثيبني) أي: يثبت لي الثواب. (به) أي: بهذا الفعل. (يوم الجزا) بالقصر لضرورة الوزن: وهو يوم القيامة. (و) يثيب أيضا كلز (من وعا) أي: فهم وحفظ، يقال: وعاه يعيه حفظه وجمعه كأوعاه كذا في القاموس. وفي المصباح: وعيت الحديث وعيا من باب وعد حفظته وتدبرته. (أو خط) أي: كتب سواء كان واعيا ما يكتب أو لا. (هذا) مفعول تنازعه فعلان وعا وخط. (هذا الرجزا) بألف الإطلاق اللاحقة للروي المنصوب، والرجز بالتحريك: ضرب من الشعر وزنه مستفعلن ست مرات سمِّي به لتقارب أجزائه وقلة حروفه وزعم أنه ليس بشعر وإنما هو انصاف أبيات وأثلاث. والأرجوزة كالقصيدة منه والجمع أراجيز وقد رجز واتجز ورجز به ورجزه كذا في القاموس.\r(و) أن (يجزل) أي: يكثر لي ولمن وعا أو خط هذه الأرجوزة. (المواهب) جمع موهبة: وهي القطية من وهبت له شيئا وهبا ووهبا بالتحريك وهبة والاسم الموهب. والموهبة بكسر الهاء فيهما كذا ف الصحاح. (السنية) بالسكون، أي: العلية الرفعية، أو المنيرة المضيئة. (و) أن (يسعف) أي: يعين ويساعد. (الرجين) أي: الطالبين والراغبين (بالأمنيه) بالسكون أيضا: أي: المطلوب والمقصود، من تمنيت كذا قيل مأخوذ من المنا بالفتح وهوك القدر لان صاحبه يقدر حصوله والاسم المنية والأمنية، وجمع الاوى مني مثل غرفة وغرف، وجمع الثاني الأماني كذا في المصباح.\r(فالغيث من إنعامه) ستحانه وتعالى ومن بيانه. (قد وكفا) يقال: وكف البيت بالمطر والعين بالدمع وكفا من باب وعد و وكوفا ووكيفا: سال قليلا قليلا. ويجوز إسناد الفعل إلى الدمع وأوكف لغة كذا في المصباح. (على البرايا) أي: المخلوقات جمع بريّة فعلية بمعنى مفعولة من برا الله الخلق يبرؤها بفتحتين خلقها فهو الباري كما في المصباح.\r(وهو) أي: الله تعالى. (حسبي) أي: الكافي في جميع أحوالي. (وكفى) من الكفاية."], [23, "مقدمة صاحب المتن\r"]], "pg": [9, 23]}, "496.3": {"x": [[23, "من رام فنّا فليقدّم أولا ... علما بحدّه وموضوع تلا\r[الشرح]\rيقال: كفى الشيء يكفي كفاية فهو كاف: إذا حصل به الاسغناء عن غيره، كذا في المصباح.\r\rمقدمة\rأي: هذه مقدمة الكتاب أو العلم: وهي بكسر الدال المهملة من التقديم لأنها تقدم قارئها على فيرهن أو بالفتح اسم مفعول لتقدمها على بقية مسائل الكتاب.\r(من رام) أي: طلب. (فنًّا) أي: نوعا من العلوم. (فليقدم) بطريق اللزوم ليكون بصيرة فيما شرع فيه وذلك عشرة أمور: أشار على الأول بقوله: (أولا) طرف مؤكد للفعل قبله. (علما 9 مفعول يقدم. (بحده) متعلق بقوله علما والضمير للفن: أي يعلم حد ذلك الفن الذي يطلبه. والحد هو: التعريف بالأمور الذاتيات لأنه قول دال على ماهية الشيء. وحد هذا العلم الذي هو علم الكلام، ويسمى علم التوحيد والصفات أنه علم بالقواعد الشرعية الاعتقادية المكتسبة من أدلتها اليقينية. فخرج بالقواعد الشرعية القواعد العقلية التي هي مبني مذاهب الفرق الضالة. وبالاعتقادية العملية التي هي أصول الفقه. وبالمكتسبة من أدلتها تقليد المقلدين. وباليقينية الأدلة الظنية؛ لأنه لا عبرة بالظن في الاعتقاديات بل في العمليات. وقد أشار الناظم رحمه الله تعالى على تعريف هذا العمل برسمه في قوله: علم اعتقاد وعلم أصول الدين.\r(و) الثاني اشر إليه بقوله. (موضوع) بالعطف على قوله: بحده. وموضوع كل علم ما يبحث في ذلك العلم عنه وعن عوارضه الذاتية له. (تلا) أي: لما اتبع ما قبله، والجملة نعت لموضوع. والذي يبحث عنه في هذا العلم هو أصول الصانع العالم سبحانه وتعالى ليعتقد ثبوتها به وأحوال الجسم والعرض من الحدوث والافتقار والتركيب من الأجزاء وقبول الفنا، ليثبت بها للصانع سبحانه ما يذكر ممّا هو عقيدة إسلامية، أو وسيلة إليها وهذا موضوع علم الكلام، وقد أشار على موضوع هذا العلم بقوله: تنفع في التوحيد، وقوله: لكونها اعتقاد أهل السنة."], [24, "وواضع ونسبة وما استمد ... منه وفضله وحكم يعتمد\r[الشرح]\r(و) الثالث. (واضع) بالجر أيضا عطفا على قوله بحده: أي: واضع ذلك العلم. وهو أول إنسان تكلم في ذلك العلم. ووضعه الشيخ أبو الحسن الأشعري رحمه الله تعالى، واسمه علي بن إسماعيل بن إسحاق بن بشر بن سالم بن عبد الله بن موسى بن بلال بن أبي بردة بن أبي موسى الأشعري، صاحب رسول الله صلى الله عليه وسلم فبينه وبين جده الأعلى أبي موسى الأشعري ثمانية أجداد، واسم أبي موسى الأشعري عبد الله بن قيس.\rوإلى أبي الحسن الاشعري تنسب أئمة أهل السنة ويلقبون بالأشاعرة والأشعرية. هذا إن اعتبرناه واضع مذهب أهل السنة والجماعة. وغ، اعتبرناه واضع علم الكلام من حيث هو فقد ذكر في كتاب مصباح العلوم، قال: والمشهور أن أول ما تلكم في هذا العلم في الملة الإسلامية عمرو بن عبيد، وواصل بن عطاء من رجال المعتزلة لما وقعت لهم الشنيعة في كلام الله تعالى فأخذ منهم ألو الحسن الأشعري رحمه الله تعالى وخالفهم في كثير من المسائل.\rوأشار إلى الواضع بقوله: وكم به لعلماء الله فإنهم يدخل فيهم الشيخ أبو الحسن الأشعري وله كتاب (الأمانة) وغيره في هذا العلم. والرابع (نسبة) بالجر أيضا أي: نسبة ذلك العلم فيقال في المنتسب إلى علم الفقه: فقهي أو فقيه، وإلى علم النحو: نحوي، وإلى اللغة: لغوي، فلابد من معرفة اسم ذلك العلم لينتسب إليه الإنسان إذا علم أو في حال طلبه له.\rونسبة هذا العلم الذي هو علم الكلام أن يقال في صاحبه متكلم أو أشعري وكلامي. وأشار إلى النسبة بمفهوم قوله: فالفضل من معلومه له انتسب. وعلم أصل الدين مشهور الشرف، إلى آخره. فيقال في عالم هذا العلم متكلم ويقال أصولي. (و) الخامس (ما) أي: الأصل الذي (استمد) بالسكون ذلك العلم (منه) أي: استنبطت مسائله منه وأخذت عنه وتفرعت عليه. واستمداد هذا العلم من علم التفسير والحديث ومن الإجماع وحكم العقل والقرآن العظيم وحده كاف في الاستمداد عند أهل الهداية والرشاد. وأشار إلى استمداد بذكر أصل الدين فإنه مستند إلى أصول الدين الثلاث الكتاب والسنة والإجماع."], [25, "...........................................\r[الشرح]\rو) السادس (فضله) أي: فضيلته. قال الله تعالى: {قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ} [الزمر: 9]. قال تعالى: {يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ} [المجادلة: 11]. قال تعالى: {إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ} [فاطر: 28]. فشرط الخشية معرفة المخشي والعلم بصفاته وأفعاله، فمن كان أعلم به فهو أخشى له. وذكر العلامة شيخي زاده رحمه الله تعالى في حاشية البيضاوي قال: واعلم أن هذه الآية فيها تخويف شديد، وذلك لأنه ثبت أن الخشية من الله تعالى من لوازم العلم بالله فعند عدم الخشية يلزم عدم العلم بالله. وهذه الدقيقة تنبهك على أن العلم الذي هو سبب القرب من الله تعالى هو الذي يورث الخشية وأن أنواع المجادلات وإن دقت وعظمت إذا خلت من إفادة الخشية كانت من العلم المذموم.\rوفي حاشية البيضاوي للشيخ جمال الدين خليفة: {إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ} [فاطر: 28] أي: العلماء بالله دون غيرهم وهم الذين علموه تعالى بجلال ذاته وكمال صفاته وقوة أفعاله. انتهى\rوروى أبو داود، والترمذي، وابن ماجه، عن كثير بن قيسن قال: كنت جالسا مع أبي الدرداء رضي الله عنه في مسجد دمشق، فجاء رجل فقال: يا أبا الدرداء! إني جئتك من مدينة الرسول صلى الله عليه وسلم لحديث بلغني أنك تحدثه عن رسول الله صلى الله عليه وسلم، ما جئت لحاجة.\rقال: فإني سمعت رسول الله صلى الله عليه وسلم يقول: ((من سلك طريقا فيها علما سلك الله به طريقا من طرق الجنة، وإن الملائكة لتضع أجنحتها رضا لطالب العلم، وإن العالم ليستغفر له من في السموات ومن في الأرض والحيتان في جوف الماء، وإن فضل العالم على العابد كفضل القمر ليلة البدر على سائر الكواكب، وإن العلماء ورثة الأنبياء، وإن الأنبياء لم يورثوا دينارا ولا درهما وإنما ورثوا العلم فمن أخذه أخذ بحظّ وافر) (¬1)\rوذكر السيوطي في الجامع الصغير من الشيرازي في الألقاب، عن علي رضي الله عنه عن رسوله صلى الله عليه وسلم أنه قال: (ركعة من عالم بالله خير من ألف ركعة من جاهل الله) (¬2)\r¬__________\r(¬1) () رواه أبو داود (3/ 317) ن والترمذي (5/ 48، 50)، وابن ماجه (1/ 81)، وأحمد في المسند (5/ 196)، وأبو يعلى في مسنده (2/ 163)، والطبراني في لكبير (8/ 233)، وفي الشاميين (2/ 224).\r(¬2) () أورده المناوي في فيض القدير (4/ 36)."], [26, "واسم وما أفاد والمسائل ... فتلك عشر للمنى وسائل\r[الشرح]\rوأخرج برمز ابن أبي شيبة، والحكيم الترمذي، عن الحسن مرسلان وبرمز الخطيب البغدادي في التاريخ عن جابر رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال: (العلم علمان فعلم في القلب فذلك العلم النافع، وعلم اللسان فذلك حجة على ابن آدم) (¬1) وأشار إلى الفضيلة بقوله: وبالنجاة فاز من له انتمى وما بعده.\r(و) السابع (حكم) أثر ثابت لذلك العلم الذي يريد الشروع فيه. (يعتمد) بالسكون والبناء للمفعول، أي: يعتمد عليه المكلف ليخرج من عهدته. وحكم علم الاعتقاد أنه فرض عين على كل مكلف كما سيأتي، وأشار إلى ذلك بقوله: وحكم على البرايا انحتما كما مرّ.\r(و) الثامن (اسم) أي: اسم العلم والمراد لقبه لقتبه به علماؤه، ويسمى علم الأصول وعلم الكلام وعلم العقائد وعلم التوحيد والصفات. وأشار إلى ذلك بقوله: والأول الكلام، أي: علم الكلام، وعلم أصل الدين، وعلم العقائد السنية كما تقدم.\r(و) التاسع (ما) أي: الذي (أفاد) أي: أفاده هذا العمل يعني: فائدته هو غايته، وذلك أن يصير الإيمان والتصديق بالأحكام الشرعية متيقنا محكما لا تزلزله شبه المبطلين. ومنفعته في الدنيا انتظام أمر المعاش بالمحافظة على العدل والمعاملة التي يحتاج إليها في بقاء النوع الإنساني على وجه لا يؤول إلى الفساد. وفي الآخرة النجاة من العذاب المترتب على الكفر وسوء الاعتقاد، كذا ذكره اللقاني في شرح الجوهرة، وأشار إلى ذلك الناظم بقوله:\rوهو مفيد للورا ... علما بمن أنشأهم وصورا\r(و) العاشر (المسائل) أي: مسائل العلم. ومسائل العلم. ومسائل هذا العلم هي القضايا النظرية الشرعية الاعتقادية. فقيد النظرية لإخراج البديهية؛ لأنه لم يقع خلاف في أن البديهي لا يكون من المسائل والمطالب العلمية، بل لا معنى للمسألة إلا ما يسأل عنه يطلب بالدليل. وقيد الشرعية لإخراج الأدبية والرياضية والعقلية، وبالاعتقادية تخرج العلمية وقد ذكرها الناظم رحمه الله تعالى في جملة أبيات هذه المنظوم. (فتلك) أي: هذه الأمور\r¬__________\r(¬1) () رواه الدارمي (1/ 114)، والربيع في مسنده (1/ 365)، وابن أبي شيبة في المصنف (7/ 82)، وابن البارك في الزهر (ص 407)، والحكيم ي النوادر (2/ 303)، والديلمي في الفردوس (3/ 68)."], [27, "وبعضها فيها على البعض اقتصر ... ومن يكن بدري جميعها انتصر\r\rفصل في بيان الحكم وذكر أقسامه\r"]], "pg": [23, 27]}, "496.4": {"x": [[27, "الحكم وهو النفي والإثبات ... إلى ثلاث قسم الأثبات\rعقلي أو عادي أو شرعي ... وهاهنا أولها المرعي\r[الشرح]\rالمذكورة (عشر) من المقدمات التي يلزم معرفتها أولا قبل الشروع. (للمنى) أي: للمقصود. (وسائل) جمع وسيلة، وهي ما يتقرب به في الشيء. وسلت إلى الله تعالى بالعمل أسل من باب وعد رغبت وتقربت ومنه اشتقاق الوسيلة والجمع الوسائل كذا في المصباح.\r(وبعضهم) أي: بعض العلماء. (فيها) أي: في هذه المقدمات العشر (على البعض) منها (اقتصر) بالسكون للوزن لم يذكرها كلها. (ومن يكن يدري) أي: يعلم ويحفظ. (جميعها انتصر) بالسكون أيضا على غيره وتحقق مطلوبه وأدرك مرغوبه.\r\rفصل في الحكم وأقسامه\r(فصل) أي: هذا فصل من قولك: فصلته عن غيره من باب ضرب، نحيته أو قطعته سُمي به لامتيازه عما قبله وعما بعده من المسائل فتفصل. (في) بيان (الحكم) من حيث هو حكم. (و) في ذكر (أقسامه) الثلاثة. (الحكم) بالضم في الأصل معناه القضاء والجمع أحكام وقد حكم عليه بالأمر حكما وحكومة كذا في القاموس. (وهو) في اصطلاح العلماء (النفي) نحو: ما قدم زيد. (إلى ثلاث) من الأقسام (قسم الأثبات) بالفتح جمع ثبت. قال في الصحاح: رجل ثبت، أي: ثابت القلب. وفي المصباح: رجل ثبت ساكن الباء ومتثبت في أموره وثبت الجنان، أي: ثابت القلب وثبت في الحرب فهو ثبيت مثال قرب فهو قريب والاسم ثبت بفتحتين ومنه قيل للحجة: ثبت ورجل ثبت بفتحتين أيضا إذا كان عدلا ضابطا والجمع أثبات، مثل: سبب وأسباب. انتهى. يعني: قسم المشايخ الأثبات العلماء الضابطون الحكم إلى ثلاثة أقسام لأن الحاكم فيه إما أن يكون الشرع أو العقل أو العادة؛ فإن كان الحاكم فيه العقل فالحكم (عقلي أو) الحكم (عادي) إن كان الحكم فيه الشرع والواو هنا للتقسيم لا للترديد، وبيان هذه الأقسام الثلاثة بتعاريفها وتقاسيمها استوفيناه في كتابنا: (المطالب الوفية). (وهاهنا) أي: في هذا المحل, (أولها) وهو الحكم العقلي (المرعى) أي: المطلوب الملاحظ، تقول: راعيته لاحظته محسنا إليه، وراعيت الأمر."], [28, "واعلم هُديت أن حكم العقل لا ... يعدو ثلاثا حصرها قد علا\rإيجاب أو تجويز أو إحاله ... فواجب لا ينتفي بحاله\rأي كل أمر نفيه لا يدرك ... عقلا وسر بدائه لا يترك\r[الشرح]\rنظرت إلى ما يصير، وراعى أمره حفظه كرعاه كذا في القاموس، وهذا سبب تقديم الحكم العقلي هنا في النظم لأنه مقصور في بيان النظر لاستخراج الأدلة العقلية في تحصيل المعرفة الإلهية والتخليص من قيود التقليد في معرفة التوحيد، فقالك فصل في بيان أقسام الحكم العقلي المذكور، ولم يتعرض للحكم العادي إذ أحكام العادة تُعرف بالتجربة وغيرها مما هو معلوم في كتب علم الطب من أن الشيء الفلاني يفعل كذا ويفعل كذا والمركب الفلاني ينفع من كذا ويضر كذا بحكم العادة الجارية في أمزجة المخلوقات والخالق لذلك كله هو الله تعالى عند هذه الأشياء لا بها ولا فيها كما سيأتي بيانه إن شاء الله تعالى. ولم يتعرض للحكم الشرعي أيضا لأن علم الفقه وعلم أصوله وعلم الحديث وعلم التفسير متكفل ببيان ذلك على أتم الوجود وأكمله، ولم يبق إلا الحكم العقلي فشرع في بيانه في هذه المنظومة حيث قال: (واعلم هديت) أي: هداك الله تعالى إلى معرفته وأنواع عبادته. (أ، حكم العقل لا يعدو) أي: لا يُجاوز ثلاثا من الأقسام فلا يزيد عليها ولا ينقص عنها. (حصرها) أي: هذه الثلاثة في الحكم العقلي ويلزم منه حصر الحكم العقلي فيها. (قد عللا) بألف الإطلاق أي: صار معللا، وبيان ذلك أن كل ما يحكم فيه العقل بإثبات أو نفي إما أن يحكم فيه بوجود فقظ أو عدم فقط أو بوجود تارة أو عدم أخرى، وليس هناك قسم رابع أصلا.\r\rفالأول: الواجب. والثاني: المستحيل. والثالث: الجائز. وبينما الممكن (إيجاب) وهو أو الثلاثة قدمه لشرفه واصالته. (أو تجويز) وهو ثاني الثلاثة قدمه على ما بعده لشرفه بالنسبة إليه. (أو إحاله) بالسكون، أي: استحالة وهي ثالث الأقسام. ثم شرع في ليان هذه الثلاثة على هذه الترتيب وجاء بفاء التعقيب حيث قال: (فواجب) أي: الموصوف بالإيجاب هو حكم عقلي. (لا ينتفي) عن تصور العقل. (بحاله) بالسكون. أي: أصلا فلا يتصور في العقل عدمه، ثم زاده بيانا فقال: (أي كل أمر نفيه) وإنكاره (يدرك) بالبناء للمفعول. (عقلا) أي: من جهة العقل. (وسر) أي: سبب (بدائه) أي: الابتداء به وتقديمه على القسمين الآخرين. (لا يترك) أي: لا يعرض عنه أحد ثم علل ذلك بقوله:"], [29, "لكونه يوصف ذو المحال ... به وعكسه اجع بالمحال\rوحائز ما صح بالعقل اكتفا ... فيه لدى حكمي ثبوت وانتفا\rوما دعوا منه ضروريا جلي ... والنظري بعد فكر ينجلي\r[الشرح]\r(لكونه) أيك الواجب أو الإيجاب. (يوصف ذو) أي: صاحب. (المحال) بكسر الميم يقال: تمحلت مالا لغريمي، قيل: هو مثل تحيلت من الحيلة، وقيل: هو بمعنى سعيت وتصرفت من قولهم: محلني فلان، أي: قواني، ومن قوله تعالى: {شَدِيدُ الْمِحَالِ} [الرعد: 13]. أي: القوة، وقيل: شديد المكر والكيد كذا في المصباح. اهـ\rوفي القاموس: المحال ككتاب الكيد وروم الأمر بالحيل والتدبير والمكر والقدرة والجدال والعذاب والعقاب والعداوة والمعادة كالمماحلة والقوة والشدة والهلاك والإهلاك. (به) متعلق بيوصف وذو المحال هو الله تعالى فإنه يوصف بأنه واجب الوجود والإهلاك. (به) متعلق بيوصف وذو المحال هو الله تعالى فإنه يوصف بأنه واجب الوجود فلأجل هذا بدأ به دون القسمين الآخرين. (وعكسه) وهو كل حكم عقلي لا يوجد بحال أصلا، أي: كل أمر وجوده لا يدرك عقلا, (ادع) من دعاه يقال: دعوته زيدا ويزيد سميته به كذا في القاموس. (بالمحال) بضم الميم: أي: سمه محالا.\r(وجائز) (ما) أي: حككم عقلي. (صح بالعقل اكتفاء فيه) أي: اكتفى العقل فيه. (لدى) وهو ظرف زمان ومكان كعند كذا في القاموس. (حكمي) أصله حكمين تثنية حكم حذفت منه النون لإضافته إلى (ثبوت وانتفا) يعني: يصح في العقل ثبوته وحكم انتفائه معا على السواء.\r(وما دعوا) أي: سموا يعني علماء هذا الشأن. (منه) أي: من هذه الأقسام الثلاثة. (ضروريا) أي: سموه حكما ضروريا يعني مدركا بالضرورة من غير احتياج إلى فكر ولا نظر. (جلي) بفتح الجيم وكسر اللام، أي: فهو واضح لا يحتاج إلى البيان كالحكم على الاثنين بالزوجية فإنه حكم على الزوجية مثلا بالاثنين حكم عقلي جائز، إذ يصح في القعل أن هذا الحكم في هذه الثلاثة: بالوجوب والاستحالة، والجواز ضروري بديهي لا يتوقف على ذكر ولا تركيب مقدمات للنظر. (و) ما دعوه الحكم (النظري) أي: الذي لا يدرك إلا بعد سبق نظر فهو الحكم الذي (بعد) استعمال (فكر) بترتيب مقدمات."], [30, "فلتعرف الواجب والمحالا ... وجائزا في حقه تعالى\rفعلمها فرض علينا شرعا ... ومثلها في حق رسل ترعى\r[الشرح]\r(ينجلي) أي: ينكشف ويتضح كالحكم بثبوت الوحدانية لواجب بالذات فإنه يحتاج إلى نظر عقلي بأن لو تعدد واجب الوجود بالذات لما وجد ممكن أصلا وهذه مقدمة أولى، وبيانها أن الممكن لا يوجد إلا بالواجب، فلو تعدد الواجب لوجد الممكن وجدين أو أكثر وهو محال أو وجود واحدا فيكون بواجب واحد وبقية الواجبات لا تأثير فتنقلب ممكنات لمنع الواجب لها عن التأثير.\rويقال في المقدمة الثانية: والممكنات موجودات في الحس والعقل وهي لا تحتج إلى البيان فالنتيجة أن واجب الوجود بالذات واحد فهذا حكم نظري لا يدرك إلا بعد استعمال الفكر والنظر العقلي وهكذا جميع المسائل الاعتقادية النظرية على هذا المنوال.\r(فالتعرف) أيها المكلف وهو أمر بلام الأمر الجازمة. (الواجب) من الصفات (ومحالا) بألف الإطلاق، أي: المستحيلات من الأوصاف (وجائزا) أي: وصفا يجوز أن يتصف به، وأن لا يتصف. (في حقه) أي: الله (تعالى) وتقدس وهو معرفة ما يجب في حق الله تعالى. (فرض) عين (علينا) معشر المكلفين (شرعا) أي: من جهة الشرع لا عقلا.\rقال في كتاب الانتقاد شرح عمدة الاعتقاد: \"الايمان بالله تعالى فرض باتفاق أهل الملة والكفر به حرام، لكنهم اختلفوا في وجوبه بالعقل أصلا ولا يعرف حسن الإيمان وقبح الكفر أصلا بالعقل بل وجوب الإيمان وعرفان حسنه وقبح الكفر لا يحصل إلا بالشرع أي: بالسماع من الشارع.\rوقالت المعتزلة: العقل يوجب الإيمان وشكر المنعم ويعرف حسنهما أيضا، وبه عند أصحابنا أئمة أهل السنة والجماعة العقل آلة يعرف بها حسن بعض الأشياء لا كلها وقبح بعض الأشياء. والفرق بيننا وبين المعتزلة أنهم يقولون العقل موجب بذاته مستقل في إيجابه كما يقولون إن العبد موجد لأفعاله، وعندنا العقل آلة للمعرفة والموجب هو الله تعالى في الحقيقة لكن بواسطة العقل يعني لا يوجب الله تعالى شيئا من الفرائض"], [31, "فصل في النظر وأنه أول واجب\r"]], "pg": [27, 31]}, "496.5": {"x": [[31, "أول واجب على المكلف ... إعماله للنظر المؤلف\r[الشرح]\rوالواجبات بدون العقل بل بشرط أن يكون العقل موجدا كما أن الرسول معرف الوجوب لا موجب، فالمواجب هو الله تعالى حقيقة، ولكن بواسطة الرسول فكأن العقل بمنزلة الرسول في أنهما آلتان للوجوب عندنا، ثم بسط الكلام في هذا المقام، ثم ذكر أن مذهب الأشعري رحمه الله تعالى أنه لا يجب الإيمان ولا يجب شيء غيره بالعقل ولا يحرم شيء أيضا بالعقل ولكن يجوز أن يعرف حسن بعض الأشياء وقبحها به فعند جميع الأحكام المتعلقة بالتكليف متعلقات من جهة السمع إلى مذكور هناك.\rوالحاصل أن الشرع هو الموجب عند الكل وإنما الخلاف في إسناد الإيجاب، فبعضهم أسند الإيجاب إلى الشرع على الأصل وبعضهم أسنده إلى الواسطة والشرط وهو العقل كإسناده إلى الرسول. (ومثلها) مبتدأ وخبره قوله بعد ذلك تراعي يعني: ما يجب وما يستحيل وما يجوز أيضا. (في حق الرسل) بيكون السين جمع رسول يعني: رسل الله تعالى. (ترعى) بضم المثناة الفوقية مبني للمفعول، أي: تحفظ. قال في القاموس: رعا أمره حفظه كرعاه انتهى. أي: كما يقال: راعي يقال: رعا أيضا.\r\r(فصل في بيان النظر) العقلي\rوهو ترتيب المقدمات لإنتاج اليقين. (و) بيانه (أنه) أي: النظر المذكور (أول واجب) أي: فرض عين على المكلف كما قالوا وبيان ذلك أن (أول واجب) إنما هو معرفة الله تعالى، ولكن لما كانت معرفة الله تعالى لا تحصل للعقل من طريق التكليف إلا بالنظر الصحيح العقلي كان النظر العقلي أول واجب على المكلف لأجل تحصيل المعرفة، والمراد بالمعرفة هنا معرفة العماء كما ذكر المناوي رحمه الله تعالى في شرحه الكبير على الجامع الصغير. وعبارته:\r\"فمعرفة الله تعالى والعلم به أول واجب مقصود لذاته على المكلف، لكن ليس المراد المعرفة الحقيقة لأن حقيقته تعالى غير معلومة للبشر ولا للعيانية لأنها مختصة بالآخرة عند من نفى الرؤية في الدنيا مطلقا، أو لغير نبينا صلى الله عليه وسلم وهم الجلة الأكابر أولو الرتب العلية وقليل ما هم، ولا الكشفية فإنها منحة إلهية ولا تكليف بمثلها إجماعا. بل البرهانية وهو أن يعلم بالدليل القطعي وجوده تعالى وما يجب تعالى وما يجب له وما يستحيل عليه\" انتهى كلامه."], [32, "....................................\r[الشرح]\rفعلمنا من هذا أن المعرفة بالله تعالى على أربعة أنواع: المعرفة الحقيقية: وهي معرفة الله تعالى لنفسه. والمعرفة العيانية: وهي معرفة أهل الجنة في الجنة. والمعرفة الكشفية: وهي معرفة الأولياء لربهم. والمعرفة البرهانية: وهي العلماء لربهم. وهذه المعرفة الأخيرة هي المرادة هنا.\r\r(على المكلف) أي: البالغ العاقل عند أهل السنة، والصبي العاقل لا يجب عليه شيء قبل البلوغ وعليه أكثر المشايخ، فيكون الصبي العاقل معذورا عندنا إذا مات بدون التصديق، وعند المعتزلة لا عذر لمن عقل صغيرا كان أو كبيرا. وفي رواية عن الشيخ أبي منصور الماتريدي من أئمة أهل السنة في الصبي العاقل، أنه يجب عليه معرفة الله تعالى.\rوعلى هذا لا فرق بيننا وبين المعتزلة من حيث الأحكام، بل من حيث إن العقل مستقل في الإيجاب عندهم وعندنا لا يستقل. ولذلك نقول فيمن لم تبلغه الدعوة إنه غير مكلف بمجرد العقل، وإذا لم يعتقد إيمانا ولا كفرا كان معذورا، وإذا أعانه الله تعالى بالتجربة وأمهله لدرك العواقب لم يكن معذورا وإن لم تبلغه الدعوة فإن عندنا وجوب الإيمان بإيجاب الله تعالى لكن بشرط العقل، والعقل المطلق ليس بكاف في الوجوب بل بشرط البلوغ، وتمامه في كتاب الانتقاد شرح عمدة الاعتقاد.\r(إعماله) أي: استعماله في معرفة ربه. (للنظر) العقلي وهو ترتب المقدمات العقلية المسلمة. (المؤلف) من مقدمتين كبرى وصغرى. فالمشتملة على المحكوم به كبرى، والمشتملة على المحكوم عليه صغرى. والمكرر بين مقدمتي القياس يسمى الحد الأوسط وهو المحمول في الصغرى الموضوع في الكبرى، كقولك: العالم متغير وكل متغير حادث.\rفالمعتبر هو الحد الأوسط وهو الساقط في النتيجة فتقول: العالم حادث، وهذا يسمى القياس الاقتراني. وأما القياس الاستثنائي: فلا بد فيه من المقدمة الكلية أو الشرطية. ثم تعقبها بمقدمة أخرى استثنائية، كقولك: إن كانت الشمس طالعة فالنهار موجود لكن الشمس طالعة فإنه ينتج أن النهار موجود مثلا، وكقولك: كل إنسان حيوان ولا شيء من الحيوان بحجر، فإنه ينتج أن النهار موجود مثلا، وكقولك: كل إنسان حيوان ولا شيء من الحيوان بحجر، فإنه ينتج لا شيء من الإنسان بحجر مثلا.\rوهكذا يكون ترتيب النظري العقلي في النفس، وهذه المباحث مستوفاة في كتب علم المنطق."], [33, "كي يستفيد من هدى الدليل ... معرفة المصور الجليل\rوتطمئن نفسه لما سلم ... من ورطة الجهل وللحق علم\rفإن يكن قبل البلوغ حصلا ... ذاك وللمطلوب قد توصلا\rفليشتغل بعد البلوغ بالأهم ... ثم الأهم فاتحا لما انبهم\rوفي المقلد خلاف مستطر ... لأنه إيمانه على خطر\r[الشرح]\r(كي يستفيد) المكلف (من هدى) بضم الهاء وفتح الدال المهملة (الدليل*معرفة) مفعول ليستفيد (المصور) بصيغة اسم الفاعل وهو الله تعالى. (الجليل) أي: العظيم.\r(وتطمئن) أي: تسكن بالعلم. (نفسه) المتحركة بالجهل (لما سلم) بالسكون. (من ورطة) أي: هلاك، وأصل الورطة الوحل يقع فيه الغنم فلا تقدر على التخلص. وقيل: أصلها أرض مطمئنة لا طريق فيها يرشد إلى الخلاص ثم استعملت في كل شدة وأمر شاق، كذا في المصباح (الجهل) بالله تعالى. (وللحق) أي: ضد الباطل، أو الله تعالى (علم) بالسكون أيضا، فإن العادة جارية باطمئنان النفوس عند ثبوت الأمر المطلوب.\r(فإن يكن) المكلف (قبل البلوغ) حين كان صغيرا (حصلا) بالتشديد وألف الإطلاق (ذاك) أي: النظر العقلي وإدراك نتيجته. (وللمطلوب) من معرفة ربه (قد توصلا) بالتشديد وألف الإطلاق.\r(فليشتغل) ذلك المكلف (بعد البلوغ بالأهم) بالسكون للوزن من عباد الله تعالى. (ثم الأهم) من ذلك (فاتحا) حال من فاعل يشتغل أي: متحققا وكاشفا. (لما أنبهم) بالسكون أيضا عليه من دقائق المعرفة الإليهة بأنواع العبادات والطاعات الشرعية.\r(و) قد ورد عن العلماء (في) حق (المقلد) بصيغة اسم الفاعل. وهو الذي يقلد غيره في إيمانه بالله تعالى وبأنبائه بالله تعالى وبأنبيائه ورسله عليهم السلام من غير معرفة ولا نظر ولا استدلال. (خلاف مستطر) بالسكون للوزن، أي: مذكور في كتب أئمة هذا الشأن.\rونقل بعضهم عن الشيخ الأشعري، والقاضي الباقلاني، والأستاذ الإسفرايني، وإمام الحرمين، والجمهور وعدم صحة إيمان المقلد، وأنه لا يكفي التقليد في العقائد الدينية، وبالغ بعضهم فيه فحكى عليه الإجماع، وعزاه ابن القصار لمالك بن أنس رضي الله عنه، ونقل وبالغ بعضهم فيه فحكى عليه الإجماع، وعزاه ابن القصار لمالك بن أنس رضي الله عنه، ونقل بعضهم عن الجمهور وعمن سبق ذكرهم عدم جواز التقليد في العقائد، وأنهم اختلفوا في المقلد. فمنهم من قال: هو مؤمن إلا إنه عاص بترك المعرفة التي ينتجها النظر الصحيح."], [34, "..................................................................\r[الشرح]\rومنهم من فضل فقال: هو مؤمن عاص إن كان فيه أهلية لفهم النظر الصحيح، غير عاص عن فقدت منه أهلية ذلك.\rوبعضهم نقل أن من قلد القرآن والسنة القطعية صح إيمانه اتباعه القطعي، ومن قلد غير ذلك لم يصح إيمانه لعدم أمن الخطأ على غير المعصوم.\rوبعضهم نقل أن من قلد القرآن والسنة القطعية صح إيمانه اتباعه القطعي، ومن قلد غير ذلك لم يصح إيمانه لعدم أم الخطأ على غير المعصوم.\rوقال بعضهم: لا فرق بين بهيمة تنقاد في الاعتقاد، حتى نقل عن بعضهم أنه قال: إن الذي يجده المقلد في نفسه إنما هو مجرد تحسين ظن بمخبره الإيمان، ونقل بعضهم أن النظر ليس شرطا في صحة الإيمان بل وليس بواجب أصلا وإنما هو شرط كما فقط، واختار هذا القول القشيري وابن ابي حمزة وهو قول الغزالي وابن رشد وجماعة من القدماء والمتأخرين، وذكر والدي المرحوم في شرحه على شرح الدار في فقه الحنفية، قال في باب المرقد (من كتاب الجهاد): والإيمان التصديق بجميع ما جاء به النبي صلى الله عليه وسلم من الله تعالى مما علم مجيئه به ضرورة وهل هو فقط أو مع الإقرار؟ قولان: وأكثر الحنيفة على الثاني، والمحققون على الأول.\rوالإقرار شرط إجراء أحكام الدنيا، فمن صدق الرسول فيما جاء به فهو مؤمن فيما بينه وبين الله تعالى، والإقرار شرط إجراء الأحكام، وهذا بعينه القول المختار عند الأشاعرة والمراد أحكام الدنيا من الصلاة خلفه ودفنه في مقابر المسلمين وغير ذلك.\rواعلم أن الاستدلال ليس شرطا لصحة الإيمان على المذهب المختار حتى صححوا إيمان المقلد وقل أن يرى مقلد في الإيمان بالله تعالى وعلى صفاته، والتقليد مثلا أن يسمعهم يقولون إن للخلق ربا خلقهم وخلق كل شيء ويستحق العبادة عليهم وحده لا شريط له فيجزم بذلك بجزمه بصحة إدراك هؤلاء تحسينا لظنه بهم وتكبيرا بشأنهم عن الخطأ فإذا حصل ما هو المقصود منه ثم قيامه بالواجب من الإيمان إذا لم يبق سوى الاستدلال ومقصوده من حصول ذلك الجزم فإذا حصل ما هو المقصود منه ثم قيامه بالواجب، من الإيمان إذا لم يبق سوى الاستدلال؛ لأن وجوبه إنما كان ليحصل فإذا حصل سقط هو لأن الصحابة رضي الله عنه كانوا يقلبون إيمان عوام الأمصار التي فتحوها من العجم تحت السيف. انتهى ما ذكره الوالد رحمه الله تعالى"], [35, "........................................................................\r[الشرح]\rفقد وقع إجماع الصحابة رضي الله تعالى عنهم على قبول إيمان المقلد، وقال الله تعالى: {قُولُوا آمَنَّا بِاللَّهِ} [البقرة: 136]. إلى آخر الآية فهو الإقرار باللسان.\rثم قال تعالى: {فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنْتُمْ بِهِ فَقَدِ اهْتَدَوْا} [البقرة: 137]. يعني: صدقوا بمثل ما صدقتم به وهذا هو التصديق بالقلب، ولم يذكر العمل بالأركان وقد أخبر تعالى أن من قال ذلك وهو مؤمن به فقد اهتدى ولم يشترط سبحانه إقامة دليل على ذلك ولا نص برهان، وهذا نص كتاب الله تعالى.\rوروى البخاري، ومسلم في صحيحيهما، عن عبد الله بن عمر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: (أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأن محمد رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم غلا بحق الإسلام وحسابهم على الله).\rفليس في هذا الحديث الصحيح اشتراط دليل ولا برهان في أمر الإيمان.\rوذكر العيني في شرح البخاري قال: \"والإيمان عند المحققين وإليه ذهب الأشعري وأكبر الأئمة كالقاضي عبد الجبار والأستاذ أبو إسحاق الإسفرايني، والحسين بن الفضل، وغيرهم هو مجرد التصديق بالقلب، أي: تصديق الرسول صلى الله عليه وسلم في كل ما علم مجيئه به بالضرورة تصديقا جازما مطلقا، أي: سواء كان بدليل أو لا، فقولهم: مجرد التصديق إشارة إلى أنه لا يعتبر فيه كونه مقرونا بعمل الجوارح والتقليد بالضرورة لإخراج ما لا يعلم بالضرورة إذ الرسول جاء به كالاجتهاديات كالتصديق بأن الله تعالى عالم بالعلم أو عالم بذاته، والتصديق بكونه تعالى مرئيا أو غير مرئي فإن هذين التصديقين وأمثالهما غير داخلة في مسمى الإيمان، ولهذا لا يكفر منكر الاجتهاديات بالإجماع، والتقييد بالجازم لإخراج التصديق الظني فإنه غير كاف في حصول الإيمان، والتقييد بالإطلاق لدفع وهم خروج الاعتقاد من القلب، فإن إيمانه صحيح عند الأكثرين وهو الصحيح، وذكر الإمام القرطبي في شرح صحيح مسلم قال:\r\"مذهب السلف وأئمة الفتوى من الخلف أن من صدق بهذه الأمور، يعني: الواقعة في حديث جبريل عليه السلام لمّا جاء إلى النبي صلى الله عليه وسلم في صورة رجل سأله عن الإيمان والإحسان وأجابه النبي صلى الله عليه وسلم بما أجابه به تصديقا جزما لا ريب فيه ولا تردد ولا توقف كان مؤمنا حقيقة سواء كان ذك عن براهين قاطعة أو عن اعتقادات جازمة، وعلى هذا انقرضت الأعصار الكريمة، وبه صرحت فتاوى أئمة الهدى المستقيمة حتى حدثت"], [36, "وهو معرض لشك يطرق ... وفيه للأشياخ تنمى طرق\r[الشرح]\rمذاهب المعتزلة المبتدعة، فقالوا: إنه لا يصح الإيمان الشرعي إلا بعد الإحاطة بالبراهين العقلية والسمعية، وحصول العلم بنتائجها ومطالبها ومن لم يحصل إيمانه كذلك فليس بمؤمن ولا يجزي إيمانه بغير ذلك، وتبعهم على ذلك جماعة من متكلمي أصحابنا كالقاضي أبي بكر وأبي إسحاق الإسفرايني وأبي المعالي في أحد قوليه، والأول هو الصحيح. إذ المطلوب من المكلفين ما يقال عليه إيمان لقوله تعالى: {آمِنُوا بِاللَّهِ وَرَسُولِهِ} [النساء: 136].\rوالإيمان هو التصديق لغة وشرعا، فمن صدق بذلك كله ولم يجوز نقيض شيء من ذلك فقد عمل بمقتضى ما أمر الله به على نحو ما أمره الله به، ومن كان كذلك فقد قضى عهدة الخطاب إذ قد عمل بمقتضى السنة والكتاب ولأن رسول الله صلى الله عليه وسلم كان أصحابه تعده حكموا بصحة غيمان كل من آمن وصدق بما ذكرناه ولم يفرقوا بين من آمن عن برهان أو عن غيره؛ ولأنهم لم يأمروا أجلاف العرب بترديد النظر ولا سألوهم عن أدلة تصديقهم ولا أرجئوا إيمانهم حتى ينظروا ويتحاشوا عن إطلاق الكفر على أحد منهم بل سموهم المؤمنين والمسلمين وأخذوا عليهم أحكام الإيمان والإسلام؛ ولأن البراهين التي حررها المتكلمون ورتبها الجدليون إنما أحدثها المتأخرون، ولم يخض في شيء من تلك الأساليب السلف الماضون، فمن المحال والهذيان أن يشترط في صحة الإيمان مالم يكن معروفا ولا معمولا به لأهل ذلك الزمان وهم أكثر منهم فهما عن الله وأخذا عن رسول الله وتبليغا لشريعته وبيانا لسنته وطريقه انتهى. وتمامه في كتابنا (فتح المقند المبدي). فلنرجع إلى شرح ما نحن بصدده في هذا المقام من أبيات هذا النظام جريا على قاعدة علماء الكلام، بعد تحقيق المقصود والمرام.\r(لأنه) أي: المقلد. (إيمانه على خطر) بالسكون: وهو الإشراف على الهلاك وخوف التلف. كذا في المصباح، والخظر في ذلك قبول التشكيك من شكك عليه في أمر من أمور الدين وعروض فتنة له في ماله أو بدنه أو اهله فتحمله على جحود اطلاع الله تعالى عليه أو نسبته تعالى إلى الظلم أو أمور أخرى تعتري أهل الجهل والغفلة ولهذا قال بعده: (وهو) أي: المقلد, (معرض) بصيغة اسم المفعول، يقال: تعرض للمعروف وتعرض يتعدى بنفسه وبالحرف، إذا تصدى له وطلبه كذا في المصباح. أي: متصدي له ومطلوب. (لشك) في دينه واعتقاده الذي قلد فيه غيره. (بطرق) ذلك الشك له، من الطرق، وهو: الإتيان ليلا في القاموس."], [37, "وذو احتياط في أمور الدّين ... من فرّ من شك يقين\rومن له عقل أبى عن شرب ما ... لم يصف مذ الفى زلالا شبم\rفبان أن النظر الموَصِّلات ... أول واجب كما قد أَّصّلا\r[الشرح]\rوقال في المصباح: وكل ما أتى ليلا فقد طرق وهو طارق. انتهى. ولمّا كان الشك يدخل عليه وهو في ليل الجهل استعمل فيه الطرق. (وفيه) أي: في المقلد (للأشياخ) جميع شيخ، وعم علماء هذا الشأن، (تنمي) بالبناء للمفعول، أي: تنسب، يقال: انتمى إليه انتسب. (طرق) بضمتين جمع طريق، أي: قول يسلك عليه حتى إن بعضهم قلل وجود المقلد في إيمانه وبعضهم كثر وجوده وبعضهم أنكر وجوده كما نقل عن القاضي الباقلاني أن التقليد في أصول الدين ممتنع حيث قال: المعرقة بالله تعالى على وجه الإحاطة لا سبيل إليها، فالمعتبر إذا الإقرار بالله عز وجل وبرسله من مسند جملي، واختار أن التقليد غير متصور في الوحيد، وسبق ذكرنا للخلاف في المقلد وبيان الصحيح من ذلك وقد بسطناه في كتابنا (المطالب الوفية).\r(وذو) أي: صاحب. (احتياط) من احتاط للشيء افتعال، وهو: طلب الأحوط والأخذ بأوثق الوجوه، وبعضهم يجعل الاحتياط من الياء والاسم المحيط كذا في المصباح. والمحتاط: هو الذي يجمع أصول الأحكام، ويبعد شوائب التأويلات. (في أمور الدين) أي: أحكامه في شرائعه. (من) أي: الذي او رجل (فر من شك) عرض له او يمكن أن يعرض له بسرعة لفراغ قلبه من قواعد الدين وأصوله. (إلى يقين) محقق.\r(ومن له عقل) أي: بصيرة صحيحة وأدركه حين التوفيق، فكان له نعم الرفيق. (أبى) أي: امتنع. (عن شرب ما) أي: مشروب أو ماء بالمد وهو مقصور في النظم منعوت بأنه 0 لم يصف) من صفا يصفو: إذا راق من القدر (مذ) بالضم فالسكون، أي: حين (ألفى) بالفاء، أي: وجد. (زلالا) قال في القاموس: ماء زلال كغراب وأمين وصبور وعلابط، سريع المر في الحلق بارد ع 1 ب صافي سهل سلس. (شبما) بكسر الباء المؤخرة والف الإطلاق. قال في المصباح: الشبم بفتحتين: البرد ويوم 1 و شبم أي: بردن والشبم بالكسر: البارد.\r(فبان) أي: ظهر واتضح مما ذكر. (أن النظر) العقلي. (الموصلا) بتشديد الصاد المهملة المكسورة وألف الإطلاق. (أول واجب) على المكلف، وربما يقال إن المراد به هنا الوجوب الصناعي العرفي دون الوجوب الشرعي لما قدمنا؛ ولأن تركه مخل بالكمال دون لحوق الإثم كما قال ابن الجزري في منظومته في علم التجويد:"], [38, "وقد عزوا ذا الإمام الأشعري ... وهو عن الإشكال والضعف عري\rوقيل بل قصد إليه أول ... فرض وفرقة عليه عوّلوا\rوقيل بل معرفة الخلاق ... أول واجب على الإطلاق\rوغير واحد نماه أيضا ... للأشعري المستمدّ فيضا\rوليس ذا مخالفا ما قبله ... إذ هي قصد وسواها وصله\r[الشرح]\rإذ واجب عليهم محتم ... قبل الشروع أولا أن يعلموا\rفقال بعض شراحه: هذا الوجوب صناعي ونحو هذا في كلام المصنفين. (كما قد أصلا) بضم الهمزة وكسر الصاد المهملة مشددة وألف الإطلاق. قالك في المصباح: يقال: أصلته تأصيلا جعلت له أصلا ثابتا يبني عليه غيره، انتهى. ومراده ما ذكر في النظم من الترغيبات في استعمال النظر والتباعد عن التقلد في الاعتقاد.\r(وقد عزوا) أي: نسبوا، يعني: أئمة هذا الشأن. (ذا) أي: هذا القول بأن أول واجب هو النظر العقلي في الاعتقاد (للإمام) أبي الحسن (الأشعري) نسبة إلى اشعر، وهيك قليلة من اليمن, (وهو) أي: هذا القول. (عن الإشكال) بكسر الهمزة: أي الاشتباه. (والضعف) ضد القوة. (عري) أي: خالي من ذلك. (وقيل بل قصد اليه) أي: قصد الإنسان إلى النظر (أول * فرض) على المكلف، وذلك لتوقف النظر على قصده، بمعنى: تفريغ القلب عن الشواغل، وعزى هذا القول للقاضي الباقلاني رحمه الله تعالى والإمام الحرمين. (وفرقة) من العلماء. (عليه) أي: على هذا القول (عولوا) أي: اعتمدوا.\r(وقيل بل معرفة الخلاق) سبحانه وتعالى (وأول واجب على الإطلاق) أي: أول الواجبات كلها ليس قبله واجب أصلا. (وغير واحد) من العلماء (نماه) أيك نسب هذا القول (أيضا) كما نسب إليه أن النظر هو أول واجب فيما مر (للأشعري) أبي الحسن رحمه الله (المستمد) نعت للأشعري، أي: الطالب من الله (فيضا) أي: مدادا متصلا. (وليس ذا) أي: هذا القول بأن المعرفة أول الواجبات (مخالفا ما قبله) بالسكون، أي: القول الأول بأن النظري هو أو الواجبات (إذ هي) أي: لأن المعرفة (قصد) أي: مقصوده. (وسواها) من النظر الموصل إليها (وصل) أي: وسيلة إليها، فمن أطلق على المعرفة بأنها أول واجبات أراد من حيث إنها الأمر المقصود بالذات، ومن أطلق على النظر بأنه أول الواجبات أراد من حيث إنه وسيلة إلى نيل المعرفة، فليس هما قولان في الحقيقة."], [39, "فصل في الحث على النظر العقلي في العقائد\r"]], "pg": [31, 39]}, "496.6": {"x": [[39, "وجاء في القرآن والأخبار ... حث على الفكر والاعتبار\rوهو على وجوبه قد دلا ... مع كونه بالقصد ما استقلا\rفاقرأ \"وفي أنفسكم مع \"افلا\" ... تظفر برشد نوره ما أفلا\r[الشرح]\r(فصل في الحث)\rقال في الصحاح: حثه على الشيء واستحثه بمعنى: حضه عليه. انتهى\rيعني: والإلزام (على) استعمال (لنظر) العقلي في العقائد.\r(وجاء في القرآن) العظيم (والأخبار) أي: الأحاديث النبوية (حث على الفكر) في مصنوعات الله تعالى (و) على (الاعتبار) فيها، أي: العبرة من إشارات ظواهرها إلى أسوار بواطنها.\rقال تعالى: {وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ} [آل عمران: 191]. وقال تعالى: {إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ} [الرعد: 3].\rوقال تعالى: {فَاعْتَبِرُوا يَاأُولِي الْأَبْصَارِ} [الحشر: 2]. وقال تعالى: {وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً} [النحل: 66] الآية.\rوأخرج السيوطي في الجامع الصغير، عن أبي الشيخ في العظمة، عن أبي هريرة رضي الله تعالى، عن رسول الله صلى الله عليه وسلم قال: (فكر ساعة خير من عبادة ستين سنة) وعن ابن عباس رضي الله عنه: (تفكروا في الخلق ولا تفكروا في الخالق).\rوأخرج السيوطي في الجامع الصغير، عن أبي الشيخ في العظمة، عن أبي هريرة رضي الله عنه، عن رسول الله صلى الله عليه وسلم قال: (فكر ساعة خير من عبادة ستين سنة). وعن ابن عباس رضي الله عنه: (تفكروا في الخلق ولا تفكروا في الخالق).\r(وهو) أي: هذا الوارد في الآيات والأحاديث. (على وجوبه) أي: النظري (قد دلا) بألف الإطلاق (مع) بسكون العين لغة فيها والمشهور فتح العين. (كونه) أي: ما ذكر (بالقصد) أي: المقصود متعلق باستقل. (ما استقلا) بألف الإطلاق، يعني: مع أنه ليست كيفية النظر العقلي المقصود مذكورة صريحا في الآيات والأخبار، وإنما المذكور مطلق التفكر والاعتبار في الآيات والمصنوعات.\r(فاقرأ) يا أيها المكلف قوله تعالى: {وَفِي أَنْفُسِكُمْ} [الذاريات: 21] (مع) قوله بعده (أفلا) تبصرون (تظفر برشد) أي: هدى (نوره ما أفلا) وبين قوله أفلا وقوله: (أفلا) جناس التلفيق. وفي هذه الآية توبيخ على عدم والاستدلال وحث عليه."], [40, "واستجل معنى من لنفسه عرف ... تلحق بمن من نهر عرفان غرف\rومن يقدم نفسه عند النظر ... مؤلفا من القضايا ما حضر\rيقس بشكل بين الإنتاج ... إذ خلقه من نطفة أمشاج\r[الشرح]\r(واستجل) أي: استكشف (معنى) الحديث من قوله صلى الله عليه وسلم فيما اشتهر بين الناس (من لنفسه عرف) بالسكون، يعني: من عرف نفسه فقد عرف به. وقد ذكر السيوطي في كتاب الدرر المنتثرة، في الأحاديث المشتهرة قال: حديث: (من عرف نفسه فقد عرف ربه). قال النووي رحمه الله تعالى: غير ثابت. وقال ابن السمعاني: هو من كلام يحيى بن معاذ الرازي. انتهى\rوعلى كل حال فمعناه صحيح، يعني من عرف نفسه فقد عرف به. وقد ذكر السيوطي في كتاب الدرر المنتثرة، في الأحاديث المشتهرة قال: حديث: (من عرف نفسه فقد عرف ربه) قال النووي رحمه الله تعالى: غير ثابت. وقال ابن السمعاني: هو من كلام يحيى بن معاذ الرازي. انتهى\rوعلى كل حال فمعناه صحيح، يعني من عرف نفسه بالذل والفناء فقد عرف ربه بالعز والبقاء. وقال بعض الكاملين: قيل أول ما يلزم الإنسان معرفة نفسهن وقيل: معرفة ربه، وليس بين القولين منافاة فإنهم عنوا بالأول من حيث الترتيب الصناعي والثاني من حيث الشرف والفضل، فإن معرفة الله تعالى أعظم الأشياء إليه وأجل العلوم وألطفها.\rولمّا كانت نفس الإنسان أقرب الأشياء إليه وأدل دليل يستدل بمعرفتها على ربه تعالى فيفوز لديه كانت أول ما اجتهد في معرفتها فهي معرجه إلى ما فوقها وهي أول باب عالم الملكوت. (تلحق) بالجزم جوابا للأمر في قوله واستجل، أي: إن تستجل تلحق بالبناء للمفعول (بمن) أي: برجل أو بالذي (من نهر عرفان) أي: معرفة الإلهية. (غرف) بالسكون أي: تناول.\r(ومن يقدم نفسه) مستدلا بها على معرفة ربه (عند النظر) بالسكون العقلي (مؤلفا) أي: مركبا حال من فاعل يقدم (من القضايا) جمع قضية اسم من القضى وهو الحكم، والقضية الجملة المركبة ن موضوع ومحمول. (ما) أي: قياسا مركبا من القضايا (حضر) بالسكون، أي: وجد وثبت في نفسه بعقله.\r(يقس) بالجزم جواب الشرط (بشكل) بفتح فسكون: المثل، والمراد هنا قياس مركب من مقدمتين، وهو النظر العقلي (بين) أي: ظاهر (الإنتاج) أي: النتيجة (إذ) أي: لأن (خلقه) أي: الإنسان كما قال الله تعالى: {إِنَّا خَلَقْنَا الْإِنْسَانَ مِنْ نُطْفَةٍ أَمْشَاجٍ} [الإنسان: 2]. يقال: مشجت بينهما مشجا، خلطت والشيء مشيج والجمع أمشاج، ويقال: نطفة أمشاج لماء الرجل يختلط بماء المرأة ودمها كذا في الصحاح."], [41, "وبعد أن لم يك شيئا صارا ... حيا حوى الأسماع والأبصار\rوالحكمة الرّائقة للعيان ... والفضل بالمنطق والبيان\rوالعقل والغرض على الحقائق ... والعلم بالأسرار والدقائق\rوغيرها من أمره الغريب ... وحصره يعيي قوى الأريب\r[الشرح]\r(وبعد أن لم يك) أي: يكن، حذف النون لغة فيها (شيئا) كما قال الله تعالى: {وَقَدْ خَلَقْتُكَ مِنْ قَبْلُ وَلَمْ تَكُ شَيْئًا} [مريم: 9]. (صار) بألف الإطلاق، أ]: الإنسان (حيا) أي: ذا حياة (حوى) أي: حاز ونال (الأسماع) جمع سمع (والأبصار) جمع بصر والألف للإطلاق، قال الله تعالى: {فَجَعَلْنَاهُ سَمِيعًا بَصِيرًا} [الإنسان: 2]. (و) حوى أيضا (الحكمة) هي العدل والعلم والحكم كذا في القاموس. (الرائقة) أي: المعجبة، من راقه الشيء: أعجبه. (العيان) أي: المعاينة يعني التي تعجب كل من عاينها. (والفضل) بالنصب عطف على الحكمة، أي: حوى الفضيلة، بمعنى المزية على جميع المخلوقات (بالمنطق) وهو النطق (والبيان) أي: الإفصاح عما في القلب، قال تعالى: {خَلَقَ الْإِنْسَانَ (3) عَلَّمَهُ الْبَيَانَ} [الرحمن: 3، 4]. إيماء بأن خلق البشر وما يميز به عن سائر الحيوان من البيان وهو التعبير عما في الضمير وإفهام الغير لما أدركه لتلقي الوحي وتعرف الحق وتعلم الشرع قاله البيضاوي.\r(و) حوى (العقل) هو العلم، أو بصفات الأشياء من حسنها وقبحها وكمالها ونقصانها، أو العلم بخير الخيرين وشر الشرين، أو يطلق الأمور لقوة بها يكون التميز بين القبيح والحين، ولمعان مجتمعة ف الذهن تكون بمقدمات يستلب بها الأغراض والمصالح، ولهيئة محمودة للإنسان في حركاته وكلامه. والحق أنه نور روحاني به تدرك النفس العلوم الضرورية والنظرية، وابتداء وجوده عند اجتنان الولد ثم لا يزال ينمو إلى أن يكمل عند البلوغ كذا في القاموس. (و) حوى (الغرض) هو في الأصل الترول تحت الماء وهو هذا كناية عن استعمال الفكر للحصور (على الحقائق) العلمية (و) حوى (العلم بالأسرار) جمع سريرة، وهو: ما يكتم والمراد ما خفي من بدائع الحكم وروائع النعم (والدقائق) جمع دقيقة، وهي: الأمر الغامض من شرائف مسائل العلوم ولطائف فضائل الفهوم.\r(و) حوى (غيرها) أيضا (من أمره) أي: الإنسان (الغريب) في ظاهره وباطنه (وحصره) أي: أمر الإنسان وشأنه الذي هو فيه (يعيي) أي: يتعب (قوى) جمع قوة (الأريب) أي: العاقل ولبيت الذي بعده نقص من أوله."], [42, "ومستحيل خلقه لنفسه ... لعجزه عن غيرها من جنسه\rبل غيرها في الخلق منها أسهل ... لأنه تهافت لا يجهل\rإذ فيه تقديم وتأخير معا ... وهو تنافي ظاهر لمن وعا\rولا تصح سنبة التأثير ... لنطفة بالطبع في التقدير\rلأنه يفضي إلى شكر الكره ... ومنعه أظهر من أن نذكره\r[الشرح]\r(ومستحيل) عقلا وشرعا (خلقه) أي: الإنسان، يعني تكوينه وإيجاده (لنفسه) من العدم (لعجزه) في ظاهر الأحوال بالضرورة (عن) خلق (غيرها من جنسه) ومن غير جنسه أيضا (بل غيرها) أي: نفسه (في الخلق) أي: الإيجاد والتصوير (منها) أي: من خلق نفسه (أسهل) وهو عاجز عنه أيضا مع سهولته (لأنه) أي: خلق نفسه (تهافت) أي: تساقط واضمحلال لأنه أمر باطل لا يبقي له معنى في العقل لزيادة بطلانها.\rقال في المصباح: هفت الشيء يهفت من باب ضرب خف فتطاير. وفي الصحاح: التهافت التساقط قطعة قطعة. (لا يجهل) بالبناء للمفعول، لا يجهله أحد من الناس أصلا. (إذ) أي: لأن (فيه) أي: في فرض خلق الإنسان نفسه (تقديم) لوجود نفسه على وجود نفسه؛ لأن الخالق لا بد أن يتقدم وجوده على وجود المخلوق (وتأخير) أيضا لوجود نفسه عن وجود نفسه؛ لأن المخلوق لابد أن يتأخر وجوده عن وجود خالقه فيلزم من ذلك أن يكون لنفسه تقديم وتأخير (معا) أي: في وقت واحد (وهو) أي: التقديم والتأخير للمجتمعين معا بالنسبة إلى الإنسان الواحد مع نفسه (تناف) أي: تناقض (ظاهر) لا خفاء فيه (لمن وعى) أي: أدرك وميز.\r(ولا تصح نسبة التأثير لنطفة) بأن تكون النطفة هي التي تكون نفسها إنسانا (بالطبع) دون اختيار منها ولا تأثير من غيرها (في التقدير) أي: في تقدير ذلك (لأنه) أي: تأثير الطبع (يفضى) بالفاء، أي: يوصل (إلى شكل الكره) بالسكون للوزن، وهو الشكل المستدير المتساوي الأطراف في كل شيء (ومنعه) أي: منع التأثير للطبع (أظهر من أن نذكره) بالسكون لأنه بديهي، ثم استشعر بأن الأفلاك شكلها كري، واقتفي كلامه أن تأثير الطبع يكون في الشكل الكري فدفع توهم ذلك بقوله:"], [43, "فإن نظرت في السموات العلا ... ومالها من الشيات والحلا\rوسعفها المرفوع نم غير عمد ... والنيرات المشعرات بالأمد\rوما حوته الأرض والبحار ... أبصرت ما فيه النهى تحار\rهذا وما قد عنا أكثر ... من البدائع التي لا تحصر\r[الشرح]\r(فإن نظرت) أيها العاقل (في) أجرام السماوات (العلا وما لها) أي: السماوات (من الشيات) جمع شية وهي: اللون. قال في القاموس: شية الفرس كعدة لونه. وفي المصباح: والشية العلامة وأصلها وشية والجمع شيات مثل عدات وهي في ألوان البهائم سواء في بياض أو بالعكس و {بقرة لَا شِيَةَ فِيهَا} أي: ليس فيها لون يخالف سائر ألوانها (والحلا) بالقصر بضم الحاء المهملة وبكسرها جمع حيلة بالكسر الصنعة كذا في المصباح.\r(وسقفها) أي: السقف الذي هو السموات (المرفوع من غير عمد) بالسكون جمع عمود. قال في المصباح: العمود هوالبيت وجمع القلة أعمدة، وجمع الكثرة عمد وعمد يعني بالفتحتين والضمتين (و) الكواكب (النيرات) أي: المضيئات المشرقات (المشعرات) أي: المعلمات (بالأمد) بالسكون أيضا، أي: الغاية، يعني: أنهن مشعرات بأن لهن غاية ومنتهى بتغييرهن بالانتقال والطلوع والغروب ولحوق الكسوف.\r(و) إن نظرت أيضا (ما) أي: الذي أو شيء (حوته الأرض) من كل ما عليها نم الجمادات أو النباتات والحيوانات المختلفة الأجناس والأنواع والأشخاص وما حوت (والبحار) جمع بحر من أنواع العوالم والعجائب (ابصرت ما) أي: شيئا عجيبا وأمرا غريبا. (فيه النهى) بالضم جمع نهية. قال في المصباح: النهية العقل لأنها تنهى عن القبيح والجمع نهى مثل مدينة ومدى. (تحار) حار في أمره يحار حيرا من باب تعب وتحير لم يدر وجه الصواب فهو حيران كذا في المصباح.\r(هذا) أي: اعرف هذا (وما) أي: الذي (قد غاب عنا أكثر) فما ذكر (من) بيانية (البدائع) جمه بديع فعيل: بمعنى المنفرد بذلك من بين نظائره، وفيه معنى العجب، ويقال ابدع الله الخلق إبداعا، خلقهم لا عن مثال، وأبدعت الشيء وأبدعته، استخرجته واستحدثته، ومنه قيل للحالة المحدثة بدعة كذا في الصباح، يعني: بل بدائع من أسرار ملك الله تعالى وعجائب مخلوقاته. (التي لا تحصر) بالباء للمفعول، أي: لا يمكن أحدا أن يحيط بها."], [44, "فهل يكون الصنع دون فاعل ... أو وضعه من غير جعل جاعل\rكلا لقدد أفصحت الأكوان ... عن فعل رب ما له أعوان\rمن أذعنت لقهره الأملاك ... وانتظمت عن أمره الأسلاك\rوأشرقت من نوره الأحلاك ... وسبحت بحمده الأفلاك\r[الشرح]\r(فهل) يمكن أن (يكون) هذا (الصنع) أي: الفعل البديع المعجب (دون) أي: من غير (فاعل) له (او) يمكن أن يكون (وضعه) على هذا الأسلوب المؤلف (من غير جعل جاعل) مختارا مريدا هذا مما لا يكون أصلا.\r(كلا) أي: كلمة ردع وزجر (لقد أفصحت) أي: كشفت وبانت (الأكوان) الظاهرة للحس والعقل (عن فعل رب) أي: مالك خالق مريد مختار (ما له أعوان) جمع عون، وهو: الظهير على الأمر كذا في المصباح.\r(من أذعنت) أذعن إذعانا: انقاد ولم يستعص كذا في المصباح (لقهره) سبحانه وتعالى (الأملاك) جمع ملك بالكسر. قال في القاموس: والملك بالفتح وككتف وأمير وصاحب ذو الملك والجمع ملوك وأملاك وملكاء وملك انتهى. يعني السلاطين (وانتظمت) أي: استقامت، يقال: نظمت الخرز نظما من باب ضرب، جعلته في سلك ونظمت الأمر فانتظم، أي: أقمت فاستقام كذا في المصباح. (عن أمره) تبارك وتعالى (الأسلاك) جمع سلك بالكسر، الخيط يخاط به والجمع سلك وجمع الجمع أسلاك وسلوك كذا في القاموس. وهي كناية عن أسلاك الكائنات المنوط بها مسببات عنه صادرة من بادرة ونادرة.\r(وأشرقت من نوره) الحق المبين (الأحلاك) جمع حلكه بالضم، والحلكة محركة: شدة السواد يعني الظلمات الحسية والمعنوية (وسبحت) أي: نزهت الله تعالى (بحمده) سبحانه وتعالى (الأفلاك) جمع فلك محركة: مدار النجوم ويجمع أيضا على فلك بضمتين، ومن كل شيء مستداره ومعظمه، وموج البحر المضطرب، والماء الذي حركته الريح كذا في القاموس.\r\r- - - -"], [45, "فصل في بيان الصفات النفسية والسلبية وما ينافيها\r\r"]], "pg": [39, 45]}, "496.7": {"x": [[45, "واعرف من الصفات ما الدليل دل ... على وجوبها له عز وجل\rوهي الوجود والبقاء والقدم ... وانف الحدوث والفناء والعدم\r[الشرح]\r(فصل في) بيان (الصفات) أي: صفات الله تعالى (النفسية)\r\rالمنسوبة إلى النفس لأنه لا يحكم على النفس بحكم إلا بعد اتصافها بها. وقال بعضهم: هي صفة ثبوتية يدل الوصف بها على النفس الذات دون معنى زائد عليها، ككون الجوهر جوهرا وذاتا وشيئا وموجودا، ويقالها المعنوية وهي صفة ثبوتية دالة على معنى زائد على الذات ككون الجوهر حادثا ومتحيزا وقابلا للأعراض كما سيأتي في صفات المعاني. (و) في بيان الصفات (لسلبية) المنسوبة إلى السلب، وهي نفي معنى لا يليق بالله تعالى (و) في بيان (ما ينافيهما) أي: ينافي كلا من الصفات النفسية والسلبية.\r(واعرف) لولو للاستئناف والأمر خطاب للمكلف بالمعرة، وهي العلم الناشئ عن الدليل النقلي (من الصفات) الإلهية (ما) أي: مطلوباتها (الدليل) العقلي القطعي (دل) بالسكون للوزن (على وجوبه) أي: كونه واجبا عقليا لا يتصور في العقل عدمه يعني وجوب ذلك المطلوب (له) أي: الله (عز) أي: امتنع عن صفات مشابهة الحوادث (وجل) بالسكون أيضا، أيك عظم عن ذلك.\r(وهي) أي: صفاته تعالى الواجبة به سبحانه وتعالى وتلك ست صفات: الصفة الأولى (الوجود) يعني: أنه تعالى موجود في ذاته وجود حقيقيا وهي صفة نفيسة والكلام على وجوده تعالى أنه عين ذاتها أو زائد على ذاته مما لا يجدى لأنه حكم على الغيب المطلق بالأحكام القاصرة العقلية وهو مستوفى في علم الكلام، ولنا في ذلك كتاب الوجود الحق، بسطنا فيه الكلام على طريقة أهل التوحيد الحقيقي دون التوحيد العقلي بما لا مزيد عليه. (و) الصفة الثانية (البقاء) بالمد، وهو: سلب العدم المتوهم أنه لاحق للوجود، فهي صفة سلبية له تعالى. (و) الصفة الثالثة (القدم) بسكون الميم لأجل الوون، وهو: سلب العجم المتوهم أنه سابق على الوجود، فهي صفة سلبية أيضا تعالى وإذن ثبت هذه الصفات الثلاثة له تعالى (وانف) أضدادها عنه سبحانه فاجحد (الحدوث) ضد القدم (والفناء) أي: الزوال ولاضمحلال ضد البقاء (والعدم) ضد الوجود بسكون الميم لأجل الوزن."], [46, "أما الدليل لوجود الحق ... سبحانه فهو حدوث الخلق\rلأنه من المحال الباطل ... وجود فعل ما بدون فاعل\rإذ فيه جمع المتنافيين ... في واحد من متساويين\rأي كونه مساوي المقابل ... له وراجحا بغير جاعل\rكالوقت والوجود مع سواه ... لأنه لذاته ساواه\rفكيف صار راجحا بلا سبب ... وهكذا كل مساو في الرتب\r[الشرح]\r(أما الدليل) العقلي (لوجود الحق سبحانه) وتعالى (فهو حدوث الخلق) أي: المخلوق والمراد الجنس، والحدوث انتقال الشيء من العدم إلى الوجود (لأنه) أي: الشأن (من المحال الباطل) أي: المحكوم ببطلانه بحيث لا يتصور في العقل ثبوته (وجود فعل) أي: مفعول (ما) أي: مفعول كان في الجنس والعقل (بدون) وجود (فاعل) له (إذ) أيك لأن (فيه) أي: في وجود فعل بلا فاعل (جمع المتنافيين) من التساوي والرجحان بالا مرجح (في) شيء (واحد) بينه بقوله (من) أمرين (متساويين) أي: كل واحدد منهما (مساوي) بفتح الياء التحتية (المقابل*له) أي: الأمر الآخر الذي قابله (و) مع ذلك (راجحا) عليه في حالة كونه مساويا له ورجحانه عليه (بغير جاعل) أي: مرجح له من الغير وهو محال.\rثم بين الأمرين المتساويين الذي رجح أحدهما على الآخر بلا مرجح فقال: (كالوقت) أي: الزمان المخصوص الذي يوجد المخلوق (والوجود) للمخلوق (مع سواه) أي: سوى كل واحد منهما فغن زمان وجود المخلوق مساو لجميع الأزمنة التي قبل ذلك الزمان وللتي بعده، وكذلك الوجود للمخلوق مساو لجميع الأزمنة التي قبل ذلك الزمان والتي بعده، وكذلك الوجود للمخلوق مساو للعدم السابق عليه وللاحق له (لأنه) أي: ذلك السوي المذكور (لذاته) أي: بمقتضى ذاته لا لأمر خارجي (ساواه) أي: مساوي كل واحد من الوقت والوجود كما ذكرنا (فكيف) يمكن أن يكون ذلك المساوي (صار راجحا) على مساويه الآخر (بلا سبب) بالسكون: أي: مرجح من الخارج فإنه جمع جمع بين الضدين وهو محال في العقل (وهكذا) أي: كما ذكر في الوقت والوجود"], [47, "من جهة مخصوصة أو قدر ... خصّ ووصف أو مكان فادر\rوفي دليل القدم المقرر ... وجوبه بالمطلب المحرر\rتقول إن ركبته لو انتفى ... عنه لكان حادثا بلا خفا\r[الشرح]\r(كل) أمر (مساو) لأمر آخر او لأمور أخر (في الرتب) بالسكون جمع رتبة (من) بيانية (جهة) أي: اعتبار من جميع الاعتبارات (مخصوصة) تلك الجهة كواحدة ن الجهات الست بالنسبة إلى الجهة الأخرى إذا كان فيها مخلوق من المخلوقات وكصورة نم الصور لون من الألوان وطعم من الطعوم وخاصية من الخواص ونحو ذلك (أو قدر)] أي: مقدار (خص) بالبناء للمفعول أي: مخصوص بكبر أو صغر وما بينهما (ووصف) كذلك من جميع الأوصاف التي عليها كل محسوس وكل معقول وكل موهوم (أو مكان) فيه مخلوق من المخلوقات أي: مكان، فإن جميع الجهات والمقادير والأوصاف والأمكنة متساوية في أن كل مخلوق يمكن أن يكونه في غير ما هو فيه منها وقد رجح ما هو فيه منها على كل سواه من بقية ما يمكن أن يكون أن يكون فيه منها ولا رجحان بع التساوي إلا بمرجح من الخارج وهو الفاعل فلا فعل إلا بفاعل فثبت المدعي وهو وجود الله تعالى الخالق لكل شيء سبحانه وتعالى، {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ} [الأنعام: 18]. أي: القاهر بالتخصيص المذكور، وله فوقية القهر والغلبة، ومع ذلك فإنه الحكيم الذي يضع كل شيء في محله، الخبير الذي لا يخفى عليه شيء في الأرض ولا في السماء (فادر) أمر من الدارية، أي: فاعرفه يا أيها المكلف ولا تجهله فإن كل شيء دليل عليه، ومطرح بالذل والانكسار بين يديه.\rفواعجبا كيف يعصى الإله ... أو كيف يجحده الجاحد\rوفي كل شيء له آية ... تدل على أنه الواحد\r\r(وفي دليل) وصف (القدم) لله تعالى (المقرر) فيما مر (وجوبه) أي: كونه واجبا عقليا لا يتصور في العقل انتفاؤه في حق الله تعالى (بالمطلب) أي: القياس أو البرهان (المحرر) أي: المراتب المؤلف عند العقلاء.\r(تقول) في بيانه يا أيها المكلف (إن ركبته) من المقدمتين الشرطين (لو انتفى) أي: القدم (عنه) أي: وجود الله تعالى (لكان) وجوده سبحانه (حادثا بلا خفا) في هذا الأمر لانهما ضدان في الموجود القدم والحدوث فمتى انتفى أحدهما ثبت الآخر."], [48, "وهو مؤد لا فتقاره إلى ... مؤثر لما عرفت أولا\rوننقل الكلام للمؤثر ... منحصرا وما سوى المنحصر\rفيلزم الدور أو التسلسل ... وما يؤدي لهما لا يحصل\r[الشرح]\r(وهو) أي: كونه حادثا سبحانه وتعالى (مؤد) أي: موصل (لافتقاره) أي: احتياجه تعالى (إلى مؤثر) فيه صفة الوجود يعني إلى موجد يوجده؛ لأنه حادث حينئذ والحادث لا يكون وجوده إلا طارئا عليه لا أصليا له (لما) أي: لأجل الذي (عرفت) ولصلة محذوفة أي: عرفته (أولا) من أن الشيء لا يمكن أن يحدث نفسه فيوجدها من العدم إلى الوجود بل لا بد من فاعل يحدثه (وننقل) هذا (الكلام) أيضا (للمؤثر) الفاعل الذي أهر ه وأحدثه. فنقول فيه أيضا إنه لا بد له من فاعل أثره أو أوجده كذلك، هم ننقل الكلام إلى ذلك الفاعل المؤثر فيه المحدث له وهلم جرا، فإن كان العدد في الفواعل (منحصرا) بأن كان بين اثنين او ثلاثة مثلا إلى مقدار معين ثم ذلك الفاعل الأول من هذا العدد المذكور (وما) أي: والعدد الذي هو (سوى) أي: غير (المنحصر) بأن كان كل فاعل قبله فاعل آخر أحدثه إلى ما لا نهاية له بحسب ما مضى ولم يكن العدد متناهيا إلى فاعل أحدثه الفاعل الأول.\r(فيلزم) على كل هذين التقديرين (الدور) في التقرير الأول (أو التسلسل) في التقدير الثاني، وهما باطلان عقلا لما يلزم على الدور من تقدم الشيء إلى نفسه بمرتبة أو بمراتب، ويلزم الجمع بين النقيضين وجود الشيء وعجم وجوده معا، وذلك محال عقلا على سيبل القطع، ولما يلزم على التسلسل من الحكم على كل فرد من أفراد مالا نهاية له في الوجود بنهاية له في الوجود وأن يكون الحكم على أفراد ما نهاية له في الوجود فإن أفراد العدد عين مجموع العدد والمغايرة بينهما محال عقلا، فمتى حكم على كل فرد من أفراد ما لا نهاية له بالحدوث لزم من ذلك على جملة ما لا نهاية له بالحدوث أيضا، وإلا لاتصف كل فرد من ذلك بالحدوث وبعدم الحدوث معا وهو ممتنع ببداهة العقل؛ لأنه جمع بين النقضين، فإنه لا يأتي مما لا نهاية له بحسب الماضي الداخل في صفة الوجود بخالفه بحسب المستقبل فإنه ممكن لعدم دخوله في صفة الوجود كمن قال لغيره لا أعطيك درهما حتى أعطيك قبله دينارا ولا أعطيك دينارا ولا أعطيك دينارا حتى أعطيك قبله فإنه لا يتصور أن يعطيه"], [49, "وهكذا يلزم في نفي البقا ... حدوثه وما فيه قد سبقا\rفلا يكون واجب الوجود ... عند طروّ العدم المردود\rإذ فيه نفي القدم الذي مضى ... مع أنه به الدليل قد قضى\rفبان من ذا أن تجويز العدم ... أمر مناف ريب للقدم\rوأن كونه قديما يلزم ... منه البقا وبهذا يجزم\r[الشرح]\rدرهما ولا دينارا لأن اشتراط القبيلة مانع عن ذلك، بخلاف ما إذا قال له: لا أعطيك درهما حتى أعطيك بعده دينارا، ولا أعطيك دينارا حتى أعطيك بعده درهما، فإنه يمكن ببداهة العقل أن يعطيه أولا درهما هم يعطيه يعده دينارا، أو يعطيه أولا دينارا ثم يعطيه بعده درهما، ومنع الدور والتسلسل مشهور في كتب علم الكلام فلا نطيل بذكره زيادة على ما لخصناه في هذا المقام. (وما) أي: الأمر الذي (يؤدي) أي: يوصل (لهما) أي: الدور والتسلسل (لا يحصل) أي: لا يوجد أصلا وقد وجد الفاعل الحقيقي وهو الله تعالى بدلالة وجود العوالم عليه سبحانه وتعالى فثبت له القدم وانتفى عنه الحدوث عز وجل.\r(وهكذا) أي: كما يلزم في نفي القدم عنه تعالى من الحدوث المؤدي إلى الدور والتسلسل (يلزم) أيضا (في نفي البقا) عنه تعالى (حدوثه) وإذ لزم حدوثه لزم (وما فيه قد سبقا) بألف الإطلاق من لزم الدور والتسلسل الباطلين (فلا يكون) سبحانه وتعالى حينئذ (واجب الوجود) أي: لا يتصور في العقل عدمه بل يكون جائز الوجود، حينئذ يصح في العقل وجوده وعدمه (عند طرو) يا: دخول (العدم المردود) أي: المنفي عنه سبحانه عز وجل وذلك محال بالبداهة العقلية.\r\r(إذ فيه) أي: في طرو العدم عليه تعالى (نفي القدم) عنه سبحانه وتعالى (الذي مضى) ثبوته له (مع أنه) أي: القدم المذكور (به الدليل) أي: البرهان العقلي القطعي (قد قضى) أي: حكم وإلزام (فبان) أي: ظهر (من ذا) أي: هذا الكلام المذكور (أن تجويز العدم) بالسكون عليه تعالى الذي هو مقتضى سلب البقا عنه سبحانه (أمر مناف دون ريب) أي: من غير ارتياب ولا شك (للقدم) بالسكون,\r(و) بان أيضا مما ذكر (أن كونه) تعالى (قديما) لا حادثا (يلزم*منه البقا) له تعالى (وبهذا) الأمر القطعي (يجزم) بالبناء للمفعول، أي: يقطع كل أحد من العقلاء بلا شك ولا وتردد، فثبت له القدم سبحانه وتعالى وثبت له البقاء أيضا كذلك ووجب قدمه."], [50, "وكونه مخالفا لخلقه ... سبحانه من واجب في حقه\rلأنه لو ماثل العوالم ... كان حدوثه من للوازم\rلأن مثل الشيء دون لبس ... له مساو في صفات النفس\rوهي التي موصوفها لا يعقل ... بدونها كالنطق فيما مثلوا\rوأوجه التماثل المعدوده ... منفية في حقه مردوده\rككونه جرما له تحيز ... أو عرضا له به التميز\r[الشرح]\rوبقاؤه كما وجب وجوده تبارك وتعالى واستحال عليه العدم المقارن والعدم السابق والعدم اللاحق وهو المطلوب.\r(و) الصفة الرابعة (كونه) أي: الله تعالى (مخالفا لخلقه) أي: جميع مخلوقاته المحسوسة والمعقولة والموهومة في الملك الظاهر والملكوت الباطن (سبحانه) وتعالى (من واجب) أي: من جملة ما يحب (في حقه) تعالى (لأنه) أي: الله تعالى (لو مثل) أي: كان مثل (العوالم) بالسكون جمع عالم، وبفتح الألم اسم لكل نوع من أنواع الخلق (كان حدوثه) أي: الله تعالى حينئذ (من اللوازم) بالسكون أيضا، ثم بينه بقوله: (لأن مثل الشيء دون) أي: الله تعالى حينئذ (من اللوازم) بالسكون أيضا، ثم بينه بقوله: (لأن مثل الشيء دون) أي: من غير (لبس) أي: التباس (له) أ]: لذلك الشيء (مساو في صفات النفس) فالمثلان متساويان في جميع صفات النفس وإلا لم يكونا مثلين (وهي) أي: صفات النفيس الصفات (التي موصوفها) أي: الموصوف بها (لا يعقل) أي: لا يمكن أن يدرك (بدونها) أصلا (كالنطق) النفساني وهو القوة المفكرة في الإنسان التي يتميز بها عن جميع الحيوان (فيما) مثلوا) أي: حيث قالوا الإنسان حيوان ناطق وصيغة التبري لأن أهل السنة لا يجعلون النطق ذاتيا للإنسان بل عرضيا له.\r(وأوجه) جمع وجه والمراد بها أنواع (التماثل) أي: المماثلة للحوادث (المعدودة) بالسكون، أي: التي يضبطها العقل (منفية) كلها (في حقه) أي: الله تعالى (مردوده) بالسكون أيضا فإنها مستحيلة عقلا عليه تعالى (ككونه) أي: الله تعالى (جرما) أي: جسما مؤلفا من الأجرام (له تحيز) أي: أحد مقدار من الفزاع كما للأجسام (أو) كونه (عرضا) بفتحتين، هو: ما لا يقوم بنفسه ولا يوجد إلا في محل يقوم به وهو خلاف الجوهر كذا في المصباح. (له) أ]: لذل العرض (به) أي: بالجرم (التميز) أي: الثبوت والظهور لأنه لا يكون إلا قائما بالجرم ولا قيام بنفسه أصلا."], [51, "أو بارتسام في خيال يعتبر ... أو بزمان أو مكان أو كبر\r[الشرح]\r(أو بارتسام) أي: انتقاش وتصوير والجار والمجرور متعلق يعتبر (في خيال) متعلق بارتسام، أي: قوة خيالية ونكره ليعلم كل خيال من خيال نبي أو رسول أو ولي أو صالح أو فاسق أو كافر، وذلك لأن الخيال حادث وجميع ما يرتسم فيه حادث مثله. (يعتبر) بالبناء للمفعول أي: الله تعالى وسكون الراء للوزن، أي: تحصل معرفته بذلك وكان الشيخ أبو إسحاق إسفرايني يقول: جميع ما قاله المتكلمون في التوحيد قد جمعه أهل الحق في كلمتين:\rالأولى: الاعتقاد أن كل ما تصور في الأوهام فالله تعالى بخلافه.\rوالثانية: اعتقاد أن ذاته سبحانه ليست كالذوات ولا معطلة عن الصفات، وقد أكد ذلك تعالى بقوله: {وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} [الإخلاص: 4]. وكتابنا المطالب الوفية زيادة بسط لهذا المبحث (أو) يعتبر سبحانه وتعالى (بزمان) وهو اقترانه متجددة بمتجدد آخر، فالزمان نسبة ما بين شيئين متجددين متأخرة عنهما فإذا نظرت إلى الشيء الأول الذي أوجده الله تعالى من العدم قبل كل شيء وجدته خرج من العدم لا في زمان؛ لأن الله تعالى ليس بمتجدد حتى تكون النسبة بينه تعالى وبين الشيء الأول زمان الذي هو نفس المدة الواقعة بين هذين الشيئين. فلولا وجود الشيء الثاني ما ظهر وجود الشيء الأول مدة، فحينئذ لولا ترتيب العالم وتقدم بعضه عن بعض ما وجد الزمان؛ لأنه مجرد النسبة بين الأشياء كما ذكرنا.\r(أو مكان) معطوف على زمان ونكرهما لقصد عمومها. فيتنزه سبحانه وتعالى عن جميع الأزمنة الحاضرة والماضية والمستقبلة، وكذلك عن جميع الأمكنة العلوية والسفلية وما بينهما. والمكان هو ما استقر عليه الشيء. والخير ما ملأ الشيء.\rوفي القاموس: المكان الموضع والجمع أمكنة وأماكن. (او كبر) بكسر الكاف وفتح الباء الموحدة وسكون الراء للوزن، وهو مصدر قولك: كبر بالضم يكبر من باب قربكبرا بضم فسكون أي: عظم جثة او كبر بالكسر ن باب تعب كبرا وزان عنب في السن إذا أسن وكلا المعنيين محال على الله تعالى.\rأما الأول: فلأنه يقتضى الجسمية وهي تقتضي التركيب والافتقار والحدوث وذلك ممتنع في حق الله تعالى."], [52, "أو ضده كما يقول الشاني ... نعم هو الأعلى الكبير الشان\rجل عن الجهات والأغراض ... فيما يشاء والوصف بالإعراض\r[الشرح]\rوأما الثاني: فلأنه يقتضي مرور الزمن والزمان، حادث ولا يمر إلا على حادث.\r(أو ضده) أي: الكبر وهو الصغر (كما يقول الشاني) من شان يشينه شينا عابه وانتقضه (نعم هو) أي: الله تعالى (الأعلى) أي: المرتفع المقدار (الكبير الشأن) بإبدال الهمزة الفا، وهو الأمر. وفي أسماء الله تعالى الكبير، هو وصف ذاتي الله تعالى راجع إلى جلالة القدر وكبر الرتبة بالإضافة إلى رتب الموجودات كلها وأقدارها المعنوية فكل موجود في الوجود سوى الله تعالى فهو صغير القدر، وللرتبة بالنسبة إلى الله تعالى هو الكبير على الإطلاق وحده، فمعنى الكبير في وصفه تعالى أنه الكبير في ذاته على الإطلاق، ومعنى الله أكبر: أي الأكبر في ذاته وصفاته ذكره اليافعي اليمني في شرح الأسماء.\r(جل) أي: عظم (عن الجهات) جمع جهة وهي ست: فوق، وتحت، ويمين، وشمال، وقدام، وخلف. والجهة عند المتكلمين هي نفس المكان باعتبار إضافة جسم آخر إليه. ومعنى كون الجسم في جهة كونه مضافا إلى جسم آخر حتى لو انعدمت الأجسام كلها لزم من ذلك انعدام الجهات كلها؛ لأن الجهات من توالع الأجسام وإضافتها كما قدمناه في المكان والزمان، وحيث انتفى عن الله تعالى الزمان والمكان انتفت الجهات كلها عنه تعالى أيضا؛ لأن جميع ذلك من لوازم الجسمية وهي مستحيلة في حقه تعالى (و) عن (الأغراض) جمع غرض بالتحريك، وهو في الأصل الهدف الذي يرمي إليه وتقول عرضه كذا على التشبيه بذلك أي مرماه الذي بقصده كذا في المصباح. (فيما) أي: في كل شيء (يشاء) من الأفعال والأحكام فليس فعل من أفعاله تعالى ولا حكم من أحكامه صادرا عنه تعالى بغرض من الأغراض العادلة والآجلة؛ لأنه تعالى غني عن العالمين، فلو كان له باعث على فعل أو حكم يجلب نفع له أو دفع ضرر عنه في الحال أو المآل لكان محتاجا إلى ذلك والمحتاج إلى الشيء عاجز عنه والعاجز عن الشيء لا يقدر على إيجاده، فلما وجد كل شيء دل على قدرته عليه وقدرته عليه دلت على عدم عجزه عنه وعدم عجزه عنه دال على استغنائه عنه واستغنائه عنه يدل على أنه لا غرض له فيه، وحيث انتفى الغرض عن أفعاله تعالى وأحكامه فلا يقال إن أفعاله تعالى وأحكامه حينئذ عبث؛ لأن العبث محال على الله تعالى أيضا لأنه نقص في الربوبية يقتضي انتفاء الحكمة"], [53, "فليس مثله علا شيء كما ... بذاك نقل وفق عقل حكما\rوواجب قيامه بالنفس جل ... أي لا مخصص له ولا محل\rلأنه ذات قديمة فلا ... تنصت إلى ما قاله من غفلا\r[الشرح]\rفي العقل والحكم، قال تعالى: {أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا} [المؤمنون: 115]. وقال تعالى: {وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ} [الأنبياء: 16]. فتعين أن كون أفعاله تعالى وأحكامه غير متشابه لأفعال خلقه وأحكامهم، لأن جميع أفعاله الخلق وأحكامهم لا تخلو إما أن تكون بأغراض أو بمجرد العبث وأفعاله الله تعالى وأحكامه ليست كذلك لأنها متقنة محكمة جارية على الحكمة (و) عن (الوصف بالأعراض) جمع عرض بالتحريك كالحركة والسكون والاجتماع والافتراق والصور والألوان والطعوم والروائح والكيفيات والكميات والتركيب والتبعيض والتجزؤ والمحاذة والتلقؤات والتناهي والحديد والمجانسة والمشابهة والأبوة والبنوة فإن ذلك كله مستحيل على الله تعالى لأنه تعالى ليس بجسم ولا يتصف (فليس مثله) أي: الله تعالى (علا) أي: تتره (شيء) مطلقا (كما بذلك نقل) أي: نص كلامه سبحانه حيث قال: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ} [الشورى: 11]. (وفق) أي: على موافقة نظر (عقل حكما) أي: النقل والألف للإطلاق، يعني أن النقل حكم على حسب موافقته للقعل له في ذلك.\r(و) الصفة الخامسة (واجب) عقلي (قيامه) أي: وجوده وثبوته تعالى (بالنفس) أي: بذاته (جل) بالسكون أي: عظم وتنزه عن صفات المخلوقين (أي لا مخصص له) تعالى ولمخصص الفاعل الذي يخصصه بعض ما يجوز عليه من المقدار والصورة والزمان والمكان والجهة وغير ذلك من أنواع التخصيصات الجنسية والنوعية والشخصية لأن ذلك من لوازم الجسيمة وهي مستحيلة على الله تعالى ولأن القائم بغيره لا يكون إلا مخلوقا والله تعالى خالق لا مخلوق (ولا محل) بالسكون أيضا للوزن، أي: موضع يحل فيه فيكون صفة لذلك المحل إذ لا يحل في الذات إلا صفاتها والله تعالى ليس بصفة حتى يحل في غيره ..\r(لأنه) تعالى (ذات) واحدة (قديمة) مولا يتصور في الذات أن تحل في ذات أخرى لما يلزم عليه من رجوع الذاتين إلى ذات واحدة أو انحصار أحدهما في الأخرى وكلاهما"], [54, "إذ لو إلى المخصص احتاج وجب ... حدوثه ورد هذا ما احتجب\rإذ قام جل ربنا بذات ... لكان معدوما من الصفات\rوتلك لا توصف بالمعاني ... والله قد حقق بالبرهان\rوجوب وصفه بها فأنى ... يكون وصفا من هدانا منا\r[الشرح]\rباطل لاقتضاء ذلك الحدوث والافتقار وانتفاء القدم والفناء المطلق وعما واجبان عقليان لله تعالى لا يتصور في العقل انتفاؤهما عنه تعالى كما مر (فلا تنصب) أي: تصغي وتميل، وفي المصباح: أنصت إنصاتا استمع ونصت له ينصت من باب ضرب لغة، أي: سكت مستمعا. (إلى ما) أي: قول (قاله من غفلا) بألف الإطلاق من الغفلة، وهي غيبة الشيء عن بال الإنسان وعدم تذكره له، وقد استعمل فيمن تركه إهمالا وإعراضا كذا في المصباح يعني الغافل عن الحق التارك له.\r(إذا) أي: لأن الله تعالى (لو) إلى المخصص كما ذكرنا (احتاج) سبحانه وتعالى (وجب) بسكون الباء للوزن، أي: لزم من ذلك (حدوثه) تعالى (ورد) أي: إبطال (هذا) أي: الحدوث عنه تعالى (ما احتجب) بالسكون، أي: استتر عن أحد لوضوحه عن العقل كما تقدم في برهان البقاء والقدم. (إذ) لو فرضنا أنه تعالى (قام) أي: وجد وثبت (جل) أي: عظم (ربنا) جملة معترضة بين الفعل ومتعلقة للتعظيم والتنزيه (بذات) متعلق بقام أي: ذات كانت من ذوات الحوادث (لكان) الله تعالى (معدوما) من ذاته موجودا من جهة الذوات الأخرة التي هو قائم بها بمنزلة صفة. (من الصفات وتلك) أي: الصفة (لا توصف بالمعاني) أي: بصفات المعاني التي سيأتي ذكرها؛ فإن الصفة لا تتصف بصفة لها معنى زائد على معنى قيامها بالموصوف وإن اتصفت الصفة بالصفات السلبية كالقدم والبقاء والصفة المعنوية التي هي صفة ثبوتية، لكن يدل الوصف بها على نفسها دون غيرها زائدا عليها ككون القدرة مثلا قدرة مؤثرة في الممكن. (والله) سبحانه وتعالى (قد حقق بالبرهان) العقلي والقطعي.\r(وجوب وصفه) تعالى (بها) أي: بصفات المعاني كما سيأتي (فأنى) بفتح النون مشددة استفهام عن الجهة تقول: أنى يكون هذا؟ أي: من أي وجه وطريق، كذا في المصباح. (يكون وصفا) أي: صفة قائمة بموصوف (من) أي: الذي اسم يكون (هدانا)"], [55, "ويستحيل أن يقوم المعنى ... بمثله فاحتط بهذا المعنا\rولا تصخ لمذهب النصارى ... ومن إلى وعوى حلول صارا\rفذاك كالقول بالاتحاد ... نحلة أهل الزيغ والألحاد\r[الشرح]\rأي: دلنا وأوصلنا إليه ستحانه (منا) عقلا (أن يقوم) أي: يوجد ويثبت (المعنى) الذي ليس بذات (بمثله) أي: بمعنى آخر مثله، فلا تتصف الصفة بصفة أخرى مثلها كما قدمناه (فاحتط بما) أي: احفظ واجمع الذي (ألمعنا) به هنا، أي: أشرنا غليه من الكلام. قال في القاموس: كل من بلغ أقصى شيء وأحصى علمه فقد أحاط به. ولمع البرق: أضاء. انتهى\rوقوله ألمعنا: أي: اعلمنا به بطريق الاستعارة من الإلماع وهو الإظهار والإبانة.\r(ولا تصخ) من أصاخ له، أي: استمعه كذا في المصباح. (لمذهب) أي: لما ذهبت إليه (النصارى) جمع نصراني، وهم طائفة من أهل الكتاب معروفون كافرون بالله وبالأنبياء عليهم السلام. (و) لمذهب (من) أي: واحد من طائفة يدعون الإسلام (إلى دعوى حلول) في الله تعالى (صارا) بألف الإطلاق كما تدعي ذلك النصارى. (فذاك) أي: القول بالحلول (كالقول بالاتحاد) أي: اتحاد ذات الله ذات أخرى بحيث يصيران ذاتا واحدة (نحلة) بكسر النون، أي: دعوى كما في المصباح والقاموس (أهل الزيغ) أي: الميل عن الحق (والإلحاد) أي: العدول عن ظواهر النصوص بلا ضرورة.\rواعلم أن الحلول والاتحاد في الله تعالى بطلانهما بديهي وبراهين بطلانهما مذكورة في كتب العقائد كالطالع والمواقف والمقاصد، فبطلان الحلول أن الحال في الشيء يفتقر إليه سواء كان حلول جسم في مكان أو عرض في جوهر أو صورة في مادة كما هو رأي الحكماء أو صفة في موصوف والافتقار إلى الغير ينافي الوجوب، ومن ذلك حلول الامتزاج كالماء في الورد فإنه من خواص الأجسام وهي مفتقرة إلى الغير، وأيضا فإن الحلول في الغير إن لم يكن صفة كمال وجب نفية عن الواجب، وإن كان كمالا وجب كون الواجب مستكملا بالغير وهو باطل."], [56, "وموهم المحذور من كلام ... قوم من الصوفية الأعلام\rجريا على عرفهم المخصوص ... يرجع بالتأويل للمنصوص\r[الشرح]\r(وموهم) من الأيهام، يقال أوهمه: أدخل عليه الوهم أي: الغلط (المحذور) أي: ما يحذر منه من المعنى الفاسد كالحلول والاتحاد في حق الله تعالى (من) بيانية (كلام قوم) أئمة (من الصوفية) أي: المنتسبين إلى التصوف أهل الاعتقاد الصحيح والعمل الصالح (الأعلام) جمع علم بالتحريك كسبب وأسباب. والعلم: العلامة والجبل العالي، كأنهم لاشتهارهم بالكمال والشرف صاروا علامات على ذلك، أو لرسوخهم في المعرفة والعمل صاروا كالجبال العالية.\r(جريا) أي: إنما قالوا ذلك لجريهم فيه (على) مقتضى (عرفهم) بضم العين المهملة، أي: اصطلاحهم وما تعارفوا هم عندهم (المخصوص) نعت لعرفهم، أي: الذي اختصوا بها دون غيرهم، فإن لهم عبارات وإشارات منظومة ومنثورة في أشعارهم ومصنفاتهم توهم أهل العقول الجامدة على درك المحسوسات والمعقولات من العوام والمستعملين لقواعد العلوم الظاهرة واصطلاحاتها من خواص العلماء خلاف مقصودهم من معاني الحلول والاتحاد في حق الله تعالى وهم رضي الله عنه بريئون من ذلك وحاشهم منهن وكل من جهل قواعدهم المعقولات واصطلاحات أهل العلوم الظاهرة، ففهم منها المعاني الفاسدة، والمفاهيم الكاسدة، فأنكر عليهم ما هم فيه من الدين الحق والمذهب الصدق، وفي نفس الأمر إنما إنكاره على ما فهمه لا على كلامهم (والله بصير بالعباد) [آل عمران: 15] وقد أوضحنا أصولهم وقواعدهم في كتاب الوجود الحق والمذهب الصدق لنا بما لا مزيد عليه.\r(يرجع) بالبناء للمفعول والجملة خبر عن قوله وموهم إلى آخره ونائب الفاعل محذوف وتقديره فيه (بالتأويل) وهو تفسير اللفظ بأحد محتملاته، وقيل: التأويل تفسير الشيء بالوجه المرجوح، وقيل: حمل الظاهر على المحمل المرجوح بدليل يصيره راجحا (للمنصوص) أي: الحكم المنصوص عليه في كتاب الله تعالى أو في سنة نبيه صلى الله عليه وسلم أو في إجماع أئمة المسلمين، فإن جميع ما عليه الصوفية من الأقوال والأعمال والأحوال والاعتقاد مقيد جميع ذلك عندهم بالمطابقة للكتاب والسنة."], [57, "وما يفوهون به في الشطح ... فقيل غير مقتض للقدح\rوهو إلى التأويل ذو انتحال ... أو أنهم قد غلبوا بالحال\r[الشرح]\rقال اليافعي اليمني رحمه الله تعالى في كتاب صنفه في ذلك: روينا عن الأستاذ أبي القاسم الجنيد رضي الله عنه قال: من علامات المحب متابعة حبيب الله صلى الله عليه وسلم في أخلاقه وأفعاله وأوامره ونواهيه وسننه.\r(وما يفهون) أي: يتكلمون يعني الصوفية (به) من الكلمات التي يفهم منها المخالفة للشريعة بحسب المعنى الظاهر للعوام ولمن يستعمل اصطلاحات العلوم الظاهرة من الخواص (في) حال (الشطح) وهو حال الغيبة عن عالم الحس والاشتغال بعالم الملكوت الأعلى (فقيل غير مقتض) أي: متضمن (للقدح) فيهم، أي: الإعابة عليهم والانتقاض لهم؛ لأنه في تلك الحالة مغلوبين في أحوالهم (وهو) أي: ذلك الأمر الصادر منهم (إلى التأويل) بالمعاني الحسنة (ذو انتحال) أي: الدعاء وانتساب، من قولك: انتحله وتنحله، ادعاه لنفسه وهو لغيره كذا في القاموس، يعني: هو لازم التأويل كيلا يظن بأولياء الله تعالى سوء.\rقال الإمام حجة الإسلام أبو حامد الغزالي رحمه الله تعالى: وما تداولته ألسنة الصوفية من كلمات تشير إلى ما يوهم عند غير المحصل شيئا من معنى الحلول والاتحاد فذلك غير مظنون بعاقل فضلا عن التميز بخصائص المكاشفات\rوقال الشعراوي رحمه الله تعالى: ولعمري إذا كان عباد الأوثان لم يتجرؤوا على أن يجعلوا آلهتهم عين الحق بل قالوا: {مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى} [الزمر: 3]. فكيف يظن بأولياء الله تعالى أنهم يدعون الاتحاد بالحق على حد ما تتعقله العقول الضعفة. هذا كالمحال في حقهم رضي الله عنه، إذما من ولي إلا وهو يعلم أن حقيقته تعالى قديمة وأنها خارجة عن معلومات جميع الخلائق؛ لأن الله تعالى بكل شيء محيط.\r(أو أنهم) أي: القائلين بذلك الشطح (قد غلبوا) بالبناء للمفعول (بالحال) أي: تقتضي غيبة عقل التكليف فلا تترتب الأحكام مع غيبة العقل."], [58, "وقيل بل يناط حكم الظاهر ... بهم صيانة لشرع طاهر\rفلا يقر ظاهر في الميل ... عنه وذا أمر طويل الذيل\rوليس يقتدى بهم في ذلك ... لكونه من أصعب المسالك\r[الشرح]\r(وقيل بل يناط) أي: يتعلق (حكم) الشريعة المحمدية بحسب المفهوم و (الظاهر) من الكلام على مقتضى المخاطبة مع العوام (بهم) متعلق بقوله يناط أي: بالمتكلمين بذلك (صيانة) أي: محافظة (لشرع) إلهي محمدي (طاهر) أي: نظيف نقي من كل دنس وعيب. (فلا يقر) بالبناء للمفعول، أي: لا يترك ولا يهمل أحد (ظاهر) بين الناس متجاهر بذلك بين عوام المؤمنين (في الميل) أي: العدول (عنه) أي: عن الشيء الظاهر الذي تفهمه عوام المسلمين (وذا) أي: هذا القول (أمر) صعب (طويل الذيل) فيه تفاصيل واختلاف بين العلماء.\rوالذي عليه فقهاء الحنيفة وجوب التأويل في مثل ذلك وحمله على المحامل الحسنة، قال في شرح الدرر والغرر: ثم إذا كان في المسألة وجوه توجب الإفكار ووجه واحد يمنعه يميل العالم إلى ما يمنعه ولا يرجح الوجوه على الواحد، لأن الترجيح لا يقع بكثرة الأدلة والاحتمال أنه الوجه الذي لا يوجب الإكفار.\rوذكر في شرح الكنز المسمى بالبحر الرائق قال: والذي تحرر أنه لا يفتي بتكفير مسمل أمكن حمل كلامه على محمل حسن أو كان في كفره اختلاف ولو على رواية ضعيفة فعلى هذا فأكثر ألفاظ التفكير المذكورة لا يفتي بالتفكير بها، ولقد ألزمت نفسي أن لا أفتي بشيء منها، وإلى هنا انتهى كلامه رحمه الله تعالى وتبعه التمرتاشي رحمه الله تعالى في متن تنوير الأبصار فحكم مثل ذلك.\rوذكر من أئمة الشافعية الشيخ النووي رحمه الله تعالى في آداب العالم والمتعلم من مقدمة شرح المهذب قال: يجب على الطالب أن يحمل كلام إخوانه على المحامل الحسنة في كل كلام يفهم منه نقص إلى سبعين محملا، ثم قال: ولا يعجز عن ذلك إلا كل قليل التوفيق.\r(وليس يقتدي) بالبناء للمفعول، أي: لا يقتدي أحد (بهم) أي: المتكلمين بالكلام الذي ظاهر معناه مخالف لظاهر الشرع (في ذلك) بالسكون للوزن، أي: الكلام الذي قالوه (لكونه) أي: ذلك الكلام (من أصعب المسالك) بالسكون أيضا أي: الطرق التي يسلكها المكلف لدقة المعاملة التي عليها أهل ذلك القام وعسر إدراكها على العقول القاصرة والأفهام عن كمال عزة حال الشهود والإلهام."], [59, "والحزم أن يسير من لم يعلم ... مع رفقة مأمونة ليسلم\rويسلك المحجة البيضا ... فنورها للمهتدي استضا\rوفي بينات الطريق يخشى ... سار ضلالا أو هلاكا يغشى\rأمننا الله من الآفات ... في الدين والدنيا إلى الوفاة\r[الشرح]\r(والحزم) يقال: حزم فلان رأيه حزما، أتقنه كذا في المصباح. وفي القاموس: الحزم ضبط الأمر والأخذ فيه بالثقة وحزم ككرم فهو حازم وحزيم (أن يسير) أي: يسلك في جميع الأحوال (من لم يعلم) بسكون الميم أو حركتها بالكسر، أي: الذي لا علم عنده بأسرار النفوس الإنسانية وأنوار القلوب الروحانية. (مع) بسكون العين المهملة لغة في فتحها (رفقة) اسم للجماعة ترافقهم في سفرك فإذا تفرقتهم زال اسم الرفقة وهي بضم الراء في لغة بني تميم وبكسرها في لغة قيس كذا في المصباح. (مأمونة) أي: عند الأمان من الهالك الظاهرة (ليسلم) بالسكون أو الكسر.\r(ويسلك المحجة) أ]: الطريق (البيضا) أي: الواضحة عند كل أحد بحسب ظاهر الحال، والله أعلم بما تضمر النفوس من هذاية أو ضلال، فإن المتمسك بالظاهر متقيد بإصلاح مطارح الأنظار لا يمكنه الالتفات مع ذلك إلى موضع نظر الرب سبحانه من طوايا الأسرار فهو معرض عن محل رجاه وخوفه وما جعل الله لرجل من قلبين في جوفه.\r(فنورها) أي: تلك الحجة. (للمهتدي) أي: طالب الهداية (استضا) أي: أنار وأشرق (وفي بينات) بصيغة التصغير (الطريق) قال في الصحاح: بنيات الطريق الترهات وهي جمع نزهة كمقبرة بضم التاء المثناة وتشديد الراء المفتوحة الباطل، يعني: في اتباع الأمور التي ظاهرها باطل وفاسد وضلال (يخشى) أي: يخاف (مار) فاعل يخشى أي: سالك (ضلالا) مفعول يخشى، أي: حيرة واندهاشا (أو هلاكا) موصوفا بأنه (يغشى) أي: من غشيته أغشاه من باب تعب أتيته كذا في القاموس.\r(أمننا) معشر المكلفين، أي: أعطانا الأمان (الله) تعالى 0 من جميع) (الآفات) أي: المهالك (في الدين) أي: الاعتقاد والعمل (و) في (الدنيا) أي: الأحوال المعاشية والبدنية والمالية (الوفاة)] أ: حلول الأجل المحترم."], [60, "وواجب وحدة الجلال ... في الذات ولصفات والأفعال\rلأنه لو انفت عنه عدم ... صنع من التمانع الذي علم\rونفي تأثير عن الأسباب ... يعلم من برهان هذا الباب\r[الشرح]\r(و) الصفة السادسة (واجب) عقلا يتصور لا يتصور في العقل عدمه (وحدة) مصدر وحد بالضم وحادة ووحدت فهو وحيد (ذي) أي: صاحب (الجلال) أي: العظمة والهبية وهو الله تعالى، أي كونه واحدا (في الذات) العلية، أي: لا تركيب فيها ولا قبول انقسام ولا تجرؤ ولا تبعيض (و) في (الأفعال) أي: كل فعل من أفعاله تعالى لا يشاركه فيه غيره ولا يساعده فيه مساعد ولا يعنيه في معين بل الجميع أفعاله سبحانه وتعالى لا يشاركه فيه غيره ولا تأثير معه لشيء أصلا، يخلق الأسباب ويخلق المسببات عندها لا بها ولا فيها ولا منها، وكل شيء مفتقر غليه ابتداء ودواما (لأنه) أي: الله تعالى (لو) فرضنا أنه (انتفت) أي: الوحدة المذكورة (عنه) سبحانه (عدم) بالبناء للمفعول وسكون الميم للوزن (صنع) أي: خلق وإيجاد الشيء من الأكوان (من) أجل (التمانع الذي علم) بالبناء للمفعول، أي: علمه كل عاقل وهو مذكور في كتب وهو مذكور في كتب علم الكلام والميم ساكنة للوزن، والتمانع يكون بين الإلهين الخالقين لأنه تفاعل كل واحد منهما يمنع صاحبه فإن قدر كل واحد منهما على منع صاحبه عن خلق شيء ويجاده فكل منهما عاجز أيضا حتى يقدر أحدهما أو يعجز الآخر فيوجد شيء من الأكوان، والأكوان موجودة عن قادر والقادر واحد على كل حال.\r(ونفي تأثير) أي: إيجاد أو عدم (عن الأسباب) الموضوعة في الأكوان ن الأكوان، والأسباب جمع سبب، وهي ثلاثة أقسام:\rأسباب عقلية: كترتيب المقدمات لحصول النتيجة والتفات العقل إلى الأمور الخيالية والحية لتحصل الإدراك، واستعمال قوى الحواس الباطنية والظاهرية لحصول الانطباعات فيها تأتي المذكور في علم الكلام.\rوأسباب شرعية: كأنواع العبادات والطاعات ليحصل الثواب في الآخرة ومنع العقاب، وتوجه رضوان الله تعالى، وكأنواع الكفر والعصيان والفسوق لترتب العقاب في الآخرة، وتوجه غضب الله تعالى وحصول التقليب في الدنيا بالألقاب الحسنة كالمؤمن والمسلم والصالح والالقاب القبيحة كالكافر والمشرك والفاسق والعاصي وأسباب عادية"], [61, "كالماء للرّيّ وكالسكين ... والنار في القطع وفي التسخين\rوقدرة العبد وغير ذلك ... فالكل خلق للقدير المالك\rوماله فيه صنعه من مثل ... وليس للعبد اختراع فعل\rنعم له كسب به يكلف ... شرعا ولا تأثير منه يؤلف\rولتحذر النسج على منوال ... ما خالف المذكور من أقوال\r[الشرح]\rكالنار للحرق والإنضاج والثوب للستر والدفء والماء للري والأكل للشبع والسكين للقطع ونحو ذلك فإنه عدم تأثير شيء من ذلك.\r(يعلم) بالبناء للمفعول (من برهان هذا الباب) أي: برهان التمانع المذكور في وحدة الأفعال، ثم ذكر نوعا من ذلك فقال: (كالماء) فإنه سبب (للري) بالكسر اسم من روى كعلم يروي من الماء ريا بالفتح فهو ريان والمرياة كذا في المصباح. (وكالسكين) بالكسر والتشديد سمّي بذلك لأنه يسكن حركة المذبوح كذا في المصباح. (و) مثل (النار) أيضا (في القطع) راجع إلى السكين (وفي التسخين) راجع إلى النار بطريق اللف والنشر المرتب.\r(و) مثل (قدرة العبد) على جميع ما يصدر منه من الأفعال في ظاهره وباطنه، وفي معنى العبد جميع الحيوانات والنباتات والجمادات والجن والملائكة كما قال تعالى: {إِنْ كُلُّ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ إِلَّا آتِي الرَّحْمَنِ عَبْدً} [مريم: 93]. الآية. (وغير ذلك) بسكون الكاف للوزن من أنواع الأسباب العادية، (فالكل) أي: أنواع الأسباب كلها (خلق)] أي: القادر على كل شيء (المالك) بالسكون وهو الله تعالى (وما له) سبحانه وتعالى (في صنعه) أي: خالقه وإيجاده لجميع الأسباب ومسببتها. (من مثل) بسكون الثاء المثلثة، أي: مثيل بمعنى مماثل ومشابه له (وليس للعبد) المخلوق (اختراع) أي: إيجاد (فعل) أي: منفعل من المنفعلات مطلقا فلا تأثير له في أثرها.\r\r(نعم) بالفتح فالسكون كلمة تصديق (له) أيك للعبد (كسب) أي: نسبة فعل إلى قدرته وإرادته المخلوقتين فيه. (به)] أ: بسبب ذلك الكسب (يكلف) بالبناء للمفعول، أي: يصير مكلفا مأمورا منها (شرعا) أي: من جهة الشرع (ولا تأثير منه) أي: من ذلك العبد في شيء من أفعاله ظاهرا وباطنا (يؤلف) بالبناء للمفعول، أي: يعهد ويؤنس بذلك منه.\r(ولتحذر) يا أيها المكلف (النسج على منوال) كناية عن الاتباع والاقتداء بكل (ما خالف) هذا القول (المذكور من أقوال) مختلفة من أهل السنة وغيرهم وهي خمسة أقوال وقد جمعناها في رسالة سميناها الكوكب الساري في حقيقة الجزء الاختياري."], [62, "والله عن أفعاله لا يسأل ... والقدري لم يقل ما يعقل\rوجوّز البعض دليل السمع ... في وحدة وقيل ذا ذو منع\r[الشرح]\r(والله عن أفعاله) أي: عن منفعلاته الصادرة عنه سبحانه وتعالى التي منها جميع العباد المكلفين، وجميع أعمالهم وأحوالهم في ظواهرهم وبواطنهم (لا يسأل) أي: لا يقال له لم خلقت العبد وخلقت له قدرة وإرادة العمل الفلاني ثم خلقت له العمل الفلاني على طبق قدرته عليه وإرادته له كما قال تعالى: {لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُو} [الأنبياء: 23]. أي: إنما يسأل عما يفعل العبد الكلف الذي خلق الله تعالى العمل ليكون وصفا له، فإن الخالق سبحانه لا يوصف بما يخلقه من الأوصاف، فإن خالق البياض في القرطاس مثلا لا يوصف بأنه أبيض، وإنما يوصف بذلك القرطاس، فلو خلق في القرطاء قدرة عليه وإرادة له لكان ذلك كسبا منه فلما لم يخلق القدرة والإرادة في القرطاس كان ذلك جبرا فيه وليس العبد المكلف كذلك بل به كسب ولا جبر فيه، والقدرة المخلوقة في العبد على طبق إرادته المخلوقة في كناية عن قوتين عرضيتين تظهران في القلب وتنتشران في الأعضاء فيخلق الله تعالى عندهما لا بهما ولا فيهما ذلك الأمر الذي توجهتا عليه فينسب إليها بحسب الظاهر أنه كسبهما، والكل خلق الله تعالى على كل حال ولا يتصور الجبر في ذلك لأن العبد ليس منه ممانعة أصلا ولا في خلق الإرادة فيه والقدرة بل فيه القبول لكل ما يخلق الله تعالى فيه والقبول ينافي الجبر على مالا يخفى (والقدري) أي: المنسوب إلى مذهب القدرية من المعتزلة، ومذهبهم أن لهم قدرة يخلقون بها أعمالهم التي تعلقت بها إرادتهم (لم يقل ما) أي: قولا (يعقل) لأنهم يدعون التوحيد ويعتقدون الشرك مع الله تعالى في الخلق والإيجاد، فلو كانت لهم قدرة مؤثرة كما زعموا لمنعوا بها عن أنفسهم الأوجاع والأمراض، وجلبوا بها لنفسوهم المقاصد والأغراض، ودفعوا بها عنهم الموت، ولم يدركهم بها الانقضاء ولفوت، ولكن عقولهم مغرورة، ونفوسهم مغمورة، وقلوبهم بذكر الله تعالى غير معمورة.\r(وجوز) أي: صحح (العض) من العلماء إقامة (دليل السمع) أي: من الآيات القرآنية والأحاديث النبوية حجة الخصم القدري وغيره لأنه مؤمن بالدين والشرع (في) إثبات (وحدة) أي: وحدانية الله تعالى وأن لا مؤثرة سواه تعالى في كل شيء بقوله تعالى سبحانه: {اللَّهُ خَالِقُ كُلِّ شَيْءٍ} [الرعد: 16] وقوله: {وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96]. ونحو ذلك (وقيل ذا) أي: دليل السمع (ذو) صاحب (منع) أي: يمتنع"], [63, "فتلك من صفاته القدسية ... ست وأولاها هي النفسية\rأعني الوجود والبواقي الخمس ... سلبية وما بذاك لبس\rلسلبها عن الإله ما لا ... يليق واقتضائها كمالا\rوكل وصف واجب للذات ما ... دامت بلا زيد لنفس انتمى\rومن يرى الوجود عن الذات ... كالشيخ لم يعدده في الصفات\r[الشرح]\rالاستدلال به والاحتجاج في إثبات الوحدانية، لدخول القدرية وغيرهم من فرق المعتزلة بعقولهم الفاسدة، وأفهامهم الكاسدة، في تحريف معاني الكتاب والسنة على حسب مذهبهم، وجعلهم ما فهموه من ذلك شبها طرقت الأدلة السمعية، فلم تبق قطعية الدلالة عندهم على مقاصد أهل السنة والجماعة، وإنما يقع الاحتياج عليهم بالأدلة العقلية، والبراهين النظرية، وهي فيهم أقوى أمر وأقوم قضية.\r(فتلك) أي: التي ذكرت (من صفاته) أي: الله تعالى (القدسية) المنسوبة إلى القدس، وهوا لطهارة، ويقال: وتقدس الله تعالى، أي: تنزّه (ست) من الصفات وقد من بيانها. (وأولاها) أي: الصفة الأولى منها (هي) الصفة (النفسية) المنسوبة إلى النفس (أعني) صفة الوجود الله تعالى في الصفات (البواقي) بعد صفة الوجود (الخمس) هي صفات (سلبية) منسوبة إلى سلب أمر لا يليق بالله تعالى (وما بذاك) الشيء المذكور (لبس) أي: التباس على أحد من الناس لوضوحه وانكشافه، ثم قالك في علة سميتها سلبية (لسلبها) أي: نفيها (هن الإله) الحق سبحانه وتعالى (ما لا يليق) به من الأمور المستحيلة عليه تعالى مما سبقت الإشارة غليه (واقتضائها) في ضمن ذلك (كمالا) تليق بالله تعالى (وكل وصف) من الأوصاف (واجب للذات) أي: ذات الموصوف به (ما دامت) أي: الذات وما مصدرية ظرفية يعني مدة دوامها أي: بقائها ودام هنا تامة فتكتفي بمرفوع ولا تحتاج إلى منصوب لأنها ليست بناقصة (بلا زيد) أي: زائدة على ذات الموصوف بها القديمة وهو مصدر زاد يزيد. قال الجوهري في الصحاح: زاد الشيء يزيد زيدا وزيارة، أي: ازداد. (لنفس انتمى) انتسب ولهذا يقال وصف نفسي وصفة نفسية.\r(ومن يرى) أي: يعتقد ويقول إن (الوجود) في كل موجود (عين الذات) الموصوفة فيه (كالشيخ) أبي الحسن الأشعري رضي الله عنه ومن تابعه (لم يعدده)] أ: لوجود (في الصفات) إذ لم تعتبر فيه المغايرة بينه وبين الذات أصلا ولا بد في أوصاف الذات من مغايرتها."], [64, "وقد أشرنا للمحال وهو ما ... نافى التي وجوبها تقدما\r\rفصل في بيان صفات المعاني\r\r"]], "pg": [45, 64]}, "496.8": {"x": [[64, "والعلم والحياة والقدرة مع ... إرادة الله بها العقل قطع\rلأنها لو انتفت لما وجد ... شيء من الصنع الذي لها شهد\r[الشرح]\r(وقد أشرنا للمحال) أي: ما يستحيل في حق الله تعالى (وهوما) أي: الذي أ كل وصف (نافي) أي: كان منافيا للصفات (التي وجوبها) في حق الله تعالى (تقدما) بألف الإطلاق أي سبق ذكره واندرج في ضمنه ذكر ما ضمنه ذكر ما يستحيل في حق الله تعالى لأنه ضد فلا حاجة إلى إعادته ثانيا هنا.\r\r(فصل في) بيان (صفات المعاني) أي: التي لها معان زائدة على\rقياسها بذات الموصوف بها\r\r(و) هي سبع صفات الصفة الأولى (العلم) أي: العلم من أوصافه تعالى العلم، وهو صفة أزلية قائمة بذاته تعالى ينكشف بها ما تعلقت به من الموجودات والمعدومات القديمة والحادثة انكشافا تاما لا يحتمل التبعيض (و) الصفة الثالثة (القدرة) وقي صفة أزلية تؤثر في الممكنات عند تعلقها بها (مع) بالسكون (إرادة الله) تعالى وهي الصفة الرابعة وهي صفة أزلية الله تعالى تقتضي تخصيص الممكنات ببعض ما يجوز عليها من الأوصاف والأوقات والمقادير وغير ذلك (بها) أي: بهذه الصفات الأربع المذكورة يعني ثبوتها لله تعالى (العقل قطع) بالسكون للوزن أي: حكم وجزم من غير تردد ما.\r(لأنها) أي: الصفات المذكورة (لو انتفت) أو إحداها ع عن الله تعالى (لما وجد) بالسكون للزن (شيء من الصنع) أي: المصنوع كالخلق بمعنى المخلوق (الذي لها) أي: الصفات المذكورة (شهد) فجميع المخلوقات شواهد على أن الله تعالى موصوف بالحياة والعلم والإرادة والقدرة، فهم تعالى حي يعلم أشياء فيريدها وهو قادر عليها فتوجد، فلو لم يكن حيا لما كان عالما ولا مريدا ولا قادرا، ولو لم يعلم لما أراد ولا قدر لخفاء"], [65, "وبعض من ينمى له الإيقان ... قال دليل علمه الإتقان\rلأن هذا العالم الذي ظهر ... إحكامه كل العقول قد بهر\rسبحان من أودعه إذ ابدعه ... من حكم جليلة ما أودعه\rوقد مضى ذكر لبعض ما اشتمل ... عليه إجمالا بما النظم احتمل\rوالسمع والإبصار والكلام ... جابها النقل ولا ملام\r[الشرح]\r(وبعض من ينمى) بالبناء للمفعول، أي: (له الإيقان) أي: اليقين في الدين (قال دليل) ثبوت (علمه) تعالى (الإتقان) من أتقن: الأمر أحكمه.\rقال إمام الحرمين في الإرشاد: إذا تقرر أن الباري تعالى صانع العالم واستبان للعقال لطائف الصنع وأحاط بما تتصف به السماوات والأرضون وما بينهما من الاتساق والانتظام والاتقان والإحكام فيضطر إلى العلم بأنها لم تحدث إلا من عالم بها قادر عليها ول يستريب اللبيب في امتناع الاختراع من الموتى والجمادات والعجزة وكذلك يعلم كل عاقل على البديهة أن الفعل الرصين المحكم المتين يستحيل صدوره من الجاهل به، ومن جوز وقد لاحت له أسطر منظومة، وخطوط متسقة مرقومة، صدورها من جاهل بالخظ كان عن المعقول خارجا، وفي تيه الجهل والجا.\r(لأن هذا العالم) بفتح اللام المحسوس والمعقول (الذي ظهر) بالسكون للوزن (إحكامه) بكسر الهمزة، أي: إتقانه وانتظام أحواله (كل العقول) البشرية وغيرها (قد بهر) بالسكون أيضا، أي: بهره بهرا من باب غلبه (سبحانه من) أي: الإله الذي (أودعه) بالسكون أيضا الذي أودعه مفعول أودعه الأول (وقد مضى) في هذه المنظومة قوله فإن نظرت في السماوات العلا إلى آخر الأبيات الثانية في آخر فصل الحث على النظر (ذكر لبعض ما اشتمل) بالسكون للوزن، أي: هذا العالم (عليه إجمالا) بطريق الإجمال (بما) أي: بحسب الذي له (النظم احتمل) من السنية على بدائع الصنع والإتقان بقدر الإمكان، والله المستعان.\r(و) الصفة الخامسة (السمع) وهو صفة أزلية قائمة بذات الله تعالى تتعلق بجميع المسموعات. (و) الصفة السادسة (الإبصار) بكسر الهمزة مصدر أبصر، وهو صفة أولية قائمة بذات الله تعالى تتعلق بجميع المبصرات. (و) الصفة السابعة (الكلام) وهو صفة"], [66, "إذ كل ما لم يتوقف شرع ... عليه فالدليل فيه السمع\rوعكسه ممتنع للدور ... فاقطف بأيد الفهم أبهى النور\rوقيل لو لم يتصف بها لزم ... وصف بأضداد بنقضها جزم\r[الشرح]\rأزلية قائمة بذات الله تعالى تدل عليها العبارات وما يصطلح عليها من الإشارات تتعلق بجميع ما يتعلق به العلم (جابها) أي: بهذه الصفات الثلاث (لنقل) من خصوص الكتاب والسنة وأجمعت عليها الأمة قال تعالى: {وَهُوَ السَّمِيعُ الْبَصِيرُ} [الشورى: 11]. وقال تعالى: {وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا} [النساء: 164]. إلى غير ذلك. (ولا ملام) في الاستدلال على ذلك بالأدلة السمعية دون الأدلة العقلية.\r(إذ كل ما) أي: مطلوب (لم يتوقف شرع عليه) أي: لم يحتج إليه ثبوت الشرع فثبت الشرع ولو لم ....... (¬1)\rكهذه الصفات الثلاث (فالدليل فيه السمع) أي: يجوز الاستدلال عليه بالأدلة السمعية، بخلاف ما يتوقف عليه ثبوت الشرع كالصفات الأربع التي قبل هذه الثلاث، فإن ثبوت الشرع متوقف عليها فإن خلق المعجزات وإيجادها ما يستلزم اتصاف الخالق والموجد لها بالحياة والعلم بما يخلق ويوجد وإرادة ذلك والقدرة عليه، ثم إن المعجزات تدل على صدق الرسول لأنها تصديق من الله تعالى فيما يدعيه من التبليغ عنه ومن جملة ذلك أدلة السمع، فأدلة السمع موقوفة في ثبوتها على ثبوت الصفات الأربع المذكورة فكيف يكون ثبوت الصفات الأربع أيضا موقوفا على أدلة السمع للزوم الدور حينئذ وهو قوله:\r(وعكسه) أي: كل ما يتوقف عليه ثبوت الشرع (ممتنع) الاستدلال عليه بالأدلة السمعية (للدور) اللازم حينئذ كما ذكرنا (فاقطف) أي: تناول (بأيدي الفهم أبهى النور) بفتح النون الزهر. قال في المصباح: نور الشجرة مثل فاس زهرها، والنور زهر النبت أيضا الواحدة نورة مثل ثمر وثمرة.\r(وقيل) في الدليل العقلي على هذه الصفات الثلاث (لو لم يتصف) أي: الله تعالى (بها) أي: بهذه الصفات الثلاث المذكور (لزم) بالسكون للوزن (وصف) لله تعالى (بأضداد) لها وهي الصمم صد السمع، وهي الصمم ضد السمع، والعمى ضد البصر، والبكم ضد الكلام.\r¬__________\r(¬1))) كلمة غير واضحة بالأصل."], [67, "وفيه بحث برقة قد أومضا ... بعكس وحدانية كما مضى\r[الشرح]\r(بنقضها) أي: هذه الأضداد (جزم) بالبناء للمفعول وبالسكون للميم وهذه الأضداد نقائص والنقص على الله محال.\rوقال الشيخ الأكبر محيي الدين بن العربي رضي الله عنه في مثل هذا المقام، من أحسن الكلام: لو لم يبصرك ولو لم يسمعك لجهل كثير منك ونسبة الجهل إليه محال فلا سبيل إلى نفي هاتين الصفتين عنه بحال.\r(وفيه) أي: هذا الاستدلال العقلي (بحث) للعلماء (برقة قد أومضا) أي: لمع وظهر. وبيانه أن علماء الكلام قد اختلفوا في السمع الإلهي والبصر الإلهي على ثلاثة أقوال حررناها في كتابنا المطالب الوفية. وملخصها أن بعضهم قال: إنهما ليسا عين العلم وكذا كل واحد منهما ليس عين الآخر، وهو قول الأشعري الأول وهو الحق وعليه فيتم الاستدلال بما ذكر من الدليل العقلي لأن انتفاءهما يلزم منه ثبوت نقيضهما المقتضي لعدم الكشفين الخاصين المستقلين المذكورين وذلك نقص في حق الله تعالى والنقص عليه محال.\rوقال بعضهم: إنهما نوعان من الانكشاف العلمي خاصان كل انكشاف منهما يغاير الانكشاف الآخر، ويغايران الانكشاف المطلق العلمي كمغايرة النوع للجنس بالخصوصية، فالسمع علم مخصوص، والبصر علم آخر مخصوص، ومطلق العلم هو الجنس الشامل للكل وهو قول الشيخ الاشعري أيضا في الرواية الثانية عنه.\rوعلى هذا القول لا يلزم من ثبوت يقيضهما انتفاء مطلق الكشف العلمي التام فإن الخصوصية إذا زالت عن مطلق الجنس لا يلزم من ثبوت الجنس لا يلزم زوال الجنس، ولا يلزم من فوات الخصوصية لفوات الأنواع فوات الكمال في الجنس لا يلزم زوال الجنس، ولا يلزم من فوات الخصوصية لفوات الأنواع فوات الكمال في الجنس الثابت، إذ الخصوصية قد تكون بالانكشاف الأدنى كما يكون بالانكشاف في الأعلى فلا يتم الدليل العقلي فإنه لا يقاس الكمال الإلهي على الكمال الإنساني كما نقل الخلخالي في بعض رسائله عن بعض اهل البيت النبوي أنه قال في جملة كلام له في الإله تعالى: ولعل النمل الصغار يتوهم أن الله زبانين فإن ذلك كمالها ويتوهم أن عدمها نقصان بل لا يتصف بهما ولا يكونان له وهذا حال العقلاء فيما يصفون الله تعالى به."], [68, "وأثبت الإدراك قوم واكتفى ... بالعلم نافيه وبعض وقفا\r[الشرح]\rوفي القاموس زبانا العقوب: بالضم قرناها. انتهى. والقول الثالث: إنهما عين العلم لا قدر زائد عليه، فإن انكشفت بهذه الصفات خفايا الأمور سمّيت علما، وإن انكشفت بها الظواهر فلك تسميتها علما أو سمعا أو بصرا، ولا يصح الدليل العقلي على هذا أيضا.\rوأما صفة الكلام الإلهي فلا يلزم من انتفائها عنه تعالى ثبوت البكم؛ لأن البكم هو عدم الكلام اللفظي المستحيل عليه سبحانه وتعالى لا عدم الكلام النفسي الثابت له تعالى الذي ليس بحروف ولا أصوات فلا يتم الدليل العقلي في ثبوته أيضا، كما أن الصم هو نقيض السمع المخلوق الذي هو بقوة عرضية وصماخ وأذن والعمى نقيض البصر المخلوق الذي هو قوة عرضية وحدقة وعين وذلك كله محال في حق الله تعالى ولهذا كان الدليل السمعي في إثبات هذه الصفات الثلاثة أتم وأكمل من الدليل العقلي لعدم النزاع فيه بين المؤمنين. وإنما يذكر الدليل العقلي تأييدا له وتأكيدا بعده (بعكس) الدليل العقلي المذكور في ثبوت (وحدانية) لله تعالى وبرهان التمانع (كما مضى) في النظم بطريق الإشارة غليه وسبق تقريره فإنه قوي لا يرد عليه شيء ولا فيه كلام للعقلاء ولا بحث.\r(وأثبت) صفة (الإدراك) لله تعالى (قوم) من المتكلمين أي: كونه تعالى يدرك المشمومات والمذوقات والملموسات بصفة زائدة على العلم (واكتفى بالعلم نافية) أي: الإدراك (وبعض) من العلماء (وقفا) بألف الإطلاق، أي: لم يثبته ولم ينفه. والحاصل أن للعلماء في ذلك ثلاث أقوال: الاتصاف وعدمه والوقف.\rأما الاتصاف فقد ذهب إليه القاضي الباقلاني وإمام الحرمين ومن وافقهما، قال اللقاني رحمه الله تعالى في شرح الجوهرة: يجب أن يثبت له تعالى صفة أزلية قائمة بذاته تعالى زائدة على صفة العلم والسمع والبصر اسمها الإدراك متعلقة بالملموسات والمشمومات والمذوقات من غير اتصال بها ولا تكيف بكيفياتها وهي كمالات وكل حي قابل لها، فإذا لم يتصف بها اتصف بها اتصف بأضدادها وأضدادها نقص لأن معها فوت كمال والنقص في حقه تعالى محال فوجب أن يتصف بها زائدة على علمه تعالى.\rوأما عجم الاتصاف بها فقد ذهب إليه الأستاذ أبو إسحاق الإسفرايني وجمع من الأئمة وجعلوا الإحاطة بمتعلقاتها داخلا في علمه تعالى، ولا يلزم من كونه صفة كمال في الشاهد أن تكون في الغائب كذلك."], [69, "واعلم بأن هذه المعاني ... لها وجود خارج الأذهان\rولا يقال إنها عين ولا ... غير لذات فاعرف المعوّلا\rوانسب لكلها سوى الحياة ... تعلقا وشرحة سياتي\rفكل ممكن تعلقت به ... إرادة وقدرة فانتبه\rفإن يكن علم بنيفه جرى ... ففي تعلق به خلف سرى\rمثاله الإيمان من أبي لهب ... ولبعض للتوفيق في ذاك ذهب\r[الشرح]\rوأما الوقف على القول بثبوته وانتفائه ن غير جزم بأحدهما فهو مختار ابن المقترح وابن التلمساني وبعض المتأخرين.\r(واعلم) يا أيها المكلف (بأن هذه) الصفات السبعة المتفق عليها عقلا وشرعا أو عقلا في البعض شرعا في البعض المسماة صفات (المعاني لها) في أنفسها (وجود) زائد على قيامها بذات الله تعالى (خارج الأذهان) جمع ذهن، وهو: الذكاء والفطنة كذا في المصباح.\r(ولا يقال) فيها (إنها عين ولا) يقال أيضا إنها (غير لذات) الله تعالى (فاعرف) أيها المكلف القول (المعولا) بألف الإطلاق، أي: الذي عول عليه، أي اعتمد المحققون. قيل: أهي عين ذات الله تعالى وعليه الفلاسفة نفاة الصفات والمعتزلة مثبتو الأحوال فقط ككونه حيّا وعالما، وقيل: هي عين الذات غيبا وغير عقلا وشرعا وهو مذهب الصوفية، وبعض الصوفية يطلق عليها أنها عين مع إثباتها شرعا، والمشهور الأول وهو مذهب الأشعري وأئمة الكلام.\r(وانسب) أيها المكلف (لكلها) أي: الصفات المذكورة (سوى) صفة (الحياة) الإلهية (تعلقا) أي: اقتضاء أمر زائد على قيامها بذات الله تعالى (وشرحه) أي: التعلق يعني بيانه (سيأتي) ف النظم إن شاء الله تعالى (فكل) أمر (ممكن) يصح في العقل وجوده وعدمه (تعلقت به) أي: اقتضت إيجاده أو إعدامه (إرادة 9 الله تعالى (وقدرة) له سبحانه (فانتبه) فعل أمر من الانتباه، ضد الغفلة وكسر الهاء للوزن.\r(فإن يكن) أي: ذلك الممكن (علم) لله تعالى (بنفيه) أي: بأنه لا يكون (جرى ففي تعلق) القدرة والإرادة (به خلف) أي: اختلاف (سرى) بين العلماء (مثاله الإيمان) الممكن وقوعه (من ابي لهب) بسكون الباء للوزن، وهو ابن عبد المطلب أخو عبد الله"], [70, "أي من يرى تعلقا به اعتبر ... إمكانه الأصلي مع قطع النظر\rعن غيره وما نفاه راعى ... تعلق العلم به امتناعا\rوالسمع والإبصار الموجود قد ... تعلقا لا غير عند من نقد\r[الشرح]\rوالد نبينا محمد صلى الله عليه وسلم وكان اسمه عبد العزى، فإنه لم يؤمن علم الله تعالى ما تعلق بإيمانه فمات كافرا وكان يؤذي النبي صلى الله عليه وسلم وهو عمه أخو أبيه حتى أنزل الله تعالى فيه وفي زوجته سورة في القرآن: {تَبَّتْ يَدَا أَبِي لَهَبٍ} [المسد: 1] إلى آخرها وقد كان في الدنيا مكلفا بالإيمان وإيمانه ممكن، فحقه أن تتعلق وإيمانه ممكن، فحقه أن تتعلق به القدرة والإرادة على طبق العلم، لكن امتناع وقوعه تعلق العلم الإلهي به فلزم من ذلك أن القدرة والإرادة لم يتعلقا به لم يقع منه، وليس امتناع وقوعه لذاته كوجود الشريك لله تعالى فإنه ممتنع لذاته فهو مستحيل فيتعلق بامتناعه العلم فلا تتعلق به القدرة والإرادة والحاصل أن الممكن على قسمين:\rالأول: ممكن تعلق علم الله تعالى بوقوعه، وممكن تعلق عليمه تعالى بعدم وقوعه في الأول تعلق القدرة به والإرادة بلا خلاف.\rوالثاني: في تعلق القدرة والإرادة به خلاف، فقال بعضهم يتعلقان به لأنه ممكن وهما يتعلقان بكل ممكن، أي: يصلحان للتعلق به فمنع وجوده ليس من جهتهما بل من جهة تعلق العلم بعدو وجوده، وقال بعضهم: لا يتعلقان به لأن تعلقهما تابع لتعلق العلم والعلم يتعلق بعدم وجوده كتعلقة بالمستحيل (والبعض) من العلماء وهو أبو حامد الغزالي حجة الإسلام رحمه الله تعالى (للتوفيق في ذاك) الخلاف بين القولين (ذهب) حيث قال: (أي من يرى) يعني: يعتقد (تعلقا) للقدرة والإرادة (به) أي: بذلك الممكن الذي علم الله تعالى عدم ووجوده (اعتبر) بالسكون للوزن (إمكانه) أي: مجرد كونه ممكن يصح في العقل وجوده وعدمه (الأصلي) أي: المنسوب إلى الأصل؛ لأن إمكان الممكن من ذاته التي هي أصله (مع قطع النظر) بالسكون أيضا (عن غيره) أي: غير الممكن، فإن الامتناع فيه أتاه من قبل غيره وهو تعلق العلم الأزلي بعد وقوعه وقد قطع النظر عن جهة امتناعه (ومن نفاه) أي: تعلق القدرة والإرادة بالممكن الذي علم الله تعالى عدم وقوعه (راعي) أي: اعتبر (تعلق العلم) الإلهي (به امتناعا) أي: على وجه امتناعه، يعني عدم وقوعه.\r(والسمع) الإلهي (والإبصار) بكسر الهمزة الإلهي أيضا (بالموجود) الواجب والممكن (قد تعلقا) فيكشف سبحانه وتعالى بسمعه وبصره عن ذاته وصفاته وعن جميع"], [71, "وليس يستغنى بعلم عنهما ... للافتراق شاهدا بينهما\rورده بعض ذوي التحقيق ... والنظم عن تقريره ذو ضيق\rوحكم الادراك لدى من قال به ... حكمهما فلتفرغن في قالبه\rوالعلم والكلام قد تعلقا ... بواجب ومستحيل مطلقا\rوجائز فاستوعبا الأقساما ... والرب في الجميع لا يسامى\r[الشرح]\rمخلوقاته (لا غير) الموجود وهو المعدوم الممكن والمستحيل (عند من نقد) بالسكون للوزن، أي: عند النقاد من العلماء الأمجاد، وقيل: يتعلقان بالمعدوم أو الممكن أيضا كما بسطناه في المطالب الوفية (وليس يستغني) بالبناء للمفعول (بعلم عنهما) أي: عن السمع والبصر بحيث يكون كشفهما راجعا إلى كشف العلم كما قدمنا مفصلا (للافتراق) أي: حصول الفرق (شاهدا) أي: من جهة الشاهد وهو مشاهدة كل إنسان الفرق (بينهما) أي: بين العلم وبين السمع والبصر.\r(ورده) أي: هذا القول (بعض ذوي) أي: أهل (التحقيق) من العلماء وهو شرف الدين ابن التلمساني رحمه الله تعالى بأن الغائب لا يقاس على الشاهد، وإذا كان الفرق بينهما في الشاهد لا يلزم أن يكون فيه استيفاء الكلام على وجهه وقد سبق بياننا له (وحكم) صفة (الإدراك) للمشمومات والمذوقات والملموسات على حسب ما قدمناه (لدى) أي: عند (من قال به) أي: أثبته صفة لله تعالى زائدة على العلم الإلهي (حكمهما) أي: مقل حكم السمع البصر في تعلقه بالموجودات أيضا دون المعدومات (فلتفرغن) من الإفراغ. قال في المصباح: أفرغت الشيء صببته إذا كان يسيل من جوهر ذائب، يعني أفرغ حكم الإدراك المذكور. (في قابله) أي: قالب حكم السمع والبصر، وفي هذا التعبير استعارة بالكناية وهو إضمار تشبيه حكم الإدراك بالفضة والذهب أو نحوهما من المعادن الذائبة وذكر القالب تخييل الاستعارة المكنية لأنه من لوازم المشبه به والإفراغ ترشيح لأنه ملائم ذلك، وبين قال به وقالبه جناس التركيب المفروق ..\r(والعلم) الإلهي (والكلام) الإلهي (قد تعلقا بواجب) عقلي (ومستحيل) كذلك (مطلقا) أي: سواء كان الواجب ذاتا أو صفة والمستحيل لذاته أو لغيره (وحائز) وهو الممكن بأجناسه وأنواعه وأشخاصه (فاستوعبا) أي: العلم والكلام (الأقساما) بألف"], [72, "فصل في بيان الصفات المعنوية\r\r"]], "pg": [64, 72]}, "496.9": {"x": [[72, "والسبع لازمت صفات تسمى ... بالمعنوية إليها تنمى\rكون الإله عالما قديرا ... حيا مريا سامعا بصيرا\rوذا كلام والمقال حالي ... بعدها على ثبوت الحال\rواسطة بين الوجود والعدم ... ونهجها تشكو الوجى فيه القدم\r[الشرح]\rالإطلاق، أي: أقسام الحكم العقلي الثلاثة الواجب المستحيل والجائز المتقدم ذكرها وبيانها (والرب) سبحانه وتعالى (في الجميع) أي: جميع الصفات المذكورة (لا يسامى) بالبناء للمفعول، أي: لا يشاهه شيء لكماله تنزهه.\r(فصل في) بيان (الصفات المعنوية)\r\rأي: المنسوبة إلى صفات المعاني، فنسبت إليها لأنهما أصلها\r(و) الصفات (السبع) صفات المعاني المذكورة (لاءمت صفات) سبع مثلها (تسمى) بالبناء للمفعول وسكون السين المهملة وفتح الميم، أي: تدعى (بالمعنوية) أي: بصفات معنوية (إليها) أي: إلى صفات المعاني (تنمى) بالبناء للمفعول أي: تنسب وهي سبع صفات أيضا كصفات المعاني السبع المذكورة فالأولى منها:\r(كون الإله) تعالى (عالما) أي: متصفا بصفة العلم، والثانية: كونه (قديرا) أي: متصفا بصفة القدرة، والثالثة: كونه (حيا) أي: متصفا بصفة الحياة، والرابعة: كونه (مريدا) أي: متصفا بالإرادة، والخامسة: كونه (سامعا) أي: متصفا بصفة السمع، والسادية: كونه (بصيرا) أي: متصفا بصفة البصر، والسابعة: كونه (ذا) أي: صاحب (كلام) أي: متصفا بصفة الكلام (والمقال) مصدر قال بمعنى تكلم (حالي) من حلا يحلو، والحو ضد المر، والحالي هنا بمعنى الحسن (بعدها) بالتشديد، أي: حسابها وجعلها معدودة في الصفات المعنوية يعني ذكرها من جملة صفات الله تعالى, (على) حسب (ثبوت الحال) هو صفة الشيء يذكر ويؤنث كذا في المصباح. والضباط أن كل موجود له خاصية يتميز بها عن غيره فإنما يتميز بخاصية هي حال وما تماثل المتماثلات وتختلف المختلفات به فهو حال وهي التي تسمى صفات الأجناس صفات الأجناس والأنواع.\r(واسطة بين الوجود والعدم) بالسكون للوزن، وهذا قول بعضهم بأن الحال لا موجود ولا معدوم، وهو واسطة بين الوجود والعدم. وقيل: الحال موجود، وقيل: معدوم."]], "pg": [72, 72]}, "496.10": {"x": [[73, "ومن نفى الحال فقد رآها ... عبارة عن تلك لا سواها\rومثبت الإدراك يجره على ... أحكام هذه السبع مثل ما خلا\r\rفصل في بيان معنى التعلق\rواختلف الأشياخ في التعلق ... فقيل نفسي لدى التحقق\r[الشرح]\r(ونهجها) أي: طريق الحال (تشكو الوجى) بالجيم وهو الوجع، قال في الصحاح: وجى الفرس بالكسر، وهو أن يجد وجعا في حافره (فيه) أي: ذلك النهج (القدم) بالسكون أي: الرجل السالكة فيه كناية عن صعوبة مبحثه ودقة الأدلة في إثباته وفي نفيه.\r(ومن نفى الحال) كأبي الحسن الأشعري وجمهور أهل الحق (فقد رآها) أي: الحال (عبارة عن تلك) أي: عن صفات المعاني السبع التي سبق ذكرها (لا سواها) أي: أمر زائد على ذلك.\rقال اللقاني رحمه الله تعالى في شرح جوهرته: اعلم أن من إثبات الصفات المعنوية على ثبوت الأحوال معنى العالم عندهم بثبوت كونه تعالى عالما أي متصفا بالعلم عندهم وللكون عين الذات وغير الصفة بل هو ناشئ عن العالمية التي هي حال بالمعنى الذي علمت فوجب لهذا أن تقدر زائدة على صفات المعاني، ومن لم يعدها زائدة وهم نفاة الحال الذين هم جمهور أهل الحق لم يذكرها إلا لبيان وجوب قيام الصفة بالموصوف لا لكونها صفات زائدة إذ ليس في الوجود الحقيقي إلا الذات والصفة القائمة بها.\rوأما العالمية التي يبني عليها كونه عالما فلا وجود لها إلا في العقل.\r(ومثبت) صفة (الإدراك) للمشمومات والمذوقات والملموسات عند من يقول به كما قدمناه (يجره* أحكام هذه السبع) صفات المعنوية (مثل ما) أي: الذي، أو كلام (خلا) أي: مضى، يعني يقول في صفة الإدراك المذكورة كونه مدركا لما ذكر فغير، صفات المعاني ثمانية والصفات المعنوية أيضا ثمانية بإثبات صفة الحال في الإدراك كذلك.\r(فصل في) بيان معنى (التعلق) الذي لصفات المعاني المذكورة)\r\r(واختلف الأشياخ) جمع شيخ، وهم علماء الكلام (في التعلق) الذي هو للصفات، فإن الحياة لا تتعلق بشيء والقدرة والإدراك يتعلقان بالممكن فقط، والعلم، والكلام يتعلقان بالواجب والمستحيل والممكن، والسمع والبصر، والإدراك لا تتعلق بالوجود من الواجب الممكن كما سبقت الإشارة إليه. (فقيل نفسي) أي: منسوب إلى"], [74, "أي طلب الصفات زائد على ... قيامها بذات موصوف علا\rكالكشف بالعلم وكالدلاله ... من الكلام وصف ذي الجلالة\rلكن ذا القول لوصف الحال ... بالحال أفضى وهو ذو إشكال\rفي قول من للمعنوية التزام ... وبالتعلق لها أيضا جزم\rوقيل نسبة وللفخر انتمى ... ذا القول والسعد ارتضاه واعتمى\r[الشرح]\rنفس الصفة فهو ذاتي والذاتي لا يتخلف فهو واجب قديم، وقائل هذا القول هو الشيخ أبو الحسن الأشعري وعليه جماهير أهل السنة (لدى) أي: عند (التحقق) لأنه حال لازم لنفس تلك الصفة غير معلل بعلة ومثل قيام الصفة بالموصوف وصف نفسي لها أيضا (أي طلب الصفات) السبعة صفات المعاني معنى (زاد على قيامها) أي: تلك الصفات (بذات موصوف) بها وهو الله عز و (علا) مشابهة كل شيء وهذا هو معنى التعلق وقد مر بيانه.\r(كالكشف) أي: الظهور لجميع المعلومات (بالعلم) الإلهي (وكالدلالة) بسكون الهاء للوزن على جميع ما كشف عنه العلم من المعلومات (بالعلم) الإلهي (وكالدلالة) بسكون الهاء للوزن على جميع ما كشف عنه العلم من المعلومات (من الكلام) الإلهي الذي هو وصف (ذي) أي: صاحب (الجلاله) بسكون الهاء أي: للعظمة (لكن) بالتشديد (ذا القول) بأن التعلق صفة نفسية (لوصف الحال أفضى) أي: أوصل يعني مقتضاه أن يتصف الحال (بالحال وهو ذو) أي: صاحب (إشكال) يعني فيه إشكال (في قول من) أي: الذي (للمعنوية) أي: للصفات المعنوية التي هي أحوال كما مر (التزم) بالسكون للوزن، أي: قال بثبوت الأحوال (وبالتعلق لها) أي: للصفات المعنوية كصفات المعاني (أيضا جزم) بالسكون للوزن، فإن هذا القول يلزم منه قيام الحال بالحال وهو محال.\rويمكن الجواب عنه بأن التعلق إذا كان حالا نفسيا للصفة المعنوية التي هي حال أيضا كان عينها لا غيرها فمل يتصف الحال بصفة خارجة عن نفسه (وقيل) التعلق الثابت للصفات المتعلقات إنما هو (نسبة) أي: مجرد إضافة بين تلك الصفة وبين متعلقها كثبوت الفوقية للسطح بالنسبة لمن هو داخل البيت وثبوت التحتية له لمن هو فوق السطح (وللفخر) الرازي رحمه الله تعالى (انتمى) أي: انتسب (ذا القول) العلامة (السعد) أي: سعد الدين التفتازاني رحمه الله تعالى (ارتضاه) أي: هذا القول (واعتمى) أي: اختاره قال في الصحاح: اعتمت الشيء اخترته."], [75, "ومسند الأحكام للصفات ... فقط إلى المجاز ذو التفات\rوالحق أن تنسب للذات التي ... قد وصفت بذي الصفات جلت\rهذا الذي نص عليه المقترح ... وغيره والصدر من ذاك انشرح\rوقولهم سبحان من تواضعا ... كل لعزه أبى من نازعا\r[الشرح]\r(ومسند) بصيغة اسم الفاعل، أي: الذي يسند (الأحكام) جمع حكم وهو مقتضى الصفة الإلهية (للصفات) الإلهية فيقول في إسناده حكمها إليها كشف العلم الإلهي عن المعلوم وأثرت القدرة في المقدور ورجحت الإرادة هذا الوصف للمكن دون غيره من الأوصاف ونحو ذلك (فقط) أي: من غير ذكر الموصوف بها معها بأن يقال كشف الله تعالى بعلمه عن المعلوم، وأثر بقدرته في المقدور، ونحو ذلك (إلى) طريق (المجاز) في العبارة وهو استعمال اللفظ في غير ما هو له لعلاقة ما بينهما (ذو) أي: صاحب (التفات) وعلاقة المجاز هنا السبية فإن الصفة سبب الحكم إذ لولاها لما صدر ذلك الحكم عن الموصوف بها فصح نسبته إليها في قولهم كشف العلم الإلهي عن المعلوم مجاز (والحق أن تنسب) الأحكام (للذات) الإلهية (التي قد وصفت) بالبناء للمفعول (بذي) أي: بهذه (الصفات جلت) أي: بهذه (الصفات جلت) أي: عظمت وتعالت، فيقال: كشف الله تعالى بعلمه أثر بقدرته ورجح بإرادته ونحو ذلك، وهذا حقيقة الاستعمال.\r(هذا) القول هو (الذي نص عليه) الشيخ الإمام (المقترح) بصيغة اسم المفعول والحاء المهملة ساكنة للوزن وهو مظفر بن عبد الله بن علي الأصولي وهو جد الشيخ تقي الدين بن دقيق العيد لأمه مات سية ثنتي عشرة وستمائة كذا ذكره الحافظ ابن حجر العسقلاني في كتابه: نزهة الألباب في الألقاب.\rوقال السيوطي في حسن المحاضرة: المقترح تقي الدين مظفر بن عبد الله بن علي المصري ولقب بالمقترح لأنه كان يحفظه وهو كتاب في الجدل كان إماما كبيرا له التصانيف في الفقه والأصول والخلاف (وغيره) أيضا من العلماء (والصدر) أي: القلب (من ذاك) القول (انشرح) بالسكون للوزن، أي: اتسع واطمأن لكمال هذا القول وجودته (وقولهم) أي: الدعاة من عامة المؤمنين (سبحان من تواضعا) بألف الإطلاق (كل) أي: كل شيء (لعزه) أي: عظمته وهيبته بإسناد تواضع كل شيء وخضوعه إلى العز الموصوف به الله تعالى لا إلى الله تعالى الموصف لعز والجلال (أبى) أي: امتنع من"], [76, "فصل في منافيات المعاني والمعنوية\r"]], "pg": [73, 76]}, "496.11": {"x": [[76, "وما ينافي ما مضى العقل حكم ... بأنه من المحال كالبكم\rأو ما له يرجع كالثبوت ... للحرف والصوت وكالسكوت\rوإنما كلامه القديم ... ما فيه تأخير ولا تقديم\rنعم ولا لحن ولا إعراب ... أو كل أو بعض أو اضطراب\r[الشرح]\rالقول به (من نازعا) بألف الإطلاق، أي: خالف وقال: إن الأحكام لا تنسب إلا للذات الموصوفة بالصفات لا إلى الصفات فقط القائمة بالذات والله أعلم وأحكم.\r\rفصل في بيان منافيات أي: ما ينافي صفات (المعاني) والصفات المعنوية مما هو مستحيل في حق الله تعالى\r\rو كل (ما) أي: أمر (ينافي ما) أي: الذي (مضى) من صفات المعاني السبع والصفات المعنوية السبع (العقل حكم) بالسكون للوزن (بأنه من) حملة (المحال) أي: المستحيل في حق الله تعالى (كالبكم) بالسكون المنافي لصفة الكلام الإلهي.\rقال في المصباح: بكم يبكم من باب تعب يتعب، فهو أبكم أي: أخرس، وقيل: الأخرس، الذي خلق ولا نطق له، والأبكم الذي له نطق، ولا يعقل الجواب.\r(او ما) أي: الذي، أو أمر (له) أي: للبكم (يرجع) في المعنى (كالثبوت) أي: حصول النسبة (للحرف والصوت) في الكلام الإلهي فغن ذلك يقتضي البكم أيضا لأن من ضرورة الحروف ترتيبها ومن ضرورة الصوت ترتيب أجزئه أيضا وتعاقب بعضها ببعض فعند حصول كل حرف منها وكل جزء من أجزائها يحصل البكم عن الحرف الآخر بالضرورة حيث إن الترتيب يقتضي ذلك في انتظام الكلمات وتمايزها واستقامة الأصوات لبيان كيفياتها في إظهار المعاني المختلفة التي يقتضيها الكلام (وكالسكوت) الذ هو عدم الكلام مع القدرة عليه (إنما كلامه) سبحانه وتعالى (القديم) المنزه عن الحروف والأصوات (ما فيه تأخير ولا تقديم) لأنه صفة واحدة قديمة بذاته تعالى أزلا وأبدا وإنما الكثرة والتقديم والتأخير في متعلقاته التي يقع التكلم عنها كالقدرة الواحدة والإرادة الواحدة مع كثرة متعلقاتهما وترتيبها بالتقدم والتأخر من جميع الممكنات (نعم ولا) فيه (لحن) أي: مخالفة للقانون العربي وفي المصباح في كلامه لحن بسكون الحاء."], [77, "إذ كلها إلى الحدوث انتسبا ... ككون علمه علا مكتسبات\rوهو محال وكذا الجهل وما ... ضاهاه والوصف بموت أو عمى\rأو صمم وقد سما من خلقا ... عن عجزه عن ممكن ما مطلقا\rكذلك الإيجاد مع كراهته ... لفعله أعني انتفاء إرادته\r[الشرح]\rإذ أخطأ الإعراب (ولا إعراب) في موافقة لذلك القانون العربي أيضا؛ لأن ذلك من توابع الحروف والأصوات وكلام الله تعالى منزه عن ذلك كما ذكرنا (أو) له (كل) أي: مجموع مركب منه (أو لعض) كذلك (أو اضطرب) أي: اختلاف بين أبعاضه إذ لا أبعاض له من حيث هو كلام الله تعالى حتى تختلف تلك الأبعاض أو تأتلف وإنما الأبعاض متعلقاته التي وقع التكلم عنها.\r(إذ) أي: لأن (كلها) أيك جميع هذه الأمور المذكورة من البكم وما في معناه والتقديم والأخير واللحن والإعراب والكل والبعض والاضطراب (إلى الحدوث) أي: الخروج من العدم إلى الوجود (انتسبا) بألف الإطلاق والحدوث على الله تعالى وعلى صفاته محال (ككون عليمه) عزو (علا) عن مشابهة الحوادث (مكتسبا) بصيغة اسم المفعول، أي: مأخوذ من دليل أو حاصلا بواسطة جارحة (وهو) أي: الاكتساب في علمه تعالى (محال وكذا) محال أيضا في حقه تعالى الجهل المنافي للعلم (و) كل (ما) أي: أمر (ضاهاه) بالتحقيق. قال في المصباح: ضاهأه مضاهأة مهموز عارضه وباراه ويجوز التخفيف فيقال ضاهيته مضاهاة، وهي مشاكله الشيء بالشيء والذي يضاهي الجهل السهو وللهو والغفلة والذهول والشك والظن والوهم. (و) محال في حقه تعالى أيضا (لوصف بموت) وهو منافي صفة الحياة (أو عمى) وهو منافي البصر (أو صمم) وهو منافي صفة السمع وهذه المنافيات نقائض في حقه تعالى والنقص عليه تعالى محال (وقد سما) أي: ارتفع وتنزه (من خلقا) بألف الإطلاق أي: الله تعالى الموصوف بصفة القدرة (عن عجزه) سبحانه أي: عدم قدرته المنافي لقدرته عن ممكن ما يعني أي: ممكن كان جليلا أو حقيرا (مطلقا) أي: بحسب ما سيأتي.\r(كذلك) محال ف حقه تعالى أيضا (الإيجاد) لكل شيء من الأشياء أو الإعدام كذلك (مع كراهته) بسكون الهاء للوزن (لفعله) أي: ذلك الشيء (أعني) أي: اريد بالكراهة المذكورة (انتفا) بالقصر للوزن (إرادته) بالسكون أيضا يعني إرادة الله."], [78, "أو كونه طبيعة أو عله ... للخلق أو إيجاده مع غفلة\r\rفصل في الأمر والرضا والمحبة\r"]], "pg": [76, 78]}, "496.12": {"x": [[78, "وأمره يغاير الإرادة ... إذ عم أمر طاعة عبادة\r[الشرح]\r(أو كونه) أي: الإيجاد المذكور وكذلك الإعدام (طبيعة) أي: بمقتضى الطبيعة وهو الفعل الذي يتوقف على وجود شرط وانتفاء مانع ككون النار محرقة عند القائل بتأثيرها بالطبع كالطبعيين فعلها ذلك موقوف عندهم على شرط المقارنة وانتفاء مانع البلل كالحطب مثلا (أو كونه) أي: الإيجاد (طبيعة) أيضا حاصل منه تعالى بطريق (أو عله) بالهاء الساكنة للوزن (للخلق) أي: بمقتضاها وهو الفعل الذي يحصل عند وجود العلة من غير توقد على وجود شرط ولا انتفاء مانع كحركة اليد مثلا علة لحركة الخاتم عند القائلين بذلك من الفلاسفة.\rوعند أهل السنة لا فاعل إلا بطريق الإرادة والاختيار وهو الله تعالى حقيقة في الكل ويوصف الإنسان بذلك أيضا بسبب خلق الله تعالى له القدرة والإرادة الحادثتين كما قدمناه مفصلا (أو إيجاده) تعالى لشيء من الأشياء (مع غفله) بالسكون أيضا أي: عن ذلك الشيء فإنه ينافي الإرادة الإلهية كذلك\r\r(فصل في) بيان (الأمر) الإلهي التكليفي\r(والرضا) والإرادة (والمحبة) والإلهيات وبيان الفرق بينهما\r\r(وأمره) سبحانه وتعالى وهو قسمان: أمر تكوين، وأمر تكليف.\rفأمر التكوين: توافق الإرادة بلا خلاف وهو قوله لشيء كن فيكون، ولكنه تارة يوافق الرضا أو المحبة وتارة لا يوافقها لقوله تعالى: {وَلَا يَرْضَى لِعِبَادِهِ الْكُفْرَ} [الزمر: 7] مع تكوينه ذلك.\r\rوأمر التكليف: بضده تارة يوافق الإرادة وتارة لا يوافقها ولكنه موافق للرضى والمحبة والمراد هنا أن أمر التكليف (يغاير الإرادة) بسكون الهاء للوزن، أي: هو غير الإرادة الإلهية للمعتزلة (إذ) أي: لأنه (عم) أي: يشمل (أمر طاعة) أي: أمر تكليف بطاعة (عباده) بسكون الهاء أيضا أي: عباده الله المكلفين كلهم."], [79, "ولم يرد وقوعها من كلهم ... بلا ارتياب بل ولا من جلهم\rفصح أن يأمر بالشيء ولا ... يرده من بالهدى تطولا\rومثله الرضى فليس يرضى ... كفران أصحاب القلوب المرضى\rأي لا يكلف النفوس ما نهى ... عنه ولا يحب غيا شانها\r[الشرح]\r(و) الحال سبحانه وتعالى من الأزل (لم يرد وقوعها) أي: تلك الطاعة (من كلهم) أي: جميع عباده الذين توجه عليهم أمره بتلك الطاعة (بلا ارتياب) أي: شك وتردد (بل ولا) أراد وقوع ذلك أيضا (من جلهم) أي: أكثرهم وإنما أراد وقوع ذلك من البعض دون البعض على حسب ما يعلم سبحانه وتعالى من الأزل.\r(فصح) حينئذ (أن يأمر) كل عباده المكلفين (بالشيء) الذي هو طاعة (ولا يريده) أي: ذلك الشيء أن يقع من بعض عباده (من) أي: الله تعالى الذي (بالهدى تطولا) بتشديد الواو والألف للإطلاق، أي: أنعم وتفضل، فلزم من ذلك أن يكون الأمر غير الإرادة لأنا نجد كثيرا مما توجه عليهم أمر الله تعالى بالطاعات لا يمثلون شيئا منها لعدم إرادة لأنا نجد كثيرا مما توجه عليهم أمر الله تعالى بالطاعات لا يمثلون شيئا منها لعدم إرادة الله تعالى منهم ذلك ولا يكون شيء إلا بإرادة الله تعالى، فإيمان أبي بكر رضي الله عنه مأمور به مراد الله تعالى، وإيمان أبي جهل به غير مراد الله تعالى.\r(ومثله) أي: الأمر الرضا من الله تعالى فإنه غير الإرادة غير الإرادة أيضا عند أهل الحق (وليس يرضى) سبحانه وتعالى (كفران) بالضم. قال في المصباح: كفر بالله يكفر كفرا وكفرانا وكفر النعمة وبالنعمة أيضا جحدها (أصحاب القلوب المرضى) جمع مريض من الكافرين والفاسقين أي: (لا يكلف) تعالى (النفوس) البشرية ذات العقل والبلوغ (ما) أي: إرادته فإنه يريد ما هو واعق من الكفر والفسق ولا يرضى به بحكم قوله سبحانه وتعالى: {وَلَا يَرْضَى لِعِبَادِهِ الْكُفْرَ} [الزمر: 7]\r(ولا يحب) سبحانه أيضا (غيا) وهو مصدر غوا يغوي غيا من باب ضرب انهمك في الجهل وهو خلاف الرشد ولاسم الغواية بالفتح كذا في المصباح (شأنها) أي: شان النفوس، يعني: أعابها فالمحبة أيضا تغاير الإرادة، فقد يريد ما لا يحب سبحانه كالغي والضلال الواقعين من أهله بإرادة الله تعالى لا بمحبته ولا برضاه."], [80, "وكل ما أراد فهو الكائن ... وإن نهى عنه وأخطأ المائن\rوليس عما شاءه محيد ... لأنه يفعل ما يريد\rتجري على اختياره الاقدار ... في الخلق والإيراد والإصدار\r\rفصل في حدوث العالم\r\r"]], "pg": [78, 80]}, "496.13": {"x": [[80, "والعالم اسم ما سوى الديان ... من نوعي الأعراض والأعيان\r[الشرح]\r(وكل ما) أي: شيء (أراد) الله تعالى إيجاده (فهو الكائن) أي: الموجود (وإن نهى) سبحانه وتعالى (عنه) كالكفر والفسوق (وأخطأ) الصواب (المائن) أي: الكاذب الذي يقول كل ما نهى الله تعالى عنه فإنه لم يرده وإنما يقع بغير إرادة الله تعالى وهم المعتزلة القائلون بأن الأمر يستلزم الإرادة والنهي يستلزم عدم الإرادة فجعلوا إيمان الكافر مرادا وكفره غير مراد، ونحن نعلم أن الشيء قد لا يكون مرادا ويؤمر به وقد يكون مرادا وينهى عنه لحكم ومصالح يحيط بها علم الله تعالى، أو لأنه لا يسأل عما يفعل، ألا ترى أن السيد إذا أراد أن يظهر على الحاضرين عصيان عبده يأمره بالشيء ولا يريده منه.\r(وليس عما) أي: عن الشيء الذي (شاءه) سبحانه وتعالى (محيد) من حاد عن الشيء يحيد، تنحى وبعد والمراد موضع عدول وفرار (لأنه) سبحانه وتعالى (محيد) على كل حال (تجري على) مقتضى (اختياره الأقدار) أي: المقادير التي قدرها (في الخلق) أي:. المخلوقات (والإيراد) أي: الإقبال من كل شيء على كل شيء (والإصدار) ضده والورد خلاف الصدر، يقال: ورد البعير وغيره الماء يرده ورودا بلغه ووافاه وقد يحصل دخولا فيه وقد لا يحصل كذا في المصباح، والصدر: الرجوع والانصراف.\r\r(فصل في) بيان (حدوث العالم) بفتح اللام\rوهو ما يعلم الله تعالى به كالخاتم اسم لما يختم به\r\r(والعالم اسم ما) أي: كل شيء (سوى) الله الملك (الديان) القهار والحاكم والمجازي الذي لا يضيع عملا بل يجزي بالخير والشر كذا في القاموس (من نوعي) بكسر الياء التحتية تثنية نوع والنون محذوفة للإضافة إلى (الأعراض) جمع عرض بالتحريك وهو النوع الأول من العالم (والأعيان) جمع عين وهو النوع الثاني منه."], [81, "فالعين ما بنفسه يقوم ... وما عداه العرض المرقوم\rولم يحقق غير ذين قسم ... وكل ما ألف فهو الجسم\rوما انتهى لحد منع القسم ... فالجوهر الفرد الشهير الوسم\rوهو على مذهبنا المحمود ... يوصف بالحدوث والوجود\r[الشرح]\r(فالعين ما) أي: الشيء الذي (بنفسه يقوم) أي: يثبت ويتحقق بنفسه لا بغيره، ومعناها ان لا يكون تحيزه تابعا لتحيزه غيره كما قالوا، والمراد قيام ظهور لا قيام حقيقة، وإلا فإن جميع العوالم قائمة بالله تعالى لا بنفسها ولا بغيره تعالى بال خلاف عند الكل فإن من أسمائه تعالى القيوم الذي قام به كل شيء. (وما عداه) أي: غير ما يقوم بنفسه (العرض) بالتحريك (المرقوم) أي: الذي رقم أي: كتب يعني ذكر فيما مرهنا.\rواختلفوا في تحديد العرض، فقال بعضهم: هو ما يستحيل بقاؤه. وقيل: ما يوجد وقيل: ما يقوم بالجوهر. وقيل ما لا يبقى زمانين كذا في كتاب الانتقاد شرح عمدة الاعتقاد.\r(ولم يحقق) بالبناء للمفعول (غير ذين) أي: هذين النوعين نوع العين ونوع العرض (قسم) نائب فاعل يتحقق وغير ذين صفة لقسم، والمعنى لم يحقق المحققون قسما ثالثا غير هذين القسمين للعالم (وكل ما ألف) بضم الهمزة أي: ركب من الأجزاء وهي الجواهر الفردة ولو من جزءين منها (فهو الجسم) وأدنى التركيب من جزءين فصاعدا، وعند البعض لا بج من ثلاثة أجزاء لتحقق الأبعاد الثلاثة أعني الطول والعرض والعمق، وعند البعض من ثمانية أجزاء ليتحقق تقاطع الأبعاد الثلاثة أعني الطول والعرض والعمق، وعند البعض من ثمانية أجزاء ليتحقق تقاطع الأبعاد على زوايا قائمة ذكره السعد التفتازاني في شرح العقائد. ورده الخيالي بأن التقاطع يتحقق بأربعة: بأن يتألف اثنان بجنب أحدهما ثالث يقوم عليه رابع. وفي شرح الصحائف قال أهل السنة: الجسم هو متحيز قابل لقسمة، فعلى هذا يكون المركب من جوهرين فرجين جسما عندهم.\r(وما انتهى) أي: وصل (لحد منع القسم) بالفتح وهو مصدر قسمته قسمته قسما من باب ضرب، فرزته أجزاء، كذا في المصباح. (فالجوهر الفرد) الذي لا يحتمل القسمة أصلا وجميع الأجسام مركبة منه (الشهير) أي: المشهور (الوسم) أي: العلامة أي: الثبوت. (وهو) الجوهر الفرد (على مذهبنا) معشر أهل السنة (المحمود) وصف لمذهبنا (يوصف) أي: الجوهر الفرد (بالحدوث) أي: كونه حادثا لا قديما (والوجود) أي: كونه موجودا لا"], [82, "هذا في القول به إزاحة ... لظلمه الغاوين واستراحه\rوفي حدوث ما عدا الله الغرض ... إذ كل عين ليس تخلو عن عرض\r[الشرح]\rمعدوما وقد أنكر الفلاسفة وجود الجواهر الفرد وزعموا أن الأجسام مركبة من الهيولي ولصورة وهذه الأبحاث مبسوطة في كتب علم الكلام، وقد لخصنا منها فوائد في كتابنا المطالب الوفية.\r(هذا) منصوب بفعل محذوف تقديره اعرف أو اعلم ونحو ذلك (وفي القول به) أي: بثبوت الجوهر الفرد على مذهب أهل السنة (إزاحة) بسكون الهاء، أي: إزالة ومنع (لظلمة الغاوين) جمع غاوي من الغي ضد الرشد وهم الفلاسفة الضالون المضلون المنكرون الأجسام ن الجواهر الفردة التي لا تتجرا لنفيهم الجوهر الفرد وقولهم بانقسامه إلى ما لا نهاية له حتى ينمحق، وزعمهم أن الأجسام مركبة من الهيولي وهي المادة الواحدة القديمة عندهم ومن الصورة الحادثة بالشخص القديمة بالنوع وترتيبهم على ذلك قدم العالم بضلالات واضحة البطلان عند أهل الإسلام والإيمان (واستراحة) بالسكون أيضا يعني من ذلك.\rقال السعد في شرح العقائد: فإن قيل لهذا الخلاف ثمرة؟ قلنا: نعم، في إثبات الجوهر الفرد نجاة عن كثير من ظلمات الفلاسفة مثل إثبات الهيولي والصورة المؤدي إلى قيام العالم ونفي حشر الأجساد وكثير من أصول الهندسة المبني عليها دوام حركة السماوات وامتناع الخرق والالتئام عليها.\r(وفي حدوث ما عدا الله) تعالى (الغرض) بالغين المعجمة وفتح الراء وسكن الضاد المعجمة للوزن، يعني: أن المقصود هو إثبات الحدوث لجميع العالم (إذ) أي: لأن (كل عين) أي: جوهرة فرد أو جسم مركب منه (ليس تخلو عن عرض) بالتحريك وسكون الضاد المعجمة.\rقال الاصفهاني في شرح طوالع البيضاوي: اعلم ان التصديق بوجود الجسم لا يفتقر إلى نظر لأن الجسم في ذاته محسوس بل لأنه بالحس أدركت النفس بعض أعراضه كسطحة من مقولة الكم ولونه من مقولة الكيف، ثم إن الحس لما أدى إلى ذلك العقل حكم العقل بوجود الجسم حكما ضروريا أي غير مفتقر إلى نظر وتركيب قياس، فالجسم محسوس من جهة أعراضه المذكورة معقول من جهة ذاته فليس الجسم بمحسوس صرفا"], [83, "مثل الروائح او الأكوان ... فلا تكن هن شرحها بألواني\rولنقتصر هنا على الأكوان ... فإنهما للقصد كالعنوان\rهو اجتماع أو سكون او ما ... نافى فكل للحدوث أو ما\rلأنها محقق فيها العدم ... عند طرو ضدها فلا قدم\r[الشرح]\rبل الحس معاون للعقل في حكمه الضروري بوجود الجسم، وليس كل ما يحكم به العقل حكما ضروريا يشترط فيه أن يكون مأخوذا من الحس في جميع الوجوه بل منه كذلك ومنه ما لا يؤخذ من الحس في بعض الوجوه. انتهى\rفظهر من هذا أن كل جسم لا ينفك عن الأعراض أصلا وأن الأعراض أول ما يدرك من العالم ولا يمكن أن تتحقق الأعيان إلا بها.\r(مثل الروائح) الروائح: جمع رائحة (أو الأكوان) جمع كونه، وهو من كون الله الشيء فكان أوجده (فلا تكن) أيها المكلف (عن شرحها) أي: بيانها (بالواني) من الوني، وهو الضعف الفتور والكلال والإعيان كذا في الصحاح (ولنقتصر هنا) من عن يعن إذا ظهر، وكل ما استدللت بشيء تظهره على غيره فعنوان له، كذا في القاموس (وهي) أي: الأكوان (اجتماع) بمخالطة أو مجاورة (أو سكون) أصلى أو غير أصلي (أو ما) أي: الذي أو شيء (نافي) من النفي، أي: خالف ما ذكر من الافتراق ينافي الاجتماع، والحركة تنافي السكون. قال السعد في شرح العقائد: الأكون هي الاجتماع والافتراق والحركة والسكون.\rوقال في التجريد في شرحه: من أجناس العرض الأين وهو النسبة إلى المكان. وأنواعه أربعة: الحركة، والسكون، والاجتماع، والافتراق؛ لأن حصول الجوهر في الحيز إما أن يعتبر بالنسبة إلى جوهر آخر أم لا، وعلى الأول إما أن يكون بحيث يمكن أن يتوسطهما ثالث فهو الافتراق وإلا فالاجتماع، وعلى الثاني إن كان مسبوقا بحصوله في ذلك الحيز فهو السكون، وإن كان مسبوقا بحصوله في حيز آخر فهو الحركة.\r(فكل) أي: من الأكون (للحدوث أو ما) أي: أشار، وبين أو ما الجناس الملفق (لأنها) أي: الأكوان المذكورة (محقق) أي: ثابت ظاهر واضح (فيها العدم) بالسكون للوزن (عند طرق) أي: تجدد (ضدها) كما هو المعروف المشهور المحسوس (فلا قدم) بالسكون أيضا فيها لأن حدوثها محقق لا شبهة فيه."], [84, "وكل ما كان بعقل قدمة ... كان محالا دون ريب عدمه\rوكل ما لازم حادثا وجب ... له من الحدوث ما له انتسب\rوعد الاجتماع في نوع العرض ... كذاك الافتراق بعض اعترض\rوقال: بل هما أمران نسبيان ... لم يصلا الوجود في التبيان\r[الشرح]\r(وكل ما) أس: شيء (كان بعقل) أي: بسبب إدراكه (قدمه) بسكون الهاء للوزن (كان محالا) أي: مستحيلا (دون ريب) أي: بلا شك ولا تردد (عدمه) بسكون الهاء أيضا، وهذه الأكوان المذكورة التي هي أعراض متجددة لا شبهة لأحد في عدمها ثم وجودها ثم عدمها كذلك، فكونها قديمة مستحيل لأنه ثبت عدمها فاستحال قدمها والعالم ملازم لها لا ينفك عنها؛ لأنه لا يخلو دائما من الاجتماع والافتراق والحركة والسكون.\r(وكل ما) أي: شيء (لازم حادثا وجب) بالسكون للوزن له أي: لذلك الشيء الملازم (من الحدوث) بيان لقوله (ما) أي: أمر (له) أي: لذلك الحادث (انتسب) بالسكون أيضا، فيلزم من هذا أن يكون العالم حادثا لملازمة الحوادث من الأكوان العارضة له (وعد) بالنصب مفعول مقدم، الاعتراض (الاجتماع في نوع العرض) بالسكون للوزن، أي: من أقسام الأعراض (كذلك) عد (الافتراق) من ذلك (بعض) من المتكلمين على ذلك (اعترض) بالسكون كذلك.\r(وقال) أي: المعترض (بل) هما أمران (نسبيان) أي: كل منهما مجرد نسبة حاصل بين شيئين موجودين، فالاجتماع نسبة بين الأجزاء أو بين الأشياء المتجاورة والافتراق كذلك نسبة بين الأشياء (لم يصلا) أي: الاجتماع والافتراق (الوجود) أي: إلى الوجود، يقال: وصل الشيء وإلى الشيء وصولا، بلغه وانتهى إليه. كذا في القاموس. (في التبيان) بالكسر والفتح مصدر شاذ من أبان أي: ليسا بموجودين فإن النسب أمور اعتبارية كالأبوة والبنوة ونحو ذلك. لكن يرد على المعترضة أن النسبة أيضا معدودة من أقسام العرض.\rقال في المعارف شرح الصحائف: العرض عندهم تسعة أقسام؛ لأنه يقتضي إما نسبة أو قسمة أو لا هذا ولا ذاك، والأول هو الكم والثاني سبعة والثالث الكيف، ثم عرف النسبة بأنها العرض الذي يكون تعلقه بالقياس إلى تعقل الغير وذكر أقسامها السبعة: الإضافة، والأين، والمتي، والوضع، والملك، وأن يفعل، وأن ينفعل، وعرف كل واحد منهما وذكر أمثلته."], [85, "فبان مما قد مضى بالسرد ... حدوث ما سوى الإله الفرد\rولا يتم المبتغى للطالب ... إلا بعلم السبعة المطالب\rإثبات أعراض وكون العين ... تلازم الأعراض دون مين\rوالمنع للكمون والظهور ... والانتقال المدعى بالزور\r[الشرح]\r(فبان) أي: ظهر وانكشف (مما قد مضى بالسرد) سردت الحديث سردا من باب قتل أتيت به على الولاء كذا في المصباح، يعني: مما ذكر هنا من أن هذه الأكوان الأربعة اللازمة لكل شيء حدوثا ظاهر بتجديدها في كل آن فيلزم من ذلك حدوث كل شيء لأن ملازم الحادث حادث (حدوث ما) أي: كل شيء (سوا الإله الفرد) سبحانه وتعالى (ولا يتم المبتغى) بصيغة اسم المفعول، أي: المطلوب (للطالب) وهو حدوث العالم المعنون له في هذا الفصل (إلا بعلم السبعة المطالب) فالمطلب الأول (إثبات أعراض) جمع عرض أي: كونها ثابتة وذلك بالحس والعقل، (و) المطلب الثاني (كون العين) وهو الجوهر الفرد وما تركب منه وهو الجسم (تلازم الأعراض) بحيث لا تنفك عنها أصلا هو مدرك بالحس والعقل أيضا (دون) أي: كذب وارتياب.\rوالمطلب الثالث: (المنع للكمون) أي: الاستتار (والظهور) في الأعراض وقد قال به بعض حكماء الفلاسفة وهو ممتنع؛ لأنه لو كان كذلك لاجتمع الضدان في المحل الواحد وكما نعلم استحالة كون الشيء متحركا ساكنا فكذلك نعلم استحالة اجتماع الحركة والسكون ثم لو ظهرت الحركة مرة واستكنت أخرى لكان ذلك اعتوار حكمين عليها وذلك يتضمن ثبوت معنيين يقتضي أحدهما كون الحركة بادية ويقتضي الآخر كونها مستكنة خافية؛ فإن الدال على إثبات الأعراض تناوب الأحكام وتعاقبها على الجوهر ثم يلزم لو قدرنا الظهور والكمون معنيين ظهورهما عند ظهور أثرهما وكمونهما عنج كمون أثرهما ويتسلسل في ذلك، ثم الحركة توجب كون محلها متحركا لعينها فلو جاز ثبوتها من غير أن توجب حكمها للزم تجوز ذلك أبدا فيها وذلك يقلب جنسها أو يحل حقيقة نفسها كذا في الإرشاد لإمام الحرمين.\r(و) المطلب الرابع (الانتقال) في الأعراض من جسم إلى جسم (المدعى) بصيغة اسم المفعول من ادعاه (بالزور) أي: الكذب."], [86, "أو أنها قائمة بنفسها ... أو كونها قديمة في جنسها\r[الشرح]\rقال الأصبهاني في شرح الطوالع: أجمع العقلاء على امتناع الانتقال على الأعراض، واحتجوا عليه بأن المقتضى لتشخص أفرادها لا يكون ما هيتها ولا لوازمها وإلا انحصرت أنواعها في أشخاصها ولا عوارضها الحالة فيها لتوقف حلول عوارضها الحالة فيها على تشخصها وتعينها، فلو توقف تشخصها على العوارض الحالة فيها لزم الدور والأمر مباينا لها وإلا لو استغنت عن الموضوع مشخصها لها تكون محتاجة إلى موضوع فيكون الموضوع من جملته لأنه في وجوده وتشخصه مكتف بغير الموضوع والمكتفي في الوجود والتشخص بغير المحل لا يفتقر إلى المحل فيستغنى عنه وهو باطل فيتعين أن يكون تشخيصها بمحالها او بما حل فيها، وعلى التقدير يفتقر في تشخصه إلى الموضوع مشخصا لها تكون محتاجة إلى موضوع مشخص لأن الموضوع المهم لا يكون من حيث هو مبهم موجودا في الخارج، وما لا يكون كذلك لا يفيد تشخص ما هو حال فيه، فالعرض إذن لا يتحقق وجوده إلا بموضوع يعينه فلا يصح عليها الانتقال، وهذا بخلاف الجسم في احتياجه إلى الحيز فإن الجسم غير محتاج في وجوده وتشخصه إلى الحيز، بل يحتاج الجسم في تحيزه على حيز غير معين فلا يمتنع أن ينتقل من حيز إلى حيز آخر من حيث إنه موجود مشخص ولا من حيث هو متحيز؛ لأن كونه متحيزا حاصل باعتبار الحيزين.\rوقال إمام الحرمين في الإرشاد: إن الحركة حقيقتها الانتقال فينبغي أن تقتضي إذا وددت انتقال جوهرها ولو انتقل جوهر إلى آخر للزم طريان حالة عليها فلا يكون فيها انتقال وذلك قلب جنسها وانقلاب الأجناس محال، ولو انتقل الانتقال لافتقر إلى انتقال ثم كذلك القول في الانتقال المنتقل إلى الانتقال وذلك يفضي إلى ما لا يتناهى.\r(أو) يعني: المطلب الخامس (أنها) أي: الأعراض (قائمة) أي: ثابتة متحيزة (بنفسها) أي: ليس تحيزها تابعا لتجيز الأجسام وذلك بديهي البطلان؛ لأن معنى وجود العرض هو وجوده في الموضوع وهو الجسم الذي هو محله المقدم له ولهذا يمتنع الانتقال عنه كما قلنا، فلو قام بنفسه لانتقل عنه وهو محال. (أو) يعني: المطلب السادس (كونها) أي: الأعراض (قديمة في جنسها) أ]: مقدمها بالجنس لا بالشخص."], [87, "أي قولهم ليس لها من أول ... فالأربع اردد واعضد المعول\rوانف التغير عن القديم ... وسر بنهج السنة القويم\rواحذر هنا أقوال أهل الفلسفة ... فإنها محض الضلال والسفه\r[الشرح]\r(أي قولهم) يعني: القائلين بذلك وهم حكماء الفلاسفة (ليس لها) أي: الأعراض بالنوع (من أول) بالسكون لنية الوقف عليه. قال السعد في شرح العقائد:\rذهب الفلاسفة إلى قدم السماوات بموادها وصورها وأشكالها وقدم العناصر بموادها وصورها لكن بالنوع بمعنى أنها لم تخلو قط عن صورة انتهى. فالصدر والأشكال في السماوات وفي جميع المولدات من العناصر الأربعة: الماء، والهواء، والنار، والتراب. إنما هي أعراض فهي قديمة عندهم بالنوع والجنس لا بالشخص وذلك باطل لضرورة مشاهدة التغير فيها والتبدل وهو علامة الحدوث، وإذا كانت أشخاص النوع والجنس حادثة فمجموع ذلك حادث كله كما مر في بطلان التسلسل.\r(فالأربع) من هذه المطالب وهي الكمون والظهور في الأعراض والانتقال فيها وكونها قائمة بنفسها وكونها قديمة (اردد) أي: لا تقبل شيئا من ذلك (واعضد) يقال: عضدت الرجل عضد من باب قتل، أعنته فصرت له عضدا، أي: معينا وناصرا، وتعاضد القوم: تعاونوا كذا في المصباح. القول (المعول) بتشديد الواو وسكون اللام بينة الوقف وهي لغة ربيعة أن يوقف على المنصوب بالحذف والإسكان نحو رأيت زيد بالسكون.\r(و) المطلب السابع أشار إليه بقوله (انف) أمر من النفي (التغير عن القديم) يعني: أن القديم لا يتغير ولا يكمن فيه التغير، فلو كان شيء مع الله تعالى قديما عرضا نوعيا كان أو مادة هيولانية أو غير ذلك لما تغير لأن التغير حدوث والحدوث ضد القدم واجتماع الضدين محال. (وسر) يا أيها المكلف (بنهج) أي: فيه والنهج مثل قلي الطريق الواضح (السنة) أي: الطريقة المحمدية (القويم) نعت للنهج أي: المستقيم.\r(واحذر هنا) أي: في هذا المحل عند هذا المطلب السابع وفي المطالب الأربعة أيضا المردودة المذكورة (أقوال أهل الفلسفة) بسكون الهاء للوزن وأصلها فيلاسوف، أي: محب الحكمة القائلين بقدم العالم بالهيولي الصورة النوعية كما قدمناه (فإنها) أي: أقوالهم (محض) خالص (الضلال والسفه) بسكون الهاء للوزن وأصلها فيلاسوف، أي: محب الحكمة القائلين بقدم العالم بالهيولي والصورة النوعية كما قدمناه (فإنها) أي: أقوالهم (محض) خالص (الضلال والسفه) بسكون الهاء أيضا، وهو: نقص في العقل وأصله الخفة كذا في المصباح."], [88, "جروا بها من غيهم ذيولها ... من قدم النفس أو الهيولا\rوغيرها من المقالات التي ... أقدام من فيها تلاهم زلت\rفلا قديم غير ذي الجلال ... نسأله الأمن من الضلال\r\rفصل في بيان الجائز\r\r"]], "pg": [80, 88]}, "496.14": {"x": [[88, "وجائز في حقه تعالى ... أن يخلق الأنام والأفعالا\rكذلك التكليف للعباد ... وهديهم لهنج رشد بادي\r[الشرح]\rجرو بها) أي: بأقوالها الباطلة (من غيهم) الغنى، هو ضد الرشد (ذيولها) جمع ذيل على طريقة الاستعارة فأظهروا الافتخار والإعجاب (في قدم النفس) وهي شاملة للنفوس النباتية والحيوانية والإنسانية والنفوس الفلكية، وقد ذهب أفلاطون ومن قلبه من الحكماء إلى أن النفس قديمة. (أو) قدم (الهيولي) أي: المادة التي لا تنفك من الصورة النوعية. (وغيرها) أي: العظمة سبحانه وتعالى، وكل ما سواه حادث (نسأله) أي: نطلب منه سبحانه عز وجل (الأمن) أي: السلامة لنا ولجميع أمة محمد صلى الله عليه (من الضلال) في الاعتقاد والعمل.\r(فصل في) بيان (الجائز) أي: الحكم الذي يصح في العقل وجوده وعدمه\r\r(وجائز في حقه) أي: الله (تعالى) من غير وجوب عليه ولا امتناع عنه (أن يخلق الأنام) أي: الإنس والجن، وقيل: الأنام ما على وجه الأرض من جميع الخلق كذا في المصباح. وفي القاموس: الأنام كسحاب، وساباط، وأمير: الخلق، والجن، والإنس، أو جميع ما على وجه الأرض. انتهى والمراد هنا جميع الخلق.\r(و) يخلق (الأفعال) بألف الإطلاق أي: أفعال الخلق كلها من خير وشر ونفع وضر (كذلك) أي: جائز في حقه تعالى (التكليف) بالأمر والنهي وغيرهما (للعباد) العاقلين الباغين (وهديهم) مصدر هدى يهدى، أرشد (لنهج) أي: لطريق (رشد بادي) أي: ظاهر لهم ولغيرهم."], [89, "وليس أمر واجبا عليه ... منها بل اختباره إليه\rولا صلاح واجب أو أصلح ... هذا الذي دان به من أفلح\rفكل ما أراده الصواب ... سواء العقاب والثواب\rفذاك بالعدل وذا بالفضل ... من فاعل ما يشاء دون عضل\rوما لعقل وحده توصل ... إلى قبيح أو إلى ما يجمل\r[الشرح]\rوليس أمر واجبا) تعالى (منها) أي: من المذكورات خلق الأنام وخلق أفعالهم وتكليف العباد وهدايتهم إلى منهج الرشاد (بل اختياره) أي: الله تعلى الأمر منها (إليه) أي: موكول أو مفوض له، فهو سبحانه يفعل ما يشاء ويختار ما يريد (ولا) فعل (صلاح) للعباد (واجب) تعالى (أو) فعل (أصلح) بالسكون بنية الوقف، أي: ما هو أصلح في حق البعض منهم (هذا) القول هو (الذي دان به) أي: اتخاذه ربنا ومعتقد (من أفلح) بالسكون أيضا للوقف عليه وهم أهل السنة، خلافا للمعتزلة القائلين بوجوب الصلاح والأصلح على الله تعالى في حق معاملة العباد.\rقال في شرح المقاصد: ذهب البغداديون من المعتزلة إلى أنه يجب على الله تعالى ما هو الأصلح للعباد في الدين والدنيا، وقال البصريون: بل في الدين فقط. (فكل ما) أي: شيء (أراده) الله تعالى هو (الصواب) ضد الخطأ (سواء) في ذلك (العقاب) منه تعالى لمن شاء (والثواب) منه لمن شاء (فذاك) أي: العقاب (بالعدل) خلاف الظلم (وذا) أي: الثواب (بالفضل) أ]: الكرم والإحسان (من فاعل) وهو الله تعالى مختار يفعل (ما يشاء دون عضل) أي: منع (وما لعقل) من العقول (وحده) بدون اهتداء منه تعالى بمتابعة الشرع (توصل*إلى) معرفة أمر (قبيح) من الاعتقاد أو الأعمال أو الأحوال (أو إلى ما) أي: أمر (يجمل) أي: يحسن.\rقال في شرح العمدة: قالت المعتزلة: العقل يوجب الإيمان وشكر المنعم ويعرف حسنها أيضا بذاته ويثبت الأحكام على ما يقتضيه صلاح الخلق، وعند أصحابنا العقل آلة يعرف بها حسن بعض الأشياء لا كلها إما يديهة كحسن إنقاذ الغرقى والهلكى أو استدلالا كحسن الكذب النافع فإنه لاشتماله على صفة المنفعة حسن، ويعرف أيضا قبح بعض الأشياء إما بديهة كقبح الظلم أو استدلالا كقبح الصدق الضار فإنه لاشتماله على صفة المفرد قبيح، وحسن بعض الأشياء وقبحها لا يعرف بالعقل أصلا لا بديهة ولا استدلالا كحسن صوم آخر يوم رمضان وقبح صوم أول شوال فإنه لا مجال للعقل في إدراكهما."], [90, "بل ما بفعله أمرنا فالحسن ... وضده انقاد لقبح بالرسن\rفلو عليه وجب الصلاح ... سبحانه عم الورى الفلاح\r[الشرح]\rوفي شرح منظومة ابن الجزري الشيخ السنوسي رحمه الله تعالى قال: إن الذي أوقع المعتزلة في الضلالات كإيجاب الثواب وفعل الصلاح والأصلح على الله تعالى اعتمادهم في عقائدهم على التحسين والتقبيح بالعقليين وقياسهم أفعال الله تعالى وأحكامه على أفعال المخلوقين وأحكامهم من غير أن يكون في ذلك جامع يقتضي التسوية في الأحكام، والذي أجمع عليه أهل الحق أن الأفعال كلها مستوية بالنسبة إلى تعلق أحكامه تعالى الشرعية بها فلا يتصف شيء منها بالحسن لذاته أو صفة كما لا يتصف شيء منها بالقبيح لذاته أو صفة فلا يجب أدنى شيء منها عقلا على الله تعالى ولا يستحيل، وكذا لا مجال للعقول في حكم شرعي لها، فليس الحسن شرعا عند أهل الحق إلا ما قيل فيه من جهة مولانا عز وجل افعلوه ولا القبيح شرعا إلا المقول ففيه من جهته لا تفعلوه، وتخصيص كل واحد من الأفعال بما اختص به من الأحكام لا علة له ولا غرض يبعث عليه وللشرع حكم إن يقله نتبعه في ذلك وإن سكت فلا مجال لعقولنا في ذلك أصلا. انتهى\rقلت: وهذا الكلام في التحسين والتقبيح لا ينافي ما سبق عن شرح العمدة من أن حسن بقض الأشياء وقبح بعضها يدرك بالعقل بديهة أو استدلالا كما مر؛ لأن العقول غير ملزم في حسن ولا مبصر في قبيح وإن كان مدرك لبعض ذلك فإن الإلزام والتغيير يعني الإيجاب والنهي شرعيان لا عقليان، ولهذا قال في شرح العمدة بعد ذكره ما تقدم: إن العبد موجد لأفعاله. وعندنا العقل آلة المعرفة والموجب هو الله تعالى إلى آخر عبارته، وإنما الحاكم هو الشرع فلا حكم بحسن ولا قبح قبل ورود الشرع مطلقا عندنا.\r(بل ما) أي: الذي (بفعله) من الطاعات (امرنا 9 بالبناء للمفعول أي: أمرنا الله تعالى (فالحسن) بالسكون للوزن (وضده) أي: الذي أمرنا بتركه والكف عنه فإنه (انقاد لقبح بالرسن) بالسكون أيضا أي: فهو قبح (فلو) كان (عليه) أي: الله تعالى (وجب الصلاح) أو الأصلح (سبحانه) تنزيه له عن ذلك (عم) أي: شمل جميع (الورى) أي: المكلفين (الفلاح) أي: الهداية والرشاد؛ لأن ذلك هو الصلاح والأصلح لهم دون ما هم عليه من فلاح البعض وهدايتهم وغواية البعض وضلالتهم."], [91, "وكان خلقهم لدرار المأوى ... أصلح من تعريضهم للأوى\rوللتكاليف بهذي الدار ... وما يقاسون من الأكدار\rإن قيل زادهم بذاك أجرا ... له على قدر العناء أجرى\rقلنا الإله قادر أن يوصله ... إليهم دون أمور معضلة\rوأيضا الذي على الكفر هلك ... تكليفه به إلى خسر سلك\rبل خلقه إن عاش خدن البوس ... إذ هو في الدارين ذو العبوس\r[الشرح]\rوكان) أيضا (خلقهم) أي: المكلفون (لدار لمأوى) وهي الجنة (أصلح) لهم (من) خلقهم في الدنيا (وتعريضهم) فيها (للأوى) أصلها بالمد وقصره لضرورة الشعر، وللأوى: الشدة كذا في المصباح، أي: شدة الدنيا وبلائها بأنواع المحن كما هو الواقع.\r(و) تعريضهم فيها أيضا (للتكاليف) الشرعية (بهذا الدار) أي: دار الدنيا (وما يقاسون) فيها أي: يكابدونه (من الأكدار) جمع كدوره، وهو خلاف الصفو في معايشهم (إن قيل) أي: من طرف المعتزلة الموجبين على الله تعالى فعل الصلاح والأصلح للعباد (زاد) أي: مقدار (العناء) أي: التعب الحاصل لهم بمقاساة ذلك (أجرى) أي: أرسل، من الإجراء، وهو الإرسال، كذا في الصحاح. أو من الجريان، يقال: جرى الماء، إذا سال. وبين قوله: أجرا وأجرى الجناس التام فهذا السبب يكون ذلك أصلح لهم.\r(قلنا) في جواب ذلك معشر أهل السنة (الإله) تعالى (قادر) على (أن يوصله) بسكون الهاء للوزن، أي: الأجر (إليهم) أي: العباد (دون)] أي: من غير حصول (أمور معضله) بسكون الهاء للوزن أيضا بصيغة اسم الفاعل، أي: متعبة، من أعضل الأمر بالألف: اشتد ومنه داء عضال، أي: شديد كذا في المصباح. فإن الله على كل شيء قدير (وأيضا) الإنسان (الذي على الكفر هلك) بالسكون للوزن: أي مات (تكليفه) أي: كونه مكلفا (به) متعلق بسلك (إلى خسر) أي: خسران (سلك) بسكون الكاف أيضا فلم يورثه خيرا في الدنيا والآخرة.\r(بل خلقه) أي: ذلك الإنسان الكافر يعني كونه مخلوقا بوصف الكفر (إن عاش) في الدنيا حتى بلغ عاقلا بذلك الوصف فهو (خدن) بالكسر أي: صديق في السر وجمعه أخدان كحمل وأحمال وخادنته صادقته كذا في المصباح. (البوس) بالضم وأصله بالهمزة"], [92, "فأينما من الصلاح يدعى ... له وذا أنف اعتزال جدعا\rوقصة الشيخ مع الجبائي ... ترد قول الإفك والإباء\r[الشرح]\rالساكنة ويجوز تخفيفها، وهو الضر كذا في المصباح. وفي القاموس: البأس العذاب والشدة في الحرب، يؤس ككرم وبئس كسمع بأسا وبؤسا (إذ هو) أي: لأنه (في الدارين) أي: الدنيا والآخرة (ذو) أي: صاحب (العبوس) بالضم مصدر عبس من باب ضرب عبوسا، قطب وجهه كذا في المصباح. وفي القاموس: وجهه يعبس عبسا وعبوسا كلح.\r(فأينما) أي: أفعل الذي هو (الصلاح) والأوصلح (بدعى) بتشديد الدال المهملة والبناء للمفعول، قال في المصباح: دعيت الشيء تمنيته وادعيته طلبته لنفسي (له) أي: لذلك الإنسان لكافر (وذا) أي: وهذا الاحتياج (أنف اعتزال) على الاستعارة تشبيه بإنسان له أنف صاحب اعتزال (جدعا) بتشديد الدال المهملة مبالغة في الجدع، وهو قطع الأنف أو الأذن أو اليد والشفة (وقصة الشيخ) أبي الحسن الأشعري رحمه الله تعالى (مع) أستاذه أبي علي (الجبائي) بضم الجيم وتشديد الباء الموحدة، نسبة إلى قرية من قرى البصرة (ترد قول الإفك) بكسر الهمزة وفتحها أي: الكذب والامتناع عن الحق: والقصة هي أن الشيخ أبا الحسن الأشعري رحمه الله تعالى قال لأستاذه أبي علي الجبائي: ما تقول في ثلاثة إخوة مات أحدهم مطيعا ولآخر عاصيا والثالث صغيرا؟\rفقال: إن الأول يثاب بالجنة، والثاني يعاقب بالنار، والثالث لا يعاقب ولا يثاب، قال الأشعري: فإن قال الثالث يا رب لما أمتني صغيرا لئلا أعصي لك أمرا فلا أدخل النار؟ ماذا يقول الرب فبهت الجبائي وترك الأشعري مذهبه واشتغل هو ومن تبعه بإبطال رأي المعتزلة وثبات ما وردت به السنة ومضت عليه الجماعة فسموا أهل السنة والجماعة. كذا في شرح العقائد للسعد."], [93, "وما اعترى الأطفال من آلام ... يفضي لأهل السنة الأعلام\rوالحق لا يخفى ذي عين ... والله نرجو عصمة من مين\r\rفصل في الرؤية\r\rورؤية الإله بالأبصار ... تجوز عند أهل الاستبصار\r[الشرح]\rوقال الخيالي: هم الأشاعرة وهذا هو المشهور في ديار خراسان والعراق والشام وأكثر الأقطار. وفي ديارنا ما وراء النهر اهل السنة هم الماتريدية أصحاب ابي منصور الماتريدي رحمه الله تعالى، وماتريد: قرية من قرى سمرقند وبين الطائفتين اختلاف في بقض المسائل كمسألة التكوين وغيرها.\r(وما اعترى) أي: أصاب (الأطفال) جمع طفل بالكسر، وهو الولد الصغير من الإنسان والدواب. قال ابن الأنباري: ويكون الطفل بلفظ واحد للمذكر والمؤنث والجمع قال الله تعالى: {أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَى عَوْرَاتِ النِّسَاءِ} [النور: 31]. ويجوز المطابقة في التثنية والجمع والتأنيث فيقال طفلة وأطفال وطفلات كذا في المصباح. (من آلام) جمع ألم، وهو الوجع (يقضي) بالمعجمة على المعتزلة (لأهل السنة الأعلام) جمع علم كسبب وأسباب. والعلم: هو الجبل الطويل وسيد القوم؛ فإن إيلام الأطفال مما يدل على فساد مذهب المعتزلة إذ لا نفع للأطفال في إنزال الأسقام بهم وكذا شبه الأطفال من الدواب والعجزة من الناس وغيرهم.\r(والحق) من مذهب أهل السنة (لا يخفى على) أحد (ذي عين) أي: كل ذي بصيرة يرى الحق وأما الأعمى فلا يراه (والله) بالنصب مفعول مقدم (نرجو) أي: يعطينا (عصمة) أي: حفظا (من مين) أي: كذب في قول أو اعتقاد.\r\rفصل في بيان الرؤية "]], "pg": [88, 93]}, "496.15": {"x": [[93, "أي: رؤية الله تعالى\r\r(ورؤية الإله) سبحانه وتعالى (بالأبصار) جمع بصر (تجوز) عقلا (عند أهل الاستبصار) أي: البصيرة، إما في الدنيا مناما فهي جائزة بالاتفاق كما تكلمنا عليها في كتابنا ((تعطير الأنام في تعبير المنام))، وإما يقظة فقد اختلف العلماء في ذلك والأقوى أنها لا تجوز. وقال القشيري: سمعت من ابن فورك يحكي عن الأشعري في ذلك قولين:"], [94, "دون تقابل أو اتصال ... بل بالذي يليق بالجلال\rوأهل الاعتزال والضلال ... قضوا بأنها من المحال\rإذ فسروا الرؤية بالشعاع ... وذاك في ذا الباب ذو امتناع\rوإنما الرؤية معنى خلقا ... في الشيء بالمرئي قد تعلقا\rوكون موسى سأل الجليلا ... في أمرها غدا لنا دليلا\r[الشرح]\rقال النووي: قلت: نقل جمع الإجماع على أنها لا تحصل للأولياء في الدنيا، قال: وامتناعها بالسمع وإلا فهي ممكنة بالعقل عند أهل الحق. وأما في الآخرة فهي جائزة باتفاق أهل السنة.\r(دون تقابل) أي: من غير مقابلة (أو اتصال) به سبحانه أو انفصال أيضا (بل بالذي يليق بالجلال) أي: عظمته سبحانه وتعالى إذ ليست رؤيته تعالى كرؤية غيره من المخلوقات فهي رؤية مخصوصة يخص بها تعالى من شاء من عباده على الوجه الذي يليق بجلاله وكماله (وأهل الاعتزال) أي: المعتزلة (والضلال) من الفرق المنكرين كذلك (قضوا) أي: حكموا (بأنها) أي: رؤية الله تعالى في الدنيا والآخرة (من المحال) الذي لا يتصور في العقل وجوده (إذ) أي: لأنهم (فسروا الرؤية بالشعاع) أي: اتصال الشعاع الخارج من العين بالمرئي أو ارتسام صورة من المرئي في العين (وذاك) أي: طريق الشعاع المذكور أو الارتسام (في ذا الباب) أيك في رؤية الله تعالى (ذو امتناع) أي: أمر ممتنع باتفاق منا ومن المعتزلة وإنما الخلاف هل يصمح أن تقع رؤية الله تعالى بدوت المقابلة والجهة وقوع الشعاع والارتسام وأن تتعلق الرية به تعالى منزها عن الجهة والمكان أم لا.\r(وإنما الرؤية معنى خلقا) بألفا الإطلاق، أي: خلق الله تعالى (في الشيء) أي: نفس الرائي إذا فتح بصره (بالمرئي قد تعلقنا) بألف الإطلاق أيضا، فالذي يخلقها بأسباب وشرائط على حسب العادة قادر على أن يخلقها أيضا بغير سبب ولا شرط إذ لا تأثير لسبب والشرط أصلا عند أهل السنة.\rوكون موسى) ابن عمران عليه السلام (سأل الجليلا) بألف الإطلاق أي: طلب من الله تعالى (في أمرها) أي: رؤية الله تعالى (غدا) أي: صار سؤاله ذلك (لنا دليلا) على جواز الرؤية في الدنيا والآخرة."], [95, "إذ مثله لا يجهل المحالا ... في حق من كلمه تعالى\rوقد رأى خير الورى الديانا ... ليلة إسراء به عيانا\rفي المذاهب المصحح المشهور ... وهو الذي ينمى إلى الجمهور\r[الشرح]\r(إذ مثله) أي: مثل موسى عليه السلام وهو نبي رسول من اولي العزم معصوم من الخطأ والخطل عالم بالله تعالى وبما يجب في حقه سبحانه وما يجوز وما يستحيل (لا يجهل) الأمر (المحالا) بألف الإطلاق (في حق من كلمه) وهو الله (تعالى) قال عز من قائل: {وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا} [النساء: 164]\r(وقد رأى) ببصره (خير الورى) أي: الخلق نبينا محمد صلى الله عليه وسلم (الديانا) هوه الرب سبحانه وتعالى (ليلة إسراء به) وهي ليلة المعراج وقصته مشهورة (عيانا) بالكسر. قال في القاموس: لقيته عيانا، أي: معاينة لم يشك في رؤيته إياه. (في المذهب المصحح المشهور) بين العلماء (وهر) القول (الذي ينمى) بالبناء للمفعول أي: ينسب (إلى الجمهور) من الصحابة والتابعين ومن بعدهم.\rقال في شرح الهمزية في المديح النبوي اختلفت العلماء قديما وحديثا في أن نبينا صلى الله عليه وسلم رأى ربه في هذا المقام الذي وصل إليه دون غيره من الخلق بعين رأسه أو بعين قلبه فقط. والذي صح عن ابن عباس رضي الله عنه، وفي رواية: ((أنه رأى ربه بعين بصره (¬1))) وفي الأخرى: (أنه رآه بعين قلبه) (¬2) ولا تخالف لأنه صح عنه كما رواه الطبراني بإسناد رجاله رجال الصحيح غلا واحد فوثقه ابن حبان: أنه صلى الله عليه وسلم رآه مرتين واحدة بالعين وواحدة بالقلب (¬3). بمعنى أنه تعالى خلق فيه إدراكا كإدراك البصر وليس المراد مجرد العلم لأنه حاصل له بل ولغيره فلا خصوصية ورواية بان مردويه من لم يره بعينه لم تصح وبتسليمها فالإثبات مقدم على النفي.\rوجاء عن أنس بإسناد قوي: رأى محمد صلى الله عليه وسلم ربه (¬4). وإطلاق الرؤية إنما ينصرف لرؤية العين. وكان الحسن البصري رحمه الله تعالى يحلف أن محمدا صلى الله عليه وسلم رأى ربه وبذلك قال عروة وسائر أصحاب بن عباس رضي الله عنه وجزم به كعب الأحبار والزهري، ومعمر وآخرون وهو قول الأشعري وغالب أتباعه، وأنكرت عائشة رضي الله عنها الرؤية.\r¬__________\r(¬1) رواه الطبراني في الأوسط (6/ 50)، وفي الكبير (11/ 224) بنحوه\r(2) ... رواه أبو نعيم في المسند المتخرج على مسلم (1/ 241)\r(3) ... أورده الهيثمي في مجمع الزوائد (1/ 79)، وعزاه للطبراني في الأوسط (6/ 50)\r(¬2) رواه البخاري (4/ 1840)، ومسلم (1/ 160)\r(5)"], [96, "والمؤمنون خصهم في الآخرة ... بها منيلهم مزايا فاخره\rكما أتى عن صاحب السيادة ... فالجنة الحسنى وذي الزيادة\rوكم أحاديث بها صريحة ... مروية من طرق صحيحه\r[الشرح]\rقال النووي: ولكن خالفها غيرها من الصحابة، والصحابي إذا خولف لا يكون قوله حجة اتفاقا ولا حجة لها فيها رواه مسلم عنها أن مسروقا قال لها: لم أنكرت الرية ألم يقال الله: {وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى} [النجم: 13] فقالت: أنا أول هذه الأمة سألت رسول الله صلى الله عليه وسلم عن هذا فقالت: يا رسول الله! هل رأيت ربك؟ قال: ((لا، إنما رأيت جبريل)). وذلك لأنها إنما سألت عن ما في الآية فأجابها بأن لم يره إلا في قصة المعراج ولا حجة لها في قوله تعالى: {لَا تُدْرِكُهُ الْأَبْصَارُ} [الأنعام: 103] لأن المراد لا تحيط بحقيقة ذاته العلية بدليل قوله تعالى: {إِلَى رَبِّهَا نَاظِرَةٌ} [القيامة: 23]. وإذا جازت في الآخرة جازت في الدنيا لتساويهما للمرئي، وسؤال موسى صلى الله عليه وسلم إياها في الدنيا أظهر دليل على ذلك إذ لا يجوز على نبي أن يسأل محالا.\r(المؤمنون خصم في) الدار (الآخرة) بسكون الهاء للوزن (بها) أي: بالرؤية (منيلهم) فاعل خصهم. أي: معطيهم وهو الله تعالى (مزايا) جمع مزية مفعول منيل بصفة اسم الفاعل. والمزايا: هي المراتب العالية التي خص الله تعالى بها بعض عباده المؤمنين يوم القيامة (فاخره) بسكون الهاء أيضا نعت لمزايا، أي: ذات فخر. والشيء الفاخر الجيد والفخار مثل كلام المباهاة بالمكارم والمناقب من حسب ونسب كذا في المصباح. واحتراز بالمؤمنين عن الكفار والمنافقين فإنهم لا يرون ربهم يوم القيامة لقوله تعالى: {كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ} [المطففين: 15]. وتدخل الملائكة في عموم المؤمنين كما نص عليه الأشعري و وافقه البيهقي والبلقيني، وجزم الجلال السيوطي بأن المؤمنين منه الجن تحصل لهم الرؤية أيضا ودخل في المؤمنين والمؤمنات أيضا النساء وكذلك المؤمنين من الأمم السابقة، وتمام هذه الأبحاث في كتابنا ((المطالب الوفية))\r(كما أتى عن صاحب السيادة) بسكون الهاء للوزن المؤذن وهو الله تعالى فإنه قال سبحانه: {لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ} [يونس: 26]. وزيادة (فالجنة) هي (الحسنى وذي) أي: هذه يعني رؤية المؤمنين لربهم في الجنة (الزيادة) بسكون الهاء أيضا كما ذكر جمهور أئمة التفسير (وكم أحاديث) جمع حديث عن النبي صلى الله عليه وسلم (بها) أي: بالرؤية"], [97, "كقوله: \"كما ترون القمرا\" ... وقبل هذا \"سترون\" الخبر\rووجه ذا التشبيه دون مريه ... نفى تزاحم لحال الرؤية\rلا أنه من كل وجه أشبه ... جل الإله أن يكون في جهة\r[الشرح]\rصريحه) بسكون الهاء للوزن أي: غير محتملة للتأويل (مروية) في كتب الأحاديث (من) عدة (طرق) جمع طريق بأسانيد (صحيحه) ليس فيها طعن لطاعن.\rكقوله) صلى الله عليه وسلم (كما ترون القمرا) بألف الإطلاق (وقل هذا) المقول قوله عليه الصلاة والسلام في ابتداء هذا الحديث إنكم (سترون الخبرا) بألف الإطلاق أي: اقرأ الخبر الوارد وهو ما رواه أصحاب الكتب الستة بأسانيدهم عن جرير بن عبد الله البجلي رضي الله عنه قال: كنا جلوسا عند النبي صلى الله عليه وسلم إذ نظر إلى القمر ليلة البدر قال: إنكم سترون ربكم كما ترون هذا القمر لا تضامون في رؤيته (¬1)).\r(ووجه ذا التشبيه) الواقع في هذا الحديث في قوله: (كما ترون هذا القمر). (دون مريه) بكسر الميم اسم من امترى في أمره، شك كذا في المصباح (نفي تزاحم) أي: مزاحمة (لحال الرؤية) فالتشبيه إنما هو في الرؤية في المرئي لأنه صلى الله عليه وسلم قال: ((سترون ربكم كما ترون القمر)). وجه هذا التشبيه من جهة أن الناس في رؤيته لا يتزاحمون بحيث إن بعضهم يشغل القمر برؤيته له عن رؤية غيره له فلا يقع لهم الضميم في رؤيتهم له في وقت واحد وهم ألوف وإلى ذلك الإشارة بقوله صلى الله عليه في هذا الحديث: ((لا تضامون في رؤيته)). لا أنه أي: هذا التشبيه لرؤية الله تعالى برؤية القمر (لا أنه من كل وجه اشبه) بسكون الهاء للوزن، أي: هذا التشبيه لرؤية الله تعالى برؤية القمر (لا أنه من كل وجه أشبهه) بسكون الهاء للوزن، أي: أشبه الرب تعالى (جل) أي: عظم (الإله أن يكون في جهه) بسكون الهاء أيضا.\rقال اللقاني رحمه الله تعالى في بيان الرؤية: إنها الإدراك التام بحاسة البصر بلا كيف للمرئي من مقابلة وجهة ونحوهما مما هو تابع لرؤية المخلوق عادة وتساوي الرؤيتين غير لازم قطعا، وقياس الغائب على الشاهد فاسد. وقال الأصفهاني: إنه تعالى يرى من غيره ارتسام صورة المرئي في العين أو اتصال شعاع إلى المرئي وحصول مواجهة لما عرفت أنه تعالى مقدس عن الجهة منزه عن المكان متعال عن المواجهة. (¬2)\r¬__________\r(¬1) () رواه البخاري (11/ 203، 209)، ومسلم (1/ 439).\r(¬2))) رواه البخاري (6/ 2703)."], [98, "فصل في أحكام الرسالة والنبوة\r"]], "pg": [93, 98]}, "496.16": {"x": [[98, "وبعثه الرسل إلينا جائزة ... في حقه وكل خير حائزة\rكي يبلغونا أمره ونهيه ... فمن أجابهم غدا ذا نهيه\r[الشرح]\rفصل في بيان أحكام الرسالة من الله تعالى إلى البشر والنبوة الاختصاصية\r\r(وبعثه الرسل) جمع رسول من الله تعالى (إلينا) معشر المكلفين بمعنى العقلاء البالغين (حائزه) بسكون الهاء أي: كيفية أفعاله تعالى غير واجبة عليه خلافا للمعتزلة بناء على مسألة وجوب الصلاح والأصلح عندهم، ولا مستحيلة أيضا خلافا للبراهمة والسمنية (في حقه) أي: الله تعالى (وكل خير حائزه) بسكون الهاء، أي: جامعة الأنواع الخيرات، وبين جائزة الجناس المصحف.\rواعلم أن البعثة لطف من الله تعالى ورحمة للعالمين لما فيها من حكم ومصالح لا تخفى منها معاضدة العقل فيما يستقل بمعرفته مثل وجود الباري تعالى وعلمه وقدرته {لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللَّهِ حُجَّةٌ بَعْدَ الرُّسُلِ} [النساء: 165]\rومنها: بيان حال الأفعال التي تحسن تارة وتقبح أخرى من غير اهتداء العقل إلى موافقتها. ومنها: بيان منافع الأغذية والأدوية ومضارها التي لا تفي بها التجرية إلا بعد أمرار وأطوار مع ما فيها من الأخطار. ومنها: تكميل النفوس البشرية بحسب استعداداتها المختلفة في العلميات والعمليات. ومنها: تعليم الصنائع الخفية من الحاجات والضروريات.\rومنها: تعديل الأخلاق الفاضلة الراجعة إلى الأشخاص والسياسات الكاملة العائدة إلى الجماعات من المنازل والمدن، ومنها: الإخبار بتفضيل ثواب المطيع وعقاب العاصي ترغيبا في الحسنات وترهيبا عن السيئة إلى غير ذلك من الفوائد.\rفلهذا قالت المعتزلة بوجوبها على الله تعالى والفلاسفة بلزومها في حفظ نظام العالم كذا في شرح المقاصد للسعد.\r(كي يبلغونا) أي: الرسل عليهم الصلاة والسلام، بمعنى: يوصلونا من أبلغ بمعنى بلغ بالتشديد، أي: أوصل. قال في المصباح: أبلغه السلام وبلغه بالألف والتشديد أوصله."], [99, "ومن أبى فساقط في هوة ... وما بكسب تدلك النبوة\rولا بحملة ولا ارتياض ... لكن بفضل ذي الندى الفياض\rيخص من أراد بالعناية ... وبالرسالة او الولاية\r[الشرح]\r(أمره) أي: الله تعالى (ونهبه) بسكون الهاء للوزن (فمن أجابهم) بقبول جمع ما جاءوا به من الأمر والنهي وغير ذلك اعتقادا وامتثالا (غدا) أي: صار (ذا) أي: صاحب (نهية) بضم النون وسكون الهاء، وفتح الياء التحتية والهاء والثانية ساكنة للوزن.\rقال في المصباح: النهية العقل: لأنها تنهى عن القبيح والجمع نهي مثل مدية ومدى (ومدى أبي) أي: امتنع عن قبول شيء من ذلك (فساقط) أي: وقع (في هوه) بضم الهاء وتشديد الواو والهاء الثانية ساكنة للوزن. والهوة: الحفرة، وقيل: الوهدة العميقة، كذا في المصباح. (وما بكسب) أي: اكتساب وسعى (تدرك) بالبناء للمفعول، أي: تحصل (النبوة) بسكون الهاء وكذا الرسالة.\r(ولا بحيلة) يحتالها العبد (ولا ارتياض) أي: عمل رياضة كما زعمت الفلاسفة (لكن) تكون بفضل (ذي) أي: صاحب (الندى) أيك العطاء والكرم (الفياض) قال السنوسي رحمه الله تعالى في شرح منظومة ابن الجزري:\rوليست النبوة عند أهل الحق ذاتيه ... لنبي كما صار إليه الكرامية\rولا مكتسبة كما صار إليه الفلاسفة فإنهم يرون التزكية والتخلية صقالا في مرآة النفس إلى أن يتهيأ لما لا يتهيأ لإدراكه غير بل ترجع النبوة عند أهل الحق إلى اصطفاء الله تعالى عبدا من عباده بالوحي إليه.\r(يخص) أي: الله تعالى (من أراد) من عباده (بالعناية) بسكون الهاء وكسر التاء المثناة الفوقية وهي هنا كناية عن النبوة (وبالرسالة) كذلك فضلا من الله تعالى وإحسانا وكرما على عبادة وامتنانا (أو الولاية) بالهاء الساكنة أو التاء المكسورة. يعني: أن الولاية في الأولياء أيضا حاصلة بلا كسب من العبد ولا حيلة ولا رياضة، وإنما هي بمحض فضل الله تعالى وعناية بمن شاء من عباده، وقد مشى على ذلك في شرحها.\rوالذي عليه المحققون من الأولياء والعارفين بربهم أن الولاية ليست كالنبوة وأنها مكتسبة والنبوة غير مكتسبة كما حققنا في كتابنا (المطالب الوفية) وقال الشيخ الأكبر."], [100, "وهو أي الرسول إنسان دكر ... أوحى له من لم تكيفه الفكر\rوقال بلغ من بعثت فيهم ... حكما دعوا إليه يقتفيهم\rوإن يك الوحي بحكم قصرا ... عليه فالنبي فيما اشتهر\r[الشرح]\rمحيي الدين العربي رفي كتابة ((الفتوحات المكية)): الولاية مكتسبة إلى يوم القيامة، فمن يعمل في تحصيلها حصلت له، والعمل في تحصيلها اختصاص من الله تعالى: {يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشَاءُ} [البقرة: 105].\r(وهو أي) يعني النبي (الرسول) من الله تعالى إلى العباد (إنسان ذكر) بسكون الراء للوزن، فخرج بالإنسان غيره من الملائكة والجن وبقية الخلق، وخرج بقوله ذكر الأنثى والخنثى فليس منها نبي قط لنقصان خلقتهما بالنسبة إلى الرجال، قال الله تعالى: {وَمَا أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا} [الأنبياء: 7] الآية. ولابد من قيد الحرية أيضا ليخرج العبد كلقمان رضي الله عنه فإنه ول وليس بنبي على الصحيح. (أوحى له) أي: كلمه بواسطة الملك أو بغير واسطة (من لم تكيفه) بالتشديد (الفكر) بكسر الفاء وفتح الكاف وسكون الراء جمع فكرة وهو الله تعالى، وقال: أي الله تعالى له (بلغ) بالتشديد، أي: أوصل عني (من) مفعول بلغ (بعثت) بالبناء للمفعول، أي: بعقتك (فيهم) بسكون الميم، أيك منهم لهم (حكما) مفعول بلغ (دعوا) بالبناء للمفعول، أي: دعوتهم أنا (إليه) أي: إلى قبوله وامتثاله (يقتفيهم) أي: يتبعهم على مقتضى ما هو اللائق بهم من الحكمة البالغة وعلى حسب ما يطيقونه بلا حرج عليهم في ذلك.\r(وإن يك) أي: يكن الوحي من الله تعالى إلى عبد من عباده في زمان النبوة قبل انقطاعها 0 بحكم) من أحكامه سبحانه وتعالى (قصرا) بألف الإطلاق، أي: في ذلك الحكم (عليه) فلم يتعده إلى غيره، يعني: لم يؤمر بتبليغه للغير (فالنبي فيما اشتهر) بألف الإطلاق أي: اشتهر بين العلماء وقد اختلف العلماء في النبي والرسول على أربعة أقولا بحسب النسب الأربع: فقيل: بينهما نسبة التوافق فكل نبي رسول، وكل رسول نبي، وقد اعتمد هذا الشيخ عبد الرؤوف المناوي في شرح الجامع الصغير للسيوطي، وقال: إن الزمخشري والعضد والتفتازاني والشريف الجرجاني على ترادفها وأنه لا فارق إلا الكتاب، قال: وإن كان المشهور بين الفقهاء ما ذكره الحليمي من التغاير بينهما وأن الفارق الأمر بالتبليغ."], [101, "فصل فيما يحب لهم وما يستحيل وما يجوز\r"]], "pg": [98, 101]}, "496.17": {"x": [[101, "وصدق رسل واجب في كل ما ... قالوا فكن لصدقهم مسلما\r[الشرح]\rوقيل: نسبة التباين، فالنبي غير الرسول والرسول غير النبي، فالنبي هو الذي يحكم بالمنزل على غيره مع أنه يوحى إليه، والرسول هو صاحب الكتاب والشريعة. وقيل: نسبة العموم والخصوص من وجه. فالنبي والرسول يجتمعان في مثل محمد صلى الله عليه وسلم وينفرد النبي في إنسان أوحى إليه بشرع ولم يؤمر بتبليغه كيعقوب صلى الله عليه وسلم، وقيل: نسبة العموم والخصوص المطلق، فكل رسول نبي وليس كل نبي رسول. وهذا القول هو المشهور، ومشى عليه الناظم هنا وتمام تحقيق هذا في كتابنا ((المطالب الوفية))\r\r(فصل فيما يجب) عقلا (لهم) أي: للأنبياء والرسل عليهم السلام\r(وما يستحيل) عليهم (وما يجوز) في حقهم من الصفات\r\rوصدق رسل بسكون السين المهملة جمع رسول (واجب) عقلا بحيث لا يتصور في لاعقل عدمه، والصدق هو مطابقة الكلام للواقع وشارع في الأقوال خاصة، وقد يطلق على العقائد والأديان والمذاهب باعتبار اشتمالها على المطابقة للواقع ويرادف الحق، وقد يفرق بينهما بالاعتبار، فالصدق ما طابق الواقع من ذلك، والحق ما طابق الواقع منه، والكذب ضد الصدق، والباطل ضد الحق (في كل ما) أي: أقول (قالوا) أ]: الرسل عليهم السلام (فكن) يا أيها المكلف (لصدقهم) الذي جاءوا به (مسلمّا) بتشديد اللام أي: مستلما منقادا لذلك منذ عنا له، فإن جميع ما أخبروا به عن الله تعالى مطابق لما أمرهم الله تعالى أن يخبوا به عنه سبحانه؛ لأن إخبارهم كله عما أمرهم الله تعالى أن يخبروا به عنه، فعم مبلغون عن الله تعالى أمره ونهيه ووعده ووعيده وليسوا مخبرين عن أمر من الأمور من قبل أنفسهم فليسوا مبلغين عن غير الله تعالى مطلقا وإن أطلعهم الله تعالى وعما أطلعهم عليه، قال تعالى: {يَاأَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ} [المائدة: 67] وقال تعالى: {إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى} [النجم: 4] الآية.\rوروى أبو داود السجستاني في سننه عن جابر بن عبد الله رضي الله عنه، عن النبي صلى الله عليه وسلم قال: ((أذن لي أن أحدث عن ملك من الملائكة الله تعالى من حملة العرش أن ما بين شحمه أذنه إلى عاتقه مسيرة سبعمائة عام.))"], [102, "والكذب اعدده من المحال ... في جانب الرسل بكل حال\rلأنه يفضى لوصف الباري ... سبحانه بالخق في الأخبار\rمن أجل تصديق لهم بالمعجزة ... منجدة لما ادعوه منجزة\r[الشرح]\rقال المناوي في شرح هذا الحديث: الآذن له هو الله تعالى، ولو لا الإذن لم يجز له التحديث، فهو تنبيه على أن من أطلعه الله تعالى شيء من الأسرار ثم أفشاه بغير إذن عُذّب بالنار.\rوذكر الطيبي في قوله: أذن لي، قال: يفيد ان علم الغيب مختص به تعالى لكمنه يطلع من يشاء على من شاء وليس على من أطلعه أن يحدث إلا بإذنه. انتهى فليس في شيء مما جاءوا به مخبرين عن الله تعالى كذب وحاشاهم من ذلك، فلو أمرهم الله تعالى وكان ذلك الخبر الذي أخيروا به صدقا أيضا لأنه مطابق لما أمرهم الله به، وهم مبلغون عن الله تعالى وصادقون في تبليغهم ذلك، وكون ذلك الخبر غير مطالق للواقع لا يقدح في تسميته صدقا مطابقا لما أمر الله تعالى به، فالصدق الشرعي هو الحسن والكذب الشرعي هو القبيح لا الصدق العقلي، والكذب العقلي، وهي مسألة التحسين والتقبيح التي خالف فيها المعتزلة وقد سبق بيانها، (والكذب) على الله تعالى في شيء من أمره تعالى ونهيه (اعدده) يا أيها المكلف (من المحال) الذي لا يتصور في العقل وجوده (في جانب الرسل) عليهم الصلاة والسلام (بكل حال) من الأحوال (لأنه) أيك الكذب (يفضي) أي: يوصل (لوصف الباري سبحانه) وتعالى (بالحق) أي: عدم الوفاء (في الأخبار) أي: أخباره تعالى عنهم أنهم صادقون في جميع ما يبلغونه عنه تعالى.\r(من أجل تصديق) أي: تصديقه تعالى (لهم) أي: الرسل عليهم الصلاة والسلام (بالمعجزة) بسكون الهاء للوزن، وهي أمر خارق للعادة مقرون بالتحدي مع عدم المعارضة، فالأمر يشمل الفعل كانفجار الماء من بين الأصابع وعدمه كعدم إحراق الناس والاقتران بالتحدي الإخراج كرامات الأولياء والعلامات الإرهابية التي تتقدم بعثة الأنبياء عليهم السلام، وقيد عدم المعارضة لاستخراج السحر والشعبذة وسيأتي بيان التحدي عند تعرض الناظم له. (منجدة) حال من المعجزة، من أنجده: أعانه أ]: معينه وساعده ومؤكده (لما) أي: (ادعوه) عليهم السلام من الإخبار عن الله تعالى (منجزة) بسكون الهاء، من أنجزت الواعد إذا عجلته، أي: معجلة ذلك أيضا ومحققة له."], [103, "وهي كقول الله هذا العبد ... يصدق فيما منه عنا يبدو\rوكل من صدق كاذبا نمي ... للكذب الذي به ذاك رمي\rوهو أي الكذب مستحيل ... في حق رب وصفه جليل\rلأنه يخبر وفق علمه ... وذاك صدق ثابت في حكمه\r[الشرح]\r(وهي) أي: المعجزة (كقول الله) تعالى (هذان العبد) الذي أرسلته (يصدق فيما) أي: في جميع الذي (منه عنا يبدو) أي: يظهر، فخلق المعجزة قائم مقام هذا القول المذكور.\rقال إمام الحرمين في الإرشاد المرضى: عندنا أن المعجزة تدل من حيث تنزل منزلة التصديق بالقول وغرضنا تبيين ذلك بفرض مثال. فنقول: إذا تصدى ملك للناس وتصدر ليلج عليه رعيته واحتفل المجلس واحتشد وقد أرهق الناس شغل شاغل فلما أخذ كل مجلسه وترتب الناس على مراتبهم انتصب واحد من خواص الملك وقال: معاشر الأشهاد قد حزبكم أمر عظيم وأظلكم خطب جسيم وأتى رسول الله الملك إليكم ومؤتمنه لديكم ورقيبه عليكم ودعواي هذه بمرأى من الملك ومسمع فإن كنت أيها الملك صادقا في دعواي فخالف عادتك وجانب سجيتك وانتصب في صدرك ثم اقعد ففعل ذلك الملك على وفق دعواه ومطابقة هواه، فيستقين الحاضرون على الضرورة تصديقه إياه وتنزيل الفعل الصادر منه منزلة القول المصرح بالتصديق.\r(وكل من صدق كاذبا) فيما أتى به (نمي) بالبناء للمفعول، أي: نسب ذلك الصدق (للكذب الذي به ذاك) أي: الكاذب (رمى) بالبناء للمفعول، يعني: أن من صدق الكاذب فهو كاذب وتصديقه له كذب.\rوهو أي الكذب مستحيل) لا يتصور في العقل وجوده (في حق رب وصفه جليل) أي: عظيم قال تعالى: {وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا} [النساء: 122]. (لأنه) تعالى (يخبر) بكلامه القديم وبما ينزل منزلة كلامه من الإشارات الحادثة التي منها ما أشار إليه البيضاوي في تفسير قوله تعالى: {وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ} [الأعراف: 172]. أي: أخرج من أصلابهم نسلهم على ما يتوالدون قرنا بعد قرن {وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ} [الأعراف: 172]. أي: ونصب لهم دلائل ربوبيته وركب في عقولهم ما يدعوهم إلى الإقرار بها حتى صاروا بمنزلة من قيل لهم: ألست بربكم؟! قالوا: بلى، فترك تمكينهم من العلم بها وتمكنهم منه منزلة الإشهاد والاعتراف على طريقة التمثيل"], [104, "وواجب أمانة أي عصمة ... للرسل جل قدرتهم عن وصمه\rويستحيل منهم ارتكاب ذي ... نهي وقول ذي الضلالة انبذ\rولو فرضنا منهم إيقاعه ... لانقلب المنهي عين الطاعة\r[الشرح]\rووفق) أي: مقدار، يقال: كسبه وفق عياله، أي: مقدار كفايتهم كذا في المصباح (علمه) سبحانه (وذاك) أي: علمه تعالى (صدق) أي: مطابق للأمور على ما هي عليه ثابت أي: محقق لا شبهة فيه ولا شدة تعتريه (في حكمه) الذي هو مقتضى كونه علما وهو كشفة عن المعلومات الواجبة والجائزة والمستحيلة، كما يستحيل عليه أن يعلم الشيء على خلاف ما هو عليه حتى لا يكون علمه جهلا به، ويستحيل عليه تعالى أيضا أن يخبر عن الشيء على خلاف ما هو عليه ذلك الشيء حتى لا يكون خبره كذبا، فإن الله تعالى وإن حاز في حقه أ، يضل من يشاء ويهدي من يشاء لكن لا يجوز في حقه تصديق الكاذب لأنه تعالى بإضلاله من يشاء يظهر عدله في حقه ولا يلزم ذلك من نقص ي حقه.\rوأما تصديق الكاذب فيلزم منه وقوع الكذب في حقه تعالى ويلزم من ذلك انقلاب علمه جهلا وهو محال عليه تعالى.\r(ووجب) عقلي أيضا بحيث لا يتصور في العقل عدمه (أمانة أي عصمه) بسكون الهاء للوزن، عصمه الله من المكروه يعصمه من باب ضرب، حفظه ووقاه والاسم العصمة، كذا في المصباح (للرسل) أي: المرسلين من عند الله تعالى إلى الخلق (جل) أي: عظم (قدرهم) أي: حرمتهم ووقارهم (عن وصمه) بسكون الهاء وهي الكسل والفترة، تعالى عليهم ظواهرهم وبواطنهم من التلبس بمنهي عنه نهي تحريم أو كراهة.\r(ويستحيل) عقلا وشرعا (منهم) أي: الأنبياء عليهم السلام (ارتكاب) أمر (ذي) أي: صاحب (نهي) عنه، أي: أمر منهي عنه شرعا من الكبائر والصغائر عمدها وسهوها قبل النبوة وبعدها على الصحيح (وقول ذي) أي: صاحب (الضلالة) من المعتزلة والخوارج والشيعة الذين جوزوا على الأنبياء عليهم السلام ما لا يليق بعلو مقامهم من أنواع الذنوب (انبذ) بكسر الذال المعجمة للقافية: أي: اطرح واترك ذلك.\r(ولو فرضنا) أي: قدرنا (منهم) بضم الميم للوزن (إيقاعه) بسكون الهاء أي: الأمر المنهي عنه شرعا (لانقلب) ذلك الأمر (المنهي) عنه شرعا (عين الطاعة) بسكون الهاء أيضا فكان ذلك الأمر طاعة منهم الله تعالى."], [105, "الأمر ربنا بالاقتداء بهم ... في غير مقصرو على جنابهم\rوالله لا يأمر بالفحشاء فلا ... يأتون غير طاعة كما انجلا\rوأولا بلائق مشتبها ... كما أتى في يوسف هم بها\r[الشرح]\r(الأمر ربنا) سبحانه وتعالى لنا معشر المكلفين (بالاقتداء) بوصل الهمزة والقصر للوزن (بهم) عليهم السلام، أي: المتابعة لهم (في غير) أمر (مقصور على جنابهم) أي: هم مخصوصون به، وبيان ذلك أن الله تعالى قال: {آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا} [الحشر: 7]\rوقال تعالى: {الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الْأُمِّيَّ} [الأعراف: 157] الآية. وقال تعالى: {وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ} [الأعراف: 158] وقال تعالى: {أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ} [النساء: 59]\r(والله) سبحانه وتعالى (لا يأمر بالفحشاء) بالقصر للوزن (فلا يأتون) أي: يفعلون (غير طاعة) لله تعالى في ظواهرهم وبواطنهم على كل حال (كما انجلى) أ]: انكشف منهم واتضح عند أهل البصائر المنورة والسرائر المطهرة (وأولا) أمر بالتأويل لك يا أيها المكلف (بلائق) بهم عليهم السلام، أي: تأويل مناسب لعلو مقامهم أمرا (مشتبها) عليك قد ورد في حقهم عليهم السلام في النصوص القطيعة التي لا يمكن ردها (كما أتى) في القرآن العظيم (في) حق (يوسف) عليه السلام في قوله تعالى: ({وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَنْ رَأَى بُرْهَانَ رَبِّهِ} [يوسف: 24] قال البيضاوي: قصدت مخالطته وقصد مخالطتها، والهم بالشيء قصده والعزم عليه، ومنه الهمام: وهو الذي إذا هم بالشيء أمضاه، والمراد بهمه ميل الطبع ومنازعة الشهوة لا القصد الاختياري وذلك مما لا يدخل تحت التكليف بل الحقيق بالمدح والأجر الجزيل من الله تعالى من يكف نفسه عن العقل عند قيام هذا لاهم أو مشارفة الهم كقولك: عتلته لو لم أخف الله. قال: ولا يجوز أن يجعل (وهم بها) جواب (لولا) فإنها في حكم أدوات الشرط فلا يتقدم عليها جوابها بل الجوال محذوف يدل عليه المذكر."], [106, "وكون والد الورى قد أكلا ... وما سوى ذلك مما أشكلا\r[الشرح]\r(وكون والد الورى) أي: الخلق يعني نوع البشر منهم وهو آدم عليه السلام (قد أكلا) بألف الإطلاق، أي: أكل من الشجرة التي من الشجرة التي نهاه عنها في قوله سبحانه: {وَقُلْنَا يَاآدَمُ اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ} [البقرة: 35] والجواب عن ذلك أن الله تعالى به أن يأمر وينهى ويلقب بالألقاب لمن شاء كيف شاء ويؤاخذ ويعفوا على وجه التكليف وعلى وجه التشريف قبل بعثه الرسل وبعدها لمن هو محل التكليف كالإنسي والجني ولمن لم يكن محل التكليف كما قال للسماوات والأرض والجبال كما في الآية، فأخبر تعالى عن آدم عليه السلام أنه نهاه عن أكل الشجرة ولم يكن لآدم حينئذ بعثة ولا تكليف بشرع ولا أمة له، وأخبر تعالى أنه أمر إبليس بالسجود لآدم فأبى واستكبر حيث لم يقبل هذا الأمر وكان من الكافرين، ولم يكن كفره من عدم سجوده لآدم فإن العصيان ليس بكفر خصوصا العصيان قبل شرع الشرائع وتقرير الأحكام بالبعثة، وإنما كفره من عدم قبوله للحكم الإلهي عليه بما أمر به وهي الإنابة المذكورة في الآية، فأخبر تعالى عنه أنه من الكافرين، وآدم عليه السلام قبل النهي ولكنه فعل ما نهي عنه بوسوسة الشيطان له بذلك فلقبه الله تعالى بما أخبر عنه من أنه عصى وغوى وكان من الظالمين، وأنه اجتباه وتاب عليه وهدى، كما قال لنبينا محمد صلى الله عليه وسلم: {لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ} [الزمر: 65]\rمع علمه تعالى أن هذه الأمور لا تصدر منه صلى الله عليه وسلم، فإنه لا يشرك ولا يحيط عمله ولا يكون في الآخرة من الخاسرين، ولكن لما كانت الأنبياء عليهم السلام من أعز الخلق على الله وأكملهم وأشرفهم عنده أخبر عنهم بمثل ذلك حتى يعتبر بهم غيرهم ممن هو دونهم من الأمم في مخافة أمره ونهيه وهذا الإطلاق في حقهم لا يخرجهم من مقام عصمته لهم حفظه لأحوالهم واحترامه تعالى لجنابهم لأنهم خاصة خلقه وأشرف عباده، فحسنات غيرهم إذا صدرت عنهم كانت سيئات لهم عند ربهم فيلامون عليها ويعاتبون ويطلق عليهم بسببها لقب العصيان ونحو ذلك: {وَاللَّهُ بَصِيرٌ بِالْعِبَادِ} [آل عمران: 15]"], [107, "وقل إذا استدللت للتبليغ ... لو كتموا لكان ذا تسويغ\rفيتكلم المرء العلوم النافعة ... عن طالب لها ويغدو مانعه\r[الشرح]\r(وما سوى ذلك) المذكور في يوسف وآدم عليهم السلام (مما أشكلا) بألف الإطلاق في حق بقية الأنبياء عليهم السلام، فإنه محمول على أحسن المحامل ومصروف عن ظاهره المقتضى للنقص في مقاماتهم العلية، وهو غير مناف لعصمتهم من جميع الذنوب الكبائر والصغائر قبل النبوة وبعدها عمدها وسهوها وخطأها كما قدمنا.\rوالحاصل أنه لا تقاس ذنوب المعصومين المحفوظين عند ذي الجلال على ذنوب غير المعصومين من القاصرين الغافلين المغمورين في ظلمات الطبع والهوى كما لا تقاس حسناتهم بحسنات غيرهم، وما أحسن قول الشيخ العارف بالله محمد بن وفا المصري قدس الله سره هذا المقام من النظام:\rعبادك يا مولى الذي هم ... عبادك محفوظين حفظ الحبائب\rمن الذار لم يبدوا بصافي ذواتهم ... سوى نورك الماحي لجنح الغياهب\rذوات صفت معنى ولطفا ورونقا ... وصينت عن الأكدار من كل جانب\rورضي الله تعالى عن حسان شاهر النبي صلى الله عليه وسلم حيث قال في قصيدته يوم فتح مكة في المديح المحمدي:\rخلقت مبرأ من كل عيب ... كأنك قد خلقت كما تشاء\rوللبوصيري رحمه الله تعالى في مثل ذلك:\rكرمت نفسه فلا يخطر السوء ... على قلبه ولا الفحشاء\r(وقل) يا أيها المكلف (إذا استدللت) أي: أقمت الدليل (للتبليغ) أي: تبليغ الأنبياء عليهم الصلاة والسلام لجميع ما أمروا بإبلاغه لأممهم (لو كتموا) فلو كتموا فلم يبلغوا شيئا من ذلك (لكان) أي: ذلك الكتمان (ذا) أي: صاحب (تسويغ) أي: كان أمرا سائغا، أي: جائزا، يقال: ساغ فعل الشيء، بمعنى الإباحة ويتعدى بالتضعيف فيقال سوغته، أي: أبحثه كذا في المصباح,\r(فيكتم المرء) أي: الإنسان (العلوم النافعة) بسكون الهاء للوزن (عن طلب لها) من الناس (ويغدو) أي: يصير (مانعه) بسكون الهاء أيضا أي: مانع العلم النافع ويسوغ له ذلك شرعا."], [108, "كيف وقد باء ذوو الكتمان ... للرشد باللعنة في القرآن\rوالمصطفى المعجز كل الفصحا ... أدى الرسالة وكلا نصحا\rواقتضت الآيات في الكتاب ... تبليغه والنفي للعتاب\rفالله يجزيه أجل ما به ... جازى نبيا ذا مقام نابه\r[الشرح]\r(كيف) يقال هذا (و) الحال أنه (قد جاء) أي: رجع (ذووا) أي: أصحاب (الكتمان) الذين يكتمون (للرشد) من العلوم النافعة عن طالبها منهم (باللعنة) أي: البعد و الطرد عن رحمة الله تعالى متعلق بيانه (في القرن) قال تعالى: {إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ أُولَئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ} [البقرة: 159]\r(والمصطفى) نبينا محمد صلى الله عليه وسلم (المعجز) أي: الذي أعجز (كل الفصحا) بالقصر للوزن جمع فصيح، وهو التكلم بالعربية من غير لحن (أدى) إلى هذه الأمة (الرسالة) جاء بها إلى أمته (وكلا) أي: كل واحد من أمته (نصحا) بألف الإطلاق أي: وصل الله تعالى نصيحته لكل مكلف من أمته بمشافهته وبعلماء ملته.\r(واقتضت الآيات) القرآنية المنزلة (في الكتاب) أي: القرآن العظيم (تبليغه) أي: نبينا صلى الله عليه وسلم ما أمر بإبلاغه حتى سماه الله مناديا ينادي للإيمان أن آمنوا بربكم فآمنا الآية.\rقال البيضاوي: والمراد بالمنادى الرسول صلى الله عليه وسلم، وقال الله تعالى له صلى الله عليه وسلم من كثرة تبليغه وإنذاره لأمته وزيادة حرصه على هدايتهم: {إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ} [القصص: 56] وقال له: {فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍ} [فاطر: 8] وقال له: {قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَى} [الشورى: 23]. أي: على ما بلغتكم ونصحت لكم.\r(و) اقتضت الآيات أيضا (النفي للعتاب) عنه صلى الله عليه وسلم أي: المعاتبة في التقصير في قوله تعالى: {لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ} [البقرة: 272] وقوله تعالى: {لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍ} [الغاشية: 22] أي: بمسلط. وقوله: {مَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ} [المائدة: 99] ونحو ذلك (فالله) سبحانه وتعالى بجزل كرمه وجوده (يجزيه) أي: نبينا صلى الله عليه وسلم (أجل) أي: عظم (ما) أي: جزى (به) بسكون الهاء (جازى نبيا) قلبه عن أمته (ذا) أي: صاحب (مقام نابه) بسكون الهاء أيضا"], [109, "من النباهة، وهي الشرف. قال في المصباح: نبه بالضم نباهة شرف فهو نبيه. انتهى، ونبيه بمعنى: نابه.\rوغير قادح من الأعراض ... في حقهم يجوز كالأمراض\rللأجر والتشريع والتجلي ... عن زهرة الدنيا وللتسلي\rإذ خيرة العباد عنها أعرضوا ... وربهم قرضا جميلا أقرضوا\rولله لم يرد لأنبيائه ... بها جزاء أو لأوليائه\rفيحصل الزهد من الأنام ... في عيشها الذاهب كالمنام\r[الشرح]\r(وغير قادح) أي: منقص من القدح، يقال: قدح فلان في فلان عابه ووقع فيه (من الأعراض) البشرية أي مما يعرض للبشر (في حقهم) أي: الأنبياء عليهم السلام (يجوز كالأمراض) جمع مرض، وهو: الداء المقتضي للآلام والوجع، لا المراض المزن أو ما تعافه الأنفس كالأفعال والبرص والجذام والعمى والجنون وما حصل ليعقوب عليه السلام كان غشاوة فزالت وليس بعمى. ويجوز عليهم جميع الأعراض البشرية التي لا تؤدي إلى نقص في مراتبهم العلية كالجوع والعطش والغضب والضجر والضعف وأنواع المحن بزيادة في مكانتهم ورفعة في درجاتهم، وأسباب الاستخراج حالات الصبر والرضا والشكر والتسليم والتوكل والتفويض والدعاء، والتضرع منهم.\r(للأجر) أي: حكمة ذلك حصول الأجر لهم من الله تعالى (والتشريع) للأحكام في الأمة كصلاة المريض وكيفية الأكل والشرب والنوم ولبس الثياب ونحو ذلك (والتخلي) أي: الفراغ والرجوع (عن) الانهماك (زهرة) الحياة (الدنيا) باعتبار أحوالهم عليهم الصلاة والسلام فيها ومعايشهم في المساكن والملابس (وللتسلي) أي: فوات الحظوظ فيها أي: لأن (خيرة العباد) أي: المختارين منهم (عنها) أي: عن الدنيا (أعرضوا) فلم يرغبوا فيما زاد على قدر كفايتهم منها أدنى الكفاية (وربهم) مفعول مقدم (قرضا جميلا) أي: حسنا (أقرضوا) كما قال تعالى: {مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ} [البقرة: 245]. وذلك بأن يبدل إحسانهم إلى فقراء المؤمنين وإيثارهم بالمعروف.\r(والله لم يرد لأنبيائه) لكرام عليهم الصلاة والسلام (بها) أي: بالدينا (جزاء أو لأوليائه) الصالحين عليهم رضوان رب العالمين (فيحصل الزهد) أي: الإعراض بالقلب عن الدنيا وترك الانهماك في لذاتها وشهواتها (من الأنام) أي: الناس المتقدمين بالأنبياء"], [110, "عليهم السلام والمتابعين لهم من أممهم (في عيشها) أي: الدنيا (الذهب كالمنام) أي: كالخيالات التي يراها النائم في منامه فإذا استيقظ لا يجد شيئا منها\r\rوكل من أمد بالتوفيق ... ممن بأعين التحقيق\rيعلم قطعا أنها خسيسة ... ويحذر التموية والدسيسة\rولم يفز منها من ادخر ... أعمال طاعات بها قد افتخر\rوهي حراب ما بها إقامة ... والله نرجو حسن الاستقامة\r\rفصل في عدة الرسل عليهم السلام\r"]], "pg": [101, 110]}, "496.18": {"x": [[110, "وعدة الرسل الكرام الكمل ... في اسم محمد بدت في الجمل\r[الشرح]\r(وكل من أمد) بالبناء للمفعول، أي: أمده تعالى وأيده (بالتوفيق) وهو خلق الطاعة في العبد على مقتضى إرادته لها (ممن رأى) أي: أبصر الأمور بأعين التحقيق من غير شك ولا شبهة (يعلم قطعا أنها) أي: الدنيا (خسيسة) بسكون الهاء للوزن، أي: حقيرة ويحذر التموية، يقال: قول مموه أي: مزخرف أي: ممزوج من الحق والباطل كذا في المصباح (والدسيسة) بسكون الهاء، من دس الشيء أخفاه ومنه يقال للجاسوس دسيس القوم.\r(ولم يفز منها) أي: الدنيا (سوى من ادخر) بسكون الراء للوزن (أعمال طاعات) له أخلص فيها (بها) أي: في الآخرة يوم العرض على الله تعالى (وقد افتخر) بسكون الراء لا في الدنيا لأن ذلك مذموم.\r(وهي) أي: الدنيا (خراب ما بها) أي: فيها (إقامة) بسكون الهاء أي: لأحد مطلقا (والله نرجو) من كرمه وإحسانه أ، يمنحنا فيها (حسن الاستقامة) بسكون الهاء أي: الدوام على العمل الصالح في الظاهر والباطن.\r\r(فصل) في عدة الرسل عليهم السلام، وبيان المعجزات\r\r(وعدة الرسل) جمع رسول وتقدم بيانه (الكرام) جمع كريم، من كرم الشيء كرما، نفس وعز كذا في المصباح. (الكمل) بتشديد الميم جمع كامل (في اسم محمد) نبينا"], [111, "صلى الله عليه وسلم، فكما جمع لمقاماتهم وحقائق مراتبهم من حيث مقامه صلى الله عليه وسلم أجمعين، وحقيقة مرتبته جمع لعددهم أيضا من حيث حروف اسمه الشريف (بدت) أي: عدت ذلك (في الجمل) بضم الجيم وفتح مشددة. قال في القاموس: جمل كسكر حساب الجمل وحروف الاسم الشريف هي.\r\rميم وحاء ثم ميم كررت ... وبعدها دال كما قد قررت\rوكلهم من ربه مؤيد ... بمعجزات لا تنالها ليد\rقد قارنت دعواهم الرسالة ... مع التحدي لفظا أو بالحالة\r[الشرح]\rميم وحاء ثم ميم كررت) مرتين باعتبار التشديد (وبعدها دال) مهملة (كما قد قررت) بالبناء للمفعول أي: ثبتت في اللفظ. وبيان ذلك أنها خمسة حروف ثلاث ميمات وحاء ودال لكنها تعتبر أسماء الأحرف فكل ميم هجاؤها ثلاثة حروف ميم وياء وميم والحاء هجاؤها حرفان حاء وألف والدال هجاؤها ثلاثة حروف دال وألف ولام فجملة الحروف الخارجة من ذلك أربعة عشر حرفا فالميمات من ذلك ستة والياءات المثناة التحتية ثلاثة وألفان وحاء ودال ولام، فالميمات في الحساب مائتان وأربعون كل ميم بحساب أربعون والثلاثة الياءات ثلاثون كل ياء بحساب عشرة والألفان باثنين كل ألف بحساب واحد، والحاء ثمانية، والدال أربعة، واللام ثلاثون فالمئتان وأربعون إلى ثلاثين مائتان وأربعة وثمانون وإلى ثلاثين ثلاثمائة وأربعة عشر وهذا العدد هو عدد المرسلين من الأنبياء عليهم السلام فإنه ورد في الحديث عن النبي صلى الله عليه وسلم: أنه سئل عن عدد المرسلين عليهم السلام، فقال: مائة ألف. وفي رواية: ((مائتان ألف وأربعة وعشرون ألفا الرسل منهم ثلاثمائة وثلاثة عشر).\rو في رواية: وأربعة عشر. فمن اعتبر الألف في هجاء الحاء عدهم أربعة عشر ومن لم يعتبرها عدهم ثلاثة عشر، أو من أدخله صلى الله عليه وسلم في جملة العدد الذي قال عدهم أربعة عشر، ومن قال إنه عد من سواه وسكته عن نفسه عدهم ثلاثة عشر، وإن اعتبرت الهمزة أيضا مع الألف في الحاء كانوا خمسة عشر ولعله قوله أيضا ولم أره. وقد أشار إليه بعضهم.\r(وكلهم) أي: كل واحد من المرسلين عليهم السلام (من ربه) تعالى (مؤيد بمعجزات) جمع معجزة وقد مضى بيانها (لا تنالها اليد) أي: لا يقدر أحد على تحصيلها بكسب ولا غيره. (قد قارنت) أي: المعجزات (دعواهم) أي: المرسلين عليهم السلام"], [112, "(الرسالة) بسكون الهاء للوزن (مع التحدي) أي: طلب المعارضة من الخصوم، يقال: تحديث الناس القرآن، طلبت إظهار ما عندهم ليعرف أينا أقرأ، وهو في المعنى مثل قول الشخص الذي يفاخر الناس يقوله: هاتوا قوما مثل قومي أو مثل واحد منهم كذا في المصباح.\r\rومعجزات المصطفى الكثيرة ... دلت على رتبته الأثيرة\rلأن معجزات غيره انقضت ... بعصرهم كما مشيئة قضت\rوبعض معجزات طه باقي ... لأنه الحائز للسباق\rفكم وكم آي بها تحدي ... إحصاؤها بالعد فات حدا\rوحسبك القرآن ذو الآيات ... وحفظه الآخر الغايات\r[الشرح]\rلفظا) راجع لدعواهم الرسالة وللتحدي كمعجزة القرآن، فإن التحدي فيها صريح في قوله تعالى: {فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ وَادْعُوا شُهَدَاءَكُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ} [البقرة: 23] وقوله تعالى: {فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ} [هود: 13]. (أو بالحالة) بسكون الهاء، يعني: لا بصريح اللفظ كما في كثير من المعجزات، فإن دعوى الرسالة والتحدي كان فيها بطريق لسان الحال لا بصريح المقال، كتظليل الغمام، وتسليم الحجر والمدر، ونبع الماء من بين الأصابع، وتسبيح الحصى ونحو ذلك.\r(ومعجزات المصطفى) صلى الله عليه وسلم (الكثيرة) بسكون الهاء للوزن التي لا تكاد تحصى، والذي نقل منها ووصل إلينا وثبت عندنا قليل من قليل من قليل (دلت على رتبته) صلى الله عليه وسلم (الأثيرة) بسكون الهاء للوزن بمعنى المأثورة، من أثرته بالمد فضلته، أي: المفضلة على جميع المراتب.\r(لأن معجزات غيره) من الأنبياء عليهم السلام (انقضت) أي: زالت (بعصرهم) أي: مع زمانهم الذي انقضى (كما مشيئة) الله تعالى (قضت) أي: حكمت بذلك (وبعض معجزات طه) نبينا عليه الصلاة والسلام (باقي) ذلك البعض منها (لأنه) صلى الله عليه وسلم (الحائز للسباق) مصدر سابقت مسابقة وسباقا، كذا في المصباح، أي: جامع لجيمع أنواع السبق وجميع الكمالات (فكم وكم) تأكيد لفظي (أي) جمع آية بمعنى معجزة (بها تحدي) أي: طلب المعارضة من أخصامه بالصريح أو"], [113, "بالكناية (إحصاؤها) أ]: ضبطها (بالعد فات) أ]: تجاوز (حدا) أي: نهاية. قال في الصحاح: حسب الشيء منتهاه.\r(وحسبك) أي: يكفيك يا أيها المكلف من معجزاته ج (القرآن) العظيم (ذو) أي: صاحب (الآيات) جمع آية وهي الجملة من كلماته المؤلفة على أبلغ ما يكون من التأليف (وحفظه) أي: القرآن من التغيير والتبديل كما قال تعالى: {إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ} [الحجر: 9] (الآخر الغايات) جمع غاية، وهو حد الشيء.\r\rفهو لوعد الحق ذو إنجاز ... وفيه أنواع من الإعجاز\rكنظمه البدائع في أسلوبه ... وعجز من باراه عن مطلوبه\rوالجمع للعلوم وأسرار ... وكونه يحلو مع التكرر\rوفي الجزالة بوجه أعلا ... والروع في القلوب حين يتلى\rوما احتوى عليه من أيباء ... غيب بتصريح وبالإيمان\rففيه من هذا أمور تكثر ... والبعض بالفيض عليها يعثر\r[الشرح]\rفهو) أي: القرآن العظيم (لوعد الحق) تعالى (ذو) أي: صاحب (إنجاز) يعني: أنه منجز لوعد الله تعالى بحفظه كما قال: {وَإِنَّا لَهُ لَحَافِظُونَ} [الحجر: 9]. فهو محفوظ على مدى الأزمان من كل زيادة ونقصان (وفيه) أي: القرآن العظيم (أنواع من الإعجاز) من جهة حين سبكه وفصاحة كلماته وبلاغة معانيه وعذوبة انسجامه واشتماله على الحكم والأحكام والمواعظ والإخبار عن المغيبات وقصص الأمم الماضية وغير ذلك مما لا يحصى.\r(كنظيمة) أي: انتظام كلماته (البديع) أي: الذي لا يمكن أن يداني مثله (في أسلوبه) قال في المصباح: الأسلوب بضم الهمزة الطريق والفن (وعجز من باراه) أي: عارضه، وقصد الإتيان بمقله عن حصول (مطلوبه) الذي قصده (والجمع للعلوم) الكثيرة (والأسرار) العظيمة (وكونه يحلو) أي: عذب (مع) كثرة (التكرار) له آناء الليل وأطراف النهار (وفي الجزالة) أي: حين تناسق الكلمات وعدم ركاكتها (بوجه أعلا) أي: أكمل ما يكون. (و) حصول (الروع) أي: الخوف والخشية (في القلوب) أي: قلوب المؤمنين (حين يتلى) بالبناء للمفعول، أي: يتلوه القارئ."], [114, "(وما احتوى عليه من أنباء) جمع نبأ، أي: أخبار (غيب) كأحوال القيامة والجنة والنار وأهلها (بتصريح) تارة (والإيمان) أي: الإشارة إلى ذلك تارة أخرى (ففيه من هذا) القبيل (أمور تكثر) لا يمكن إحصاؤها ولا ضبطها (والبعض) من عباد الله الصالحين وخاصة أوليائه المقربين (بالفيض) أي: الفتح والإلهام، لصفاء القلب بدوام مشاهدة الملك العلام (عليها) أي: تلك الأمور (يعثر) أي: يطلع ويكشف عنها، وقد روى البخاري في الجهاد عن أبي جحيفة رضي الله عنه قال: ((قلت لعلي بن أبي طالب رضي الله عندكم شيء من الوحي إلا\r\rومنه ما ابن برجان أظهر ... في أخذ بيت المقدس المطهر\rمن قوله بضع سنين قبل أن ... يكون ثم كان طبقا في الزمن\rوبعضهم في وجه أعجاز نحى ... لرد بعض وسواه رجحا\r[الشرح]\rما في كتاب الله؟ قال: لا، والذي فلق الحب وبرأ النسمة ما أعلمه إلا فهم يعطيه الله رجلا في القرآن (¬1). الحديث. وهو في سنن الترمذي، وابن ماجه بألفاظ قريبة من هذا.\rوفي الإتقان للسيوطي رحمه الله (¬2): أخرج ابن أبي حاتم من طريق الضحاك، عن ابن عباس رضي الله تعالى قال: إن القرآن ذو شجون وفنون وبطون لا تنقضي عجائبه ولا يبلغ غايته.\rوقد قال بعض العلماء: لكل آية ستون ألف فهم. وقال بان أبي حمزة، عن علي بن أبي طالب رضي الله عنه أنه قال: (لو شئت أن أوقر سبعين بعيرا من تفسير أم القرآن لفعلت). (ومنه) أ]: ما ذكر من أسرار القرآن العظيم (ما) أي: الذي (ابن) بوصل الهمزة حتى تسقط (برجان) بضم الباء الموحدة وفتح الراء المشددة وبالجيم فالألف فالنون: وهو ابن الحاكم عبد السلام بن برجان، وقد وقفت له على تفسير للقرآن العظيم بلسان الإشارة على اصطلاح العارفين من أهل الله تعالى (أظهر) بسكون الراء أي: أظهره وكشف عنه (في اخذ بيت المقدس المطهر) سكون الراء أيضا، أي: من ايدي الفرند لما حوصرت في دولة الأكراد أيام الملك صلاح الدين بعد نور الدين الشهيد حين قطع ابن برجان رضي الله عنه بفتح بيت المقدس سنة وثمانين وخمسمائة. (من قوله) تعالى: {الم (1) غُلِبَتِ الرُّومُ (2) فِي أَدْنَى الْأَرْضِ وَهُمْ مِنْ\r¬__________\r(¬1) ... رواه البخاري (3/ 1110)، (6/ 2531)\r(¬2) ... انظر: الإتقان للسيوطي (1/ 28)"], [115, "بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ} [الروم: 1 - 3]. في (بضع سنين) فذكر إشارة فلكية استخرج منها حصول الفتح المذكور (قبل أن يكون) ذلك الفتح (ثم كان) أيك حصل (طبقا) أ] ك مطابقا لما قال (في الزمن) بسكون النون للقافية (وبعضهم) أي: العلماء (في وجه إعجاز) للقرآن العظيم (نحا) أي: قصد (لرد) قول (بعض) آخر (وسواه) أي: غير قول ذلك البعض الذي رده (رجحا) بألف الإطلاق.\r\rواختلفوا هل كان طوف البشر ... من قبل لكن صرفوا كما انتشر\rأولم يكن في طروقهم صححا ... والبحث في ذاك يطول شرحا\rوأخبر الله بعجز الإنس ... والجن عن إتيانهم بالجنس\r[الشرح]\r(واختلفوا) أيك العلماء (هل كان) الإثبات بمثل القرآن 0 في طوق البشر) أي: طاقته وقدرته 0 البشر) بسكون الراء (من قبل) أنه من قبل أن يأتي به نبينا محمد صلى الله عليه وسلم معجزة له أعجز به الفصحاء والبلغاء عن معارضته وعن الإتيان بمثله (كما انتشر) بسكون الراء، أي: الخبر بذلك، أو هذا القول بأن إعجازه بأن صرفه. قال ابن كمال باشا رحمه الله تعالى في رسالة له في بيان إعجاز القرآن: وقال الأستاذ أبو إسحاق الإسفرايني منا والنظام من المعتزلة صرفهم الله تعالى عنها أي: عن المعارضة مع قدرتهم عليها وذلك بأن صرف دواعيهم إليها مع كونهم محبولين عليها خصوصا عند توافر الأسباب الداعبة في حقهم كالتفريع بالعجز والاستنزال لمحن الرياسات والتكليف بالانقياد وهذا الصرف خارق العادة فيكون معجزا.\rوقال المرتضى من الشيعة: بل صرفهم بأن سلبهم العلوم التي يحتاج إليها في المعارضة، يعني أن المعارضة والإتيان بمثل القرآن يحتاج إلى علوم يقتدر بها عليها وكانت تلك العلوم حاصلة لهم لكنه تعالى سلبها عنهم فلم يبق لهم قدرة عليها. (أو لم يكن) أي: الإتيان بمثله (في طوقهم) أي: قدرتهم (ما صححا) بالبناء للمفعول وألف الإطلاق. قال اللقاني رحمه الله تعالى: الجمهور على أن إعجاز القرآن يكون في الطبقة العليا من الفصاحة والدرجة القصوى من البلاغة على ما يعرفه فصحاء العرب بسليقتهم وعلماء الأدب بمهارتهم في فن البان وإحاطتهم بأساليب الكلام، هذا مع اشتماله على الإخبار عن المغيبات الماضية والآتية وعلى دقائق العلوم الإلهية وأحوال المبدأ والمعاد ومكارم الأخلاق والإرشاد إلى فنون الحكمة العلمية والعملية، والمصالح الدينية والدنيوية على ما يظهر للمتدبرين، ويتجلى على قلوب المتفكرين.\r(والبحث في ذاك) أي: وجه إعجاز القرآن (يطول) بين العلماء (شرحا) أي: بيانا على عشرة أقوال بسطنا الكلام فيها في كتابنا ((المطالب الوفية))"], [116, "(وأخبر الله) تعالى في كلامه القديم (بعجز الإنسان والجن عن إتيانهم بالجنس) أي: بما يجانس القرآن، أي: يماثله (من مثله) أي: القرآن أو النبي الأمي صلى الله عليه وسلم الذي لم\r\rمن مثله وطولبوا بسورة ... فما استطاعا مثلها ضرورة\rومن بجلباب الحيا أزجا ... معارضا له حوى افتضاحا\rكمثل ما جاء به مسيلمة ... من ترهات باختلاف معلمة\r[الشرح]\rيقرأ ولم يكتب ولم يتعلم من بشر قال تعالى: {قُلْ لَئِنِ اجْتَمَعَتِ الْإِنْسُ وَالْجِنُّ عَلَى أَنْ يَأْتُوا بِمِثْلِ هَذَا الْقُرْآنِ لَا يَأْتُونَ بِمِثْلِهِ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا} [الإسراء: 88]\r(وطولبوا) أي: طالبهم الله تعالى (بسوره) بسكون الهاء للوزن، قال تعالى: {فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ} [البقرة: 23] الآية. (فما استطاعوا مثلها) أيك ما قدروا أن يأتوا بمثل أقصر سورة منه (ضرورة) بسكون الهاء أيضا، أي: بالضرورة لعجزهم عن ذلك. (ومن بجلباب) وهو ثوب أوسع من الخمار وجون الرداء. وقال ابن الأعرابي: الجلباب الإزار. وقال ابن فارس: الجلباب ما يغطى به من ثوب أو غيره كذا في المصباح.\r(الحيا) بالقصر للوزن وأصله المد، وهو الاستحياء، وهو خلق يبعث على ترك القبيح ويمنع من التقصير في حق ذا الحق وهذا المروءة (أزاحا) بألف الإطلاق أي: أزال.\r(معارضا له) أي: القرآن العظيم (حوى افتضاحا) بألف الإطلاق أيضا، أي: فضيحة وعارا شنيعا (كمثل ما) أي: الذي (جاء به مسيلمة) بسكون الهاء للوزن وصيغة التصغير. قال السنوسي في شرح الجزائرية: اسمه هارون بن حبيب الحنفي نسبة إلى بني حنيفة، وكان يكنى بأبي ثمامة، وكان يزعم أن جبريل صلى الله عليه وسلم يأتيه، وذلك أنه لما سمع برسول الله صلى الله عليه وسلم من يخبر بأحواله، وصار ينقل إليه ما يسمع من رسول الله صلى الله عليه وسلم من القرآن وغيره فكان يقرأ القرآن على من عنده ويزعم أنه أنزل عليه، ولما افتضح حين اشتهر القرآن عن رسول الله صلى الله عليه وسلم ولم يمكنه دعواه أخذ يضع القرآن بزعمه فأتى بما هو ضحكة لكل سامع (من ترهات) بضم التاء المثناة الفوقية وفتح الراء مسددة جمع ترهة.\rقال في القاموس: الترهة كقبرة الباطل. وقال في الصحاح: الطرق الصغار غير الجادة. الواحدة ترهة فارسي معرب ثم استعبر في الباطل فقالوا: الترهات البسابس"], [117, "والترهات الصحاصح، وهو من أسماء الباطل (باختلال) أي: نقصان وفساد (معلمه) بصيغة اسم المفعول وسكون الهاء من أعلم الشيء جعل له علامة.\r\rركيكة في لفظها والمعنى ... كقوله والطاحنات طحنا\rوغيره مما انتحاه الأبله ... وهو بنوع الهذيان أشبه\rوهل يقدس ذا بأن الله ... يأمر بالعدل وما تلاها\rوأينما هذى به في الضفدع ... من قول ربنا تعالى فاصدع\r[الشرح]\r(ركيكة) أي: ضعيفة (في لفظها والمعنى) بحيث تمجها الأسماع وتنفر منها الطباع (كقوله) أي: مسيلمة الكذاب في محاكاته للقرآن لما سمع بسورة ((والنازعات غرفا)) فقال: والزراعات زرعا والحاصدات حصدا (والطاحنات طحنا) والخابزات خبزا والثاردات ثردا يا ضفدع بنت ضفضعين تنقين لا الماء تكدرين ولا الشاربين تمنعين أعلاك في الماء وأسفلك في الطين.\r(وغيره) أي: غير ما ذكر (مما) أيك من الذي (انتحاه) أي: قصده (الأبله) بسكون الهاء للزن. قال في المصباح: بله بلها من باب تعب ضعف عقله فهو أبله (وهو) أي: ما قاله من ذلك (بنوع الهذيان) هذى الهاء كقوله أيضا وقد سمع سورة الفيل فقال: الفيل وما الفيل وما أدرك ما الفيل له ذنب وتيل وخرطوم طويل فانظر هذه المضاحك وما أقبحها، وقد قيل: إن هذا الخبيث هو المراد في قوله تعالى: {وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ قَالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَيْءٌ وَمَنْ قَالَ سَأُنْزِلُ مِثْلَ مَا أَنْزَلَ اللَّهُ} [الأنعام: 93] (وهل يقاس ذا) أي: هذا الهذيان الباطل (بإن الله) أي: بقوله سبحانه وتعالى: {إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى وَيَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ} [النحل: 90] (وما) أي: والذي (تلاها) أي: تبع هذه الآية من بقية الآيات (وأينما) أي: الذي (هذى) من الهذيان (به) يعني مسيلمة الكذاب (في الضفدع) بكسرتين ومنهم من يفتح الدال كذا في المصباح وهو الذي تقدم ذكره في معارضته سروة النازعات (من قول ربنا تعالى) وتبارك (فاصدع) بكسر العين للقافية لا على أنه من القرآن لحديث قوله تعالى: {فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ} [الحجر: 94]\rقال اللقاني رحمه االله تعالى: حتى ان أعرابيا سجد عند سماع قوله تعالى: {فَاصْدَعْ بِمَا تُؤْمَرُ} [الحجر: 94] وقال: سجدت لفصاحة هذا الكلام."], [118, "أجارنا الله من الخذلان ... والغني في الإسرار والإعلان\r\rفصل في بيان السمعيات مما يجب الإيمان به\r\r"]], "pg": [110, 118]}, "496.19": {"x": [[118, "وكل ما جاء من الأخبار ... عن أحمد المخصوص بالإكبار\rفذاك حق كائن لا يمترى ... فيه وما كان حديثا يفترى\rمثل السؤال وعذاب القبر ... والبعث للأبدان يوم الحشر\r[الشرح]\rوقالت جارية للأصمعي حين رأته يتعجب من فصاحة بعض حديثها أو يعدُّ هذا فصاحة بعد قوله تعالى: {وَأَوْحَيْنَا إِلَى أُمِّ مُوسَى أَنْ أَرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ وَلَا تَخَافِي وَلَا تَحْزَنِي إِنَّا رَادُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ الْمُرْسَلِينَ} [القصص: 7] جمع فيها بين أمرين ونهيين وخبرين وبشارتين.\r(أجارنا) أي: حمانا (الله) تعالى (من الخذلان) خذلته أخذله من باب قتل والاسم الخذلان، تركت نصرته وإعانته وتأخرت عنه، كذا في المصباح، وهو ضد التوفيق (والغي) ضد الرشد (في حال) الإسرار أي: الإخفاء (والإعلان) أي: الجهر.\r\rفصل في بيان السمعيات مما يجب الإيمان به (¬1)\r\r(وكل ما جاء من الأخبار) جمع خبر عن احمد أي: ابن عبد الله بن عبد الله بن عبد المطلب ابن هاشم نبينا صلى لله عليه وسلم. (المخصوص) بالإكبار) أي: الإعظام يقال: أكبرته إكبارا، استعظمته (فذاك) أي: جميع ما ورد (حق كائن) أي: ثابت واقع (لا يمترى) بالبناء للمفعول أي: سؤال اللمكين منكر ونكير ميت في قبره بعد الدفن.\r\rروى البخاري، ومسلم، عن أنس بن بن مالك رضي الله عنه، أن رسول اله صلى الله عليه وسلم قال: إن العبد إذا وضع في قبره وتولى عنه أصحابه وإنه يسمع قرع نعالهم أتاه ملكان فيقعدانه فيقولان: ما كنت تقول في هذا الرجل لمحمد صلى الله عليه وسلم في هذا الرجل لمحمد صلى الله عليه وسلم: فأما المؤمن فيقول: أشهد إنه عبد الله ورسوله، فيقال له: انظر معقدك من النار، قد أبدلك الله به مقعدا من الجنة فربهما جميعا، قال: وأما المنافق، والكافر، فيقال له: ما كنت تقول في هذا الرجل؟ فيقول: لا أدري كنت أقوال ما يقوله الناس فيقال: لا دريت ولا تليت ويضرباه بمطارق وحديد ضربة فيصيح صيحة يسمعها من يليه غير الثقلين.\r¬__________\r(¬1) في نسخة: فصل يجب الإيمان به من السمعيات مصححة."], [119, "بعينها لا مثلها إجماعا ... والاختلاف بعد هذا شاعا\rهل ذاك عن تفريق تلك الأجزا ... أو عدم محض إليها يعزى\rلكن هذا باعتبار ما ورد ... والكل في الجواز بالعقول اطرد\r[الشرح]\r(وعذاب القبر) في حق الكافرين وبعض عصاة المؤمنين. قال اللقاني رحمه الله تعالى: ((والأحاديث في عذاب القبر بلغت جملتها التواتر، ولا يمتنع عند العاقل أن الله تعالى يعيد الحياة في الجسد أو في جزء منه ويعذبه وكل ما لا يمنعه العقل وورد وقوعه بالشرع وجب قبوله واعتقاده)). (والبعث) أي: الإعادة (للأبدان) بإرجاع الأرواح إليها (يوم الحشر) أي: يوم القيامة.\r(بعينها التي كانت في الدنيا (لا مثلها إجماعا) من أهل الإسلام (واختلاف) بين العلماء (بعد هذا) الإجماع منهم (شاعا) بألف الإطلاق، أي: اشتهر من وجه آخر بأنه يقوله: (هل ذاك) أي: البعث بالإعادة كما كان (عن تفريق تلك الأجزاء) بالقصر للوزن، أي: أجزاء البدن فيجمعها الله تعالى بقدرته ثم يعيد أرواحها إليها كما كانت في الدنيا (أو) عن (عدم محض) أي: خالص (إليها) أي: إلى تلك الأجزاء (يعزى) بالبناء للمفعول به، أي: ينسب، بأن يعيدها الله تعالى بعد فنائها واضمحلالها (لكن هذا) الاختلاف (باعتبار ما ورد) بالسكون أيضا وهو قول البعض (في الجواز) أي: كون كل واحد من ذلك حائز (بالعقل اطرد) بالسكون أيضا إن أمكن القول به ولا يترتب عليه محذور في الشرع، ولكن تقديم القول بأنه عن تفريق يؤذن باختيار الناظم رحمه الله تعالى، وهو الأقرب لتوارد الأخبار بأن القبر روضة من رياض الجنة أو حفرة من حفر النار، وأن المعذب أو المنعم في القبر هو الروح والجسد معا لا الروح وحدها، فإذا كانت الإعادة عن عدم محض ذهبت القبور الآن بالكلية لانعدام أجزاء الموتى منها والوارد يقتضي وجود القبر وجود عذاب القبر أو نعيمة وذلك يقتضي بقاء الأجزاء الترابية فيه فالإعادة يجمعها بعد التفريق، ولعمري إن الله تعالى قادر عل كل شيء؛ لأنه أوجد من العدم أول مرة فإيجاده من العدم مرة أخرى مما لا يشك في إمكانه وعدم استبعاده."], [120, "واستثن من ذا الخلف عجب الذنب ... وما أتت به النصوص كالنبي\rواختلفوا في عود وقت عرض ... وبعضهم إعادة الوقت اعترض\rبقوله جل جلودا غيرها ... فاركب مطايا البحث واعرف سيرها\r[الشرح]\r(واستثن) بصيغة الأمر للمخاطب (من ذا) أي: هذا (الخلف) أي: الاختلاف المذكور (عجب) بفتح العين المهملة وسكون الجيم (الذنب) بالتحريك. قال في المصباح: العجب وزان فلس: من كل دابة ما ضمت عليه الورك عن أصل الذنب وهو العصعص، وذكر أنه يقال له العجم أيضا على وزن العجب، وقال: هو أصل الذنب وهو العصعص. انتهى وقال المناوي في شرح الجامع الصغير: عجب الذنب الذي لا يبلى من الإنسان، أو عجم بالميم، عظم لطيف كحبة خردل عند رأس العصعص مكان رأس الذنب من ذوات الأربع. وقال المحلي في شرح جمع الجوامع: عجب الذنب هل يبلى؟ فيه قولان: المشهور منهما: أنه لا يبلى لحديث الصحيحين: ((ليس من شيء إلا يبلى إلا عظما واحدا وهو عجب الذنب منه يركب الخلق يوم القيامة)).\r(و) استثنى أيضا (ما أتت) عن الشارع صلى الله عليه وسلم (به النصوص) أي: الأحاديث والأخبار (كالنبي) أي: كل نبي فإنه لا يبلى وكذا الشهداء والعلماء وحملة القرآن والمؤذنون المحتسبون (واختلفوا) أي: العلماء (في عود وقت) أي: زمان وعود (عرض) بالسكون للوزن وفتح الراء وقد سبق بيانه أبي: جميع أزمنة الأجسام التي مرت عليها في الدنيا تبعا للأجسام والذوات المعادة فتعاد بأزمنتها وأوقاتها كما تعاد لجميع أعراضها وألوانها وهيئاتها.\rقال اللقاني رحمه الله تعالى: وفي إعادة الأشخاص والأعراض التي كانت في الدنيا قائمة بالجسم حالة الحياة من مبدئه إلى منتهاه قولان: الإعادة وهو مذهب الأكثرين وإليه ميل الأشعري. وعدم جواز إعادتها وإليه ذهب بعض المعتزلة وأهل السنة.\r(وبعضهم) أي: العلماء وهو الفقيه القاضي أبوبكر بن العربي رحمه الله تعالى (إعادة الوقت اعترض) بالسكون للوزن (بقوله) أي: الله (جل) وعز في حق أهل النار {كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ} [النساء: 56] (جلودا غيرها) أي: غير الجلود الأولى (فاركب) أيها المكلف (مطايا) جمع محطة، من المطاء وزان العصا، الظهر، وقيل للبعير مطية فعلية بمعنى مفعولة لأنه يركب مطاء ذكرا كان أو أنثى، كذا في المصباح. (البحث) في هذه المسألة وكل مسألة (واعرف سيرها) أي: المطايا المذكورة، ثم بين ذلك حيث قال:"], [121, "فليس إلا الغير بالأزمان ... للمنع من غيرية الأبدان\rفبان أن الوقت لا يعاد ... من ذلك الحصر الذي يفاد\rوهكذا الحساب والميزان ... من ماء به قد وجب الإيمان\r[الشرح]\r(فليس) في قوله: جلودا غيرها أن الجلود التي يقع عليها العذاب غير الجلود الأولى لأن الثانية لم تعص فكيف تعذب وتعذيب من لم يعص ظلم وهو على الله محال (إلا) أن يكون (الغير بالأزمان) فتعود بعينها وهو غيرها باعتبار الأزمان المتغايرة (للمنع من غيرية الأبدان) إذ يلزم منه تعذيب من لم يعص كما ذكرنا.\rوذكر البيضاوي أن هذه الغيرية باعتبار صورة أخرى لقولك بدلت الخاتم قرطا، أو بأن يزال عنها أثر الإحراق ليعود إحساسه للعذاب، وقيل: يخلف مكانه جلدا آخر، والعذاب في الحقيقة للنفس العاصية المدركة لآلة إدراكها فلا محذور. انتهى\rقلت: فعلى هذا الأوجه للحصر المذكور فلا يرد الاعتراض المذكور. (فبان) بهذا التأويل (أن الوقت) أي: الزمان (لا يعاد من ذلك الحصر) اللازم (الذي يفاد) من عبارة النظم المذكورة، إذ لو أعيد الزمان بعينه يوم القيامة لم تكن الغيرية باعتبار الزمان حيث كان زمان العذاب هو زمان المعصية بعينه وقد أعيد، فتكون الغيرية بدنية ويلزم منه ما ذكرناه.\r(وهكذا) أي: كالأمور المذكورة (الحساب) يوم القيامة من الله تعالى لعباده المكلفين. والحساب: لغة العد. واصطلاحا: توفيق الله تعالى عباده قبل الانصراف من المحشر على أعمالهم خيرا كانت او شرا تفصيلا لا بالوزن إلا من استثناء منهم، وقد اختلف العلماء في معنى كونه تعالى محاسبا عباده على ثلاثة أقوال:\rأحدهما: أنه تعالى يعلمهم ما لهم وما عليهم. قال الفخر الرازي: بأن يخلق الله تعالى سبحانه في قلوبهم علوما ضرورية بمقادير أعمالهم من الثواب والعقاب. وثانيها: وهو منقول عن ابن عباس رضي الله عنه، وأن الله تعالى يوقف عباده بين يديه ويؤتيهم كتب أعمالهم فيها سيئاتهم وحسناتهم، فيقول: هذه سيئاتكم فقد تجاوزت عنها، وهذه حسناتكم وقد ضاعفتها لكم.\rوثالثها: أ ن يكلم الله عباده في شأن أعمالهم وكيفية ما لها من الثواب والعقاب."], [122, "وتوزن الصحف بلا إشكال ... وقيل بل أمثلة الأعمال\rوالأخذ للكتب به النص أتى ... والخلف في العاصي لديهم ثبتا\r[الشرح]\rقال الفخر: إما بأن يسمعوا كلامه القديم او يسمعوا صوتا يدل عليه يتولى الله تعالى خلقه في أذن كل واحد من المكلفين او في محل يقرب من أذنه بحيث لا تبلغ قوة ذلك الصوت منع الغير من سماع ما كلف به ولا شك في صحة شهادة الآثار الصحيحة له. واعلم أن كيفيات الحساب مختلفة وأحواله متباينة، فمنه اليسير ومنه العسير ومنه السر ومنه الجهر ومنه التكريم ومنه التوبيخ ومنه الفضل ومنه العدل ويكون للمؤمن والكافر وللإنس والجن إلا من ورد الحديث باستثنائهم وروى الترمذي بإسناده عن ابي أمامة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: ((وعدني ربي أن يدخلني الجنة من امتى سبعين ألفا لا حساب عليهم ولا عذاب مع كل سبعون ألفا وثلاث حثيات من حثيات ربي.\r(والميزان) وقد ورد في صريح الآيات والأحاديث، وذهب كثير من المفسرين إلى أنه ميزان له كفتان ولسان وساقان عملا بالحقيقة لإمكانها توضع في صحف أعمال العباد ليظهر الراجح والخاسر وفي العقائد للسعد: والميزان عبارة عما تعرف به مقادير الأعمال، والعقل قاصر عن إدراك كيفيته.\rوقال القرطبي في التذكرة: واعلم أن من الأخيار من لا يوزن له عمل ولا ينشر له كتاب كأهل البلاء وكذلك من الأشرار، بل يزف الأولون إلى الجنة من غير وزن ولا حساب ويساق الآخرون إلى النار كذلك بدليل قوله تعالى: {فَحَبِطَتْ أَعْمَالُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا} [الكهف: 105] (من ما) أي: من كل أمر (به قد وجب الإيمان) على المكلفين.\r(وتوزن الصحف) جميع صحيفة، وهي الكتاب الذي كتبته الملائكة الحفظة على المكلف في الدنيا بجميع ما فعله (بلا إشكال) في ذلك (وقيل بل) أي: الذي يوزن (أمثلة الأعمال) أي: الأمثلة المتصورة من الأعمال، قال اللقاني رحمه الله تعالى: توزن حقائق الأعمال وذواتها بأن يجعل الله تعالى الأعمال أجساما نورانية في كفة الحسنات وظلمانية في كفة السيئات ثم تطرح تكل الأجسام في الميزان الأولى في اليمين والثانية في الشمال.\r(والأخذ للكتب) أي: كتب الأعمال (به النص) في القرآن والسنة (أتى) قال تعالى: {فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ (7) فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا (8) وَيَنْقَلِبُ إِلَى أَهْلِهِ"], [123, "هل بيمين أو شمال يعطى ... كتابة ومن يقف ما أخطأ\rإذ لم يرد نص صريح يعمل ... عليه والوارد فيه مجمل\rوكالصراط ذي الكلاليب ومن ... أنقذ منه فهو بالفوز قمن\r[الشرح]\r=\rمَسْرُورًا} [الانشقاق: 9] الآية. وقال تعالى: {وَإِذَا الصُّحُفُ نُشِرَتْ} [التكوير: 10] إلى غير ذلك من الآيات.\rوروى الترمذي، عن أبي هريرة رضي الله عنه قال: رسول الله صلى الله عليه: ((يعرض الناس يوم القيامة ثلاث عرضات، فأما عرضتان فجدال ومعاذير فعند ذلك تطير الصحف في الأيدي فآخذ بيمنه وآخذ بشماله.\r(والخلف) أي: الاختلاف (في) حق (العاصي) من المؤمنين (لديهم) أي: العلماء (ثبتا) بألف الإطلاق (هل بيمين أو شمال يعطى) بالبناء للمفعول (كتابه ومن يقف) في ذلك (ما أخطا) لأنه فوض علم ذلك إلى الله تعالى (إذ) أي: لأنه (لم يرد) في النصوص (نص صريح) في ذلك (يعمل) بالبناء للمفعول (عليه و) النص (الوارد فيه مجمل) غير مفصل فالتوقف أولى. قال اللقاني رحمه الله تعالى: فإن قلت دلت الآيات على أن المؤمن الطائع يأخذ كتابه بيمينه والكافر يأخذ كتابه بشماله فما حكم المؤمن الفاسق الذي مات على فسقه دون توبة؟\rقلت: جزم الماوردي بأن المشهور يأخذ كتابه بيمينه، ثم حكى قولا بالوقف. قال: والأقاويل أنه يأخذ بشماله.\rوقال يوسف بن عمر: اختلف في عصاة المؤمنين، فقيل: يأخذون كتبهم بيمينهم، وقيل: بشمالهم. واختلف الأولون فقيل: يأخذونها قبل الدخول في النار ويكون ذلك علامة لهم على عدو خلودهم فيها، وقيل: يأخذونها بعد الخروج منها، ومن أهل العمل من توقف فيهم لتعارض النصوص.\r(وكالصراط) في ورود النصوص به (ذي) أي: صاحب (الكلاليب) جمع كلاب وزن تفاح ويقال: كلوب وزن تنور، خشبة في رأسها عقافة منها أو من حديد، كذا في المصباح. وحديث البخاري الذي أورده في رؤية الله تعالى في الآخرة حديث طويل عن أبي هريرة رضي الله عنه، وفيه: يضرب الصراط بين ظهراني جهنم فأكون أنا وأمتي أول منن يجيز ولا يتكلم يومئذ إلا الرسل ودعوى الرسل يومئذ اللهم سلم سلم وفي جهنم كلاليب مثل شوك"], [124, "جسر على متن جهنم التي ... يهوي بها من رجله قد زلت\rوما يقال إنه أدق ... من شعر صدقه فهو حق\rوفي صحيح مسلم ما أرشدا ... إليه والضرير فيه أنشدا\rوالرب لا يعجزه إمشاؤهم ... عليه إذ لم يعيه إنشاؤهم\r[الشرح]\rالسعدان هل رأيتم السعدان؟ قالوا: نعم يا رسول الله. قال: فإنها مثل شرك السعدان غير أنه لا يعلم قدر عظمها إلا الله تعالى تخطف الناس بأعمالهم) (¬1). والحديث في البخاري بطوله. (ومن) أي: والذي (انقذ) بالبناء للمفعول، أي: نجاه الله تعالى (منه) أي: من هوله ومهالكه (فهو بالفوز) أي: بالسعادة والعناية (قمن) بفتح القاف وفتح الميم وبسكون النون للوزن. قال في المصباح: هو قمن أن يفعل كذا بفتحتين. أي: جدير وحقيق ويستعمل بلفظ واحد مطلقا فيقال: هو وهي وهم وهذه قمن، ويجوز قمن بكسر الميم فيطابق في التذكير والتأنيث والإفراد والجمع.\r(جسر على متن) أي: على ظهر (جهنم) قال في المصباح: الجسر ما يعبر عليه مبنيا كان أو غير مبني بفتح الجيم وكسرها (التي) نعت لجهنم (يهوي) أي: يسقط (بها) أي: فيها (من) أي: الذي (رجله قد زلت) بكسر التاء للقافية، أي: أخطأت في المشي عليه (وما يقال) في وصف الصراط (إنه أدق) أي: أكثر دقة (من شعر) بفتح العين المهملة ويجمع على أشعار كسبب وأسباب. وبسكن العين، فيجمع على شعور مثل فلس وفلوس، كذا في المصباح. (صدقه) فعل أمر من التصديق، أي: آمن به (فهو حق) وصدق (وفي صحيح) الإمام (مسلم) بن حجاج النيسابوري رحمه الله تعالى (ما) أي: حديث وارد في ذلك (أرشد) بألف الإطلاق (إليه) أي: إلى ما ذكر.\rقال في صحيح مسلم بعد إيراده حديث أبي سعيد الخدري رضي الله عنه في رؤية الله تعالى وفيه ذكر الصراط. قال أبو سعيد: بلغني أن الجسر أدق من الشعر وأحد من السيف (و) أبو يعقوب يوسف (الضرير) شيخ القاضي عياض رحمها الله تعالى (فيه) أي: فيما ذكر (أنشد) بألف الإطلاق في قوله (والرب) سبحانه وتعالى (لا يعجزه إمشاؤهم) أي: عباده المؤمنين يوم القيامة (عليه) أي: على الصراط الذي هو أدق من الشعر وأحد من السيف (إذ) أي: لأنه (لم يعيه) أي: يتبعه (إنشاؤهم) أي: خلقهم من العدم.\r¬__________\r(¬1) رواه البخاري (1/ 278)، ومسلم (1/ 164)"], [125, "تبا لقوم ألحدوا في أمره ... ما قدروا الإله حق قدره\r[الشرح]\rوقال اللقاني رحمه الله تعالى في شرح الجوهرة: وإمكان العبور ظهار كالمشي على الماء والطيران في الهواء غايته مخالفة العادة، ولا شك أن الآخرة أكثر أحوالها خوارق وهي محل امتحاء أكثر الرسوم المعتادة ومعدن انفجار أمرو لم تخطر قط ببال أكابر العلماء السادة، وما جاء في محله فلا يستغرب ولا يسأل عنه، كيف وقد شاهدنا في الدنيا حسا ما يؤكد جواز ذلك، فإن الطير في الهواء يسيره الله تعالى فيه على ثلاثة أنواع: الأول أنه يذهب في الهواء فاتحا جناحيه محركها. والثاني: أنه يذهب فاتحا جناحيه غير محركها أصلا. والثالث: أنا شاهدناه يذهب في سرعة شديدة قابضا جناحيه لا محركها ولا ناشرهما إذا شوهد هذا المعنى واستبان بالعيان أنه لا أثر لجناح ولا لتحريكه في الطيران، وإنما الله سبحانه يمسك ما شاء كيف شاء، فكيف يستبعد مرور الخلائق على الصراط على الوصف الذي وصف به عليه الصلاة والسلام، ثم إن الله تعالى يسهل الصراط على من أراد كما جاء في الحديث: إن منهم من يمر كالبرق الخاطف ومنهم من يمر كالريح الهابة، ومنهم من يمر كالجواد المسرع، ومنهم من تسوخ رجلاه في النار وتتعلق يداه، ومنهم من يجر على وجهه. انتهى\rقلت: ومن هذا القبيل ما روى البخاري، ومسلم، عن أنس بن مالك رضي الله عنه، أن رجلا قال: يا رسول الله! أيحشر الكافر على وجهه يوم القيامة؟ قال: أليس الذي أمشاه على رجليه في الدينا قادر على أن يمشيه على وجهه يوم القيامة. قال قتادة: روي هذا الحديث عن أنس بلى وعزة ربنا.\r(تبا) بفتح التاء المثناة الفوقية وفتح الباء الموحدة مشددة، أي: هلاكا وخسرانا (لقوم الحدوا) أي: مالوا عن الحق إلى الباطل. وفي المصباح: الحد الرجل في الدين لحد وألحد إلحادا طعن. وقال أبو عبيدة: ألحد إلحادا جادل ومارى. (في أمره) أي: الصراط. قال للقاني رحمه الله تعالى: اتفقت لأمة على إثبات الصراط في الجملة وأهل السنة يبقونه على ظاهره من كونه جسرا ممدودا على متن جهنم أحد من السيف وارق من الشعر، وأنكر هذا الظاهر القاضي عبد الجبار المعتزلي وكثير من أتباعه زعما منهم أنه لا يمكن العبور عليه وإن أمكن، ففيه تعذيب ولا عذب على المؤمنين والصلحاء يوم القيامة، وإنما المراد به طريق الجنة المشار إليه بقوله تعالى: {سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ}"], [126, "وللقرافي هنا كلام ... نيط به من أجله ملام\r[الشرح]\rوطريق النار المشار إليه بقوله تعالى: {فَاهْدُوهُمْ إِلَى صِرَاطِ الْجَحِيمِ} [الصافات: 23] ومنهم من حمله على الأداة الواضحة أو المباحة أو الأعمال المروية سأل عنها ويؤاخذ بها والكل باطل لوجوب حمل النصوص على ظواهرها إلا ما خالف القواطع، والقبور عليه ليس بأبعد من المشي على الماء او الطيران في الهواء أو الوقوف فيهن وقد اعتذر صلى الله عليه وسلم عن حشر الكافر على وجهة بأن القدرة صالحة لذلك (ما قدروا الله) سبحانه وتعالى (حق قدره) فإنه عز وجل على كل شيء قدير فكيف يستبعد على قدرته ممكن من الممكنات.\r(وللقرافي) من أئمة أهل السنة وقد سبقه في ذلك شيخه العز بن عبد السلام رحمهما الله تعالى مع علو مقامهما (هنا) في الكلام على الصراط (كلام) مذكور في مصنف كل منهما (نيط) أي: علق (به) أي: بالقرافي رحمه الله تعالى (من أجله) أي: بسبب ذلك الكلام (ملام) أي: اللوم من علماء أهل السنة، وبيان ذلك هو أن القرافي أنكر كون الصراط أدق من الشعر وأحد من السيف وسبقه إلى ذلك العز بن عبد السلام. وعبارة الزر كشي: الصراط وردت فيه الأخبار الصحيحة واستفاضت، وهو محمول على ظاهره بغير تأويل، والله أعلم بحقيقة. وفي الصحيحين: إنه جسر ممدود يضرب على ظهر جهنم يمر عليها جميع الخلائق وهم في جوازه متفاوتون (¬1).\rثم قال القرافي وبعض الروايات: (أدق من الشعر وأد من السيف) (¬2). فإن ثبتت فهي غير محمولة على ظاهرها لمنافاتها للأحاديث الأخر من قيام الملائكة على جنبتيه وكون الكلاليب والحسك فيه وإعطاء كل من المارين عليه من النور قدر موضع قدميه، زاد القرافي: والصحيح أنه عريض ويه طريقان يمنى ويسرى، فأهل السعادة يسلك بهم ذات اليمين وأهل الشقاوة يسلك بهم ذات الشمال، وفيه طاقات كل طاقة تنفذ إلى طبقة من طبقات جهنم وجهنم بين الخلائق وبين الجنة والجسر على ظهرها منصور فلا يدخل الجنة أحد حتى يمر على جهنم وهو معنى قوله تعالى: {وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا} [مريم: 71] على أحد الأقوال.\r¬__________\r(¬1) رواه البخاري (5/ 2403)، ومسلم (1/ 177)\r(¬2) رواه البخاري (5/ 2381)، ومسلم (1/ 170)"], [127, "والناس في ذاك ذوُو أحوال … ناج سريعا أو مع الأهوال\rومنهم الموبق والمخردل … ومن به عن الجنان يعدل\r[الشرح]\rثم قال تبعا للبيهقي: كون الصراط أدق من الشعر وأحد من السيف لم أجده في الروايات الصحيحة، وإنما يروى عن بعض الصحابة فتأول بأن أمره أدق من الشعر فإن يسر الجواز عليه وعسره على قدر الطاعات والمعاصي ولا يعلم حدود ذلك إلا الله وقد جرت العادة بضرب دقة الشعر مثلا للغمض الخفي وضرب حد السيف لإسراع الملائكة في المعنى الامتثال أمر الله تعالى في إجازة عليه.\rوقال القرطبي وغيره: وكل هذا مردود بإخراج مسلم تلك الزيادة عن أبي سعيد بلاغا وليست مما للراي والاجتهاد في مدخل، فهي مرفوعة في الصحيح والإيمان بكل ذلك واجب، والقادر على إمساك الطير في الهواء قادر على أن يمسك عليه المؤمن يجريه أو يمشيه ولا يعدل عن الحقيقة إلى المجاز إلا عند الاستحالة ولا استحالة في ذلك مع الآثار الواردة فيه وإثباتها بنقل الأئمة العدول {وَمَنْ لَمْ يَجْعَلِ اللَّهُ لَهُ نُورًا فَمَا لَهُ مِنْ نُورٍ} [النور: 40]. كذا ذكره اللقاني رحمه الله تعالى.\r(والناس في ذاك) أي: المرور على الصراط (ذوو) جمع ذو، أي: أصحاب (أحوال) مختلفة فمنهم (ناج) من الوقوع في النار يمر عليها (سريعا) كالبرق الخاطف والريح الهابة (أو) يمر (مع) مكابدة (الأهوال) أي: المشقات العظام والشدائد الفخام (ومنهم الموبق) بفتح الباء الوحدة بذنوبه أي: المهلكة، يقال: وبق يبق يوبق فهم موبق كذا في النهاية لابن الأثير. (والمخردل) بفتح الدال المهملة، وهو: المرمي المصروع، وقيل: المقطع تقطعه كلاليب الصراط حتى يهوي في النار، يقال: خردلت اللحم بالدال والذال، أي: فصلت أعضاءه وقطعته كذا في النهاية.\r(ومن) يعني إنسان (به عن) إدخال (الجنان) جمع جنة وسيأتي الكلام عليها (يعدل) بالبناء للمفعول يعني لا يريد الله تعالى إدخاله الجنة، روى البخاري، عن ابي سعيد الخدري رضي الله عنه في حديث الرؤية الطويل قال: ثم يؤتى بالجسر فيجعل بين ظهر جهنم قلنا: يا رسول الله! وما الجسر؟ قال: مدحضة مزلة عليه خطاطيف وكلاليب وحكسة مطحلفة عقيفة تكون بنجد يقال لها السعدان يمر المؤمن عليها كالطرف وكالبرق وكالريح وكأجاويد الخيل واركاب فناج"], [128, "للنار وهي مسكن الكفار ... ومن أبى عن طاعة الغفار\rوما بنوع واحد يختص ... منهم وفي الأنواع جاء النص\rوواجب أن ينفذ الوعيد في ... بعض العصاة دون ما توقيف\r[الشرح]\rمسلم وناج مخدوش ومكدوش في نار جهنم حتى يمر آخرهم يحسب سحبا (¬1). إلى آخر الحديث.\rوالمطحلفة: المرققة المبسوطة. والعقيفة: المنحنية المعوجة. والمكدوس: بالسين المهملة من الكدس، وهو: الدفع والسقوط، ولاشين المعجمة من الكدش، وهو السوق الشديد. (والنار) أي: نار جهنم (وهي مسكن الكفار) والمشركين بالله تعالى (ومن أبي) أي: امتنع (عن طاعة) الله تعالى (الغفار) للذنوب ومات من غير توبة وهم العصاة من المؤمنين الذين شاء الله تعالى عذابهم، قال تعالى: {إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ} [النساء: 48] فلا نقطع لعصاة المؤمنين الذين ماتوا من غير توبة بعقاب أو مغفرة.\r(و) لكن (واجب) سمعا لا عقلا (ان ينفذ الوعيد) بالعقاب (في بعض العصاة) الذين ماتوا وهم مصرون على ذنوبهم من غير توبة (دون ما توقف) أي: من غير توقف غي شأنهم (وما بنوع واحد يختص) بالعقاب ولا بالغفران أيضا (منهم)] أي: من أنواع العصاة المذنبين (وفي) جميع (الأنواع) من العصاة (جاء النص) بحصول العقاب.\rقال اللقاني رحمه الله تعالى: والصغير من الذنوب يجوز العفو عنها وهو إجماع لم يخالف فيه إلا الخوارج والكبيرة يجوز العفو عنها أيضا بلا توبة وهو مذهب أهل السنة والجماعة بل أثبتوا وقوعه محتجين على جواز العفو بأن العقاب حقه تعالى فيحسن إسقاطه مع أن فيه نفعا للعبد من غير ضرر لأحد، وبالآيات والأحاديث الناطقة بذلك كقوله تعالى: {وَهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَعْفُو عَنِ السَّيِّئَاتِ} [الشورى: 25]. {أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا وَيَعْفُ عَنْ كَثِيرٍ} [الفاتحة: 34]. {إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا} [الزمر: 53]. {إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ} [النساء: 48]. {وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِلنَّاسِ عَلَى ظُلْمِهِمْ} [الرعد: 6]\r¬__________\r(¬1) رواه البخاري (6/ 2706) / وابن حبان (16/ 378)، والبيهقي في الشعب (1/ 333)، والطبراني في الكبير (9/ 203) وابن منده في الإيمان (2/ 801)"], [129, "لكن ذا العصيان لا يخلد ... فيها وذو الكفر بها مويد\r[الشرح]\rوفي الحديث: يا عبدي لو أتيتني بقراب الأرض ذنوبا لأتيتك بمثلها (¬1). إلى غير ذلك.\rوقال المناوي في شرح الجامع الصغير: والإجماع منعقد على أنه لا بد إنفاذ الوعيد في طائفة من العصاة؛ لأنه تعالى توعدهم وكلامه صدق فلا بد من وقوعه، وهل المراد طائفة من جميع العصاة أو طائفة من كل صنف؟ الظاهر الثاني لأنه كل صنف على حدته (¬2). وقال اللقاني رحمه الله تعالى وواجب سمعا وإجماعا اعتقادا تعذيب الله تعالى بالنار بعض عصاة هذه الأمة حيث ارتكب كبيرة من غير تأويل يعذر به شرها فعلا كانت أو تركا أو أقوالا أو اعتقاد لا يكفر مرتكبها ومات بلا توبة، ولا يجوز الحكم بالعذاب لفرد بعينه لجواز العفو والتوفيق للتوبة.\rثم قال: وإنما وجب العقاب لطائفة من أهل الكبائر لئلا تخلو نصوص الشرع الدالة على الوعيد لأهل الكبائر عن الصدق وهو محال ولئلا يخرق إجماعا المسلمين على نفوذ الوعيد في العصاة من الموحدين، والظهار أن كل نوع من أنواع الكبائر لا بد من نفوذ الوعيد في طائفة من مرتكبيه أقلها واحد على المختار من صدق الطائفة لغة به.\r(لكن) بتشديد النون (ذا) أي: صاحب (العصيان) من المؤمنين (لا يخلد فيها) أي: في النار. قال اللقاني رحمه الله تعالى: والعصاة من المؤمنين لا يخلدون في النار إض الإيمان عمل خير وقد قال تعالى: {فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ} [الزلزلة: 7]. ولا يمكن أن يراه قبل دخول النار لقوله: {وَمَا هُمْ مِنْهَا بِمُخْرَجِينَ} [الحجر: 48] ولا في النار لأنها ليست ذات خير، فتعين أنه بعد دخولها وذلك بالخروج منها (وذو) أي: صاحب (الكفر) بالله تعالى بأنواعه (بها) أ]: بالنار (مؤيد) أي: إلى الأبد لا يخرج منها، وهذا ما دلت عليه الآيات والأخبار وأطبق عليه جمهور العلماء سلفا وخلفا.\r¬__________\r(¬1) رواه مسلم (4/ 2068)، الدارمي (2/ 414)، وابن ماجه (2/ 1255)، والترميذي (5/ 548)، البزر في المسند (9/ 398)، والحاكم في المستدرك (4/ 269)، وأحمد في المسند (5/ 148، 154، 155)، والطيالسي في مسنده (1/ 62)، والطبراني في الكبير (12/ 19)، والبيهقي في الشعب (2/ 16، 17)، وابن مسنده في الإيمان (1/ 219)\r(¬2) انظر التمهيدي لابن عبد لبر (15/ 7)، (18/ 332)"], [130, "كالشفاعة لأزكى مرسل ... فاضرع على المنان فيها وأسأل\rوقد أتت أنواعها منصوصا ... والبعض كالكبرى به مخصوصة\rلأنها أظهرت ارتفاعه ... إذ وجه الكل له الشفاعة\rوالأنبياء تقول نفسي نفسي ... سواه فالفضل له كالشمس\rفينقذ الجميع من غموم ... قد اعترتهم ومن هموم\rوهي وعود ربه يوفيها ... له فنسأل الدخول فيها\r[الشرح]\r(وكالشفاعة) في ورود النصوص بها (لأزكى) أي: أفضل (مرسل) من الله تعالى إلى العبا وهو نبينا محمد صلى الله عليه وسلم (فاضرع) أي: ادع وابتهل (إلى) الله تعالى (المنان) أي: كثير المنن (فيها) أي: حصول الشفاعة لك (واسأل) بكسر اللام للقافية، أي: اطلب ذلك من الله تعالى.\r(وقد أتت أنواعها) أي: الشفاعة (منصوص) بسكون الهاء للوزن، أي: مبنية في النصوص (والبعض) منها (كالكبرى) أي: كالشفاعة الكبرى وهي أول الشفاعات في فصل القضاء به أي: بأزكى مرسل وهو نبينا صلى الله عليه وسلم (مخصوصة) بسكون الهاء أيضا (لأنها) أي: الشفاعة الكبرى المذكورة (أظهرت ارتفاعه) بسكون الهاء أيضا، أي: ارتفاع نبينا صلى الله عليه وسلم على جميع الأنبياء والمرسلين عليهم السلام (إذ) أي: لأنه (وجه) بتشديد الجيم يقال: وجهت الشيء، جعلته على جهة واحدة كذا في المصباح، فمعنى وجهت إليه الخطاب جعلت الخطاب على جهته (الكل) من الأنبياء والمرسلين عليهم السلام (له) أي: لنبينا صلى الله عليه وسلم (الشفاعة) بسكون الهاء في فصل القضاء.\r(والأنبياء) عليهم السلام في ذلك (تقول) كما ورد في الحديث (نفسي نفسي) تأكيد لفظي، أي: قولهم لا أعرف إلا نفسي (سواه) أي: سوى نبينا صلى الله عليه وسلم فإنه يقول في موضع قولهم ذلك أمتي أمتي (فالفصل له) صلى الله عليه وسلم يظهر على الكل يومئذ (كالشمس) أي: كظهور الشمس ووضوحها حيث لا يشكل فيها أحد (فينقذ) أي: الأنبياء عليهم السلام وأممهم (من غموم) جمع غم، وهي ما يقاسونه من أهوال المحشر (قد اعترتهم) بضم الميم للوزن، أي: غلبت عليهم (ومن هموم) أي: ما يهتمون به. (وهي) أي: الشفاعة التي اختصت به صلى الله عليه وسلم (وعود) جمع وعد تعددت بتعداد أنواعها (ربه) سبحانه وتعالى (يوفيها) أي: الله تعالى (له) صلى الله عليه وسلم بالقبول إن شاء الله تعالى (فنسأل) أي: نطلب من الله تعالى (الدخول فيها) أي: شمولها لنا معشر المكلفين."], [131, "0000000000000000000000000000000000000000000000000\r[الشرح]\rقال اللقاني رحمه الله تعالى: وله صلى الله عليه وسلم شفاعات ذكر القاضي عياض والنووي رحمه الله تعالى منه خمسا: إحداهما: وهي أعظمها وأعمها شفاعة فصل القضاء، وثانيتها: في إدخال قوم الجنة بغير حساب. وثالثتها: في قوم استوجبوا النار فيشفع فيهم فلا يدخلونها. ورابعتها: فيمن دخل النار من المؤمنين المذهبين. وخامستها: الشفاعة في زيادة الدرجات في الجنة.\rوزاد الأسيوطي رحمه الله تعالى في شرح النقاية: الشفاعة في تحقيق العذاب عمن استحق الخلود في النار كما في حق ابي طالب. وذكر في الخصائص الشفاعة أيضا في إخراج عموم أمته من النار حتى لا يبقى منهم أحد ذكره السبكي والشفاعة لجميع من صلحاء المؤمنين ليتجاوز عنهم في تقصيرهم في الطاعات ذكره القزويني في العروة الوثقى، والشفاعة في الموقف تخفيف عمن يحاسب، والشفاعة في أطفال المشركين أن لا يعذبوا، والشفاعة في أله بيته صلى الله عليه وسلم أن لا يدخل أحد منهم النار.\rوروى البخاري ومسلم، والترمذي، والنسائي، وابن ماجه حديث الشفاهة الأولى في فصل القضاء عن أبي هريرة رضي الله عنه، وهذه رواية مسلم عنه: أتي رسول الله صلى الله عليه وسلم يوما بلحم فرفه إليه الذارع وكانت تعجبه فنهش منها نهشة فقال: أنا سيد الناس نوم القيامة وهل تدرون بما ذلك؟ يجمع الله يوم القيامة الأولين ولآخرين في صعيد واحد فيسمعهم الداعي وينفذهم البصر وتدنو الشمس فيبلغ الناس من الغم والكرب ما لا يطيعون وما لا يحتملون فيقول بعض الناس لبعض: ألا ترون ما أنتم فيه؟ ألا ترون ما قد بلغكم؟ ألا تنظرون إلى من يشفع لكم إلى ربكم؟ فيقول بعض الناس ائتوا آدم فيأتون آدم فيقولون: يا آدم أنت أبو البشر خلقك الله بيده ونفخ فيك من روحه وأمر الملائكة فسجدوا لك، اشفع لنا إلى ربك ألا ترى ما نحن فيه! ألا ترى ما قد بلغنا، فيقول آدم: إن ربي غضب اليوم غضبا لم يغضب قبله مثله، ولن يغضب بعده مثله، وإنه نهاني عن الشجرة فعصيته نفسي اذهبوا إلى نوح فيأتون نوحا فيقولون: يا نوح! أنت أول الرسل إلى الأرض وسماك الله عبدا شكورا اشفع لنا إلى ربك ألا ترى ما نحن فيه؟ ألا ترى ما قد بلغنا؟ فيقول لهم: إن ربي قد غضب اليوم غضبا لم يغضب قبله مثله، ولن يغضب بعده مثله، وإنه قد كانت لي دعوة على قومي نفسي نفسي، اذهبوا إلى إبراهيم فيأتون إبراهيم فيقولون: أنت نبي الله خليل الهلم نل أهل الأرض اشفع لنا إلى ربك ألا ترى ما نحن فيه؟ ألا ترى ما قد بلغنا؟ فيقول لهم إبراهيم: إن ربي قد غضب اليوم غضبا لم يغضب قبله"], [132, "وحوضه مما به النص ورد ... وفيه خلف هل به الهادي انفرد\r[الشرح]\rمثله ولن يغضب بعده مثله، وذكر كذباته نفسي نفسي، اذهبوا إلى غيري اذهبوا إلى موسى، فيأتون موسى فيقولون: يا موسى! أنت رسول الله فضلك الله برسالاته وبتكليمه على الناس، اشفع لنا إلى ربك ألا ترى ما نحن فيه؟ ألا ترى ما قد بلغنا؟ فيقول لهم موسى: إن ربي قد غضب غضبا لم يغضب قبله مثله ولن يغضب بعده مثله، وإني قتلت نفسا لم أؤمر بقتله نفسي نفسي اذهبوا إلى عيسى. فيأتون عيسى فيقولون: يا عيسى! أنت رسول الله وكلمت الناس في المهد وكلمته ألقاها إلى مريم وروج منه، فالشفع لنا إلى ربك ألا ترى ما نحن فيه؟ ألا ترى ما قد بلغنا؟ فيقول لهم عيسى: إن ربي قد غضب غضبا لم يغضب قبله مثله، ولن يغضب بعده مثله ولم يذكر له ذنبا نفسي نفسي اذهبوا إلى غيري اذهبوا إلى محمد. فيأتون فيقولون: يا محمد! أنت رسول الله وخاتم الأنبياء وغفر لك الله ما تقدم من ذنبك وما تأخر اشفع لنا إلى ربك، ألا ترى ما نحن فيه؟ ألا ترى ما قد بلغنا؟ فانطلق فآتي تحت العرش فاقع ساجدا لربي ثم يفتح الله علي ويلهمني من محامده وحسن الثناء عليه شيئا لو يفتحه لأحد قبلي، ثم يقال: يا محمد ارفع رأسك سل تعط واشفع تشفع، فأرفع رأسي فأقول: يا رب أمتي أمتي، فيقال: يا محمد أدخل الجنة من أمتك من لا حساب عليه من الباب الأيمن من أبواب الجنة وهم شركاء الناس فيما سوى ذلك من الأبواب، والذي نفس محمد بيده إن ما بين المصراعين من مصارع الجنة لكما بين مكة وهجر وكما بين مكة وبصرى (¬1).\r(وحوضه) أي: نبينا صلى الله عليه وسلم (مما به النص) الشرع (ورد) بسكون الدال المهملة للوزن، يعني مما يجب الإيمان به حوض نبينا محمد صلى الله عليه وسلم الذي يعطاه في الآخرة ترده أمته من شرب منه لا يظمأ أبدا وهو حق ثابت بالنقل الصحيح وأحاديثه مختلفة في تحديده بالمسافات البعيدة والقريبة. وأجابوا بأنه عليه الصلاة والسلام خاطب كل أناس بما يعرفون وليس المراد التحديد وبعضهم عد الاختلاف في ذلك اضطرابا في حديث الحوض وبعضهم لم يعده اضطرابا في حديث الحوض وبعضهم لم يعده اضطرابا، وأجبنا عن ذلك في كتابنا (المطالب الوفية) بأنه يمكن الاعتذار عنه بأنه يكبر في حق قوم ويصغر في حق آخرين، ونظيرة الصراط يتسع بحسب بعض المارين فيكون كبطن في حق قوم ويصغر في حق آخرين، ونظيره الصراط يتسع بحسب بعض المارين فيكون كبطن الوادي ويضيق بحسب البعض الآخر كما ذكروه، ومثله القبر يضيق على الكافر ويتسع على الزمن وكذلك يوم القيامة يطول على الكافرين ويقتصر على المؤمنين ونحو ذلك.\r¬__________\r(¬1) رواه البخاري (3/ 1215)، (4/ 1746)، (6/ 2727)، ومسلم (1/ 170/ 183)"], [133, "وهو الأصح أو لكل مرسل ... حوض من العذب الرحيق السلسل\rوكونه بعد الصراط مختلف ... فيه وبعض بالتعدد اعترف\rوذود ذي التغير قد بدا ... ومن يذقه ليس يظمأ أبدا\r[الشرح]\r(وفيه خلف) أي: اختلاف بين العلماء (هل به) أي: بالحوض (الهادي) أي: نبينا محمد صلى الله عليه وسلم (انفرد) بسكون الدال للوزن أي: ليس لغيره من الأنبياء عليهم السلام، وإنما هو شيء اختص به صلى الله عليه وسلم.\r(وهو) القول (لأصح) عند العلماء (أو لكل) نبي (مرسل حوض) على حدته (من) الماء (العذاب) السائغ شربه (الرحيق)] أي: الخالص الصافي (السلسل) كجعفر: البارد. وفي شرح الجامع الصغير للمناوي قال القرطبي نقلا عن البكري المعروف بابن الوسطي: لكل نبي حوض إلا صالحا عليه السلام: فإن حوضه ضرع ناقته، قال: ولم أقف على ما يدل عليه أو يشهد له لكن هذا الحديث أعني قوله عليه الصلاة والسلام: إن لكل نبي حوضا وإنهم يتباهون أيهم أكثر واردة وإني أرجو أن أكون أكثرهم واردة (¬1). صريح فإن الحوض ليس من الخصائص المحمدية، لكن اشتهر الاختصاص وحينئذ فالمختص نبينا صلى الله عليه وسلم بالكوثر الذي يصب من مائه في حوضه فإنه لم ينقل نظيره لغيره.\r(وكونه) أي: الحوض (بعد الصراط مختلف) بفتح اللام وسكون الفاء للوزن (فيه وبعض) من العلماء (بالتعدد) أي: تعدد الحوض قبل الصراط حوض وبعد الصراط حوض (اعترف) بسكون الفاء. قال اللقاني رحمه الله تعالى: وقد تعارضت الآثار في محله، ففي بعضها قبل الصراط والميزان، وفي بعضها بعد الميزان وفي بعضها بعد الصراط وجمع بتعدده واختار صاحب القوت والإيضاح والقاضي بعد أن صحح أن للنبي صلى الله عليه وسلم حوضين حديث، قال: وهما حوضان الأول قبل الصراط وقبل الميزان على الأصح، فإن الناس يخرجون عطاشا من قبورهم فيردونه قبل الميزان والصراط والثاني في الجنة وكلها يسمى كوثرا.\r(وذود) بالذال المعجمة فالواو ثم دال مهملة، أي: منع وطرد (ذي) صاحب (التغيير) والتبديل في الأحكام الشرعية بعمل البدع والضلالات في الاعتقادات وفي العمليات (عنه) أي: عن الحوض (قد بدا) أي: ظهر واتضح. قال السنوسي رحمه الله تعالى في شرح\r¬__________\r(¬1) رواه الترمذي (4/ 268)"], [134, "والله لا يحرمنا من شرب ... منه بجاه المصطفى ذي القرب\rوالجنة التي أعد الله ... حق لمن إنعامه أولاه\r[الشرح]\rالجزائرية: وقيل إن له صلى الله عليه وسلم حوضين أحدهما قبل الصراط والآخر بعده، فالأول هو الذي يذاد عنه من بدل أو غير، والثاني لا يذاد عنه احد لأنه لا يجتاز إليه إلا من تخلص من العذاب.\rوأخرج مالك في الموطأ، ومسلم في صحيحه، عن أبي هريرة صلى الله عليه وسلم، أن رسولا الله صلى الله عليه وسلم خرج إلى المقبرة فقال: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون وددت أني قد رأيت إخواننا. فقالوا: يا رسول الله! ألسنا بإخوانك؟ قال: بل أنتم أصابي وإخواننا الذين لم يأتوا بعد وأنا فرطهم على الحوض. فقالوا: يا رسول الله! كيف تعرف من يأتي بعدك من أمتك؟ فقال: أرأيتم لو كان لرجل خيل غر محجلة في خيل دهم بهم ألا يعرف خيله؟ قالوا: بلى يا رسول الله. قال: فإنهم يأتون يوم القيامة غرا محجلين من آثار الوضوء وأنا فرطهم على الحوض فليذادن رجال عن حوضي كما يذاد البعير الضال أنادي بهم ألا هلم ألا هلم ألا علم فيقال: إنهم قد بدلوا بعدك فأقول: فسحقا فسحقا فسحقا (¬1)\r(ومن يذقه) أي: يشرب منه شربة (ليس يظمأ) أي: لا يعطش (أبدا) حتى لو اتفق أن الذي شرب منه كان ممن يدخل النار من عصاة الموحدين فإنه يعذب فيها ولكن بغير الظمأ والعطش كما أشار إليه الشيخ علوان بن عطية بن الحموي في شرح الشيبانية.\r(والله لا يحرمنا) معشر المكلفين (من شرب منه) أ] ك الحوض (بجاه) أي: بحرمة (المصطفى) نبينا صلى الله عليه وسلم: (ذي) أي: أصحاب (القرب) أي: رفعة المقام عند الله تعالى (والجنة) أي: دار النعيم في الآخرة (التي أعد) أي: هيأها (الله حق) ثابت بالكتاب والسنة وإجماع الأمة (لمن) أي: للمؤمن الذي (إنعامه) سبحانه وتعالى عليه (أولاه) أي: تابعه وأدامه وأكثره سرا وجهرا. فيه إشارة إلى أن دخول الجنة بمجرد إنعام الله تعالى على عبده ومحض فضله العميم كما ورد في الحديث، وروى البخاري ومسلم عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: لن يدخل أحدا عمله الجنة. فقالوا: ولا أنت يا رسول الله؟ قال: ولا أنا إلا أن يتغمدني الله بفضله ورحمته، فسدوا وقاربوا ولا يتمنى احدكم الموت إما محسنا فلعله أن يزداد خيرا وإما مسيئا فلعله أن يستعتب (¬2)\r¬__________\r(¬1) رواه مسلم (1/ 218)، (2/ 669)\r(¬2) تقدم تخريجه أول الكتاب."], [135, "والمؤمنون بالأماني أسعدوا ... فيها في أوج التهاني أصعدوا\rوكيف لا وقد تناءى كل سو ... عنهم ونالوا ما اشتته الأنفس\rوأتحفوا من العطايا والبشر ... ما لم يكن يخطر في قلب بشر\rومن رضي الرحمن ما قرت به ... عيونهم مع أمنهم من سلبه\r[الشرح]\r(والمؤمنون بالأماني) جميع: أمنية، وهي ما يتمناه الإنسان ويرجو حصوله من أنواع المقاصد (أسعدوا) بضم الهمزة، أي: أسعدهم الله تعالى (فيها) أ]: في الجنة (وفي أوج) أي: أعلاما يكون من (التهاني) جمع تهنية خلاف التعزية، تقولك هنأت بالولاية تهنئة وتهنيئا كذا في الصحاح. وفي المصباح: هنأني الولد يهنأني مهموز من باب نفع وضرب، أي: سرني. انتهى. والمراد هنا أنواع المسرات. (أصعدوا) بضم الهمزة، أي: أصعدهم الله تعالى بمعنى رقاهم ورفع درجاتهم.\r(وكيف لا) يكون شأنهم كذلك (وقد تناءى) أي: تباعد (كل سوء) بضم السين المهملة (وسكون الواو والهمزة محذوفة وأصله سوء. قال في الصحاح: ساءه يسوؤه سوءا بالفتح نقيض سر والاسم السوء بالضم (عنهم) أي: عن المؤمنين (ونالوا ما اشتته) أ]: طلبته (الأنفس) جمع نفس، قال الله تعالى: {وَفِيهَا مَا تَشْتَهِيهِ الْأَنْفُسُ وَتَلَذُّ الْأَعْيُنُ} [الزخرف: 71]\r(وأتحفوا) بضم الهمزة أي: أتحفهم الله تعالى (من العطايا) جمع عطية (والبشر) بسكون الراء للوزن جمع بشرى، وهي البشارة التي تكون بالخير، والمراد أنواع الخيرات (ما) أي: أمرا عظيما (لم يكن يخطر) أي: يمر (في قلب بشر) بفتحتين وسكون الراء، إنسان، قال تعالى: {فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ} [السجدة: 17]\r(ومن رضى الرحمن) سبحانه وتعالى (ما) أي: نصيبا وافيا (قرت) أي: بردت (به) أي: سبب حصوله (عيونهم) أي: المؤمنين، وأصله أن دموع السرور باردة ودموع الحزن حارة فكنى ببرد الدموع عن السرور، بل أضيف ذلك إلى العيون مجازا (مع أمنهم من سلبه) أي: زواله عنهم لأنهم خالدون فيها أبدا (وزادهم من بعد هذا) المذكور (كله رؤيتهم) أي: كونهم يرون (من) فاعل زادهم أو مفعول المصدر (عمهم) أي: شملهم (بفضله) وهو الله تعالى."]], "pg": [118, 135]}, "496.20": {"x": [[136, "وزادهم من بعد هذا كله ... رؤيتهم من عمهم بفضله\rفنسأل الكريم أن يجعلنا ... منهم وأن ييسر النفع لنا\r\rخاتمة\rوأسأل الله حسنها في مسائل نافعة\r\rوواجب إيماننا بالقدر ... خير وضده كما في الخبر\r[الشرح]\rوروى البخاري ومسلم، والترمذي، عن أبي سعيد الخدري رضي الله عنه قال: قال النبي صلى الله عليه وسلم: ((إن الله يقول لأهل الجنة: يا أهل الجنة! فيقولون: لبيك وسعديك ربنا والخير في يديك فيقول: رضيتم؟ فيقولون: وما لنا لا نرضى وقد أعطيتنا ما لم تعط أحدا من خلقك؟ فيقول: ألا اعطيكم أفضل من ذلك؟ فيقولون: يا رب وأي شيء أفضل من ذلك؟ فيقول: أحل عليكم رضواني فلا أسخط عليكم بعده أبدا (¬1)\r(فنسأل) الله (الكريم أن يجعلنا) وجميع إخواننا من المسلمين والمسلمات والمؤمنين والمؤمنات الأحياء منهم والأموات (منهم) أي: من أهل الجنة المذكرين (وأن ييسر النفع) في الدين والدنيا والآخرة (لنا) ولإخواننا المذكورين أجمعين.\r(خاتمة) يختم بها الكتاب\r(وأسأل الله تعالى) أي: أطلب منه (حسنها)\rأي: خاتمة بالمعنيين: خاتمة الكتاب وخاتمة الأعمال بحلول (لأجل) ساعة الاقتراب (في بيان مسائل نافعة) وفوائد مختلفة وفوائد مؤتلفة نافعة لأمة محمد صلى الله عليه وسلم إن شاء تعالى وذلك قوله:\r(وواجب) شرعا علينا معشر المكلفين (إيماننا) أي: تصديقنا (بالقدر) بفتح الدال ويقال بسكونها أيضا وهو ما يقدر الله تعالى من القضاء. وفي شرح العقائد للسعد قال: هو تحديد كل مخلوق بحده الذي يوجد عليه من حسن وقبح ونفع وضر وما يحويه من زمان ومكان وما يترتب عليه من ثواب وعقاب. (خير) بدل من القدر (وضده) أي: الشر (كما) ورد (في الخير) أي: الحديث عن النبي صلى الله عليه وسلم فيما رواه الترمذي في سننه، وعن جابر بن عبد الله رضي الله عنه قال: رسول الله صلى الله عليه وسلم: لا يؤمن عبد حتى يؤمن بالقدر خيره وشره حتى يعلم أن ما أصابه لم يكن ليخطئه، وأن ما أخطأ لم يكن ليصيبه.\r¬__________\r(¬1) رواه البخاري (3/ 1221)، (6/ 2732)، ومسلم (1/ 201، 535)، والترمذي (3/ 177)، (5/ 486)"], [137, "وذو السعادة السعيد في الأزل… وعكسه الشقي حيثما نزل\rوكلهم ميسر لما خلق …له فداج أمره ومؤتلق\r[الشرح]\rوروى الترمذي أيضا، عن عبد الله بن عمر رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: ((قدر الله المقادير قبل أن يخلق السماوات والأرض بخمسين ألف سنة)). إلى غير ذلك من الأحاديث.\r(وذو) أي: صاحب (السعادة) عندنا في الدنيا وهو (السعيد في الأزل) بسكون اللام للقافية والوزن أي: في حضرة علم الله تعالى القديم (وعكسه) أي: الشقي في الأزل وهو (الشقي) عندنا في الدنيا (حيثما) أي: في أي حالة أو مكان (نزل) بسكون اللام أيضا، فالمعتبر في السعيد والشقي ما في الأزل ويظهر في خاتمة العمل، ولا عبرة بما يظهر على المكلف في الدنيا من ذلك فيلزم من هذا أن السعيد لا يشقى والشقي لا يسعد وهو قول الأشعري.\rوقال أبو منصور الماتريدي: السعيد هو المتصف بالسعادة في الشرع بحسب ما يظهر عليه في الدنيا والشقي كذلك هو المتصف بالشقاوة شرعا بمقتضى ظاهر الحال، فيلزم من ذلك أن السعيد قد يشقى إذا كان شقيا في الأزل والشقي قد يسعد إذا كان سعيدا في الأزل والخلاف بينهما لفظي كما قال العلماء فكل منهما ناظر إلى طرف، فمن نظر إلى خاتمة العمل وإلى ما في حضرة الأزل من علم الله تعالى بتفاصيل أحوال العباد قال بالأول، ومن نظر إلى تسمية الشرع المؤمن مؤمنا وإجراء أحكام الإيمان عليه وإن كان في تقدير الله موته على الكفر وكذلك المطيع والكافر والفاسق قال بأن السعيد قد يشقى والشقي قد يسعد، ولا خلاف بينهما في تسميته سعيدا أو شقيا بحسب أحكام الشرع في الدنيا، كما أنه لا خلاف أيضا في أن من له السعادة في الأزل أو الشقاء فلا تتبدل ولا تتغير.\r(وكلهم) أي: السعداء والأشقياء من المكلفين ومن تبعهم (ميسر) أي: مهيأ (لما خلق) بالبناء للمفعول بسكون القاف للوزن (له) أي: لأجله من الخير والشر (فداج) أي: مظلم، يقال: دجا الليل إذا أظلم (أمره) أي: شأنه وحاله، وهو: الشقي (مؤتلق) بسكون القاف، من قولهم: تألق البرق، أي: لمع والائتلاق مثل التألق كذا في الصحاح. والمراد منير مشرق أمره وحاله وهو السعيد. @"], [138, "والكل لا يخرج عن حكم القضا وليس ما أظلم مثل ما أضا\rوما إلى الأعمال ظاهرا رجع فذاك إسلام به العبد انتفع\rومرجع الإيمان للإذعان بالقلب والتصديق بالجنان\rونطق ذي القدرة شرط فيه على اختلاف كتبهم تحويه\r[الشرح]\r(والكل) من الفريقين (لا يخرج عن حكم القضا) بالقصر للوزن أي: قضاء الله تعالى عليه وتقديره (وليس ما) أي: أمر وحال (أظلم) لشقاء صاحبه (مثل ما) أي: أمر وحال (أضا) بحذف المد أي: أنار وأشرق لسعادة صاحبه (وما) أي: الأمر الذي (إلى الأعمال) البدنية (ظاهرا) أي: في ظاهر أحوال المكلفين (رجع) بسكون العين المهملة من فعل أو كف قطعي أو ظني (فذاك إسلام) لأنه انقياد بحسب الظاهر (به) أي: سببه (العبد) المكلف (انتفع) بسكون العين المهملة في الدنيا حيث عصم دمه وماله وعرضه.\r(ومرجع الإيمان) أي: التصديق بما يجب التصديق به (للإذعان) أي: الانقياد والاستسلام بالقلب والتصديق، أي: نسبة المؤمن إلى الصدق (بالجنان) بالفتح، وهو القلب، سمي بذلك لأن الصدر يستره، وأجنه الليل بالألف وجن عليه جنونا من باب قعد ستره كذا في المصباح. فبهذا الاعتبار كان الإسلام غير الإيمان وأما باعتبار عدم قبول أحدهما بدون الآخر عندنا وعند الله تعالى معا فهما بمعنى واحد، وأما عندنا فقط فيقبل الإسلام بدون الإيمان كما قال تعالى: {قَالَتِ الْأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ} [الحجرات: 14]. وأما عند الله تعالى فقط فيقبل الإيمان بدون الإسلام كمن صدق بقلبه وأذعن للحق ولم يظهر شيئا من ذلك في الدنيا فهو مؤمن عند الله تعالى لا عندنا، فلا نجري عليه أحكام أهل الإسلام في الشرع كما قدمناه، وقد أشار إلى ذلك بقوله:\r(ونطق ذي) أي: صاحب (القدرة) على النطق ليخرج الأخرس ونحوه (شرط فيه) أي: في الإيمان خارج عن ماهيته فيتصور وجود الإيمان بدون شرط لكن عند الله تعالى بحيث لا يعلم به إلا الله تعالى لا عندنا، وعننا لا يتصور شرعا إلا بالنطق أو ما يدل عليه (على) حسب (اختلاف) في ذلك لقول بعضهم: إن النطق شطر من الإيمان فلا يتصور وجوده بدون النطق عندنا وعند الله تعالى (كتبهم) أي: كتب علماء الشرع والكلام (تحويه) أي: هذا الاختلاف، قال والدنا المرحوم في شرحه على شرح الدرر من باب المرتد:"], [139, "والخلف في النقصان والزياده مقرر عند ذوي الإفاده\rوقيل للأعمال يرجعان فينتفي الخلاف في المعاني\r[الشرح]\rالإيمان هو التصديق بالقلب واللسان، وهو منقول عن أبي حنيفة ومشهور عن أصحابه، وبعض المحققين من الأشاعرة قالوا: إنما يكون الإيمان هو التصديق، والتصديق كما يكون بالقلب يكون باللسان فيكون كل منهما ركنا من الباب ولا يثبت الإيمان إلا بهما عند الفخر.\r(والخلف) أي: الاختلاف واقع بين العلماء (في النقصان) أي: في وجود نقصان الإيمان (والزيادة) بسكون الهاء، أي: زيادة الإيمان (ومقرر عند ذوي) أي: أصحاب (الإفاده) بسكون الهاء، أي: إفادة العلوم وهم العلماء (وقيل) أي: الزيادة والنقصان في الإيمان (للأعمال) البدنية (يرجعان فينتفي الخلاف) في ذلك (في المعاني) المقصودة ويبقى الخلاف في مجرد اللفظ.\rقال السعد في شرح العقائد: حقيقة الإيمان لا تزيد ولا تنقص لما مر أنه التصديق القلبي الذي بلغ حد الجزم والإذعان، وهذا لا يتصور فيه زيادة ولا نقصان حتى إن من حصل له حقيقة التصديق فسواء أتى بالطاعات أو ارتكب المعاصي فتصديقه باق على حاله لا تغير فيه أصلا، والآيات الدالة على زيادة الإيمان محمولة على ما ذكره أبو حنيفة - رضي الله تعالى عنه - أنهم كانوا آمنوا في الجملة ثم يأتي فرض بعد فرض وكانوا يؤمنون بكل فرض خاص.\rوحاصله أنه كان يزيد بزيادة ما يجب الإيمان به وهذا لا يتصور في غير عصر النبي صلى الله عليه وسلم. وفيه نظر لأن الاطلاع على تفاصيل الفرائض يمكن في غير عصر النبي صلى الله عليه وسلم، والإيمان واجب إجمالا فيما علم إجمالا وتفصيلا فيما علم تفصيلا، ولا خفاء في أن التفصيلي أزيد بل أكمل من الإجمالي وما ذكر من أن الإجمالي لا ينحط عن درجته فإنما هو في الاتصاف بأصل الإيمان وقيل: إن الثابت والدوام على الإيمان زيادة عليه في كل ساعة.\rوحاصله أنه يزيد بزيادة الأزمان لما أنه عرض لا يبقى إلا بتجدد الأمثال. وفيه نظر لأن حصول المثل بعد انعدام الشيء لا يكون من الزيادة في شيء كما هو في سواد الجسم مثلا، وقيل: المراد زيادة ثمرته وإشراق نوره وضائه في القلب فإنه يزيد بالأعمال وينقص بالمعاصي @"], [140, "واللوح والقلم والكرسي والعرش ذو الجسامة القدسي\rوالكاتبون واجب إيماننا بكلهم فرض بهم إيقاننا\r[الشرح]\rومن ذهب إلى أن الأعمال من الإيمان فقبوله الزيادة والنقصان ظاهر ولهذا قيل إن هذه المسألة فرع مسألة كون الطاعات من الإيمان، وقال بعض المحققين: لا نسلم أن حقيقة التصديق لا تقبل الزيادة والنقصان بل تتفاوت قوة وضعفا للقطع بأن تصديق آحاد الأمة ليس كتصديق النبي صلى الله عليه وسلم، ولهذا قال إبراهيم صلى الله عليه وسلم: {وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي} [البقرة: 260].\rوقال الإمام الرازي: هذا البحث لفظي لأن المراد بالإيمان إن كان هو التصديق فلا يقبلهما وإن كانت الطاعات يقبلهما، ثم ذهب إلى التوفيق فقال: الطاعة مكملة للتصديق، وكل ما دل من الدلائل على أن الإيمان لا يقبل الزيادة والنقصان كان مصروفا إلى أصل الإيمان الذي هو التصديق وما دل على كونه قابلا لهما فهو مصروف إلى الإيمان الكامل ثم ذكر وجها آخر ورجحه في حصول الزيادة والنقصان في الإيمان وقد بحثنا فيه في كتابنا ((المطالب الوفية)) وبسطنا الكلام في هذا المقام.\r(واللوح) المحفوظ، قال اللقاني - رحمه الله تعالى -: هو جسم نوراني كتب فيه القلم بإذن ربه ما كان وما هو كائن وما يكون، ونمسك عن القطع بتعيين حقيقته (والقلم) الا'لى الذي هو بيد الله تعالى يكتب به في اللوح المحفوظ ما شاء أو يمحو ما شاء. قال اللقاني - رحمه الله تعالى -: هو جسم نوراني خلقه الله تعالى وأمره بكتب ما كن وما يكون إلى يوم القيامة، ونمسك أيضا عن الجزم بتعيين حقيقته (والكرسي) بضم الكاف أشهر من كسرها وتشديد الياء التحتية.\rقال اللقاني - رضمه الله تعالى -: هو جسم عظيم نوراني بين يدي العرش ملتصق به لا قطع لنا بحقيقته فنمسك عنها لعدم العلم بها (والعرش) هو جسم عظيم نوراني علوي محيط بجميع الأجسام، قيل: هو أول المخلوقات وجودا عينيا ولا قطع لنا بتعيين حقيقته لعدم العلم بها ذكره اللقاني. (ذو) أي: صاحب (الجسامة) أي: كر الجسم لإحاطته بجميع الأجسام لاشتماله عليها (القدسي) المنسوب للقدس وهو الطهارة والنزاهة لأنه مجلي الحضرة الرحمانية، ومستوى ومجموع الأسماء الربانية.\r(والكاتبون) لأعمال العباد وهم الملائكة الحفظة لبني آدم، قال تعالى: {لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ} [الرعد: 11]. وقيل: إنهم في الآية هم الحفظة"], [141, ".......................................\r[الشرح]\rوهم غير الكتبة. وقال اللقاني: هم غير الكتبة بلا خلاف، وعن عثمان رضي الله عنه، أنه سأل النبي صلى الله عليه وسلم: كم من ملك على الإنسان؟ فذكر عشرين ملكا.\rقال المهدوي في الفصل وذكر الأبي أنه يحفظ لابن عطية أن كل آدمي يوكل به حين وقوعه نطفة في الرحم إلى موته أربعمائة ملك، وفي النهاية شرح الهداية: اختلفت الأخبار في عددهم، فقد روي عن ابن عباس رضي الله عنهما، عن النبي صلى الله عليه وسلم أنه قال: ((مع كل مؤمن خمسة من الحفظة واحد عن يمينه يكتب الحسنات، وآخر عن يساره يكتب السيئات، وآخر أمامه يلقنه الخيرات وآخر وراءه يدفع عنه المكاره، وآخر عن ناصيته يكتب ما يصلي على النبي صلى الله عليه وسلم ويبلغه إلى الرسول)).\rوفي بعض الأخبار: ((مع كل مؤمن ستون ملكا وفي بعضها مائة وستون)).\r(واجب) شرعا (إيماننا) معشر المكلفين (بكلهم) أي: بكل ما ذكر من كرام كاتبين وما قبلهم من اللوح والقلم والكرسي والعرش على طريقة التغليب (فرض) تأكيد (بهم) أي: بالمذكورين تغليبا أيضا (إيقاننا) على سبيل القطع لورود ذلك في الكتاب والسنة وإجماع الأمة، قال تعالى: {بَلْ هُوَ قُرْآنٌ مَجِيدٌ (21) فِي لَوْحٍ مَحْفُوظٍ} [البروج: 21، 22]. وقال تعالى: {عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ} [العلق: 5].\rوقال تعالى: {وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ} [البقرة: 255]. وقال تعالى: {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى} [طه: 5]. وقال تعالى: {وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ (10) كِرَامًا كَاتِبِينَ (11) يَعْلَمُونَ مَا تَفْعَلُونَ} [الانفطار: 10 - 12].\rوأخرج أبو الشيخ، وابن أبي حاتم بسند جيد عن ابن عباس رضي الله عنهما قال: ((خلق الله اللوح المحفوظ كمسيرة مائة عام، فقال للقلم قبل أن يخلق الخلق وهو على العرش: اكتب فقال القلم: وما أكتب؟ قال: اكتب علمي في خلقي فجرى القلم بما هو كائن في علم الله إلى يوم القيامة))."], [142, "… وإن للعبد كراما حفظه … لكل ما أخفاه أو ما لفظه\r[الشرح]\rوأخرج أبو الشيخ من طريق مالك بن دينار، عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((إن لله لوحا أحد وجهيه ياقوتة حمراء، والوجه الثاني زمردة خضراء، قلمه النور فيه يخلق وفيه يرزق، وفيه يحيي وفيه يميت، وفيه يعز وفيه يذل، وفيه يفعل ما يشاء في كل يوم وليلة)).\rوأخرج أبو داود، والترمذي، عن عبادة بن الصامت رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: ((إن أول ما خلق الله القلم فقال له: اكتب. فقال: يا رب! وماذا أكتب؟ قال: اكتب مقادير كل شيء حتى تقوم الساعة)).\rوفي رواية للترمذي، عن عبادة بن الصامت رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: ((إن أول ما خلق الله القلم، فقال له: اكتب، فجرى بما هو كائن إلى الأبد)).\rوأخرج ابن جرير، وابن مردويه، وأبو الشيخ، عن أبي ذر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((يا أبا ذر ما السماوات السبع في الكرسي إلا كحلقة ملقاة في فلاة وفضل العرش على الكرسي كفضل الفلاة على تلك الحلقة)).\rوأخرج الفريابي، وابن المنذر، وابن أبي حاتم، والحاكم في المستدرك وصححه على شرط الشيخين، عن ابن عباس رضي الله عنه قال: ((الكرسي موضع القدمين، والعرش لا يقدر أحد قدره)). وأخرج البخاري، عن أبي هريرة - رضي الله تعالى عنه - قال: قال رسول الله صلى الله عليه وسلم: ((لما قضى الله الخلق كتب في كتاب فهو عنده فوق العرش إن رحمتي وسعت غضبي)).\r(وإن للعبد) ولو لم يكن مكلفا وللجن أيضا كما ذكره اللقاني - رحمه الله تعالى - (كراما حفظه) بالتحريك جمع حافظ وبسكون الهاء للوزن من الملائكة الموكلين بالعباد (لكل) أي: جميع ما يأتي به من أقواله وأفعاله (ما أخفاه) من ذلك عن غيره (أو ما لفظه) بسكون الهاء، أي: تكلم به."], [143, "ويجعل الله لهم علامه على الضمير فاسأل السلامه\rوقيل لا يكتب ما في القلب والكل لا يفوت علم الرب\r[الشرح]\r(ويجعل الله) تعالى (لهم) أي: للحفظة المذكورين (علامه) بسكون الهاء (على الضمير) أي: ما يضمره العبد (فاسأل) أي: اطلب من الله تعالى (السلامه) بسكون الهاء أيضا من الخطر في ذلك (وقيل لا يكتب) بالبناء للمفعول (ما في الطلب) أي: قلب العبد من الخواطر التي يهتم بها ويعزم عليها ما لم يفعلها.\rوأخرج البخاري، ومسلم، عن أبي هريرة - رضي الله عنه -، أن رسول الله صلى الله عليه وسلم قال: ((يتعاقبون فيكم ملائكة بالليل وملائكة بالنهار ويجتمعون في صلاة العصر وصلاة الفجر، ثم يعرج الذين باتوا فيكم فيسألهم وهو أعلم بهم كيف تركتم عبادي؟ فيقولون: تركناهم وهم يصلون وأتيناهم وهم يصلون)).\rوذكر والدي المرحوم في شرحه على شرح الدر قال: الحفة محركة الذين يحصون أعمال العباد من الملائكة وهم الحافظون، وسموا بذلك إما لحفظهم أعمالهم فهم الكرام الكاتبون أو ذاته من الجن وأسباب المعاطب فهم جميع من معه فقيل مع كل مؤمن خمسة، وقيل: ستون، وقيل: مائة وستون، وقيل: أكثر من ذلك يذبون عنه ولو بدوا لكم لرأيتموهم على كل سهل وجبل كلهم باسط يده فاتح فاه ولو وكل العبد إلى نفسه طرفة عين لاختطفته الشياطين. انتهى\rوقدمنا أنهم هم الكرام، وقيل: إنهم غيرهم، وذكرهم بعد الكاتبين يقتضي أنهم غيرهم، ولكن قوله: لكل ما أخفاه أو ما لفظه، وقوله: وقيل: لا يكتب ما في القلب يدل على أنهم ليسوا غيرهم وهو المتبادر للفهوم، وقال اللقاني - رحمه الله تعالى -: إن الملائكة يكتبون على الإنسان كل شيء من أمره القول والعقد والعمل. واختلف في كتبهم جميع أفعاله حتى يكتبون الأنين الصادر عنه بمقتضى طبيعته في حال المرض والصحيح كتب حسنات الصبي وإن كان المجنون لا حفظة عليه، وقد بسطنا هذا البحث في ((المطالب الوفية)). (والكل) من ذلك (لا يفوت علم الرب) سبحانه وتعالى."], [144, "وليس يحتاج إلى الاستظهار بهم تعالى عالم الأسرار\rوما له سبحانه من اسما قديمة لها المقام الأسمى\rوهي لنا تدرى بالاستقراء من طرق التوقيف لا الآراء\r[الشرح]\r(وليس يحتاج) الله عز وجل في إثبات ذلك على العباد (إلى استظهار) أي: طلب الظهير، أي: المعين على الإثبات كالشهود (بهم) أي: الملائكة الحفظة عليهم السلام (تعالى) أي: تنزه وتقدس (عالم الأسرار) أي: خفايا الأمور فلا يخفى عليه شيء في الأرض ولا في السماء ولكن حكمه سبحانه وتعالى في ذلك كثيرة.\r(و) جميع (ما) أي: الذي (له) أي: الله تعالى (سبحانه) وتعالى (من أسما) بالقصر للوزن، أي: من أسمائه الحسنى فهي (قديمة) ألية (لها المقام الأسمى) أي: الأعلى (وهي) أي: أسماء الله تعالى (لنا تدرى) بالبناء للمفعول، أي: تعلم فنعلمها (بالاستقراء) أي: التتبع (من طرق) جمع طريق (التوقيف) أي: الورود من الشارع في الكتاب أو السنة (لا) بمجرد (الآراء) جمع رأي، وهو: الاستحسان العقلي.\rقال السنوسي في شرح الجزائرية: إطلاق اسم عليه تعالى من الأسماء توقيفي أي يتوقف على الإذن الشرعي في إطلاقه، فلا يجوز أن يسمى جل وعلا إلا بما سمى به نفسه أو سماه به رسوله صلى الله عليه وسلم أو انعقد على التسمية فيه إجماع، واختلف هل يكتفي في جواز الإطلاق وثبوت التسمية بخبر الآحاد على قولين.\rواختلف فيما لم يرد فيه إذن ولا منع فقيل: فيه بالوقوف. وقيل: بالمنع، وعزاه ابن رشد للشيخ الأشعري ومالك.\rوقال الباقلاني: يجوز أن يسمى بكل ما يرجع إلى ما يجوز في صفته كسيد وحنان ما لم يجتمع على منع ما لا يجوز مثل عاقل وفقيه وسخي، وكره مالك التسمية بسيد وحنان، وأما ما لا يجوز في أصله فلا يسمى به وإن كان تعالى وصف نفسه بالفعل المشتق منه ذلك الاسم نحو (الله يستهزئ بهم ويمدهم - وسخر الله منهم) لأن ما يستحيل عليه تعالى لا يجري عليه منه إلا قدر ما أطلقه السمع عليه ما اعتقاد أنه ما يجب كونه عليه.\rوقال السعد في شرح العقائد: فإن قيل: كيف يصح إطلاق الموجود والواجب والقديم ونحو ذلك مما لم يرد به إذن الشرع؟ قلنا: بالإجماع وهو من الأدلة الشرعية."], [145, "ويطلق الشيء على الموجود لا غيره في المذهب المحمود\rومالك وأهل الاجتهاد كل إلى نهج الصواب هادي\r[الشرح]\rوفي شرح الجزائرية للسنوسي في الفرق بين الاسم والصفة: أن الاسم ما دل على ذاته تعالى سواء دل مع ذلك على صفة تقوم به كالعالم والقادر، أو على فعل من أفعاله كالخالق والرازق، أو لم يدل على زائد على الذات ككلمة الله، والصفة ما دل على معنى يقوم بذاته العلية فقط من غير أن يدل بلفظه على الذات كعلمه تعالى وقدرته وذاته وحياته فكما لا تسميه تعالى بفقيه ولبيب وعاقل لعدم الإذن في ذلك كذلك لا يجوز أن نقول له فقه ولب وعقل.\r(ويطلق) لفظ (الشيء على الموجود) فقط (لا) على (غيره) أي: المعدوم فلا يسمى المعدوم شيئا (في المذهب المحمود) أي: مذهب أهل السنة والجماعة والمراد المعدوم الممكن لا المعدوم الممتنع المستحيل لا سيما شيئا بالاتفاق.\rوقالت الأشاعرة: يطلق الشيء حقيقة على الموجود فقط فكل شيء عندهم موجود وكل موجود شيء. وقالت معتزلة البصرة والجاحظ: الشيء هو المعلوم موجودا كان أو معدوما وما ممكنا ويلزمهم إطلاق الشيء على مستحيل لأنه معلوم.\rوقال السعد في قول صاحب العقائد: والمعدوم ليس هي إن أريد الشيء الثابت المتحقق على ما ذهب إليه المحققون من أن الشيئية ترادف الوجود والثبوت، والعدم يرادف النفي، فهذا حكم ضروري لا ينازع فيه أحد إلا المعتزلة القائلون بأن المعدوم الممكن ثابت في الخارج، وإن أريد أن المعدوم لا يسمى شيئا فهو بحث لغوي سبني على تفسير الشيء أنه الموجود أوو المعدوم أو ما يصح أن يعلم ويخبر عنه فالمرجع إلى النقل وتتبع موارد الاستعمال.\r(و) الإمام (مالك) بن أنس بن مالك بن أبي عامر بن عمرو بن الحارث بن غيهان - بالغين المعجمة والياء التحتية - ابن خثيل بالخاء المعجمة المضمومة وفتح الثاء المثلثة - ابن عمرو بن الحارث وهو ذو أصبح الأصبحي المدني إمام دار الهجرة أحد أئمة المذاهب الأربعة المتبوعة الآن وهو من تابعي التابعين، وكنيته أبو عبد الله مات وهو ابن تسعين سنة، وقال بعضهم: كان ابن خمس وثمانين سنة، وكانت وفاته في صبح أربعة عشر من شهر ربيع الأول سنة تسع وسبعين ومائة، وصلى عليه عبد الله بن محمد بن إبراهيم بن علي بن عبد الله بن عباس رضي الله عنهما وهو يومئذ والي المدينة ودفن بالبقيع وقبره بباب البقيع عليه قبة، وإنما قدم ذكره الناظم - رحمه الله تعالى - لأنه إمام مذهبه."], [146, "كالشافعي وأبي حنيفه وأحمد ذي الرتبة المنيفه\r[الشرح]\r(وأهل الاجتهاد) من بقية المجتهدين الذين قبله وبعده رضي الله عنهم (كل) أي: كل واحد منهم (إلى نهج) أي: طريق (الصواب) أي: الحق من الدين المحمدي (هادي) أي: مرشد ودال على ذلك (كالشافعي) بيان لأهل الاجتهاد، وهو الإمام محمد بن إدريس بن العباس بن عثمان بن شافع بن سائب بن عبيد بن عبد يزيد بن هاشم بن المطلب بن عبد مناف بن قصي، القرشي المطلبي الشافعي الحجازي المكي، ابن عم رسول الله صلى الله عليه وسلم يلتقي معه في عبد مناف.\rولد سنة خمسين وهي السنة التي توفي فيها الغمام أبو حنيفة رضي الله عنه، وقيل في اليوم الذي توفي أبو حنيفة، قال البيهقي: ولم يثبت اليوم، وتوفي الإمام الشافعي - رحمه الله تعالى - بمصر سنة أربع ومائتين وهو ابن أربع وخمسين سنة (و) الإمام (أبي حنيفة) بسكون الهاء للوزن وهو النعمان بن ثابت بن زوطى بضم الزاي وفتح الطاء المهملة، ولد سنة ثمانين من الهجرة في عهد الصحابة رضي الله عنهم فهو تابعي، وتوفي سنة خمسين ومائة من الهجرة ودفن بالجانب الشرقي من بغداد في مقبرة الخيزران وقبره هناك ظاهر معروف.\r(و) الإمام (أحمد) بن حنبل وهو: أحمد بن محمد بن حنبل بن هلال بن أسد بن إدريس بن عبد الله بن حبان - بالممثناة التحتية - ابن عبد الله بن أنس بن عوف بن قاسط ابن مازن بن شيبان بن ذهل بن ثعلبة بن عكاية بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب - بكسر الهاء وسكون النون وبعدها موحدة - ابن أفصى - بالفاء والصاد المهملة - ابن دعمة بن جديلة بن أسد بن ربيعة بن نزار بن معد بن عدنان الشيباني المروزي، ثم البغدادي أبو عبد الله.\rولد في شهر ربيع الأول سنة أربع وستين ومائة وتوفي في ضحوة الجمعة الثاني عشر من شهر ربيع الأول سنة إحدى وأربعين ومائتين ودفن ببغداد وقبره مشهور معروف. وتراجم هؤلاء الأئمة الأربعة استوفيناها في كتابنا ((أزهار الحديقة في ذكر رجال الطريقة))، وفي كتابنا ((المطالب الوفية)) وغير ذلك.\r(ذي) أي: صاحب (الرتبة) في الدين المحمدي (المنيفه) بسكون الهاء، أي: المرتفعة العالية، من ناف الشيء ينوف، إذا طال وارتفع."], [147, "وكلهم على هدى من ربهم وفرقة الجنيد دن بحبهم\r[الشرح]\r(وكلهم) أي: هؤلاء الأئمة رضي الله عنهم ثابتون (على هدى) أي: هداية (من ربهم) سبحانه وتعالى. قال الشيخ تاج الدين السبكي - رحمه الله تعالى - في الطبقات الكبرى: ينبغي لك أيها المسترشد أن تسلك سبيل الأدب مع جميع الأئمة الماضين وأن لا تنظر إلى كلام بعض الناس فيهم إلا ببرهان واضح، ثم إن قدرت على التأويل وتحسين الظن بحسب قدرتك فافعل وإلا فاضرب صفحا عما ترى بينهم فإنك لم تخلق لمثل هذا وإنما خلقت للاشتغال بما يعنيك من أمر دينك، قال: ولا يزال عندي الطالب نبيلا حتى يخوض فيما جرى بين الأئمة فتلحقه الكآبة وظلمة الوجه، فإياك ثم إياك أن تصغي لما وقع بين أبي حنيفة وسفيان الثوري رضي الله عنهما، أو بين مالك وابن أبي ذؤيب، أو بين أحمد بن صالح والشعبي، وبين أحمد بن حنبل والحارث المحاسبي، وهلم جرا إلى زمان الشيخ عز الدين بن عبد السلام، والشيخ تقي الدين بن الصلاح فإنك إن فعلت ذلك حق عليك الهلاك، فإن القوم أئمة أعلام ولأقوالهم محامل ربما لم يفهمها غيرهم فليس لنا إلا الترضي عنهم والسكوت عما جرى بينهم كما نفعل فيما جرى بين الصحابة رضي الله عنهم أجمعين.\rقال: وكان الشيخ عز الدين بن عبد السلام يقول: إذا بلغك أن أحدا من الأئمة شدد النكير على أحد من أقرانه فإنما ذلك خوفا على أن أحدهم يفهم من كلامه خلاف مراده لا سيما علم العقائد فإن الكلام في ذلك أشد، وقد اختفى أحمد بن حنبل في دار إسماعيل بن إسحاق السراج، وكان الحارث المحاسبي ينام عنده هو واصحابه فلما صلوا العشاء تذاكروا في طريق القوم فبكوا وبكى أحمد معهم، فلما أصبح قالك ما رأيت مثل هؤلاء القوم ولا سمعت في علوم الحقائق شيئا يشبه كلام هذا الرجل ومع هذا فلا اراك يا إسماعيل صحبتهم خوفا عليك ان تفهم منهم غير مرادهم.\r(وفرقة) بكسر الفاء، أي: طائفة الإمام أبو القاسم (الجنيد) بن محمد بن الجنيد النهاوندي الخزاز، ويقال له: القواريري لأن أباه كان يبيع الزجاج البغدادي. أصله من نهاوند وولد ببغداد ونشأ بها، وكان سيد الطائفة الصوفية وإمامهم وكان فقيها على مذهب أبي ثور وكان يفتي في حلقة أبي ثور وعمره إذ ذاك عشرون سنة، مولده بعد العشرين ومائتين أوو قبلها، مات في شوال سنة ثمانية وتسعين ومائتين ودفن إلى جانب"], [148, "فإنهم طريقهم مرضيه قويمة لأهلها المزيه\rوجاحد المعلوم بالضروره جاء بكفر وانتحا غروره\rوقتله للكفر لا للحد وذلك الجزاء للمرتد\r[الشرح]\rخاله السري السقطي (دن) بكسر الدال المهملة وسكون النون، أمر من الدين بكسر الدال وهو الإسلام وقد دنته بكسر الدال أيضا ودنت به كذا في القاموس. (بحبهم) أي: اجعل حبهم دينا لك تعد الله تعالى به.\r(فإنهم) أي: فرقة الجنيد البغدادي رضي الله عنهم وهم جميع الطائفة الصوفية في زماننا هذا (طريقهم) من حيث ما هي مبنية عليه (مرضية) بسكون الهاء للوزن، أي: عند الله تعالى وعند رسوله صلى الله عليه وسلم وعند أئمة المسلمين وعامتهم (قويمة) أي: مستقيمة لا اعوجاج فيها (لأهلها) أي: للسالكين عليها إلى يوم القيامة (المزيه) بسكون الهاء أي: المرتبة العالية على جميع الناس لأنها مشتملة على العلم والعمل ومكارم الأخلاق فأهلها الذين هم أهلها شاركوا جميع أنواع الناس فيما هم فيه وزادوا عليهم بما ليس عندهم من العلوم والمعارف وحسن الأحوال الباطنية والظهرية والمتعلقون بهم من الأتباع الذين يتشبهون بهم على قدر استطاعتهم ومقدار جهدهم عل خير كثير، وقال العارف بالله تعالى السهروردي:\rفتشهبوا إن لم تكونوا مثلهم إن التشبه بالكرام فلاح\r(وجاحد) أي: منكر الأمر (المعلوم) من دين نبينا محمد صلى الله عليه وسلم (بالضروره) بسكون الهاء للوزن وهو ما يشترك في معرفته العام والخاص من المكلفين مثل كون الصلاة فرضا والربا حراما ونحو ذلك (جاء) أي: جاحد ذلك (بكفر) أي: يصير كافرا بالله تعالى (وانتحا) يقال: نحاه ينحوه وينحاه، قصده كانتحاه كذا في القاموس. (غروره) بسكون الهاء (وقتله للكفر) أي: لأجل الكفر (لا للحد) أي: فيموت كافرا، فإن تاب من جحوده ذلك قبلت توبته وعاد مسلما ولو كان قتله حدا لما منعت توبته من قتله وكان يقتل ولو عاد إلى الإسلام كالكافر بسلب نبي من الأنبياء - عليهم السلام - أو سب أحد الشيخين.\rوقال في الأشباه والنظائر لابن نجيم الحنفي - رحمه الله تعالى -: كل كافر تاب فتوبته مقبولة في الدنيا والآخرة إلا جماعة قالوا: إلا الكافر بسب نبي أو بسب الشيخين أو أحدهما وبالسحر ولو امرأة وبالزندقة إذا أخذ قبل توبته، وكل مسلم ارتد فإنه يقتل إلا المرأة ومن كان إسلامه تبعا والصبي إذا أسلم والمكره على الإسلام ومن ثبت إسلامه"], [149, ".............................................\r[الشرح]\rبشهادة رجل وامرأتين، ومن ثبت إسلامه برجلين ثم رجع، ولا تصح ردة السكران إلا بالرد بسب النبي صلى الله عليه وسلم فإنه يقتل ولا يعفى عنه كذا في البزازية، وحكم الردة وجوب القتل إن لم يرجع، وحبطت أعماله مطلقا لكن إذا أسلم لا يقضيها إلا الحج كالكافر الأصلي إذا أسلم، ويبطل ما رواه لغيره من الحديث فلا يجوز للسامع منه أن يرويه عنه بعد ردته وبينونة امرأته مطلقا وبطلان وقفه مطلقا، وإذا مات أو قتل على ردته لم يدفن في مقابر أهل ملته وإنما يلقى في حفيرة كالكلب، والمرتد أقبح كفرا من الأصلي، والإيمان تصديق محمد صلى الله عليه وسلم في كل ما جاء به من الدين ضرورة، والكفر تكذيب محمد صلى الله عليه وسلم في شيء مما جاء به من الدين ضرورة، ولا يكفر أحد من أهل القبلة إلا بجحود ما أدخله فيه.\rوحاصل ما ذكره أصحابنا في الفتاوى من ألفاظ التكفير يرجع إلى ذلك وفيه بعض اختلاف لكن لا يفتى بما فيه خلاف. وفي الفتاوى الصغرى: الكفر شيء عظيم فلا أعل المؤمن كافرا متى وجدت رواية أنه لا يكفر. وفي خلاصة الفتاوى: الكفر شيء عظيم فلا أجعل المؤمن كافرا متى وجدت رواية أنه يكفر. وفي خلاصة الفتاوى: إذا كان في المألة وجوه توجب التكفير ووجه واحد يمنعه فعلى المفتي أن يميل إلى ذلك الوجه. وقوله: فعلى المفتي ظاهره وجوب ذلك عليه ومثله الأفعال المقتضية للكفر على ما يظهر. قال في شرح الدرر بعد ذكره نحو ذلك لأن الترجيح لا يقع بكثرة الأدلة والاحتمال أنه أراد الوجه الذي لا يوجب إلا كفار.\rوقال والدنا المرحوم في شرحه على الدرر: بل يقع الترجيح بقوة الدليل وحيث طرق تلك الأدلة احتمال ضعفت. وفي تنوير البصائر: ولا يفتى بتكفير مسلم أمكن حمل كلامه على محمل حسن أو كان في كفره خلاف ولو في رواية ضعيفة.\rوفي البحر الرائق شرح كنز الدقائق: وعلى ها فأكثر ألفاظ التكفير المذكورة لا يفتى بالتكفير بها ولقد ألزمت نفسي أن لا أفتي بشيء منها. انتهى\rقلت: فإن كان الكفر بسب نبي أو إحدى الشيخين كما مر فحكمه كذلك لإطلاقهم ما ذكر حتى لو أسلم وقلت بأنه يقتل حدا واحتمل شبهة فكذلك الحكم لأن الحدود تدرأ بالشبهات على ما هو المعروف في محله.\rوفي شرح الدرر وغيره من كتب المذهب من الحدود في حد الزنا أنه يبدأ به شهوده، فإن أبوا أو غابوا أو ماتوا سقط الحد. انتهى"], [150, "..........................................\r[الشرح]\rوإنما يسقط الحد للشبهة باحتمال رجوعهم عن الشهادة والله أعلم، ويحتاط في الأديان كما يحتاد في الأعرض، والمسألة إذا كان فيها اختلاف بين الأئمة من أهل السنة في مذهب واحد أو المذاهب الأربعة المقررة الآن لا يفتى بها في التكفير ولو رواية ضعيفة لاحتمال الخطأ في التقليد كما أشار في البحر شرح الكنز من الطهارة إلى مسألة ما لو صلى عمدا في ثوب كله نجس وهو قادر على ستر عورته بثوب طاهر أنه لا يكفر لأن غسل النجاسة عند مالك - رحمه الله تعالى - في رواية سنة، وإن كانت رواية ضعيفة.\rفإن قلت: تصريحهم بقتله وعدم قبول توبته يأبى ما ذكر. قلت: ذلك مبني عندهم على تحقق ذلك منه، ومع الاحتمال والاشتباه لا تحقق إلا إذا أصر على ذلك ونفى الاحتمال والاشتباه عنه حتى قال في الأشباه والنظائر من كتب الحنفية: إن إنكار الردة توبة فإن شهدوا على مسلم بالردة وهو منكر لا يعرض له لا لتكذيب الشهود العدول بل لأن إنكاره توبة ورجوع كذا في فتح القدير.\rفإن قلت: قد قال قبله وتقبل الشهادة بالردة من عدلين فما فائدته. قلت: ثبوت ردته بالشهادة وإنكارها توبة. انتهى ولا يخفى أن هذا في ردة تقبل التوبة منها. وأما الردة إذا قبلت التوبة منها بالإنكار يقتل لها حدا كسب النبي أو أحد الشيخين فلا يدرأ الحد عنه بالإنكار، وإن لم يثبت له بعد قتله أحكام المرتدين بل أحكام المسلمين المحدودين بالقتل، لكن إذا وجد الخلاف في ذلك بين الأئمة أوو احتمل شبهة لا يفتي بالتكفير بذلك وإذا لم يتحقق التكفير به فلا حد.\rوالحاصل: أن احتمال التأويل في القول أو الفعل معتبر في حق من لم يتحقق منه أن يدين بذلك من الرافضة المعروفين بأعيانهم والمشهورين بالاستخفاف والاستهزاء والطعن في أحد الأنبياء أو الشيخين، وأما فمن هذا شأنهم فلا احتمال تأويل لهم، أو كان القتل لهم على وجه السياسة العادلة حتى ينزجر الناس عن أمثال هذه القبائح الشنيعة في الدين فيكون الاحتياط في تعظيم مذهب أهل السنة أولى وأحق من الاحتياط في دمائهم كما تكرر وقوع ذلك في بلادنا دمشق الشام، وأقيم عليهم الحد بالقتل قصدا لما ذكرنا.\rوإنما أطلنا الكلام في هذا المبحث لأنا لم نجد من حققه من علمائنا وغيرهم، والله الموفق لا رب غيره، ولا خير إلا خيره."], [151, "كذا من استحل نحو الخمر من ما امتناعه شهير الأمر\rوالنص إن أوهم غير اللائق بالله كالتشبيه للخلائق\rفاصرفه إن أوهم غير اللائق واقطع عن الممتنع الأطماعا\rوما له من ذاك تأويل فقط تعين الحمل عليه وانضبط\rكمثل \"وهو معكم\" فأول بالعلم والرعي ولا تطول\r[الشرح]\r(وذلك) أي: القتل هو (الجزاء) في الشرع بالإجماع (للمرتد) عن دين الإسلام (كذا من استحل) أي: اعتقد الحل وجحد الحرمة القطعية العينية في (نحو) شرب (الخمر) كقتل النفس المعصومة والزنا واللواط (مما) أي: من كل محرم (امتناعه) أي: المنع (شهير) أي: مشهور (الأمر) حيث أجمع على حرمته فاشتهر بالحرمة بين الخاص والعام من المسلمين، ولا بد أن تكون حرمته عينية كالمذكورات، بخلاف ما كانت حرمته لغيره لا لعينه كوطء الحائض فإنه لا يكفر مستحله وإن كانت حرمته قطعية، قال في تنوير الأبصار في حرمة وطء الحائض: ويكفر مستحله وقيل: لا وعليه المعول في شرح الدرر. ومن اعتقد الحرام حلالا أو بالعكس يكفر إن كان حراما لعينه، وإن كان حراما لغيره لا يكفر وإن اعتقده وكذا ذكر ذلك في الفتاوى البزازية.\r(والنص) الوارد في الكتاب أو السنة (إن أوهم) معناه (غير) الوصف (اللائق بالله) تعالى (كالتشبيه) أي: المشابهة (للخلائق) أي: المخلوقين كقوله تعالى: {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى} [طه: 5] وقوله تعالى: {وَجَاءَ رَبُّكَ} [الفجر: 22].\rوقوله صلى الله عليه وسلم: ((ينزل ربنا إلى سماء الدنيا - ضحك ربنا)). ونحو ذلك مما في الكتاب والسنة. (فاصرفه عن ظاهره) أي: لا تعتقد فيه معناه الظاهر لك كما لو وصفت نفسك به أو غيرك من المخلوقين (إجماعا) أي: هذا الصرف أجمع عليه كل الأئمة من أهل السنة فإن ظاهره عند العقل مستحيل على الله تعالى ممتنع في حقه (واقطع) أيها المكلف (عن) هذا الأمر (الممتنع) عقلا وشرعا (الأطماعا) جمع طمع والألف للإطلاق.\r(وما) أي: النص الذي (له من ذاك) أي: من جملة النصوص الموهمة غير اللائق به تعالى (تأويل) واحد (فقط تعين) عند العلماء (الحمل عليه وانضبط) إذ لا يحتمل غيره عند العقول فيتعين تأويله به (كمثل) قوله تعالى: (وهو معكم÷) أينما كنتم (فأول) أمر بالتأويل وهو تفسير اللفظ بأحد محتملاته اللائقة به (بالعلم) أي: بعلمه تعالى لا ينفك عن تعلقه بكم ولا يغفل عنكم كما قال تعالى: {وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ} [إبراهيم: 42]."], [152, "إذ لا تصح هاهنا المصاحبه بالذات فاعرف أوجه المناسبه\rوما له محامل الرأي اختلف فيه وبالتفويض قد قال السلف\rمن بعد تنزيه وهذا أسلم والله بالمراد منها أعلم\rلذاك قال مالك إذ سئلا في الاستوا الكيف منه جهلا\r[الشرح]\rوقال تعالى: {وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ} [البقرة: 74]. (والرعي) أي: الحفظ كما قال تعالى: {وَرَبُّكَ عَلَى كُلِّ شَيْءٍ حَفِيظٌ} [سبأ: 21].\rوهذه المعية الإلهية بهذا المعنى غير مختصة بنوع من المخلوقات بل هي متعلقة بالجميع ولكن النص عليها في حق البعض اعتناء بشأنهم وتنبيها لهم عليها حتى يجروا على مقتضاها في أعمالهم وأحوالهم فتحصل الخشية منه تعالى وتترك مهابته في قلوبهم (ولا تطول) بتشديد الواو وكسر اللام للقافية، أي: واقتصر على ذلك فإنه لا تأويل لها غير ذلك عن العقول لعدم احتمال معنى آخر عندها.\r(إذ) أي: لأنه (لا تصح هاهنا) في معنى المعية معنى (المصاحبه) بسكون الهاء للوزن (بالذات) العلية المنزهة عن مشابهة المخلوقين (فاعرف) يا أيها المكلف (أوجه) جمع وجه، أي: أنواع (المناسبه) بسكون الهاء في مثل ذلك ويصح أن يقول أوج أفعل تفضيل، أي: أكمل ما يكون من المناسبة أن أنسب ما يليق بذلك النص فأوله به.\r(وما) أي: النص الذي (له محامل) بالرفع على الابتداء ومنع الصرف أي: معاني متعددة (الرأي) العقلي (اختلف) بسكون الفاء (فيه) أي: في ذلك النص على أي محمل منها يحمله كما سيذكره من الاستواء والوجه إليه (وبالتفويض) أي: التسليم إلى الله وإلى رسوله صلى الله عليه وسلم في المعنى الذي يريده الله تعالى ويريده رسوله عليه الصلاة والسلام من غير حمل على أحد تلك المحامل أصلا (قد قال السلف) بسكون الفاء أي: الماضون من الصحابة والتابعين وتابع التابعين، رضوان الله عليهم أجمعين.\rوفي شرح مرقاة الوصول: هو مذهب عامة أهل السنة من مشايخ سمرقند، واختاره الإمامان فخر الإسلام وشمس الأئمة ومن تبعهما حتى حكموا بأن السؤال عنه بدعة.\r(من بعد تنزيه) أي: تبعيد وتقديس وتطهير لله تعالى عمن أراد المعنى الذي يقتضي مشاركته للمخلوقين في ذلك (وهذا) القول (أسلم) من خطر التأويل والحمل على المحامل العقلية (والله) سبحانه بالمراد منها) أي: من تلك النصوص (أعلم) دون غيره (لذاك) أي"], [153, "وصار للتأويل قوم عينوا مما يليق راجحا وبينوا\rإذ فسروا الوجه بذات واليدا بقدرة وذا الإمام أيدا\r[الشرح]\rلما ذكر (قال) الإمام (مالك) رضي الله عنه (إذ) أي: حين (سئلا) بالبناء للمفعول وبألف الإطلاق، أي: سأله سائل (في) حق (الاستواء) على العرش الوارد في شأن الله تعالى. فقال في جوابه: الاستواء معلوم يعني: معناه في اللغة (والكيف منه) أي: من الاستواء المعلوم يعني معنى ذلك حيث نسب إلى الله تعالى (جهلا) بالبناء للمفعول وبألف الإطلاق، أي: هو مجهول لا يعلم به العقل؛ لأنه وصف لله تعالى لائق به على حسب قدمه وبقائه وتنزهه عن صفات المخلوقين ولا يعلم بذلك إلا الله تعالى، وأصل ذلك أن الإمام مالك رضي الله عنه سئل مرة عن كيفية الاستواء على العرش، فقال بعد إطراق وتفكر: الكيف غير معقول والاستواء غير مجهول، والإيمان به واجب، والسؤال عنه بدعة، وأظنك صاحب بدعة، ثم أمر بالسائل فأخرج، وهذا نظير ما ذكره الشهاب السهروردي في كتابه ((رشف النصائح)) عن سليمان بن يسار، أن رجلا يقال له صبيغ قدم المدينة فجعل يسأل عن متشابه القرآن، فأرسل إليه عمر بن الخطاب رضي الله عنه وقد أعد له عرجون النخل، فقال: من أنت؟ فقال: أنا عبد الله صبيغ فأخذ عرجونا فضربه، وقال: أنا عبد الله عمر فجلده ضربا حتى دمى رأسه. فقال: يا أمير المؤمنين، حسبك فقد ذهب الذي كنت أجده في رأسي.\rوروى أبو عثمان النهدي قالك كتب إلينا عمر رضي الله عنه لا تجالسوا صبيغا فلو جاء المتأخرين وعامة المعتزلة (عينوا مما) أي: من المعنى الذي (يليق) بالله تعالى (على حسب ما ورد في قسم المحكم قولا (راجحا) عندهم أرجعوا ذلك المتشابه إلى معناه (وبينوا) وجه ذلك التأويل فيه.\r(إذ) أي: حين، أو لأنهم (فسروا الوجه) في قوله تعالى: {فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ} [البقرة: 115]. وقوله تعالى: {يُرِيدُونَ وَجْهَهُ} [الأنعام: 52]. وقوله تعالى: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88]. وقوله تعالى: {كُلُّ مَنْ عَلَيْهَا فَانٍ (26) وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ} [الرحمن: 26، 27]. وما ورد في السنة من ذلك (بذات) أي: ذات الله تعالى (و) فسروا (اليدا) بألف الإطلاق في قوله تعالى: {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75]"], [154, "وقوله سبحانه \"من في السما\" معناه بالأمر وسلطان سما\rوقس على هذا جميع ما اشتبه في الذكر والحديث وادر المرتبه\rوالذنب مقسوم إلى الكبيره كالقذف والقتل وللصغيره\r[الشرح]\rوقوله: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ} [الذاريات: 47]. وما ورد في السنة من ذلك (بقدرة) أي: بقدرة الله تعالى، وتثنيتها وجمعها باعتبار نوعي المخلوق الظاهر والباطن أو الأنواع الكثيرة. (وذا) أي: وهذا القول بالتأويل (الإمام) الأشعري (أيدا) بألف الإطلاق أي: نصره واختاره وإليه ميل إمام الحرمين في الإرشاد وإن صرح في الرسالة النظامية المتأخرة عنه باختيار التفويض والتسليم واختاره الشيخ عز الدين بن عبد السلام في بعض فتاواه طريق التأويل، وقال: هي أقرب للحق.\r(وقوله) أي: الله سبحانه وتعالى ((أأمنتم (من في السماء) بالقصر وحذف المد (معناه) أنه عز وجل في السماء بالأمر، أي: أمره نافذ في السماء (وسلطان) أ]: تسلط وقهر (سما) أي: علا وارتفع بالاستيلاء على أهل السماء لظهور ذلك عندهم وخفائه عن الغافلين عنه من أهل الأرض، وإلا فالسماء والأرض سواء في ذلك ومثلها كل شيء (وقس) يا أيها المكلف (على هذا) التأويل (جميع ما اشتبه) بسكون الهاء (في الذكر) أي: القرآن (و) في (الحديث) النبوي (وادر) من الدراية، وهي العلم أي: واعلم (المرتبه) بسكون الهاء، أي: مرتبة الإله الحق وأنه منزه عن مشابهة المخلوقين (والذنب) الذي يصير من المكلف (مقسوم إلى) قسمين:\rالأول: (الكبيره) بسكون الهاء، وهي: ما كان حراما محضا، وعن ابن عباس رضي الله عنهما: ((كل شيء نهى الله عنه فهو كبيرة)). وبهذا قال الأستاذ أبو إسحاق الإسفرايني، وحكاه القاضي عياض عن المحققين احتجاجا بأن كل مخالفة فهي بالنسبة إلى جلال الله تعالى كبيرة، وهذا قول من يذكر الصغائر وهو خلاف ما نفهم من مدارك الشرع، وروي عن ابن عباس رضي الله عنهما، أن الكبائر كل ذنب ختمه الله بنار أو غضب أو لعنة أو عذاب. ونحو هذا عن الحسن البصري.\rوقال آخرون: هي ما أوعد الله عليه بنار أو حد في الدنيا. وقال الإمام الغزالي في بسيطه: والضابط الشامل أن الكبيرة كل معصية يقدم عليها المرء من غير استشعار خوف وحذار ندم كالمتهاون بارتكابها والمستجرئ عليها اعتيادا فما أشعر بهذا الاستخفاف"], [155, "....................................\r[الشرح]\rوالتهاون فهو كبيرة، وما يحمل عليه فلتات اللسان وفترات مراقبة التقوى ولا ينفك عن تندم يمتزج به تنغيص التلذذ بالمعصية فهذا لا يمنع العدالة وليس هذا بكبيرة.\rوقال الشيخ أبو عمرو بن الصلاح في فتاواه الكبيرة: كل ذنب كبر وعظم عظما يصح معه أن يطلق عليه اسم الكبيرة أو وصف بكونه عظيما على الإطلاق.\rوقال أبو الحسن الواحدي: الصحيح أن حد الكبيرة غير معروف بل ورد الشرع بوصف أنواع من المعاصي بأنها كبائر وأنواع بأنها صغائر وأنواع لم توصف وهي مشتملة على كبائر وصغائر.\rوالحكمة في عدم بيانها أن يكون العبد ممتنعا من جميعها مخافة أن تكون من الكبائر، قال: وهذا شبيه بإخفاء ليلة القدر وساعة يوم الجمعة واسم الله الأعظم والولي في الناس.\r(كالقذف) للنساء المحصنات الغافلات (والقتل) للنفس التي حرمها الله تعالى بغير حق. وقال اللقاني - رحمه الله تعالى -: اختلفت الروايات في عدد الكبائر، فروى ابن عمر رضي الله عنهما أنها تسعة: الشرك بالله، وقتل النفس بغير حق، وقذف المحصنة، والزنا، والفرار من الزحف، والسحر، وأكل مال اليتيم، وعقوق الوالدين المسلمين، والإلحاد في الحرم. وزاد أبو هريرة رضي الله عنه: أكل الربا. وزاد علي رضي الله عنه في روايته: السرقة: وشرب الخمر.\rوفي رواية نفيع أبي بكرة رضي الله عنه: وشهادة الزور، وقول الزور. وقد زاد بعضهم أشياء كثيرة، وللشهاب ابن حجر - رحمه الله تعالى - كتاب حافل في ذلك سماه ((الزواجر في اقتراف الكبائر))، وأشار إلى القسم الثاني بقوله:\r(وللصغيره) بسكون الهاء، وهي ما لم تكن حراما محضا كالغمزة والقبلة والنظر بشهوة وشرب المسكر غير الخمر، وأكل الربا كذا في محيط السرخسي، والمراد أكل الربا مع العلم به لا نفس فعل كل الربا لأنه كبيرة كما تقدم، وقال اللقاني - رحمه الله تعالى -: والصغيرة لا تحصر أفرادها ومنها ما يتوهم كونه كبيرة وليس بها كقبلة أجنبية، ولعن ولو لبهيمة، وكذب على غير الأنبياء عليهم السلام بما لا حد فيه ولا ضرر وهجو مسلم ولو تعريضا أو صدقا، وإشراف على بيت غيره وهجر مسلم فوق ثلاثة أيام، ونوح وجلوس مع فاسق لا يناسبه ونجس، واحتكار مضر، وبيع معيب علم عيبه ولم يذكره."], [156, "وهي بالاجتناب للكبائر مغفورة من عالم السرائر\rفي الكتاب قال \"إن تجتنبوا\" والعفو منه يرتجيه المذنب\r[الشرح]\rوالأصح انقلاب الصغيرة كبيرة بخمسة أشياء: الإصرار عليها، والتهاون بها، والفرح بها، والافتخار بها، وصدورها من عالم فيعتد به فيها. انتهى\rوهذا الأخير محمول على قصد الاقتداء به فيها حتى لو لم يقصد الإمامة فيها لغيره فهي صغيرة أو قصد وجها آخر صالحا فلا إثم فيها أصلا، كما قالوا في هجر المسلم فوق ثلاث.\rقال الإمام النووي - رحمه الله تعالى - في شرح مسلم: يجوز هجر أهل البدع والفسق دائما، والنهي عن الهجران فوق الثلاثة أيام محله فيمن هجر لحظ نفسه ومعاش الدنيا.\rوقال الحافظ بن حجر: وقد أجمعوا على جواز الهجر فوق ثلاث لمن خاف من مكالمته ضررا في دينه أو دنياه، ورب هجر جميل خير من مخالطة مؤذية. وقال عمار: مصارمة جميلة أحب إلي من مودة على دغل.\rوفي شرح الجامع الصغير للمناوي قال: ومن المصلحة ما جاء من هجر لبعض السلف لبعض. فقد هجر سعد بن أبي وقاص عمار بن ياسر، وعثمان بن عفان هجر عبد الرحمن بن عوف ... هجر وهب بن منبه، والحسن بن سيرين إلى أن ماتوا، وهجر ابن المسيب أباه وكان زياتا فلم يكلمه إلى أن مات، وكان سفيان الثوري يتعلم من ابن أبي ليلى ثم هجره فمات ابن أبي ليلى فلم يشهد جنازته، وهجر أحمد بن حنبل عمه وأولاده لقبولهم جائزة السلطان.\r(وهي) أي: الصغيرة (بالاجتناب للكبائر) أي: التباعد عنها (مغفورة) من فيض فضل (عالم السرائر) وهو الله تعالى (ففي الكتاب) أي: القرآن (قال) الله تعالى (إن تجتنبوا) كبائر ما تنهون عنه نكفر عنكم سيئاتكم (والعفو) أي: المسامحة (منه) سبحانه (يرتجيه المذنب) وملخص ما يقال في ذلك الاجتناب، أن المكلف إذا اجتنب الكبائر ووقع في الصغائر يجوز أن الله تعالى يعاقبه على الصغيرة عندنا كما ذكره السعد في شرح العقائد مستدلا عليه بدخول الصغيرة تحت قوله: {وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ} [النساء: 48]."], [157, "والله لا يغفر أن يشرك به ويغفر الدونا إذا شا فانتبه\r[الشرح]\rولقوله تعالى: {لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّا أَحْصَاهَا} [الكهف: 49]. والإحصاء إنما يكون للسؤال والمجازاة، إلى غير ذلك من الآيات والأحاديث. انتهى\rفعلم من هذا أن اجتناب الكبائر بمجرده لا يوجب تكفير الصغائر بل لا بد من أعمال البر اللازمة من الاجتناب المذكور، فإن من صلى وصام وزكى وحج وفعل أنواع العبادات فهو المجتنب للكبائر إذا ترك هذه الأعمال المفروضة من الكبائر، فيلزم من اجتناب الكبائر عمل الطاعات المكفرة للصغائر فأقيم اللازم مقام الملزوم وأسند إليه التكفير، وقد ورد في الحديث عن النبي صلى الله عليه وسلم أنه قال: ((الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفرات لما بينهن إذا اجتنبت الكبائر)).\rوقال تعالى: {إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ} [هود: 114]. المراد الصغائر لإجماعهم على أن الكبائر لا بد لها من توبة فحينئذ تكفير هذه العبادة الصغائر مشروط باجتناب الكبائر، كما أن تكفير اجتناب الكبائر الصغائر مشروط بعمل هذه العبادات الاجتناب والعمل كلاهما معا هما المكفران للصغائر من غير توبة سواء نسب التكفير إلى الاجتناب وحده وأضمر شرطه الذي هو العمل أو عكس الأمر في ذلك، والآية جارية على الأول وقد بسطناه في كتابنا ((المطالب الوفية)).\r(والله) سبحانه وتعالى (لا يغفر أن يشرك به) بسكون الهاء للوزن (ويغفر الدونا) أي: غير الشرك من جميع الذنوب الكبائر والصغائر (إذا شا) يحذف المد للوزن (فانتبه) بسكون الهاء أمر من الانتباه والمراد من غير توبة إذ بالتوبة يغفر حتى الشرك فإن توبة المشرك هي التوحيد والإسلام قال تعالى: {قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ} [الأنفال: 38]- حينئذ - {مَا قَدْ سَلَفَ} [الأنفال: 38]. أي: ينتهوا عن كفرهم وشكرهم فيغفر لهم حينئذ ما سلف منهم من ذلك.\rوقال اللقاني - رحمه الله تعالى -: من ارتكب كبيرة غير مكفرة بلا استحلال وهو مؤمن ومات بلا توبة فقد اختلف الناس في حكمه. قال أهل السنة: لا يقطع له بالعفو ولا بالعقاب بل هو في مشيئة الله تعالى، على تقدير وقوع العقاب عدلا منه تعالى يقطع له بعدم الخلود في النار بل يخرج منها ألبتة لا بطريق الوجوب على الله تعالى، بل"], [158, "وجاءنا عن مانح العطايا تكفير حج البيت للخطايا\rكذلك العمرة والقيام والطهر والصلاة والصيام\r[الشرح]\rوقالت المعتزلة: يقطع له بالعذاب الدائم والبقاء المخلد في النار لكنه يعذب فيها عذاب الفساق لا عذاب الكفار بناء على مذهبهم بأن الكبيرة تخرج العبد من الإيمان ولا تدخله في الكفر ذهابا إلى أن الأعمال عندهم جزاء من حقيقة الإيمان وتمامه هناك.\r(وجاءنا) في الأحاديث النبوية الخبر (عن مانح العطايا) جمع عطية، وهو: الله تعالى فياض الكرم والإحسانات (تكفير حج البيت) أي: بيت الله الحرام على الوجه المشروع فرضا أو نفلا (للخطايا) أي: الذنوب.\rأخرج البخاري، ومسلم، والنسائي، وابن ماجه، عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((من حج هذا البيت فلم يرفث ولم يفسق رجع كيوم ولدته أمه)).\rوأخرجه الترمذي عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((من حج فلم يرفث ولم يفسق غفر له ما تقدم من ذنبه)).\r(كذلك) أي: كحج البيت في تكفير الخطايا (العمرة) وهي الإحرام والطواف والسعي بين الصفا والمروة.\rأخرج البخاري، ومسلم، والترمذي، والنسائي، وابن ماجه، عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال: ((العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة)). وأخرج الترمذي، والنسائي، عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((تابعوا بين الحج والعمرة فإنهما ينفيان الفقر والذنوب كما ينفي الكير الخبث الحديد، والذهب والفضة، وليس للحجة المبرورة ثواب إلا الجنة)).\r(والقيام) أي: قيام الليل في شهر رمضان وغيره، أخرج البخاري، ومسلم، والنسائي، عن أبي هريرة رضي الله عنه، عن رسول الله صلى الله عليه وسلم أنه قالك سمعت رسول الله صلى الله عليه وسلم يقول لرمضان: ((من قامه إيمانا واحتسابا غفر له ما تقدم من ذنبه))."], [159, "وغيرها وهو على الخصوص يحمل للتوفيق للنصوص\r[الشرح]\rوأخرج النسائي، عن عبد الرحمن بن عوف رضي الله عنه، عن رسول الله صلى الله عليه وسلم أنه قال: ((من قام رمضان إيمانا واحتسابا خرج من ذنوبه كيوم ولدته أمه)).\r(والطهر) أي: الطهارة، أخرج مسلم، والترمذي، عن أبي هريرة رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال: ((ألا أدلكم على ما يمحوا الله به الخطايا ويرفع به الدرجات)). قالوا: بلى يا رسول الله، قال: ((إسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد، وانتظار الصلاة بعد الصلاة فذلكم الرباط)).\rوأخرج الترمذي، عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: (إذا توضأ العبد المسلم فغسل وجهه خرجت من وجهه كل خطيئة نظر إليها بعينه مع الماء، أو مع آخر قطرة الماء، أو نحو هذا فإذا غسل يديه خرجت من يديه كل خطيئة بطشتها يداه مع الماء أو مع آخر قطرة الماء، حتى يخرج نقيا من الذنوب)).\r(والصلاة) المفروضة وغيرها. أخرج أبو داود، عن زيد بن خالد الجهني صلى الله عليه وسلم، أن النبي صلى الله عليه وسلم قال: ((من توضأ فأحسن وضوءه ثم صلى ركعتين لا يسهو فيهما غفر له ما تقدم من ذنبه)).\rوعن عبادة بن الصامت رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: ((خمس صلوات افترضهن الله عز وجل من أحسن وضوءهن وصلاهن لوقتهن وأتم ركوعهن وخشوعهن كان له على الله عهدا أن يغفر له ومن لم يفعل فليس له على الله عهدا إن شاء غفر له وإن شاء عذبه)).\r(والصيام) المفروض وغيره، وأخرج مسلم من حديث أبي قتادة الحارث بن ربعي رضي الله عنه، أن رسول الله صلى الله عليه وسلم سئل عن صوم يوم عرفة؟ قال: ((يكفر السنة المضية)). ونحو هذا كثير في الأحاديث والأخبار.\r(وغيرها) أي: غير ما ذكر من أنواع العبادات التي يكفر الله تعالى بها الصغائر من الذنوب (وهو) أي: هذا الوارد من التكفير فيما ذكر (على الخصوص يحمل) بالبناء للمفعول، أي: خصوص المكفرات والأول مشتمل على الغفران ما عدا الشرك محمول على العموم في حق من عمل شيئا من ذلك أو لم يعلمه. ((للتوفيق) أي: لأجل التوفيق.\r(للنصوص) أي: بين النصوص المختلفة، فقد خصص الشارع مرة التكفير بالأعمال وعمم مرة أخرى فلا تناقض في النصوص الشرعية."], [160, "وذو كبيرة عليه التوبه فرض بنور واجتناب الحوبه\rوفي قبولها لغير الكافر قطعا وظنا وجه خلف سافر\r[الشرح]\r(وذو) أي: صاحب (كبيرة) من الذنوب (عليه التوبة) بسكون الهاء للوزن من تلك الكبيرة (فرض بنور) على الغفران من غير تأخر (واجتناب) أي: التباعد من الحوبة (الحوبة) بسكون الهاء أي: الذنب والمعصية، قال الله تعالى: {وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ} [النور: 31].\rقال اللقاني - رحمه الله تعالى -: قضية كلام المازني والقاضي عياض، والنووي وغيرهم أن وجوبها على الفور متفق عليه، بل مجمع عليه ولا يجوز تأخيرها سواء كانت المعصية صغيرة أو كبيرة. وللتوبة ثلاثة شروط: أي يقلع عن المعصية وأن يندم على فعلها، وأن يعزم عزما جازما أن لا يعود إلى مثلها أبدا، فإن كانت المعصية تتعلق بآدمي فلها شرط رابع وهو رد الظلامة إلى صاحبها أو تحصيل البراءة منه وهذا الشرط الرابع ورد المظالم والخروج عنها برد المال والإبراء منه أو الاعتذار إلى المغتاب واسترضاؤه إن بلغته الغيبة فواجب عندنا في نفسه لا مدخل له في الندم على ذنب آخر كما قاله إمام الحرمين في الشامل وهو مذهب الجمهور.\rوقال الآدمي: إذا أتى مظلمة كالقتل والضرب مثلا فقد وجب عليه أمران التوبة والخروج من المظلمة بتسليم نفسه مع الإمكان ليقتص منه ومن أتى بأحد الواجبين لم تكن صحة ما أتى به متوقفة على الإتيان بالواجب الآخر كما لو وجب عليه صلاتان فأتى بأحدهما صح دون الآخر، نعم إذا أراد أن يتوب من تلك الظلامة نفسها فلا بد من ردها أو التحليل ممن هي له إن وجد فيه شروط التحليل وأمن عند طلب ذلك مما هو أعظم من المعصية التي ارتكبها.\r(وفي قبولها) أي: التوبة (لغير الكافر) بالله تعالى أي: غير التوبة من الكفر (قطعا) أي: على وجه القطع بالقبول والتحقيق له (وظنا) أي: على وجه الظن لقبولها من غير تحقق له (وجه) مبتدأ خبره قوله في قبولها (خلف) أي: اختلاف بين العلماء (سافر) أي: مكشوف نعت للخلف، أو يقرأ قوله الكافر بسكون الراء وسافر أيضا بسكون الراء فيكون نعتا للوجه لأنه يقال وجه سافر، أي: مسفر بمعنى منكشف، من أسفر الصباح إذا أضاء."], [161, "والكافرون القول فيهم ما اختلف لقوله يغفر لهم ما قد سلف\rوالنفس والعقل كذا المال وجب صون لها والعرض أيضا والنسب\rوالرزق ما به انتفاع مطلقا هذا الذي قد قاله من حققا\r[الشرح]\r(والكافرون) التائبون من كفرهم (القول فيهم ما اختلف) بسكون الفاء بين العلماء بأن توبتهم من الكفر مقطوع بقبولها عند الله تعالى (لقوله) سبحانه: {قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ} [الأنفال: 38]. بسكون الفاء.\rقال اللقاني - رحمه الله تعالى -: قال أهل الحق من أهل السنة لا يجب على الله تعالى قبول توبة التائب بل لا يجب عليه شيء مطلقا كما مر، وهل يجب قبولها سمعا ووعدا؟ فقال إمام الحرمين: نعم لكن بدليل ظني إذا لم يثبت في ذلك نص قاطع لا يحتمل التأويل.\rوقال الأشعري بدليل قطعي، وعبارة النووي ولا يجب على الله قبولها إذا وجدت بشروطها عند أهل السنة لكنه سبحانه وتعالى يقبلها كرما منه وفضلا، وعرفنا قبولها بالشرع والإجماع، ومحل النزاع فيما عدا توبة الكافر، أما توبته فالإجماع على قبولها قطعا بالسمع لوجود النص المتواتر بذلك قال الله تعالى: {قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ} [الأنفال: 38]. بخلاف الآثار والأحاديث الواردة في توبة غيره فإنها ظاهرة وليست نصا في غفران ذنوب المسلم بالتوبة إذا تاب.\r(والنفس) أي: نفس كل إنسان (والعقل) أي: من كل إنسان (كذا المال) الذي لكل إنسان (وجل) بسكون الباء الموحدة، أي: افترض على كل إنسان والمراد المكلف (صون) أي: حفظ (لها) أي: لهذه الثلاثة المذكورة (والعرض) بكسر العين المهملة، وهو: موضع المدح والذم من الإنسان، وبعضهم ذكر الدين موضع العرض وعليه فهي ست (أيضا) أي: كذلك (والنسب) بسكون الباء للوزن.\rوقال اللقاني - رحمه الله تعالى -: وهي متفق على تحريمها فما أباح الله تعالى العرض بالقذف والسباب قط ولا أباح الأموال بالسرقة والغصب ولا لإنسان بإباحة الزنا، ولا العقول بإباحة المفسدات لها، ولا النفوس والأعضاء بإباحة القتل، والقطع، ولا الأديان بإباحة الكفر وانتهاك حرم المحرمات.\r(والرزق ما) أي: شيء (به انتفاع) للإنسان أو الحيوان بالأكل وغيره (مطلقا) حلالا كان أو حراما أو شبهه (هذا) القول هو (الذي قد قاله من حققا) وهم أئمة أهل السنة (وليس مقصورا على الحلال) أي: مخصوصا بالحلال من ذلك (ووجه باد) أي:"], [162, "والنصب للإمام بالشروط فرض بشرع بالهدى منوط\r[الشرح]\rظاهر واضح (بالاستدلال) عليه. قال إمام الحرمين في الإرشاد: الرزق يتعلق بمرزوق تعلق النعمة بمنعم عليه. والذي صح عندنا في معنى الرزق أن كل ما انتفع به منتفع فهو رزقه، ولا فرق بين أن يكون متعديا بانتفاعه وبين أن لا يكون متعديا به. ثم إن الرزق ينقسم إلى المحظور والمباح وإلا فإن من اغتدى بالحرام طول عمره وانصرفت انتفاعاته إلى الجهات المحظورة من كل وجه يلزم أن يقال لم يدر عليه من الله رزق وما رزقه الله تعالى قط، وتلك عظيمة لا ينتحلها متدين.\rوفي عقائد النسفي وشرحها للسعد: والحرام رزقه لأن الرزق اسم لما يسوقه الله تعالى إلى الحيوان فيأكله وذلك قد يكون حلالا وقد يكون حراما وهذا أولى من تفسيره بما يتغذى به الحيوان لخلوه عن معنى الإضافة إلى الله تعالى مع أنه معتبر في مفهوم الرزق، والعبد إنما يستحق الذم والعقاب على أكل الحرام لسوء مباشرة أسبابه باختياره وكل يستوفي رزق نفسه حلالا كان أو حراما لحصول التغذي بهما جميعا ولا يتصور أن لا يأكل الإنسان رزقه أو يأكل غيره رزقه لأن ما قدره الله غذاء الشخص يجب أن يأكله ويمتنع أن يأكله غيره، وأما بمعنى الملك فلا يمتنع.\r(والنصب للإمام) أي: تولية السلطان للمسلمين (بالشروط) منها ما هو مجمع عليه ومنها ما هو مختلف فيه: الأول: الإسلام. الثاني: العدالة؛ لأن الفاسق ربما يصرف الأموال لرض نفسه ويتعدى على الأنفس وعلى الأموال بغير موجبها فيضيع الحقوق وتكثر المفاسد. الثالث: الذكورية. الرابع: الحرية؛ لأنها مظنة فراغ البال عن الاشتغال بخدمة الغير.\rقال الشيخ ابن عرفة: ولأن الرق مظنة الاستحقار، وإذا نافى منصب الشهادة فأحرى الإمامة، وحديث أبي ذر رضي الله عنه: ((أوصاني خليلي أن أسمع وأطيع وإن كان عبدا مجدع الأطراف)). محمول على أنه نائب الأمر.\rالخامس: البلوغ. السادس: العقل. السابع: أن يكون مجتهدا في أصول الدين وفروعه ليتمكن من إيراد الأدلة وحل الشبهات والفتوى في أحكام الشرع؛ لأن المقلد تتلاعب به الآراء فلا يهتدي إلى الصواب."], [163, "والسمع مفروض على الأعيان لأمر فيما سوى العصيان\r[الشرح]\rالثامن: أن يكون شجاعا فلا يضعف عن لقاء العدو أو إقامة الحدود. التاسع: أن يكون ذا رأي بتدبير الحرب والسلم يشتد في موضع الشدة ويلين في موضع اللين.\rوذكر في الطوالع: أن جمعا تساهلوا في هذه الصفات الثلاث أعني السابع وما بعده، وقالوا: تصح إمامة من لم يتصف بها ينيب من كان موصوفا بها. قال الشيخ ابن عرفة: وهو خلاف عد الآمدي لها في الشروط المتفق عليها.\rالعاشر: أي يكون مقتدرا على إنفاذ حكمه. الحادي عشر: أن يكون قرشيا وهو مذهب جميع أهل السنة، واحتجوا باجتماع الصحابة رضي الله عنهم يوم السقيفة، فقال الأنصار: منا أمير ومنكم أمير، فمنعهم أبو بكر رضي الله عنه بقوله صلى الله عليه وسلم: ((الأئمة من قريش)).\rكذا ذكره السنوسي في شرح الجزائرية. وفي شرح المقاصد للسعد قال: فإن يوجد من قريش من يستجمع الصفات المعتبرة ولي كناني، فإن لم يوجد فرجل من ولد إسماعيل صلى الله عليه وسلم، فإن لم يوجد فرجل من العجم، قال: وأما إذا لم يوجد من قريش من يصلح لذلك أو لم يقتدر على نصبه لاستيلاء أهل الباطل وشركة الظلمة وأرباب الظلامة فلا كلام في جواز تقلد القضاء أو تنفيذ الأحكام وإقامة الحدود، وجميع ما يتعلق بالإمام من كل ذي شوكة كما إذا كان الإمام القرشي فاسقا أو جائرا أو جاهلا فضلا عن أن يكون مجتهدا، وبالجملة معنى ما ذكر في باب الإمامة من تلك الشروط والأوصاف محمول على الاختيار والاقتدار.\rوأما عند العجز والاضطرار واستيلاء الظلمة والفجار وتسلط الجبابرة الأشرار فقد صارت الرياسة الدنيوية تغليبية، وبنيت عليها الأحكام الديني المنوطة بالإمام ضرورة ولم يعبأ بعدم العلم والعدالة وسائر الشروط إذ الضرورات تبيح المحظورات، وإلى الله المشتكى. وما من زمان إلا والذي بعده شر منه، ولا حول ولا قوة إلا بالله العلي العظيم.\r(فرض) على المسلمين لأن ذلك من أتم مصالح المؤمنين وأعظم مقاصد الدين وعدمه يؤدي إلى الهلاك وفساد الأموال وتعطيل مقاصد الشرع، ويفضي إلى زوال الأمن وظفر الأعداء والخوارج وأنواع المفاسد الكثيرة (بشرع) محمدي (بالهدى منوط) أي: متعلق بالهداية وقمع الضلالة (والسمع) والطاعة من الرعايا (مفروض) قطعا (على الأعيان) جمع عين، يعني فرض عين على جميع المكلفين (لأمره) أي: الإمام ولنهيه (فيما) أي: في كل ما أمر به ونهى (سوى) أي: غير (العصيان) أي: معصية الله تعالى."], [164, "إذ جاء لا طاعة للمخلوق في ذاك وفيما عنه لا يخلو قف\rولا يجوز عزله أن طرا عليه فسق أو بغي واجترا\rولا الخروج عنه إلا إن كفر وحافر البغي هوى فيما حفر\r[الشرح]\r(إذ) أي لأنه (جاء) في الحديث (لا طاعة للمخلوق في ذاك) أي: في معصية الله تعالى، وقد أخرجه البخاري ومسلم، وأبو داود، عن عبد الله بن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم قال: ((السمع والطاعة حق ما لم يؤمر بمعصية فإذا أمر بمعصية فلا سمع ولا طاعة)).\r(وفيما) أي: في الأمر الذي (عنه) أي: عن العصيان لله تعالى (لا يخلو قف) بكسر القاف أمر بالتوقف عن الطاعة وعدمها وهو الإمساك عن أحدهما لأنه محل اشتباه فلا يقدم عليه إلا بعلم أو بغلبة ظن، وهذا محمول على الاختيار وإلا فمع التسلط والتجبر والقهر فلا توقف.\r(ولا يجوز عزله) أي: الإمام عن منصب إمامته (أن طرا) بفتح الهمزة، أي: تجدد (عليه فسق) بارتكاب كبيرة من الكبائر بعد أن كان عدلا حين توليته (أو بغى) أ]: ظلم وجار على رعيته (واجترا) بفتح الهمزة عليهم بغير حق، يعني: أسرع بالهجوم عليهم من غير توقف.\rقال السعد في شرح العقائد: ولا ينعزل الإمام بالفسق، أي: الخروج عن طاعة الله تعالى، والجور، أي: الظلم على عباد الله تعالى؛ لأنه قد ظهر الفسق وانتشر الجور من الأئمة والأمراء بعد الخلفاء الراشدين، والسلف كانوا ينقادون لهم ويقيمون الجمع والأعيان بإذنهم ولا يرون الخروج عليهم ولأن المعصية ليست بشرط للإمامة ابتداء فبقي الأولى.\r(ولا) يجوز (الخروج عنه) أي: الإمام بعدم الدخول تحت طاعته في أمره ونهيه (إلا إن كفر) بسكون الراء أي: بالله تعالى، فإن الكفر ينافي الإمامة لأن من شرطها الإسلام (وحافر البغي) أي: الظلم (هوى) أي: سقط (فيما حفر) بسكون الراء في الحفرة التي حفرها. قال اللقاني - رحمه الله تعالى -: لا يجوز لنا صرف الإمام عن إمامته وخلعه منها بسبب ما خلا الكفر من جميع المعاصي إذا ارتكبها من غير استحلال لا سرا ولا جهرا. وفي شرح المقاصد: ينحل عقد الإمامة بما يزول به مقصود الإمامة كالردة والعياذ بالله تعالى، والجنون المطبق، وصيرورة الإمام أسيرا لا يرجى خلاصه، وكذا بالمرض الذي ينسيه العلوم، وبالعمى أو الصمم والخرس، وكذا بخلعه نفسه لعجزه عن القيام بمصالح المسلمين وإن لم يكن العجز ظاهرا بل استشعره من نفسه."], [165, "والأنبيا أفضل فالملائكه يتلون في فضل علوا أرائكه\rوقيل بالعكس وبعض فضلا في ذاك تفضيلا له قد أصلا\r[الشرح]\r(والأنبيا) بالقصر للوزن (أفضل) عند الله تعالى من جميع المخلوقين (فالملائكة) بسكون الهاء جمع ملك بالتحريك (يتلون÷) للأنبياء - عليهم السلام - يكونون تلوا لهم، يعني: بعدهم (في فضل) أي: فضيلة (علوا) أي: الملائكة عليهم السلام بمعنى ارتفعوا (أرائكه) أي: أرائك ذلك الفضل جمع أريكة.\rقال في الصحاح: الأريكة سرير منجد مزين في قبة أو بيت فإذا لم يكن فيه سرير فهو عجلة والجمع الأرائك.\r(وقيل بالعكس) أي: الملائكة أفضل من الأنبياء - عليهم السلام - (وبعض) من العلماء (فصلا) أي: بألف الإطلاق (في ذلك) أي: في فضل (تفصيلا له) أي: لذلك التفصيل (قد أصلا) بألف الإطلاق وتشديد الصاد المهملة.\rقال السعد في شرح المقاصد: ذهب جمهور أصحابنا والشيعة إلى أن الأنبياء عليهم السلام أفضل من الملائكة عليهم السلام خلافا للمعتزلة، والقاضي أبي بكر الباقلاني، وأبي عبد الله الحليمي منا، وصرح بعض أصحابنا بأن عوام البشر من المؤمنين أفضل من عوام الملائكة وخواص الملائكة أفضل من عوام البشر أي غير الأنبياء عليهم السلام.\rوفي شرح الصحائف: والأنبياء أفضل من الملائكة خلافا للمعتزلة والقاضي أبي بكر، والإمام الرازي والفلاسفة. وقال الأصفهاني في شرح الطوالع: ذهب إلى تفضيل الأنبياء على الملائكة عليهم السلام أكثر أصحابنا والشيعة خلافا للحكماء والمعتزلة، والقاضي أبي بكر الباقلاني، وأبي عبد الله الحليمي من أصحابنا في الملائكة العلوية فإنهم ذهبوا إلى أن الملائكة أفضل من الأنبياء عليهم السلام دون الملائكة السفلية. انتهى\rوالحاصل أن المسألة فيها سبعة أقوال: الأول: وهو المشهور عند الجمهور بأن الأنبياء أفضل من جميع الملائكة عليهم السلام. والثاني: وهو قول الباقلاني والحليمي والرازي أن الملائكة العلوية أفضل من الأنبياء عليهم السلام ما عدا نبينا صلى الله عليه وسلم، وفي كلام بعضهم التصريح بأن المراد بالعلوية مكان السموات وبالسفلية مكان الأرض."], [166, "وانعقد الإجماع أن المقتفى أفضل خلق الله والخلف انتفى\rوما انتحى الكشاف في التكوير خلاف إجماع ذوي التنوير\r[الشرح]\rوالثالث: الوقف في هذه المسألة عن التفضيل بين الفريقين.\rوالرابع: السكوت عن القول بذلك مع اعتقاد ما أدى إليه الدليل وأشار إلى هذين القولين اللقاني - رحمه الله تعالى -. والخامس: أن الأنبياء أفضل من الملائكة عليهم السلام باعتبار النبوة لا باعتبار البشرية.\rفإن قلت: نبوة الأنبياء - عليهم السلام - حصلت للأنبياء من جهة الملائكة ولكن الملائكة فيها بمنزلة رسول أرسلت مع هدية في صندوق مقفل إلى صندوقك فأوصلها إليه وهو لا يعلم ما في الصندوق. والسادس: قول العز بن عبد السلام: إن أرواح الأنبياء عليهم السلام أفضل من أرواح الملائكة وأجساد الملائكة أفضل من أجساد الأنبياء عليهم السلام.\rوالسابع: ما ذكره في منهج الأصلين، قال: والمختار عند الحنفية أن خواص البشر هم الرسل أفضل من جملة الملائكة والملائكة الخواص أفضل من الأنبياء غير المرسلين، والانبياء غير المرسلين أفضل من غير الخواص من الملائكة.\r(وانعقد الإجماع) من الكل (أن المقتفى) بصيغة اسم المفعول وهو نبينا محمد صلى الله عليه وسلم (أفضل خلق الله) أجمعين (والخلف) أي: الاختلاف (انتفى) فلا خلاف في ذلك بين أهل السنة ولا بين المعتزلة. قال اللقاني - رحمه الله تعالى -: ذكر صاحب منهج الأصلين أن محل الخلاف في غير نبينا محمد صلى الله عليه وسلم فإنه أفضل خلق الله أجمعين (وما انتحى) أي: قصده (الكشاف) أي: الذي صنفه الزمخشري (في) سورة (التكوير) من تفسيره حيث قال في قوله تعالى: {وَمَا صَاحِبُكُمْ بِمَجْنُونٍ} [التكوير: 22]. يعني: محمدا صلى الله عليه وسلم ليس بمجنون كما يبهته الكفرة وناهيك بهذا دليلا على جلالة مكان جبريل وفضله على الملائكة ومباينة منزلته لمنزلة أفضل الإنس محمدا صلى الله عليه وسلم إذا وازنت بين الذكرين حين قرن بينهما وقايست بين قوله: {إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ (19) ذِي قُوَّةٍ عِنْدَ ذِي الْعَرْشِ مَكِينٍ (20) مُطَاعٍ ثَمَّ أَمِينٍ} [التكوير: 19 - 21]. وبين قوله: {وَمَا صَاحِبُكُمْ بِمَجْنُونٍ} [التكوير: 22]. انتهى بحروفه.\r(خلاف أجماع ذوي) أي: أصحاب (التنوير) أي: الإنارة يعني أهل النور في هذه المسألة المهتدين إليها، فإن جميع المعتزلة وافقوا أهل السنة فيها على أن نبينا محمدا صلى الله عليه وسلم أفضل خلق الله كلهم ملائكة وإنسا وجنا وغيرهم، وإنما الخلاف بينهم في غيره صلى الله عليه وسلم من بقية الأنبياء صلى الله عليه وسلم أجمعين."], [167, "فاحذر لغير منعه سماعه واتبع السنة والجماعه\rوفضل المخصوص بالإدناء على البرايا دون ما استثناء\r[الشرح]\rقال البدر الزركشي: إن نبينا محمدا صلى الله عليه وسلم مستثنى من الخلاف في المفاضلة بين الملك والبشر وكما مر التصريح به عن صاحب منهج الأصلين الإمام البلقيني - رحمه الله تعالى -، وقد حكم بعضهم بأن الزمخشري لم يكن له كمال اطلاع على أقوال أئمة مذهبه، أو نقول هي نحلة انتحلها على خلاف الإجماع.\r(فاحذر) يا أيها المكلف (لغير) أي: لأجل غير (منعه) أي: رده وإنكاره (سماعه) بسكون الهاء، أي: سماع ما انتحاه صاحب الكشاف فإنه أمر مخالف لإجماع أهل السنة والمعتزلة (واتبع) بتشديد التاء المثناة الفوقية (السنة) المحمدية (والجماعة) بسكون الهاء الإسلامية (وفضل) ضم الفاء وكسر الضاد المعجمة مشددة (المخصوص بالأدنى) أي: التقريب من حضرة الحق تعالى وهو نبينا محمد صلى الله عليه وسلم (على البرايا) أي: المخلوقات كلهم أنبياء وملائكة وإنسا وجنا وغيرهم (دون) أي: من غير (ما) زائدة (استثناء) أحد من الخلق بإجماع الكل ولا تفاوت لقول الزمخشري ولا لغيره، ثم إن بعض الأنبياء عليهم السلام كأولي العزم أفضل من غيرهم وبعض أولي العزم كمحمد صلى الله عليه وسلم أفضل من غيرهم كإبراهيم صلى الله عليه وسلم وأفضل ممن بقي لقوله تعالى: {وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَى بَعْضٍ} [الإسراء: 55]. {تِلْكَ الرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ} [البقرة: 253].\rوإن بعض الملائكة كالرسل منهم أفضل من غيرهم منهم، وبعض الرسل منهم كجبريل أفضل من غيره منهم كميكائيل وهو أفضل من بقي لقوله تعالى: {اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَةِ رُسُلًا وَمِنَ النَّاسِ} [الحج: 75]. فأفضل الرسل أولو العزم وأفضلهم محمد صلى الله عليه وسلم، وإبراهيم - عليهما الصلاة والسلام -، ثم بقية الرسل، ثم الأنبياء غير الرسل، على أن الرسل وكذا الأنبياء متفاوتون أيضا عند الله تعالى ذكره اللقاني - رحمه الله تعالى -.\rقلت: وقد سألني في بيت المقدس عام خمس ومائة وألف بعض علمائها عن الأفضل من أولي العزم بعد إبراهيم صلى الله عليه وسلم؟ فأجبت بما حاصله: أن أفضل أولي العزم الخمسة محمد صلى الله عليه وسلم، ثم إبراهيم الخليل، ثم موسى، ثم عيسى، ثم نوح عليهم السلام صرح بذلك الحافظ ابن حجر بعد قوله في الثلاثة الأخيرة، ولم أقف على نقل أيهم أفضل من الباقي. وذكر وجه الفضيلة فيما بينهم، وقد بينا ذلك مبسوطا في رسالة عملناها في بيت المقدس السائل المذكور سميناها ((صفوة الأصفياء في بيان الفضيلة بين الأنبياء))."], [168, "وأفضل الأمة ذات القدر أصحاب من أعطي شرح الصدر\rإذ جاء في القرآن ما يقضي لهم بالسبق في آي حوت تفضيلهم\rوكم أحاديث عليهم تثني كقوله \"خير القرون قرني\"\r[الشرح]\r(وأفضل) هذه الأمة المحمدية (ذات) أي: صاحبة (القدر) أي: الجاه عند الله تعالى بقوله تعالى سبحانه: {كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ} [آل عمران: 110]. وقوله: {وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا} [البقرة: 143]. الآية.\r(أصحاب) جمع صاحب، وهو: من لقي النبي صلى الله عليه وسلم مؤمنا به ومات على الإيمان (من) أي: الذي (أعطى) بالبناء للمفعول، أي: أعطاه الله تعالى (شرح) أي: سعة (الصدر) بخلقه العظيم الذي قال تعالى في حقه: {وَإِنَّكَ لَعَلَى خُلُقٍ عَظِيمٍ} [القلم: 4].\r(إذ) أي: حين، أو لأنه (جاء في القرآن) العظيم (ما) أي: أمر أو الذي (يقضي لهم) لأي: لأصحاب النبي صلى الله عليه وسلم (بالسبق) أي: الفضل والتقدم على غيرهم من هذه الأمة (في آي) جمع آية (حوت) أي: جمعت (تفضيلهم) أي: على من تأخر عنهم إلى يوم القيامة. قال الله تعالى: {مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ} [الفتح: 29].\rوقال تعالى: {وَلَا تَطْرُدِ الَّذِينَ يَدْعُونَ رَبَّهُمْ بِالْغَدَاةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُ} [الأنعام: 52]. نزلت في فقراء الأنصار. وقال تعالى: {لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمْ فَأَنْزَلَ السَّكِينَةَ عَلَيْهِمْ وَأَثَابَهُمْ فَتْحًا قَرِيبًا} [الفتح: 18].\rوقال تعالى: {إِنَّ الَّذِينَ يَغُضُّونَ أَصْوَاتَهُمْ عِنْدَ رَسُولِ اللَّهِ أُولَئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَى} [الحجرات: 3] الآية.\rوقال تعالى: {وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَآمَنُوا بِمَا نُزِّلَ عَلَى مُحَمَّدٍ وَهُوَ الْحَقُّ مِنْ رَبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَأَصْلَحَ بَالَهُمْ} [محمد: 2].\rوذكر البيضاوي أن هذه الآية تعم المهاجرين والأنصار، إلى غير ذلك من الآيات الدالة على فضائل الصحابة وعلو منزلتهم عند الله، رضي الله عنهم أجمعين.\r(وكم أحاديث) وردت عن النبي صلى الله عليه وسلم (عليهم) أي: الصحابة رضي الله عنهم (تثني) أي: تشتمل على ذكرهم بالجميل من الأوصاف (كقوله) صلى الله عليه وسلم فيما رواه البخاري ومسلم، والترمذي، والنسائي، وابن ماجه، عن عبد الله بن مسعود رضي الله عنه، أن النبي صلى الله عليه وسلم قال: (خير)"], [169, "وقول طه المصطفى \"لو أنفقا\" فجل من زكاهم ووفقا\rثم يليهم تابع بادي السنا فتابع لتابع قد أحسنا\rوالخلفاء الراشدون أربعه خير الصحابة الأولى كانوا معه\r[الشرح]\rالناس. وقال الناظم (القرون) بيانا له، أو لاستقامة الوزن، أو في رواية لهذا الحديث (قرني). والقرن بسكون الراء: الجيل من الناس، قيل: ثمانون سنة، وقيل: سبعون.\rوقال الزجاج: الذي عندي والله أعلم أن القرن أهل كل مدة كان فيها نبي أو طبقة من أهل العلم سواء قلت السنين أو كثرت. قال: والدليل عليه قوله - عليه الصلاة والسلام -: ((خير القرون قرني - يعني أصحابي - ثم الذين يلونهم - يعني التابعين -، ثم الذين يلونهم))، أي: الذين يأخذون عن التابعين. كذا في المصباح.\r(وقوله طه المصطفى) صلى الله عليه وسلم فيما رواه أصحاب الكتب الستة عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((لا تسبوا أحدا من أصحابي فإن أحدكم - (لو أنفقا) بألف الإطلاق - مثل أحد ذهبا ما أدرك مد أحدهم ولا نصيفه)).\r(فجل) أي: عظم (من) أي: النبي الذي (زكاهم) بضم الميم، أي: حكم بتزكيتهم وعدالتهم (ووفقا) بألف الإطلاق، أي: حكم بتوفيقهم وأصلح بينهم، يقال: وفقت بينهم أصلحت (ثم يليهم) أي: الصحابة في الفضيلة (تابع) لهم (بادي) أي: ظاهر (السنا) بالقصر: الضوء، وبالمد: الرفعة، والتابعي هو كل من ألفى الصحابي مؤمنا بما معه من الشرع المحمدي ومات على ذلك.\r(فتابع لتابع) لهم (قد أحسنا) بألف الإطلاق، من الإحسان، وهو الإيقان في الاعتقاد والعمل، وتابع التابعي من لقي التابعي مؤمنا بما عنده من الحق ومات على ذلك. (والخلفاء) جمع خليفة الذين خلفوا عن رسول الله صلى الله عليه وسلم بعده، أي: قاموا مقامه (الراشدون) من الرشد، وهو الصلاح وإصابة الصواب (أربعة) بسكون الهاء الآتي ذكرهم رضي الله عنهم أجمعين (خير الصحابة) أي: صحابة النبي صلى الله عليه وسلم (الأولى) أي: الذين (كانوا معه) بسكون الهاء."], [170, "ورتبن الفضل فيما بينهم على خلافة وقدم عينهم\rوهو أبو بكر وفاروق يلي وبعده عثمان واختم بعلي\rزوج البتول بضعة الرسول من نال بالسبطين أقصى السول\r[الشرح]\r(ورتبن) أمر له مؤكد بالنون (الفضل) أي: الفضيلة (فيما بينهم على) حسب ترتيب (خلافة) وقعت لهم (وقدم) أمر بالتقديم أي: إثبات زيادة الفضيلة (عينهم) أي: خلاصتهم (وهو) أي: عينهم (أبو بكر) الصديق رضي الله عنه، واسمه عبد الله بن أبي قحافة عثمان بن عامر بن عمرو بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب القرشي التيمي، توفي سنة ثلاث عشر من الهجرة وعمره ثلاث وستون سنة كعمر رسول الله صلى الله عليه وسلم.\r(وفاروق) لقب به لفرقه، أي: فصله بين الحق والباطل، واسمه عمر بن الخطاب بن نفيل بن عبد العزى بن رياح - بالمثناة التحتية - ابن عبد الله بن قرط بن رزاح - براء مفتوحة، ثم زاي ثم ألف ثم حاء مهملة - بن عدي بن كعب بن لؤي بن غالب القرشي العدوي، وكانت خلافته عشر سنين وخمسة أشهر وأحد وعشرون يوما، وطعن يوم الأربع لليال بقين من شهر ذي الحجة سنة ثلاث وعشرين من الهجرة، ودفن يوم الأحد هلال المحرم سنة أربع وعشرين وكان عمره ثلاث وستون سنة.\r(يلي) أي: بعد أبي بكر تابعا له في الفضيلة رضي الله عنهما (وبعده) أي: الفاروق في الفضيلة (عثمان) بن عفان بن أبي العاص بن أمية بن عبد شمس بن عبد مناف بن قصي القرشي الأموي، تزوج رقية بنت رسول الله صلى الله عليه وسلم فماتت ثم تزوج أختها أم كلثوم بنت رسول الله صلى الله عليه وسلم وتوفيت عنده، فقال له رسول الله صلى الله عليه وسلم: ((لو كان لنا ثالثة لزوجناكها يا عثمان)). ولا يعرف أحد تزوج ابنتي نبي غيره، ولهذا يلقب بذي النورين، قتل شهيدا يوم الجمعة لثمان عشرة خلون من ذي الحجة سنة خمس وثلاثين من الهجرة ودفن ليلا بالبقيع وأخفي قبره ذلك الوقت ثم أظهر وكان عمره تسعون سنة (واختم) الخلفاء الأربعة رضي الله عنهم (بعلي) بن أبي طالب بن عبد المطلب بن هاشم بن عبد المناف القرشي الهاشمي، تزوج فاطمة بنت رسول الله صلى الله عليه وسلم، ضربه ابن ملجم الخارجي بسيف مسموم في جبهته ليلة الجمعة فتوفي في الكوفة ليلة الأحد التاسع عشر من شهر رمضان سنة أربعين من الهجرة وعمره ثلاث وستون.\r(زوج البتول) المنقطعة عن نساء زمانها ونساء الأمة فضلا ودينا وحسبا، والمنقطعة عن الدنيا إلى الله تعالى كذا في القاموس. (بضعة) بفتح الباء الموحدة أي: قطعة من (الرسول) صلى الله عليه وسلم، واسمها فاطمة الزهراء وهي أصغر بنات رسول الله صلى الله عليه وسلم، توفيت بعد"], [171, "وبعد هؤلاء باقي العشر طلحة والزبير ذاكي النشر\rوعامر وسعد السامي الحلا مع ابن عوف وسعيد ذي العلا\r[الشرح]\rرسول الله صلى الله عليه وسلم بستة أشهر لثلاث خلون من شهر رمضان سنة إحدى عشرة من الهجرة وعمرها تسع وعشرون سنة (من) أي: الذي نعت لعلي رضي الله عنه (بالسبطين) تثنية سبط بالكسر، ولد الولد وهما الحسن والحسين ولدا فاطمة بنت رسول الله صلى الله عليه وسلم، فالحسن هو أبو محمد الحسن بن علي بن أبي طالب بن عبد المطلب بن هاشم، ولد في نصف شهر رمضان سنة ثلاث من الهجرة، وتوفي بالمدينة مسموما سنة تسع وأربعين، ودفن بالبقيع وكان عمره ستا وأربعين سنة، وأخوه الحسين بن علي بن أبي طالب رضي الله عنه، ولد لخمس خلون من شعبان سنة أربع من الهجرة، وقتل يوم الجمعة يوم عاشوراء في كربلاء من بلاد العراق سنة إحدى وستين من الهجرة وكان عمره سبعا وخمسين سنة.\r(أقصى) مفعول نال (السول) بحذف الهمزة، قال في الصحاح، السؤل: ما يسأله الإنسان، وقرئ: {أُوتِيتَ سُؤْلَكَ يَامُوسَى} [طه: 36]. بالهمزة وبغير الهمزة.\r(وبعد هؤلاء) المذكورين في الفضيلة (باقي العشر) المبشرين بالجنة على لسان نبيهم صلى الله عليه وسلم كما ورد في الحديث الآتي والعشرة هم الأربعة الخلفاء المذكورون (طلحة) بن عبيد الله بن عثمان بن عمرو بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب القرشي التيمي، قتل يوم الجمل لعشر خلون من جمادى الأولى سنة ست وثلاثين من الهجرة، وقبره في البصرة مشهور يزار ويتبرك به، وكان عمره أربعا وستين سنة (والزبير) ابن العوام بن خويلد بن أسد بن عبد العزى بن قصي القرشي الأسدي، قتل يوم الجمل بوادي السباع بناحية البصرة وقبره هناك في جمادى الأولى سنة ست وثلاثين وكان عمره حينئذ سبعا وستين (ذاكي) أي: طيب (النشر) أي: الرائحة (وعامر) بن عبيدة بن الجراح واسم أبيه عبد الله بن الجراح بن هلال بن وهيب بن ضبة بن الحارث بن فهر بن مالك، توفي سنة ثمان عشرة من الهجرة في طاعون عمواس، وهي قرية بالشام بين الرملة وبيت المقدس، أضيف الطاعون إليها لأنه بدأ منها، ودفن بقريسيان عند قرية تسمى عمساو عمره ثمان وخمسون سنة (وسعد) بن أبي وقاص، وهو أبو إسحاق سعد بن مالك بن وهيب، ويقال: أهيب بن عبد مناف بن زهرة بن كلاب بن مرة بن كعب بن لؤي القرشي الزهري، توفي بقصره العقيق على عشرة أميل من المدينة، ودفن بالبقيع سنة خمس وخمسين من الهجرة وعمره أربع وسبعون سنة."], [172, "..................................\r[الشرح]\r(السامي) أي: المرتفع (الحلا) بضم الحاء وكسرها أيضا وبالقصر جمع حلية بالكسر وهي الصيغة أي: المتفع الصفات العالي المكارم والأخلاق (مع) بفتح العين المهملة (ابن عوف) أبو محمد عبد الرحمن بن عوف بن عبد عوف بن عبد بن الحارث بن زهرة ابن كلاب بن مرة القرشي الزهري، توفي سنة اثنتين وثلاثين من الهجرة ودفن بالبقيع، وعمره اثنان وسبعون سنة.\r(وسعيد) بن زيد بن عمرو بن نفيل بن عبد العزى بن رياح - بالياء المثناة التحتية ابن عبد الله بن قرط بن رزاح براء مفتوحة ثم زاي وحاء مهملة - ابن عدي بن كعب بن لؤي بن غالب القرشي العدوي وجده عمرو بن نفيل المذكور أخو الخطاب والد عمر بن الخطاب رضي الله عنهم، وقد تزوج أخت عمر بن الخطاب فاطمة بنت الخطاب، أسلمت هي وزوجها سعيد هذا قبل إسلام عمر وكان سبب إسلام عمر رضي الله عنه، توفي بالعقيق وقيل بالمدينة سنة خمسين من الهجرة وعمره بضع وسبعون سنة.\r(ذي) أي: صاحب (العلا) بضم العين المهملة وبالقصر للوزن وأصله المد كسماء، وهو: الرفعة والشرف. والمبشرون بالجنة من أصحاب النبي صلى الله عليه وسلم أكثر من هؤلاء العشرة ولكن لما ورد ذكر هؤلاء العشرة في حديث واحد اشتهر وكذلك حديثهم في سنن الترمذي عن عبد الرحم بن عوف رضي الله عنه وهو أحدهم قال: قال رسول الله صلى الله عليه وسلم: ((أبو بكر في الجنة، وعمر في الجنة، وعثمان في الجنة، وعلي في الجنة، وطلحة في الجنة، والزبير في الجنة، وعبد الرحمن بن عوف في الجنة، وسعد بن أبي وقاص في الجنة، وسعيد بن زيد في الجنة، وأبو عبيدة بن الجراح في الجنة)).\rوأخرج أبو داود، والترمذي، وأبن ماجه، عن سعيد بن زيد رضي الله عنه وهو أحدهم، أن رسول الله صلى الله عليه وسلم قال: ((عشرة في الجنة أبو بكر في الجنة، وعمر في الجنة، وعثمان في الجنة، وعلي والزبير وطلحة وعبد الرحمن وأبو عبيدة وسعد بن أبي وقاص)). وقال: فعد هؤلاء التسعة وسكت عن العاشر فقال القوم: ننشدك الله يا أبا الأعور من العاشر؟ قال: أنشدتموني بالله، أبو الأعور في الجنة وأبو الأعور هو سعيد بن زيد. وقد جمعنا بقية المقطوع لهم بالجنة في رسالة مستقلة وأضفنا إليهم أيضا المقطوع لهم بالنار وسمناها ((لمعات الأنوار في المقطوع لهم بالجنة والمقطوع لهم بالنار))."], [173, "فأهل بدر ثم أهل أحد فبيعة الرضوان من بعد اعدد\rوالسابقون الأولون صرحا بفضلهم والخليف فيهم شرحا\r[الشرح]\r(فأهل) غزوة (بدر) بعدهم في الفضيلة وبدر اسم للوادي أو البئر فيه حفرها بدر ابن مخلد أو بدر بن الحارث أو بدر بن كلدة فسميت باسمه، أو سميت لاستدراتها كالبدر أو لصفائها أو لرؤية البدر فيها ذكره اللقاني - رحمه الله تعالى -، وأهل بدر هم المسلمون الذين كانوا مع رسول اله صلى الله عليه وسلم في تلك الغزوة، وجزم ابن عبد البر أنهم كانوا ثلاثمائة وأربعة عشر رجلا، من المهاجرين ثلاثة وثمانون رجلا ومن الأوس واحد وستون رجلا، ومن الخزرج مائة وسبعون رجلا، واستشهد منهم أربعة عشر رجلا وكان المشركون بين التسعمائة والألف، وقبل منهم سبعون رجلا، وتفصيلهم وذكر أعيانهم وأنسابهم محله كتب السير والتواريخ.\r(ثم) بعدهم في الفضيلة (أهل) غزوة (أحد) بضمتين: جبل معروف بالمدينة، قال فيه صلى الله عليه وسلم ((أحد جبل يحبنا ونحبه)). وزعم بعضهم أن به قبر هارون صلى الله عليه وسلم أخي موسى - عليهما السلام -، وأهل تلك الغزوة كانوا سبعمائة رجل والمشركون ثلاثة آلاف رجل واستشهد فيها من المسلمين سبعون رجلا وقتل من الكفار اثنان وعشرون رجلا (فبيعة الرضوان) أي: بعدهم في الفضيلة أهل بيعة الرضوان التي نزل فيها قوله تعالى: {لَقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ} [الفتح: 18].\rقال البيضاوي: روي أنه - عليه الصلاة والسلام - لما نزل الحديبية بالتخفيف والتصغير، قرية بقرب مكة على طريق جدة بعث جواس بن أمية الخزاعي إلى أهل مكة فهموا به فمنعه الأحابيش فرجع فبعث عثمان بن عفان رضي الله عنه فحبسوه فأرجف بقتله فدعا رسول الله صلى الله عليه وسلم أصحابه وكانوا ألفا وثلاثمائة أو أربعمائة أو خمسمائة وبايعهم على أن يقاتلوا قريشا ولا يفروا عنهم وكان جالسا تحت سمرة أو سدرة (من بعد) من ذكر (اعدد) بكسر الدال الثانية المهملة فعل أمر، أي: هم في الفضيلة بعد من تقدم (والسابقون الأولون) من المهاجرين والأنصار (صرحا) بالبناء للمفعول وألف الإطلاق (بفضلهم) أي: فضيلتهم ومرتبتهم على من بعدهم في نص القرآن العظيم في قوله تعالى: {وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ} [التوبة: 100] الآية."], [174, "وبعض من بالعلم قد تحلى يقول من للقبلتين صلى\rوالصحب كلهم عدول خيره فمن يرد وجه اهتدائهم يره\r[الشرح]\rوقال تعالى: {لَا يَسْتَوِي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَقَاتَلَ} [الحديد: 10]. وقال تعالى: {وَالسَّابِقُونَ السَّابِقُونَ} [الواقعة: 10] الآية. (والخلف) أي: الاختلاف بين العلماء (فيهم) أي: في تعيينهم (شرحا) بالبناء للمفعول وألف الإطلاق، فقال الشعبي: هم أهل بيعة الرضوان، وقال محمد بن كعب: هم أهل بدر ذكره اللقاني - رحمه الله تعالى -.\r(وبعض من) أي: الذي والمراد الجنس (بالعلم) الشرعي (قد تحلى) أي: تزين وهم سعيد بن المسيب، وأبو موسى الأشعري، وطائفة منهم محمد بن كعب القرظين وعطاء ابن يسار (يقول) هم كل (من) أي: الذي (للقبلتين) جهة بيت المقدس وجهة الكعبة (صلى) مع النبي صلى الله عليه وسلم من الصحابة رضي الله عنهم أجمعين. قال اللقاني - رحمه الله تعالى -: وهذا قول الأكثر وهو الأصح. انتهى\rقلت: وبيان القبلتين ما أخرج البخاري، والترمذي، عن البراء بن عازب رضي الله عنه قال: ((لما قدم رسول الله صلى الله عليه وسلم المدينة صلى نحو بيت المقدس ستة عشر شهرا أو سبعة عشر شهرا، وكان يحب أن يوجه إلى الكعبة، فأنزل الله عز وجل: {قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا} [البقرة: 144]. فوجه نحو الكعبة وصلى معه رجل العصر ثم خرج فمر على قوم من الأنصار فقال هو يشهد أنه صلى مع النبي صلى الله عليه وسلم وأنه قد توجه إلى الكعبة فانحرفوا وهم ركوع في صلاة العصر)).\r(والصحب) جمع صاحب وهم أصحاب النبي صلى الله عليه وسلم (كلهم عدول) أي: موصوفون بالعدالة لأن الله تعالى وثقهم في الآيات المتقدم ذكرها وكذلك رسوله صلى الله عليه وسلم في أحاديث كثيرة.\rوقال العراقي في شرح ألفية الحديث: والصحابة كلهم عدول وذكر بعض الآيات والأحاديث ثم قال: ولإجماع من يعتد به في الإجماع من الأئمة على ذلك، ثم إن جميع الأمة مجمعة على تعديل من لم يلابس الفتن منهم وأما من لبس الفتن منهم وذلك من حين مقتل عثمان رضي الله عنهم فاجمع من يعتد به أيضا في الإجماع على تعديلهم إحسانا للظن بهم وحملا لهم في ذلك على الاجتهاد.\r(خيره) بالتحريك وبسكون الهاء جمع خير بالتشديد، أي: ذو خير ويجمع على أخيار (فمن يرد) أي: يقصد (وجه اهتدائهم) أي: سب هدايتهم (يره) بسكون الهاء أي: ذلك الوجه ثم بينه بقوله:"], [175, "لأن من أحاط بالخبي علما خباهم صحبة النبي\rفهم نجوم في السرى من اقتدى بهم إلى معالم الحق اهتدى\rفلا تخض فيما من الأمر اختلط بينهم فاحذر إذا خضت الغلط\rوالتمسن أحسن المخارج لهم فالاجتهاد ذو معارج\r[الشرح]\r(لأن من) أي: الذي (أحاط بالخبي) بتشديد الياء التحتية فعيل بمعنى مفعول وأصله بالهمزة: خبأت الشيء سترته وحفظته (علما) تمييز وذلك هو الله تعالى القائل: {أَلَّا يَسْجُدُوا لِلَّهِ الَّذِي يُخْرِجُ الْخَبْءَ فِي السَّمَاوَاتِ وَالْأَرْضِ} [النمل: 25]. وهو اسم لما يخبأ فيهما (حباهم) أي: أعطاهم.\rوفي المصباح: حبوت الرجل حباء بالكسر والمد: أعطيته يعني الصحابة رضي الله عنهم (صحبة النبي) أي: نبينا محمد صلى الله عليه وسلم فإن صحبتهم له هي سبب هدايتهم التامة وفضلهم العام ومقام الصحابة لا يعادله مقام وذلك عليهم من سوابغ الإنعام (فهم) أي: الصحابة رضي الله عنهم (نجوم) من قوله صلى الله عليه وسلم: ((إن أصحابي بمنزلة النجوم في السماء فأيما أخذتم به اهتديتم)). الحديث بتمامه رواه البيهقي في المدخل بسنده عن ابن عباس رضي الله عنهما.\r(في السرى) بضم السين المهملة مصدر سريت إذا سرت ليلا. وفي القاموس: السرى كالهدى سير عامة الليل (من اقتدى بهم) أي: تابعهم وعمل سيرتهم وسار على سيرهم (إلى معالم الحق) المعالم جمع معلم قال في القاموس: معلم الشيء كمقعد مظنته وما يستد به. انتهى. فمعالم الحق: أدلته وطرقه الموصلة إليه، والحق خلاف الباطل، أو هو الله تعالى. (اهتدى) أي: وصل، فلا تخض أيها المكلف (فيما) أي: في مشكل (من الأمر) الذي كانوا عليه (اختلط) بسكون الطاء المهملة (بينهم) بضم الميم أي: بين الصحابة رضي الله عنهم بعد وفاة النبي صلى الله عليه وسلم (واحذر إذا خضت) في ذلك واطلعت على ما كان من بعضهم في حق بعض (الغلط) بسكون الطاء المهملة بذم البعض ومدح البعض والطعن في أحد منهم أو التشيع له.\r(والتمسن) فعل أمر مؤكد بالنون المشددة (أحسن المخارج) أي: الوجوه والاعتذارات (لهم) أي: للصحابة رضوان الله عليهم أجمعين (فالاجتهاد) في أدلة الشرع (ذو) أي: صاحب (معارج) جمع معراج كمفتاح، وهو: السلم والمرقاة وكذلك المعراج أي: ذو درجات ومراتب بعضها فوق بعض؛ لأن الاجتهاد في الدين يحتمل الخطأ"], [176, "ولا تُصِخ لمن أبى الكرامه للأولياء واجتنب مرامه\r[الشرح]\rوالصواب وكلاهما يثاب به المجتهد ولا يأثم، ثم قال ابن قاضي عجلون في شرح الشيبانية: قد استقرت آراء المحققين من العلماء على أن البحث عن أحوال الصحابة رضي الله عنهم وما جرى بينهم من المخالفة والموافقة ليس من العقائد الدينية والقواعد الكلامية ولا ينفع في الدين بل ربما يضر باليقين، فلنسكت عن الخوض في ذلك، وما نقل عنهم من الحروب والفتن فله محامل وتأويلات.\rقال ابن دقيق العيد في عقيدته: وما نقل عنهم فيما شجر بينهم واختلفوا فيه، فمنه ما هو باطل وكذب فلا يلتفت إليه، وما كان صحيحا أولناه على أحسن التأويلات وطلبنا له أجود المخارج؛ لأن الثناء عليهم من الله تعالى سابق، وما نقل محتمل للتأويل، والمشكوك لا يبطل المعلوم، فما جرى بينهم كان على سبيل الاجتهاد والمجتهد مثاب وإن كان مخطئا، كما ورد في الحديث، أن النبي صلى الله عليه وسلم قال: ((من أصاب فله أجران ومن أخطأ فله أجر)).\rوقال اللقاني - رحمه الله تعالى -: ((التمس وجوبا عليك مخرجا وتأويلا يحتمل الحال وإن كان خلاف الظاهر والمتبادر واصرف إليه التشاجر الصادر بينهم الذي يثبت بالسند الصحيح المتصل أنه مما ورد عنهم متواتر كان أو آحادا مشهورا كان أو لا، أما ما لم يصح عنهم فمردود لذاته لا يحتاج لتأويل)).\r(ولا تصخ) بضم التاء الفوقية، أي: لا تستمع قال في الصحاح أصاخ له، أي: استمعه (لمن أبى) أي: لم يقبل (الكرامه) بسكون الهاء، الثابتة (للأولياء) جمع ولي، وهو الذي تولى الله تعالى جميع أموره لصدقه في عبوديته لله تعالى باطنا وظاهرا (واجتنب) يا أيها المكلف (مرامه) بسكون الهاء، أي: مقصوده مانع الكرامة، وهو المعتزلة المخالف لمذهب أهل السنة.\rقال السنوسي - رحمه الله تعالى - في شرح الجزائرية: ومنع الكرامة أكثر من المعتزلة والأستاذ أبو إسحاق يميل إلى قريب من مذهبهم هكذا نقل عنه إمام الحرمين، ولا غرابة في إنكار أكثر المعتزلة لها إذ هم لم يشاهدوا في جماعتهم الضالة المضلة وليا لله سبحانه وتعالى وإنما الغرابة في إنكار من ينكرها من أهل السنة إن صح عنه ذلك. والكرامة أمر خارق للعادة يظهر على يد العبد ظاهر الصلاح ملتزم لمتابعة النبي صلى الله عليه وسلم.\rوقال النووي في باب البر والصلة من شرح صحيح مسلم: إن الكرامات تجوز بجواز العادات وهذا غلط من قائله وإنكار للحس بل الصواب جريانها بقلب الأعيان ونحوه. انتهى"], [177, "ونزه القرآن أن تقولا بخلقه واستوضح المعقولا\rلأنه وصف الإله جلا ومعجز النظم عليه دلا\r[الشرح]\rوقد بسطنا هذا البحث في كتابنا ((المطالب الوفية بما يفي بالأمنيه)). (ونزه القرآن) العظيم وهو كلام الله تعالى (أن تقولا) بألف الإطلاق (بخلقه) أي: بكونه مخلوقا حادثا كما قالت المعتزلة بذلك (واستوضح المعقولا) بألف الإطلاق، أي: اطلب إيضاح الأمر المقول لك ليتبين عندك الصواب ويزول عنك الخطأ والشك والارتياب، ثم بين ذلك بقوله (لأنه) أي: القرآن الذي هو كلام الله تعالى (وصف الإله جلا) بألف الإطلاق، أي: عظم؛ لأن الكلام صفة المتكلم به والوصف تابع للموصوف، فإذا كان الموصوف قديما فالوصف قديم كذلك؛ ولأن كان أثر الأوصاف والأثر لا يكون وصفا للمؤثر كخالق البياض والسواد لا يوصف به فيكون أبيض أو أسود.\r(ومعجز النظم) أي: ونظمه العجز يعني ألفاظ القرآن وكلماته التي جاء بها نبينا محمد صلى الله عليه وسلم معجزة له (عليه) أي: على القرآن الذي هو كلام الله تعالى (دلا) بألف الإطلاق، أي: أفهم ذلك وإفادة لنا باعتبار الوضع العربي كدلالة اللفظ على معناه الموضوع له بحيث لا يستقل بمفهوم دونه كقولهم الاسم عين المسمى وهو شامل هنا للفعل والحرف أيضا؛ لأن هذه الدلالة بمنزلة دلالة الدليل على مدلوله فيصح نفيه ولا يصح إطلاقه عليه إلا مجازا، فإذا قلت: جاء زيد مثلا فليس مرادك نسبة المجيء لزيد إلى هذ الحروف الثلاثة التي هي الزاي والياء والدال في حال تركيبها كذلك، وليس أيضا مرادك نسبة الجيم والألف والهمزة إلى مسمى زيد وإنما هذه إشارات انطبقت إلى معان قلبية غيبية ولا يصح نفيها أيضا فلا يصح أن يقال: زيد هذا، وإن عنيت به الحروف ليس بزيد المسمى لأنك ما تكلمت به إلا لتشير به إلى المسمى فإذا عدلت به عن الوضع لم يكن هو ذلك اللفظ الموضوع والكلام إنما هو في تلك الألفاظ الموضوعة باعتبار أنها موضوعة للدلالة المذكورة ومثله جاء وجميع الكلمات كذلك فهي حقائق لغوية مستعملة في موضوعاتها لا يصح نفيها ولا الإطلاق المجازي عليها إلا باعتبار آخر عند علماء البيان وإذا علمت هذا ..."], [178, "فذلك المتلو والمدلول عليه ما عن قدم يحول\rوالحرف والصوت كذا التلاوه محدثة وغير ذا غباوه\r[الشرح]\r(فذلك) القرآن (المتلو) أي: المقروء بالألسنة (والمدلول عليه) بالكلمات العربية المشتملة على السورة والآيات (ما عن قدم يحول) أي: لا ينفك عن كونه قديما أزليا صفة الحق سبحانه المتكلم به أزلا وأبدا، وليس كتكلم الحوادث به فإن تكلمه تعالى به من غير حروف ولا أصوات لأنه من غير فم ولا لسان، ويستحيل عليه سبحانه الجسمية والعرضية وتكلم الحوادث به إنما يكون بحروف وأصوات وفم ولسان لأنهم أجسام وأعراض، فالكلام القديم واحد والتكلم به مختلف على حساب ما يناسب كل تكلم.\r(والحرف) مراده الجنس ليشمل الحروف كلها المتكررة في النطق وغير المتكررة (والصوت) كذلك من كل قارئ (كذا التلاوة) بسكون الهاء، أي: القراءة التي هي صفة القارئ فتارة تكون قراءة صحيحة فيثاب عليها لأنها علمه وتارة تكون ملحونة فيأثم بها (محدثة) لأنها صفة العبد المحدث فهي محدثة المتلو والمقري فهو قديم كمن ذكر الله تعالى فإن الذكر صفة وهو الكلمات المشتملة على الحروف والأصوات والمذكور ليس بصفة للذاكر لأنه قديم وهو تعالى ليس من جنس الحروف والأصوات أريد ذلك ما أخرجه الطبراني في معجمه بإسناده عن أبي شريح الخزاعي رضي الله عنه أنه قال: خرج علينا رسول الله صلى الله عليه وسلم فقال: ((أليس تشهدون أن لا إله إلا الله وأني رسول الله)) قالوا: بلى. قال: ((إن هذا القرآن طرفه بيد الله وطرفه بأيديكم فتمسكوا به فإنكم لن تضلوا ولن تهلكوا بعده أبدا)).\rوفي رواية ابن أبي شيبة من حديث أبي شريح الخزاعي رضي الله عنه: ((إن هذا القرآن سبب طرفه بيد الله وطرفه بأيديكم)). الحديث بتمامه. والسبب: الحبل، أي: هو حبل ممدود طرفه الواحد الأعلى المنزه عن الحرف والصوت بيد الله تعالى أي هو كلام الله تعالى صفته القائمة بذاته، وطرفه الآخر الذي هو قراءة العباد وتلاوتهم المشتملة على الحروف والأصوات بأيدي العباد وهذا الطرف هو الذي جاء به نبينا محمد صلى الله عليه وسلم معجزة للبشر كما قال تعالى: {فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ الْمُتَّقِينَ وَتُنْذِرَ بِهِ قَوْمًا لُدًّا} [مريم: 97].\rوقال تعالى: {وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ} [القمر: 17]. وهو المنزل بقوله تعالى: {نَزَلَ بِهِ الرُّوحُ الْأَمِينُ (193) عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ (194) بِلِسَانٍ عَرَبِيٍّ مُبِينٍ} [الشعراء: 193 - 195] إلى غير ذلك من الآيات."], [179, "واحذر أقاويل ذوي الأهواء فإنها من أدوا الادواء\rواسلك سبيل السنة الغراء فنورها باد لعين الرائي\rوالشر مقرون بالابتداع والخير مضمون بالاتباع\rواعمل بما تحبي به الأجورا وحاذر الفحشاء والفجورا\r[الشرح]\rفالقرآن العظيم واحد والمتكلم به هو الله تعالى، وهو المنزل على النبي صلى الله عليه وسلم، وهو المقروء بألسنتنا المحفوظ بقلوبنا المكتوب في مصاحفنا ولكنه المقروء والمحفوظ والمكتوب، كما أنه المنزل بآلات حادثة هي المعاني والحروف الهوائية والمدادية، وهو مع ذلك قائم بذات الله تعالى منزه عن هذه الآلات الحادثة أن تكون مخالطة له أو هو مخالط لها، كما أن ذات الله تعالى وصفاته منزهة عن مخالطة الكلمات والحروف والأصوات في دعائنا له بأسمائه في قولنا: يا الله يا رحمن يا رحيم ونحو ذلك، وعن مخالطة ذلك له أيضا كما ذكرناه في كتابنا ((الحديقة الندية شرح الطريقة المحمدية)).\r(وغير ذا) أي: هذا من الأقوال (غباوه) بسكون الهاء، أي: غفلة وذهوب عن الحق والصواب (واحذر أقاويل) جمع قول (ذوي) أي: أصحاب (الأهواء) جمع هوى بالقصر، وهو الميل النفسي كالمعتزلة والفلاسفة المخالفين لمذهب أهل السنة والجماعة (فإنها) أي: أقاويلهم (من أدوا) أي: أكثر داء أي: مرض (الأدواء) جمع داء، وهو المرض أي: أعظم مرضا من جميع الأمراض (واسلك) أي: اتبع (سبيل) أي: طريق (السنة) المحمدية (الغراء) البيضاء المشرقة (فنورها) أي: السنة (باد) أي: ظاهر (لعين الرائي) أي: البصير من الناس (والشر) خلاف الخير (مقرون بالابتداع) أ]: ملازم لفعل البدع في الاعتقاد وفي الأعمال (والخير) أي: اليمن والبركة والنفع الوافر في الدين والدنيا والآخرة (مضمون) حصوله من اله تعالى للعبد (بالاتباع) لسنة النبي صلى الله عليه وسلم اعتقادا أو عملا (واعمل) يا أيها المكلف (بما) أي: بالعمل الموافق للشرع المحمدي الذي (تحبى) بالبناء للمفعول، أي: تعطى، يعني يعطيك الله تعالى (به الأجورا) بألف الإطلاق جمع أجر، وهو الثواب القمرر عند الله تعالى للعبد المؤمن يوم القيامة.\r(وحاذر) أي: توقى واجتنب (الفحشاء) وهو البخل في أداء الزكاة كذا في القاموس. وقال في المصباح: فحش الشيء فحشا مثل قبح قبحا وزنا ومعنى، وأفحش الرجل: أتى بالفحش وهو القول السيء وجاء بالفحشاء مثله انتهى. ويمكن أن يراد به"], [180, "والعجب والغيبة والرياء واطرحن فخرا وكبرياء\r[الشرح]\rهنا الفاحشة، وهي كما في القاموس الزنا وما يشتد قبحه من الذنوب وكل ما نهى الله عز وجل عنه. (والفجورا) بألف الإطلاق معطوف على الفحشاء وبيان له، وهو الانبعاث في المعاصي والزنا، وفجر: فسق، وكذب، وكذب وعصى كذا في القاموس (العجب) بالضم الاسم من قولك أعجب فلان بنفسه للبناء للمفعول فهو معجب برأيه وبنفسه كذا في المصباح والصحاح، وهو استعظام العمل الصالح، وذكر حصول شرفه بشيء دون الله تعالى من النفس أو الناس، وقد يطلق على مطلق استعظام والركون إليها مع نسيان إضافتها إلى المنعم كذا في ((الطريقة المحمدية)) للبركلي الرومي - رحمه الله تعالى -. وقد بينا ذلك في شرحنا لهما المسمى ((بالحديقة الندية بشرح الطريقة المحمدية)).\r(والغيبة) بالكسر الاسم من قولك: اغتابه اغتيابا. ذكره بما يكره من العيوب وهو حق، فإن كان باطلا فهو الغيبة في بهت كذا في المصباح، وفي الصحاح: اغتابه اغتيابا، إذا وقع فيه والاسم الغيبة وهو أن يتكلم خلف الإنسان بما يغمه لو سمعه، فإن كان صدقا يسمى غيبة، وإن كان كذبا سمي بهتانا.\rوقال اللقاني: هي ذكر الإنسان بما فيه مما يكره سواء كان في بدنه أو دينه أو نفسه أو خلقه، أو ماله أو ولده، أو زوجته، أو خادمه، أو حرفته، أو ثوبه، أو مملوكه أو عمامته، أو لونه، أو مركوبه، أو مشيته، أو حركته، أو بشاشته، أو خلاعته، أو عبوسه، أو طلاقته أو غير ذلك مما يتعلق به، سواء ذكرته بلفظك أو كتابك أو أشرت إليه بعينك أو يدل أو برأسك أو نحو ذلك.\rقال: وهي حرام بالإجماع، وهي من الكبائر، والذي جزم به ابن حجر الهيتمي في شرح الشمائل أن غيبة العالم وحامل القرآن كبيرة، وأما غيبة غيرهما فصغيرة.\r(والرياء) وهو إظهار العمل للناس ليروه ويظنوه أنه خير، فالعمل لغير الله نعوذ بالله مه كذا في المصباح. وقال أبو عبد الله الحارث بن أسد المحاسبي في كتاب الرعاية: الرياء إرادة العبد العباد بطاعة الله عز وجل، وأبحاث الرياء مفصلة في كتابنا ((الحديقة الندية)).\r(واطرحن) بتشديد الطاء المهملة فعل أمر مؤكد بالنون الخفيفة الساكنة من طرحته طرحا رميت به. وقال في الصحاح: واطرحه بتشديد الطاء المهملة أي: بعده، وهو افتعله. (فخرا) وهو المباهاة بالمكارم والمناقب من حسب ونسب وغير ذلك، إما في"], [181, "وأمر بمعروف وغير منكرا وانصح ونبه ذا اغترار من كرى\r[الشرح]\rالمتكلم أو في آبائه وتفاخر القوم فيما بينهم، إذا افتخر كل منهم بمفاخرة كذا في المصباح. (وكبرياء) وهو التعاظم ورؤية نفسه أكبر من غيره والتجبر على الغير (وأمر بمعروف) واجب بطريق الإيجاب عليك، ومندوب بطريق الندب (وغير) من الغير، وهو الإزالة (منكرا) ينكره الشرع حراما كان أو مكروها إيجابا وندبا. وللأمر بالمعروف والنهي عن المنكر شروط لا بد منها ومن بيانها:\rالأول: أن يكون المتولي لذلك عالما بما يأمر به وبما ينهى عنه، فالجاهل بالحكم لا يحل له النهي عما يراه، ولا الأمر به.\rوالثاني: أن يأمن أن يؤدي إنكاره إلى منكر أكبر منه مثل أن ينهى عن شرب الخمر فيئول نهيه عنه إلى قتل النفس أو نحوه.\rوالثالث: أن يغلب على ظنه أن إنكار المنكر مزيل له وأن أمره بالمعروف مؤثر في تحصيله ذكره اللقاني - رحمه الله تعالى _.\rوفي خزانة المتين: الأمر بالمعروف إنما يجب إذا علم أنهم يسمعون وإلا فلا. وفي جامع الفتاوى: ولو علم أن فلانا يتعاطى المناكر فإن وقع في قلبه أنه لو أخبره بذلك يترك ويغير حاله حل له الإخبار وإلا فلا، وكذا لو رأى على ثوب إنسان نجاسة أكثر من قدر الدرهم فإن وقع في قلبه أنه لو أخبره اشتغل بغسله لا يسعه أن لا يخبره إلا إذا كان قادرا على إجباره، والحكم في المنكرات والخطأ في القرآن والمسائل وغير ذلك وكذلك في الفتاوى الظهيرية ويقال: الأمر بالمعروف باليد على الأمراء، وباللسان على العلماء، وبالقلب لعوام الناس وهو اختيار الزند ويستر. (وانصح) من استطعت نصيحته من المسلمين والمسلمات والمؤمنين والمؤمنات بل كل إنسان في دين الحق وحلال الدنيا وحسن الآخرة (ونبه) أي: أيقظ بقولك أو فعلك (ذا) أي: صاحب (اغترار) بمال وجاه أو دين أو بطاعة أو معصية (من كرى) أي: نوم ذلك الاغترار على حسب ما تستطيع، وبين قول منكرا وقوله من كرى جناس التلفيق."], [182, "وابدأ بنفسك انهها عن غيها واجعل من التقوى جميل زيها\rواقطع ذوي الميل واوصل من عدل ولا تمل إلى المراء والجدل\rوفي كتاب الله أسنى مكتفى به وما سن النبي المقتفى\rوما عليه أجمع الأعلام ممن تزكت منهم الأحلام\r[الشرح]\r(وابدأ) في ذلك (بنفسك) لأنها أقرب إليك من غيرك فهي أحق بالتقديم من الغير بالنصح والتنبيه من الاغترار (انهها) أي: ازجرها واكففها (عن غيها) أي: الغي الذي فيها خلاف الرشد شامل لجميع أنواع الفسوق (واجعل من التقوى) أي: التحرز عن معصية الله تعالى (جميل زيها) أي: زيها الجميل. والزي بكسر الزاي: الهيئة والضمير للنفس.\r(واقطع) أي: اهجر وتباعد عن (ذوي) أي: أصحاب (الميل) النفساني والأغراض الفاسدة، والأهواء الكاسدة، (واوصل) أي: صاحب وخالط (من عدل) بسكون اللام، أي: المتصف بالعدل في الأقوال والأفعال والأحوال أي الموافقة فيها الميزان الشرعي من أهل السنة (ولا تمل إلى المراء) بالكسر، أي: المخاصمة بالحق أو الباطل (والجدل) بالتحريك وسكون اللام مصدر جدل كتعب، إذا اشتدت خصومته.\rأخرج الترمذي بإسناده عن أنس بن مالك رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: ((من ترك الكذب وهو باطل بني له في ربض الجنة، ومن ترك المراء وهو محق بني له في وسطها ومن حسن خلقه بني له في أعلاها)).\rوأخرج ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: ((كفى بك إثما أن لا تزال مخاصما)). (وفي كتاب الله) تعالى، وهو القرآن العظيم (أسنى) أي: أرفع وأعلى (مكتفى) بصيغة اسم المفعول (به وما) أي: الذي (سن) أي: سن بالأمة (النبي) محمد صلى الله عليه وسلم شيء يكتفي به العبد المؤمن في المتابعة والاعتقاد.\r(و) كذلك في كل (ما عليه أجمع الأعلام) أي: الأئمة من العلماء أهل السنة والجماعة (ممن تزكت) أي: طهرت وكملت (منهم÷) بضم الميم (الأحلام) أي: العقول وهو إجماع السلف الصالحين وأئم الهدى في هدى الدين."], [183, "فأكرام العباد عند الله من لم يكن في عيثه بلاهي\rوفي اتباع السلف الهداة وسيلة للأمن والنجاة\rولنجعل الختام بالشهاده تفاؤلا برتبة السعادة\rلأن لا إله إلا الله قد تضمنت جملتها ما يعتقد\rفي حق ربنا وفي الرسل الناهجين للورى أهدى السبل\r[الشرح]\r(فأكرم العابد) أي: أشرفهم وأعظمهم (عند الله) سبحانه وتعالى (من لم يكن في عيشه) أي: حياته الدنيوية (بلاهي) أي: فاعل للانهماك في دنياه عن آخرته وأمر دينه (وفي اتباع) أي: متابعة (السلف) أ]: المتقدمين من الأئمة السادات (الهداة) جمع هادي (وسيلة) عظيمة عند الله تعالى (للأمن) من مهالك الدنيا والآخرة (والنجاة) من جميع ذلك (ولنجعل الختام) أي: ختام هذه المنظومة (بالشهاده) بالسكون للوزن أي: بكلمتها وهي أشهد أن لا إله إلا الله وأشهد أن محمدا رسول الله (تفاؤلا) لنا (برتبة) أي: بحصول مرتبة (السعاده) بسكون الهاء في الدين والدنيا والآخرة (لأن) كلمة أشهد أن (لا إله) أي: معبود بحق (إلا الله) تعالى، وأشهد أن محمدا رسول الله (قد تضمنت جملتها) أي: جملة هذه الكلمة المشتملة على شهادة التوحيد لله تعالى وشهادة الرسالة لنبيه محمد صلى الله عليه وسلم (ما يعتقد) بالبناء للمفعول، أي: يعتقده كل مؤمن (في حق ربنا) سبحانه وتعالى من ثبوت الصفات الواجبات المتقدم ذكرها ونفي أضدادها من المستحيلات وإثبات الصفة الجائزة له تعالى لأن المعبود بحق متصف بذلك ومنزه عن أضداد ما اتصف به وجائز في حقه ما ذكر.\r(وفي حق الرسل) عليهم الصلاة والسلام (الناهجين) أي: الموضحين. قال في الصحاح: نهجت الطريق إذا انتبه وأوضحته. وفي المصباح نهجته وأنهجته أوضحته (للورى) أي: الخلق (أهدى السبل) أي: الطرق؛ لأن إثبات الرسالة لنبينا محمد صلى الله عليه وسلم متضمنة لتصديقه في جميع ما جاء به صلى الله عليه وسلم من جملة ما جاء به صدق الرسل كلهم عليهم الصلاة والسلام، ويتضمن ذلك أمانته وأمانة الرسل عليهم الصلاة والسلام، وكذلك تبليغهم جميع ما أمروا بإبلاغه للخلق واستحالة أضداد ذلك عليهم وجواز ما لم يقتض نقصانهم والإخلال بمراتبهم العلية."], [184, "من واجب وجائز وما امتنع ومن يكن يعرف معناها ارتفع\rكما تولى بسطه السنوسي مغترفا من فيضه القدوسي\rوقد أخذت كتبه درايه عمن تلقى في العلوم الرايه\rعمي سعيد الإمام المقري عن ابن جلال ع الحبر السري\r[الشرح]\r(من واجب) عقلا في حقه تعالى وفي حق الرسل عليهم الصلاة والسلام (وجائز) كذلك في حقه تعالى وفي حق الرسل عليهم الصلاة والسلام (وما امتنع) بسكون العين المهملة أي: الممتنع بمعنى المستحيل عقلا في حقه سبحانه وفي حق الرسل كذلك كما ذكرنا (ومن يكن يعرف) من المكلفين (معناها) أي: كلمة الشهادة ويعرف ما تضمنته من العقائد المذكورة معرفة دليل وبرهان على حسب ما تقدم (ارتفع) بسكون العين المهملة، أي: علت رتبته في عباد الله تعالى وكان صحيح العقيدة سالم القلب من كل شيء وارتياب مشمولا في الدنيا والآخرة بأنواع الثواب (كما) أي: على مقتضى ما (تولى بسطه) أي: ذكره مبسوطا مفصلا بأقسامه وأدلته الشيخ الإمام أبو عبد الله محمد بن يوسف (السنوسي) الحسني التلمساني، ونسبته إلى سنوس بالسينين المهملتين، اسم قبيلة من قبائل العرب في بلاد المغرب في مقدمته الكبرى والصغرى وفي شروحه المتعددة له على ذلك (مغترفا من فيضه) الذي أفاضه الله تعالى عليه (القدوسي) أي: الطاهر المنسوب إلى حضرة القدس الأعلى.\rقال الناظم: هذه العقيدة للشيخ الإمام العلامة أحمد المقري - رحمه الله تعالى - (وقد أخذت) أي: رويت (كتبه) أي: السنوسي - رحمه الله تعالى - (درايه) بسكون الهاء، أي: مع درايتها وفهمها (عمن) أي: عن شيخي الذي (تلقى) أي: أخذ (في العلوم) الشرعية وسائلها ومقاصدها (الراية) بسكون الهاء، وهي: العلم بالتحريك والجمع رايات، أي: كان هو الإمام المقدم في العلوم (عمي) أي: أخي أبي الشيخ (سعيد الإمام المقري) بتشديد القاف كما تقدم، والشيخ سعيد المذكور أخذ (عن) الشيخ الإمام محمد ابن عبد الرحمن (عن ابن جلال) بتشديد اللام والتلمساني، وابن جلال المذكور أخذ (عن الحبر) بكسر الحاء المهملة.\rقال في المصباح: الحبر العالم والجمع أحبار، مثل: حمل، وأحمال، والحبر بالفتح لغة فيه وجمعه حبور مثل فلس وفلوس، واقتصر بعضهم على الفتح وبعضهم أنكر الكسر. (السري) الرئيس وجمعه سرات وهو عزيز لا يكاد يوجد له نظير لأنه يجمع فعيل على فعلة كذا في المصباح."], [185, "الشهير بالكفيف عن السنوسي الرضي العفيف\rمؤلف العقائد الشهيره وفضله كالشمس في الظهيره\rوهو الذي يول ما معناه في سر لا إله إلا الله\rلعلها للاختصار مع ما تضمنته خصها ذو النعمى\rبكونها ترجمة الإيمان فالهج بذكرها مع الإدمان\r[الشرح]\r(سعيد) المناوي التلمساني تلميذ السنوسي - رحمهما الله تعالى - (الشهير) أي: المشهور (بالكفيف) أي: مكفوف البصر، وسعيد الكفيف هذا أخذ (عن) شيخه الإمام السنوسي بتشديد الياء التحتية (الرضى) أي: المرضي في أقواله وأفعاله وأحواله (العفيف) أي: صاحب العفاف. قال في المصباح: عف عن الشيء عفا من باب ضرب وعفة بالكسر وعفافا بالفتح كف عنه فهو عفيف انتهى. أي: العفيف عن رذائل الطباع ومفاسد الأحوال في الظاهر والباطن.\r(مؤلف العقائد) جمع عقيدة، وهو ما يعقد عليه القلب أي: يربط في دين الله (الشهيره) بسكون الهاء للوزن، أي: المشهورة بين الناس في غالب البلاد الشرقية والغربية (وفضله) أي: السنوسي المذكور - رحمه الله تعالى - (كالشمس) في ظهورها (في) وقت (الظهيره) بسكون الهاء، وحد انتصاف النهار أو إنما ذلك في القيظ كذا في القاموس. (وهو) أي: السنوسي - رحمه الله تعالى - (الذي يقول) في آخر عقيدته المشهورة (ما) أي: كلاما (معناه في سر) متعلق بيقول قولك (لا إله إلا الله) والذي يقوله هو (لعلها) أي: كلمة الشهادة (للاختصار) أي: قلة حروفها (مع ما) أي: الذي (تضمنته) من عقائد الإيمان (خصها ذو) أي: صاحب (النعمى) بالقصر للوزن، وهو الله تعالى المنعم على كل حال (بكونها) أي: كلمة الشهادة متعلق بخصها (ترجمة الإيمان) أي: بينة لما اشتمل عليه قلب العبد من الإيمان بالله تعالى وبرسله عليهم الصلاة والسلام وبجميع ما جاءوا به من الحق فألهج يا أيها المكلف، من لهج بالشيء لهجا من باب تعب: أولع به كذا في المصباح (بذكرها) أي: الشهادة (مع الإدمان) يقال: أدمن فلان كذا إدمانا واظبه ولازمه كذا في المصباح. وتمام عبارة السنوسي - رحمه الله تعالى - حتى تمتزج معناه بلحمه ودمه فإنه يرى لها من الأسرار والعجائب إن شاء الله تعالى ما لا يدخل تحت حصر، وبالله التوفيق لا رب غيره، نسأله سبحانه أن يجعلنا وأحبتنا عند الموت ناطقين بكلمتي الشهادة عالمين بها. وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم."], [186, "وهاهنا نظم العقيدة انتهى مبلغا لمن وعاه ما اشتهى\rوفاء عدها بنصف ألف والرمز بالجمل فيه ألف\rوكان إتمامي له في القاهره وفيه تاريخ حلاه الظاهره\r[الشرح]\r(وهاهنا نظم) أبيات هذه (العقيدة) المباركة النافعة إن شاء الله تعالى لأمة محمد صلى الله عليه وسلم (انتهى) أي: تم وكمل بعون الله تعالى وحسن توفيقه (مبلغا) بصيغة اسم الفاعل حال من نظم المضاف إلى العقيدة (لمن وعاه) أي: النظم، يقال: وعيت الحديث وعيا من باب وعد، حفظته وتدبرته كذا في المصباح، (ما اشتهى) أي: الذي اشتهاه وأراد مفعول مبلغا (وفاء) أي: تمام، وفا الشيء بنفسه يفي إذا تم فهو واف كذا في المصباح (عدها) أي: هذه العقيدة يعني عد أبياتها المنظومة (بنصف ألف) أي: خمسمائة (والرمز) أي: الإشارة أيضا (بالجمل) بضم الجيم وتشديد الميم، وهو حساب الجمل جمع جملة (فيه) أي: في قله وفاء عدها بنصف ألف، فإن حرف هذا القول إذا حسبت بحساب الجمل بلغت نصف ألف يعني خمسمائة فإن الواو بستة والفاء بثمانين وألف بواحد والعين المهملة بسبعين والدال المهملة بأربعة والهاء بخمسة والألف بواحد والباء الموحدة باثنين، والنون بخمسين والصا المهملة بتسعين، والفاء بثمانين، وألف بواحد واللام بثلاثين، والفاء بثمانين فجملة ذلك خمسمائة (ألف) بالبناء للمفعول، أي: وجد ذلك الرمز بالجمل فيه. قال في المصباح: ألفيت الشيء يعني بالفاء وجدته، وهذا من غريب الاتفاق.\r(وكان إتمامي له) أي: وفاء العد المذكور (في القاهره) بسكون الهاء للوزن، أي: مصر المحروسة، ذات الربوع المأنوسة (وفيه) أي: في هذا المصراع المذكور الذي هو قوله وكان إتمامي له في القاهرة (تاريخ) السنة إتمام ذلك. وبيانه أن الواو بستة، والكاف بعشرين والألف بواحد، والنون بخمسين والألف بواحد والثاء المثناة الفوقية بأربع مائة، والميم بأربعين والألف بواحد، والميم بأربعين، والياء المثناة التحتية بعشرة واللام بثلاثين والهاء بخمسة، والفاء بثمانين، والياء بعشرة، والألف بواحد، واللام بثلاثين والقاف بمائة والألف بواحد، والهاء بخمسة والراء بمائتين، والهاء بخمسة، فالجملة ألف وستة وثلاثون وهي سنة الفراغ من نظم وعد هذه العقيدة كما وجدناه مذكورا في بعض النسخ ولم يمكنه أن يجعل حساب التاريخ مسبوقا بلفظ أرخ ونحو ذلك كما هو المعروف."], [187, "وأرتجي من مانح العظايا سبحانه الغفران للخطايا\rوالفوز بالنجاة والأمان ونيل ما أنوي من الأماني\rبجاه نبراس الهدى الوهاج أحمد من أرشد للمنهاج\rكهف البرايا الهاشمي العربي منيلهم ما أملوا من أرب\rعليه مع آل وصحب قد علوا قدرا واتباع بإحسان تلوا\r[الشرح]\r(حلاه) أي: حلى ذلك التاريخ وهو بكسر الحاء المهملة وبضمها أيضا جمع حلية بالكسر (الظاهره) بسكون الهاء للوزن وهي نعت للحلي أي: التي لا تحتاج إلى البيان لظهورها، وذكر التاريخ على هذه الطريقة نوع اخترعه المتأخرون، وقد أدرجناه في أنواع البديع في بديعيتنا وذكرنا في شرحها كيفية ذلك وما يليق به من الأبحاث المعتبرة فيه. (وأرتجي) أي: أطلب (من مانح) أي: معطي (العطايا) جمع عطية، وهو الله تعالى وتبارك (سبحانه) تنزيه له عما لا يليق به (الغفران÷) مفعول أرتجي (للخطايا) أي: الذنوب (و) أرتجي (الفوز بالنجاة) من عقابه في الدنيا والآخرة (والأمان÷) من كل هول وسوء في الدارين (و) أرتجي (نيل) أي: حصول (ما أنوي) أي: أقصده (من الأماني) جمع أمنية، وهي ما يتمناه من الخيرات (بجاه) أي: بحرمة (نبراس) بكسر النون، أي: مصباح (الهدى) أي: الهداية إلى الحق (الوهاج) من توهجت النار، اتقدت، وتوهج الجوهر: تلألأ كذا في الصحاح. (أحمد) بن عبد الله نبينا صلى الله عليه وسلم (من أرشد) أي: هدى الأمة (للمنهاج) أي: يلجأ إليه كالبيت على الاستعارة كذا في المصباح.\r(البرايا) أي: المخلوقات (الهاشمي) المنسوب إلى جده هاشم؛ لأنه محمد صلى الله عليه وسلم بن عبد الله بن عبد المطلب بن هاشم، من الهشم: كسر الشيء اليابس والأجوف وسمي هاشم بن عبد مناف واسمه عمرو لأنه أول من هشم الشريد لأهل الحرم كذا في المصباح.\r(العربي) المنسوب إلى العرب خلاف العجم (منيلهم) أي: البرايا يعني موصلهم (إلى ما أملوا) بتشديد الميم، أي: تمنوا (من أرب) أي: مقصود (عليه) الجار مع المجرور خبر مقدم لقوله أزكى تحيات (مع آل) أي: أهل بيته المؤمنين به أولاد علي وعقيل وجعفر والحارث والعباس إلى يوم القيامة (وصحب) جمع صاحب، وهو من لقي النبي صلى الله عليه وسلم مؤمنا به ومات على الإسلام (قد علوا) أي: ارتفعوا (قدرا) في الدنيا والآخرة."], [188, "…أزكى تحيات وأسمى وأتم…بزكو بها مبتدا ومختتم\rـــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــ\r(واتباع) لهم (بإحسان) أي: خير وإتقان في الدين (تلوا) أي: اتبعوا (أزكى) أي: أنمى وأزيد (تحيات) جمع تحية.\rقال في المصباح: حياة تحية وأصله الدعاء بالحياة. (وأسمى) من السمو، وهو العلو (وأتم) بسكون الميم أي: أكمل (يزكو) أي: ينمو ويزيد (بها) أي: التحيات (مبتدا) أي: كل ابتداء (ومختتم) بسكون الميم أي: كل اختتام والله ولي الإنعام، ومنه يستمد الفيض والجود والإكرام، ونسأله سبحانه أن يختم أعمالنا بالحسنى، ويمدنا بإمداد المقام الأسنى، وأن يلطف بنا وإخواننا المسلمين والمسلمات، والمؤمنين والمؤمنات، إلى وقت الممات، وأن يحفظنا من الخطأ والخطل، في القول والاعتقاد والعمل، وأن يجعلنا من أهل رضوانه، وينعمنا وسائر إخواننا في دار جنابه بمنه وكرمه، وجوده آمين. وصلى الله على سيدنا محمد وأصحابه والتابعين، إلى يوم الدين. وقد أكملنا هذا الشرح المبارك إن شاء الله تعالى عشية نهار الثلاثاء الثاني من شعبان، سنة سبع ومائة وألف.\rقد تم بعون الله وحسن توفيقه كتابة هذه النسخة المسماة ((إضاءة الدجنة في عقائد أهل السنة مع شرحها المسمى رائحة الجنة)) على يد كاتبها الطالب غفو الله وكرامته الحقير محمد إبراهيم بن جوهر في 21 ربيع الآخر عام ألف ومائتين وثمانية وتسعين. وقد حرر بغاية الضبط من نسخة الشيخ محمد أحمد الشنقيطي غفر الله لنا وللمسلمين أجمعين آمين."]], "pg": [136, 188]}}, "units": {"1": {"tit": "رائحة الجنة شرح إضاءة الدجنة في عقائد اهل السنة", "lvl": 1, "pg": [null, 9]}, "3": {"tit": "مقدمة الشارح", "lvl": 1, "pg": [9, 23]}, "17": {"tit": "مقدمة صاحب المتن", "lvl": 1, "pg": [23, 27]}, "21": {"tit": "فصل في بيان الحكم وذكر أقسامه", "lvl": 1, "pg": [27, 31]}, "26": {"tit": "فصل في النظر وأنه أول واجب", "lvl": 1, "pg": [31, 39]}, "34": {"tit": "فصل في الحث على النظر العقلي في العقائد", "lvl": 1, "pg": [39, 45]}, "40": {"tit": "فصل في بيان الصفات النفسية والسلبية وما ينافيها", "lvl": 1, "pg": [45, 64]}, "59": {"tit": "فصل في بيان صفات المعاني", "lvl": 1, "pg": [64, 72]}, "67": {"tit": "فصل في بيان الصفات المعنوية", "lvl": 1, "pg": [72, 73]}, "68": {"tit": "فصل في بيان معنى التعلق الذي لصفات المعاني المذكورة", "lvl": 1, "pg": [73, 76]}, "71": {"tit": "فصل في منافيات المعاني والمعنوية", "lvl": 1, "pg": [76, 78]}, "73": {"tit": "فصل في الأمر والرضا والمحبة", "lvl": 1, "pg": [78, 80]}, "75": {"tit": "فصل في حدوث العالم", "lvl": 1, "pg": [80, 88]}, "85": {"tit": "فصل في بيان الجائز", "lvl": 1, "pg": [88, 93]}, "91": {"tit": "فصل في بيان الرؤية", "lvl": 1, "pg": [93, 98]}, "96": {"tit": "فصل في أحكام الرسالة والنبوة", "lvl": 1, "pg": [98, 101]}, "99": {"tit": "فصل فيما يحب لهم وما يستحيل وما يجوز", "lvl": 1, "pg": [101, 110]}, "108": {"tit": "فصل في عدة الرسل عليهم السلام", "lvl": 1, "pg": [110, 118]}, "116": {"tit": "فصل في بيان السمعيات مما يجب الإيمان به", "lvl": 1, "pg": [118, 136]}, "134": {"tit": "خاتمة وأسأل الله حسنها في مسائل نافعة", "lvl": 1, "pg": [136, 188]}}};
